INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (1, '露米娅', '凶', '使四周变暗的妖怪', '操纵黑暗程度的能力', '["\u82e5\u5fc3\u6000\u9ed1\u6697\uff0c", "\u6b64\u4e8b\u9700\u8c28\u8bb0\uff1a", "\u4e0d\u901f\u4e4b\u5ba2\u5df2", "\u6084\u7136\u6f5c\u4e8e\u80f8\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5373\u4fbf\u8eab\u5904\u660e\u4eae\u4e4b\u5904\u4e5f\u4f1a\u7a81\u7136\u5931\u53bb\u89c6\u91ce\u3002\n\u53ef\u8c13\u524d\u9014\u4e00\u7247\u9ed1\u6697\u3002", "line": "\u8fd0\u52bf\uff1a\u5373\u4fbf\u8eab\u5904\u660e\u4eae\u4e4b\u5904\u4e5f\u4f1a\u7a81\u7136\u5931\u53bb\u89c6\u91ce\u3002\n\u53ef\u8c13\u524d\u9014\u4e00\u7247\u9ed1\u6697\u3002"}, {"label": "\u5065\u5eb7", "text": "\u53ea\u80fd\u7761\u89c9\uff0c\u522b\u65e0\u4ed6\u9009\u3002", "line": "\u5065\u5eb7\uff1a\u53ea\u80fd\u7761\u89c9\uff0c\u522b\u65e0\u4ed6\u9009\u3002"}, {"label": "\u51fa\u884c", "text": "\u65e0\u59a8\u3002\n\u4f46\u4ec5\u9650\u591c\u95f4\u3002", "line": "\u51fa\u884c\uff1a\u65e0\u59a8\u3002\n\u4f46\u4ec5\u9650\u591c\u95f4\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u552f\u6570\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u552f\u6570\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u5bfb\u7269", "text": "\u65ad\u5ff5\u4e3a\u5999\u3002", "line": "\u5bfb\u7269\uff1a\u65ad\u5ff5\u4e3a\u5999\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5f62\u5f71\u5355\u53ea\u3002", "line": "\u59fb\u7f18\uff1a\u5f62\u5f71\u5355\u53ea\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5f62\u5f71\u5355\u53ea\u53cd\u5012\u65e0\u4eba\u4fb5\u6270\u3002", "line": "\u4e89\u7aef\uff1a\u5f62\u5f71\u5355\u53ea\u53cd\u5012\u65e0\u4eba\u4fb5\u6270\u3002"}, {"label": "\u52a8\u7269", "text": "\u4e0d\u77e5\u4e3a\u4f55\u53d7\u591c\u89c6\u80fd\u529b\u5f3a\u7684\u732b\u79d1\u52a8\u7269\u4eb2\u8fd1\u3002\u6216\u8bb8\u662f\u88ab\u8f7b\u89c6\u4e86\u3002", "line": "\u52a8\u7269\uff1a\u4e0d\u77e5\u4e3a\u4f55\u53d7\u591c\u89c6\u80fd\u529b\u5f3a\u7684\u732b\u79d1\u52a8\u7269\u4eb2\u8fd1\u3002\u6216\u8bb8\u662f\u88ab\u8f7b\u89c6\u4e86\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (2, '大妖精
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (3, '琪露诺', '【最凶】', '火爆的冰之妖精', '操纵冰程度的能力', '["\u80fd\u628a\u54b1\u62bd\u5230\uff0c", "\u7b97\u4f60\u624b\u6c14\u597d\uff01", "\u8fd0\u9053\u6b63\u50cf\u54b1\uff0c", "\u6700\u5f3a\u6ca1\u5f97\u6311\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5927\u8d77\u5927\u843d\u3001\u96be\u5f97\u4e00\u65e5\u5b89\u7a33\uff0c\u82e5\u80fd\u6b23\u7136\u63a5\u53d7\u4fbf\u662f\u6700\u5f3a\u3002", "line": "\u8fd0\u52bf\uff1a\u5927\u8d77\u5927\u843d\u3001\u96be\u5f97\u4e00\u65e5\u5b89\u7a33\uff0c\u82e5\u80fd\u6b23\u7136\u63a5\u53d7\u4fbf\u662f\u6700\u5f3a\u3002"}, {"label": "\u5065\u5eb7", "text": "\u67d3\u4e0a\u611f\u5192\u4e5f\u610f\u8bc6\u4e0d\u5230\uff0c\u56e0\u6b64\u65e0\u788d\u3002", "line": "\u5065\u5eb7\uff1a\u67d3\u4e0a\u611f\u5192\u4e5f\u610f\u8bc6\u4e0d\u5230\uff0c\u56e0\u6b64\u65e0\u788d\u3002"}, {"label": "\u4ea4\u6613", "text": "\u7b97\u4e0d\u6e05\u8d26\u3002", "line": "\u4ea4\u6613\uff1a\u7b97\u4e0d\u6e05\u8d26\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7b28\u86cb\u53c8\u4f55\u59a8\u3002", "line": "\u5b66\u4e1a\uff1a\u7b28\u86cb\u53c8\u4f55\u59a8\u3002"}, {"label": "\u51fa\u884c", "text": "\u73a9\u5f97\u5c3d\u5174\uff0c\u4f46\u4f1a\u5fd8\u8bb0\u5f52\u9014\u3002", "line": "\u51fa\u884c\uff1a\u73a9\u5f97\u5c3d\u5174\uff0c\u4f46\u4f1a\u5fd8\u8bb0\u5f52\u9014\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4f1a\u5fd8\u8bb0\u81ea\u5df1\u4e22\u8fc7\u4e1c\u897f\u3002", "line": "\u5bfb\u7269\uff1a\u4f1a\u5fd8\u8bb0\u81ea\u5df1\u4e22\u8fc7\u4e1c\u897f\u3002"}], [{"label": "\u604b\u7231", "text": "\u867d\u6709\u5409\u5146\u5374\u6d51\u7136\u4e0d\u89c9\u3002", "line": "\u604b\u7231\uff1a\u867d\u6709\u5409\u5146\u5374\u6d51\u7136\u4e0d\u89c9\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5bb6\u5e38\u4fbf\u996d\u3002", "line": "\u4e89\u7aef\uff1a\u5bb6\u5e38\u4fbf\u996d\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u6b22\u58f0\u7b11\u8bed\uff0c\u4f46\u4e0d\u5f97\u5b89\u5b81\u3002", "line": "\u5bb6\u5ead\uff1a\u6b22\u58f0\u7b11\u8bed\uff0c\u4f46\u4e0d\u5f97\u5b89\u5b81\u3002"}, {"label": "\u79fb\u5f99", "text": "\u5fd8\u8bb0\u81ea\u5df1\u642c\u8fc7\u5bb6\u3002", "line": "\u79fb\u5f99\uff1a\u5fd8\u8bb0\u81ea\u5df1\u642c\u8fc7\u5bb6\u3002"}, {"label": "\u65b9\u4f4d", "text": "\u516b\u65b9\u7686\u5409\u3002\u4e5f\u4f1a\u7ed9\u516b\u65b9\u90bb\u91cc\u6dfb\u9ebb\u70e6\u3002", "line": "\u65b9\u4f4d\uff1a\u516b\u65b9\u7686\u5409\u3002\u4e5f\u4f1a\u7ed9\u516b\u65b9\u90bb\u91cc\u6dfb\u9ebb\u70e6\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (4, '红美铃', '平', 'THE·门卫', '运用气程度的能力', '["\u95e8\u536b\u6709\u5565\u7528\u3002", "\u53cd\u6b63\u6240\u6709\u4eba", "\u90fd\u662f\u4ece\u5929\u4e0a", "\u98de\u8fdb\u6765\u7684\u561b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e0\u8bba\u505a\u4ec0\u4e48\uff0c\u5883\u51b5\u90fd\u6ca1\u6709\u663e\u8457\u6539\u53d8\u3002\u4e0d\u4f1a\u597d\u8f6c\u4e5f\u4e0d\u4f1a\u6076\u5316\u3002", "line": "\u8fd0\u52bf\uff1a\u65e0\u8bba\u505a\u4ec0\u4e48\uff0c\u5883\u51b5\u90fd\u6ca1\u6709\u663e\u8457\u6539\u53d8\u3002\u4e0d\u4f1a\u597d\u8f6c\u4e5f\u4e0d\u4f1a\u6076\u5316\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8eba\u5e73\u7b49\u5f85\uff0c\u673a\u9047\u81ea\u6765\u3002\u4e0d\u8fc7\u7761\u7740\u7684\u8bdd\u4f1a\u88ab\u9a82\u3002", "line": "\u4ea4\u6613\uff1a\u8eba\u5e73\u7b49\u5f85\uff0c\u673a\u9047\u81ea\u6765\u3002\u4e0d\u8fc7\u7761\u7740\u7684\u8bdd\u4f1a\u88ab\u9a82\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u522b\u5984\u60f3\u80fd\u8fb9\u7761\u8fb9\u5b66\u3002", "line": "\u5b66\u4e1a\uff1a\u522b\u5984\u60f3\u80fd\u8fb9\u7761\u8fb9\u5b66\u3002"}, {"label": "\u4f4f\u6240", "text": "\u52a1\u5fc5\u597d\u597d\u770b\u5bb6\u3002", "line": "\u4f4f\u6240\uff1a\u52a1\u5fc5\u597d\u597d\u770b\u5bb6\u3002"}, {"label": "\u51fa\u884c", "text": "\u89c1\u4e0d\u7740\u597d\u8138\u8272\u3002", "line": "\u51fa\u884c\uff1a\u89c1\u4e0d\u7740\u597d\u8138\u8272\u3002"}], [{"label": "\u7231\u597d", "text": "\u79cd\u690d\u82b1\u5349\u4e3a\u5409\u3002\u690d\u7269\u4ece\u4e0d\u80cc\u53db\u3002", "line": "\u7231\u597d\uff1a\u79cd\u690d\u82b1\u5349\u4e3a\u5409\u3002\u690d\u7269\u4ece\u4e0d\u80cc\u53db\u3002"}, {"label": "\u604b\u7231", "text": "\u6beb\u65e0\u8fdb\u5c55\u3002", "line": "\u604b\u7231\uff1a\u6beb\u65e0\u8fdb\u5c55\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u5fc5\u8f93\u65e0\u7591\u3002\u56de\u907f\u4e3a\u4e0a\u3002", "line": "\u6bd4\u8bd5\uff1a\u5fc5\u8f93\u65e0\u7591\u3002\u56de\u907f\u4e3a\u4e0a\u3002"}, {"label": "\u5fc3\u613f", "text": "\u9690\u6709\u9f99\u76f8\uff0c\u4f46\u6781\u7a00\u8584\u3002\u5e38\u6000\u9006\u98ce\u7ffb\u76d8\u4e4b\u68a6\u5427\u3002", "line": "\u5fc3\u613f\uff1a\u9690\u6709\u9f99\u76f8\uff0c\u4f46\u6781\u7a00\u8584\u3002\u5e38\u6000\u9006\u98ce\u7ffb\u76d8\u4e4b\u68a6\u5427\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (5, '小恶魔
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (6, '帕秋莉·诺蕾姬', '中吉', '知识与避世的魔法使', '使用魔法（精灵为主）程度的能力', '["\u4e00\u5468\u4e03\u66dc\u65e5\uff0c", "\u552f\u6708\u662f\u536b\u661f\u3002", "\u6bd5\u7adf\u661f\u671f\u4e00\uff0c", "\u6700\u662f\u60f9\u4eba\u538c\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e00\u5468\u4e03\u65e5\u7686\u6709\u4e0d\u540c\u9645\u9047\u3002\u4efb\u4f55\u56f0\u96be\u90fd\u80fd\u7075\u6d3b\u5316\u89e3\u3002", "line": "\u8fd0\u52bf\uff1a\u4e00\u5468\u4e03\u65e5\u7686\u6709\u4e0d\u540c\u9645\u9047\u3002\u4efb\u4f55\u56f0\u96be\u90fd\u80fd\u7075\u6d3b\u5316\u89e3\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5e7f\u589e\u5b66\u8bc6\u5219\u673a\u9047\u81ea\u81f3\u3002\u6b63\u662f\u4e8b\u4e1a\u6269\u5f20\u7684\u826f\u673a\u3002", "line": "\u4ea4\u6613\uff1a\u5e7f\u589e\u5b66\u8bc6\u5219\u673a\u9047\u81ea\u81f3\u3002\u6b63\u662f\u4e8b\u4e1a\u6269\u5f20\u7684\u826f\u673a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8fd0\u52bf\u5dc5\u5cf0\u3002\u6b63\u662f\u6311\u6218\u4e4b\u65f6\u3002", "line": "\u5b66\u4e1a\uff1a\u8fd0\u52bf\u5dc5\u5cf0\u3002\u6b63\u662f\u6311\u6218\u4e4b\u65f6\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e00\u5468\u5185\u4ec5\u4e00\u65e5\u4e3a\u5409\u3002", "line": "\u8d22\u8fd0\uff1a\u4e00\u5468\u5185\u4ec5\u4e00\u65e5\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u7f3a\u4e4f\u8fd0\u52a8\u7ec8\u81f4\u6076\u679c\u3002", "line": "\u5065\u5eb7\uff1a\u7f3a\u4e4f\u8fd0\u52a8\u7ec8\u81f4\u6076\u679c\u3002"}], [{"label": "\u75be\u75c5", "text": "\u65e7\u75be\u96be\u6108\u3002\u552f\u6709\u9759\u517b\u3002", "line": "\u75be\u75c5\uff1a\u65e7\u75be\u96be\u6108\u3002\u552f\u6709\u9759\u517b\u3002"}, {"label": "\u604b\u7231", "text": "\u5b88\u682a\u5f85\u5154\u3002\u4f46\u672a\u5fc5\u80fd\u7b49\u5230\u4eba\u6765\u3002", "line": "\u604b\u7231\uff1a\u5b88\u682a\u5f85\u5154\u3002\u4f46\u672a\u5fc5\u80fd\u7b49\u5230\u4eba\u6765\u3002"}, {"label": "\u51fa\u884c", "text": "\u6743\u5f53\u81ea\u5df1\u53bb\u8fc7\u4e3a\u5409\u3002\u5f53\u771f\u51fa\u95e8\u53cd\u800c\u4f1a\u8eab\u4f53\u4e0d\u9002\u3002", "line": "\u51fa\u884c\uff1a\u6743\u5f53\u81ea\u5df1\u53bb\u8fc7\u4e3a\u5409\u3002\u5f53\u771f\u51fa\u95e8\u53cd\u800c\u4f1a\u8eab\u4f53\u4e0d\u9002\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u8bfb\u4e66\u3002\u9605\u8bfb\u4e43\u4e07\u8da3\u4e4b\u738b\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u8bfb\u4e66\u3002\u9605\u8bfb\u4e43\u4e07\u8da3\u4e4b\u738b\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (7, '十六夜咲夜', '大吉', '无所不能的潇洒女仆', '操纵时间程度的能力', '["\u53ef\u5426\u5360\u7528\u60a8", "\u4e00\u70b9\u65f6\u95f4\u5462\uff1f", "\u65e0\u9700\u60a8\u8d39\u5fc3\uff0c", "\u5df2\u7ecf\u5b8c\u4e8b\u4e86\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5de5\u4f5c\u5b66\u4e1a\u4e07\u4e8b\u987a\u9042\u3002\u79ef\u538b\u96be\u9898\u8fce\u5203\u800c\u89e3\u3002", "line": "\u8fd0\u52bf\uff1a\u5de5\u4f5c\u5b66\u4e1a\u4e07\u4e8b\u987a\u9042\u3002\u79ef\u538b\u96be\u9898\u8fce\u5203\u800c\u89e3\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u8bf8\u4e1a\u7686\u4e3a\u5409\u3002\u552f\u7f3a\u5f97\u529b\u4e0b\u5c5e\u3002", "line": "\u5de5\u4f5c\uff1a\u8bf8\u4e1a\u7686\u4e3a\u5409\u3002\u552f\u7f3a\u5f97\u529b\u4e0b\u5c5e\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8bf8\u5b66\u7686\u4e3a\u5409\u3002\u65f6\u95f4\u662f\u65e0\u9650\u7684\u3002", "line": "\u5b66\u4e1a\uff1a\u8bf8\u5b66\u7686\u4e3a\u5409\u3002\u65f6\u95f4\u662f\u65e0\u9650\u7684\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6613\u64cd\u52b3\u8fc7\u5ea6\u3002\u6ce8\u610f\u9002\u65f6\u4f11\u61a9\u3002", "line": "\u5065\u5eb7\uff1a\u6613\u64cd\u52b3\u8fc7\u5ea6\u3002\u6ce8\u610f\u9002\u65f6\u4f11\u61a9\u3002"}], [{"label": "\u604b\u7231", "text": "\u65e0\u987b\u7126\u8e81\u3002\u65f6\u95f4\u662f\u65e0\u9650\u7684\u3002", "line": "\u604b\u7231\uff1a\u65e0\u987b\u7126\u8e81\u3002\u65f6\u95f4\u662f\u65e0\u9650\u7684\u3002"}, {"label": "\u4f4f\u6240", "text": "\u6574\u7406\u6536\u7eb3\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u6574\u7406\u6536\u7eb3\u4e3a\u5409\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u8d4c\u8fd0\u4ea8\u901a\u3002", "line": "\u8d22\u8fd0\uff1a\u8d4c\u8fd0\u4ea8\u901a\u3002"}, {"label": "\u53a8\u827a", "text": "\u4e0e\u65e5\u4ff1\u8fdb\u3002\u6311\u6218\u73cd\u7a00\u98df\u6750\u7684\u826f\u673a\u3002", "line": "\u53a8\u827a\uff1a\u4e0e\u65e5\u4ff1\u8fdb\u3002\u6311\u6218\u73cd\u7a00\u98df\u6750\u7684\u826f\u673a\u3002"}, {"label": "\u7269\u4ef6", "text": "\u643a\u5e26\u6000\u8868\u4e3a\u5409\u3002\u82e5\u516c\u7136\u643a\u5e26\u5315\u9996\u5219\u5fc5\u906d\u902e\u6355\u3002", "line": "\u7269\u4ef6\uff1a\u643a\u5e26\u6000\u8868\u4e3a\u5409\u3002\u82e5\u516c\u7136\u643a\u5e26\u5315\u9996\u5219\u5fc5\u906d\u902e\u6355\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (8, '蕾米莉亚·斯卡蕾特', '吉凶未卜', '永远鲜红的吸血鬼', '操纵命运程度的能力', '["\u533a\u533a\u672a\u6765\u4e8b\uff0c", "\u4f55\u987b\u53bb\u5360\u535c\uff1f", "\u672a\u6765\u8981\u5982\u4f55\uff0c", "\u4eb2\u624b\u53ef\u6289\u62e9\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u91cd\u5927\u6289\u62e9\u63a5\u8e35\u800c\u81f3\uff0c\u52a1\u5fc5\u5fc3\u6000\u51b3\u610f\u505a\u51fa\u9009\u62e9\u3002", "line": "\u8fd0\u52bf\uff1a\u91cd\u5927\u6289\u62e9\u63a5\u8e35\u800c\u81f3\uff0c\u52a1\u5fc5\u5fc3\u6000\u51b3\u610f\u505a\u51fa\u9009\u62e9\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u9762\u4e34\u547d\u8fd0\u5206\u6b67\u70b9\u3002\u5207\u5fcc\u9003\u907f\u9009\u62e9\u3002", "line": "\u5de5\u4f5c\uff1a\u9762\u4e34\u547d\u8fd0\u5206\u6b67\u70b9\u3002\u5207\u5fcc\u9003\u907f\u9009\u62e9\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u82e5\u56e0\u62e9\u6821\u800c\u8e0c\u8e87\uff0c\u5219\u66f4\u5f53\u6311\u6218\u96be\u5173\u3002", "line": "\u5b66\u4e1a\uff1a\u82e5\u56e0\u62e9\u6821\u800c\u8e0c\u8e87\uff0c\u5219\u66f4\u5f53\u6311\u6218\u96be\u5173\u3002"}, {"label": "\u604b\u7231", "text": "\u6289\u62e9\u4e4b\u65f6\u8feb\u8fd1\u3002\u4e09\u5fc3\u4e8c\u610f\u5fc5\u906d\u4e0d\u5e78\u3002", "line": "\u604b\u7231\uff1a\u6289\u62e9\u4e4b\u65f6\u8feb\u8fd1\u3002\u4e09\u5fc3\u4e8c\u610f\u5fc5\u906d\u4e0d\u5e78\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u9632\u6652\u63aa\u65bd\u9700\u4e07\u5168\u3002\u5fcc\u98df\u6c99\u4e01\u9c7c\u4e0e\u5927\u849c\u3002", "line": "\u5065\u5eb7\uff1a\u9632\u6652\u63aa\u65bd\u9700\u4e07\u5168\u3002\u5fcc\u98df\u6c99\u4e01\u9c7c\u4e0e\u5927\u849c\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u53e4\u57ce\u3002\u5fcc\u6c34\u7554\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u53e4\u57ce\u3002\u5fcc\u6c34\u7554\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e9b\u8bb8\u727a\u7272\u53ef\u6362\u6765\u5de8\u5927\u6536\u76ca\u3002", "line": "\u8d22\u8fd0\uff1a\u4e9b\u8bb8\u727a\u7272\u53ef\u6362\u6765\u5de8\u5927\u6536\u76ca\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5e78\u9047\u5f97\u529b\u4e0b\u5c5e\u3002", "line": "\u4eba\u7f18\uff1a\u5e78\u9047\u5f97\u529b\u4e0b\u5c5e\u3002"}, {"label": "\u4e89\u7aef", "text": "\u672a\u5c1d\u4e00\u8d25\u3002", "line": "\u4e89\u7aef\uff1a\u672a\u5c1d\u4e00\u8d25\u3002"}, {"label": "\u7231\u597d", "text": "\u54c1\u9274\u7ea2\u8336\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u54c1\u9274\u7ea2\u8336\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (9, '芙兰朵露·斯卡蕾特', '【凶猛】', '毁灭一切的吸血鬼', '将一切悉数破坏程度的能力', '["\u9971\u542b\u5fc3\u8840\u7684", "\u4f5c\u54c1\u66f4\u5e94\u8be5", "\u8f70\u8f70\u70c8\u70c8\u5730", "\u53bb\u7834\u574f\u6b86\u5c3d\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6e34\u671b\u7834\u574f\u65e2\u6709\u6210\u5c31\u3002\u4e0d\u5e78\u6216\u4ea6\u5c06\u4e00\u5e76\u7c89\u788e\u3002", "line": "\u8fd0\u52bf\uff1a\u6e34\u671b\u7834\u574f\u65e2\u6709\u6210\u5c31\u3002\u4e0d\u5e78\u6216\u4ea6\u5c06\u4e00\u5e76\u7c89\u788e\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u91cd\u6574\u4e4b\u673a\u3002\u8df3\u69fd\u524d\u987b\u59a5\u5584\u4e86\u7ed3\u5de5\u4f5c\u3002\u62c6\u8fc1\u4e1a\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u91cd\u6574\u4e4b\u673a\u3002\u8df3\u69fd\u524d\u987b\u59a5\u5584\u4e86\u7ed3\u5de5\u4f5c\u3002\u62c6\u8fc1\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8fd1\u4e4e\u6e83\u8d25\u3002\u653b\u514b\u8584\u5f31\u79d1\u76ee\u7684\u826f\u673a\u3002\u7c92\u5b50\u7269\u7406\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u8fd1\u4e4e\u6e83\u8d25\u3002\u653b\u514b\u8584\u5f31\u79d1\u76ee\u7684\u826f\u673a\u3002\u7c92\u5b50\u7269\u7406\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u907f\u5f00\u7d2b\u5916\u7ebf\u3002\u4ea6\u987b\u6ce8\u610f\u8fd0\u52a8\u91cf\u4e0d\u8db3\u3002", "line": "\u5065\u5eb7\uff1a\u907f\u5f00\u7d2b\u5916\u7ebf\u3002\u4ea6\u987b\u6ce8\u610f\u8fd0\u52a8\u91cf\u4e0d\u8db3\u3002"}, {"label": "\u4f4f\u6240", "text": "\u503e\u9893\u3002\u7b79\u5212\u91cd\u5efa\u5427\u3002", "line": "\u4f4f\u6240\uff1a\u503e\u9893\u3002\u7b79\u5212\u91cd\u5efa\u5427\u3002"}, {"label": "\u51fa\u884c", "text": "\u5f53\u4e0b\u4e0d\u5b9c\u3002\u5c24\u5fcc\u8fd1\u6c34\u3002", "line": "\u51fa\u884c\uff1a\u5f53\u4e0b\u4e0d\u5b9c\u3002\u5c24\u5fcc\u8fd1\u6c34\u3002"}, {"label": "\u604b\u7231", "text": "\u5e7b\u706d\u3002", "line": "\u604b\u7231\uff1a\u5e7b\u706d\u3002"}, {"label": "\u5bfb\u7269", "text": "\u6c38\u4e0d\u590d\u5f97\u3002", "line": "\u5bfb\u7269\uff1a\u6c38\u4e0d\u590d\u5f97\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e3b\u52a8\u758f\u79bb\u4ed6\u4eba\u3002", "line": "\u4eba\u7f18\uff1a\u4e3b\u52a8\u758f\u79bb\u4ed6\u4eba\u3002"}, {"label": "\u7231\u597d", "text": "\u7834\u800c\u540e\u7acb\u3002\u72ec\u5904\u4e3a\u4e0a\u3002", "line": "\u7231\u597d\uff1a\u7834\u800c\u540e\u7acb\u3002\u72ec\u5904\u4e3a\u4e0a\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (10, '蕾蒂·霍瓦特洛克', '中吉', '适合寒冷季节的妖怪', '操纵寒冷程度的能力', '["\u4e3b\u52a8\u62e5\u62b1", "\u51ac\u5b63\u4e4b\u4eba\uff0c", "\u5185\u5fc3\u4e00\u5b9a", "\u6e29\u6696\u5982\u6625\u3002", "\uff08\u81ea\u79f0\uff09"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8bf8\u4e8b\u987a\u9042\u5f97\u6070\u5230\u597d\u5904\u3002\u4f46\u6c14\u8fd0\u96be\u957f\u4e45\uff0c\u5b9c\u901f\u901f\u884c\u52a8\u3002", "line": "\u8fd0\u52bf\uff1a\u8bf8\u4e8b\u987a\u9042\u5f97\u6070\u5230\u597d\u5904\u3002\u4f46\u6c14\u8fd0\u96be\u957f\u4e45\uff0c\u5b9c\u901f\u901f\u884c\u52a8\u3002"}, {"label": "\u65b9\u4f4d", "text": "\u5317\u65b9\u4e3a\u5409\u3002", "line": "\u65b9\u4f4d\uff1a\u5317\u65b9\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8c28\u9632\u53d7\u5bd2\u3002", "line": "\u5065\u5eb7\uff1a\u8c28\u9632\u53d7\u5bd2\u3002"}, {"label": "\u79fb\u5f99", "text": "\u65e9\u8fc1\u4e3a\u4e0a\u3002", "line": "\u79fb\u5f99\uff1a\u65e9\u8fc1\u4e3a\u4e0a\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u56ca\u8424\u6620\u96ea\u3002\u4f46\u62e2\u96ea\u7167\u660e\u7ec8\u7a76\u4eae\u5ea6\u4e0d\u8db3\uff0c\u8fd8\u8bf7\u6b63\u5e38\u70b9\u706f\u3002", "line": "\u5b66\u4e1a\uff1a\u56ca\u8424\u6620\u96ea\u3002\u4f46\u62e2\u96ea\u7167\u660e\u7ec8\u7a76\u4eae\u5ea6\u4e0d\u8db3\uff0c\u8fd8\u8bf7\u6b63\u5e38\u70b9\u706f\u3002"}, {"label": "\u706b\u9505", "text": "\u5b9c\u98df\u517d\u8089\u3002", "line": "\u706b\u9505\uff1a\u5b9c\u98df\u517d\u8089\u3002"}, {"label": "\u6c90\u6d74", "text": "\u5b9c\u9999\u6a59\u6d74\u3002\u6e29\u6cc9\u66f4\u4f73\u3002", "line": "\u6c90\u6d74\uff1a\u5b9c\u9999\u6a59\u6d74\u3002\u6e29\u6cc9\u66f4\u4f73\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (11, '橙', '凶', '被操控的式神猫妖', '使用妖术程度的能力', '["\u62bd\u5230\u4e86\u9ed1\u732b\uff0c", "\u4f60\u53ef\u771f\u4e0d\u5e78\u3002", "\u4e0d\u8fc7\u6211\u53ea\u6709", "\u6bdb\u662f\u9ed1\u7684\u54e6\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6574\u4f53\u4e0d\u5409\u3002\u4f46\u672a\u5fc5\u771f\u6709\u574f\u4e8b\u53d1\u751f\u3002", "line": "\u8fd0\u52bf\uff1a\u6574\u4f53\u4e0d\u5409\u3002\u4f46\u672a\u5fc5\u771f\u6709\u574f\u4e8b\u53d1\u751f\u3002"}, {"label": "\u51fa\u884c", "text": "\u8ff7\u8def\u4e3a\u5409\u3002\u82e5\u64c5\u5165\u7a7a\u5b85\uff0c\u4e0d\u53ef\u5e26\u8d70\u8d22\u7269\u3002", "line": "\u51fa\u884c\uff1a\u8ff7\u8def\u4e3a\u5409\u3002\u82e5\u64c5\u5165\u7a7a\u5b85\uff0c\u4e0d\u53ef\u5e26\u8d70\u8d22\u7269\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e0d\u597d\u4e0d\u574f\u3002", "line": "\u4ea4\u6613\uff1a\u4e0d\u597d\u4e0d\u574f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9700\u52e4\u52c9\u5411\u5b66\u3002", "line": "\u5b66\u4e1a\uff1a\u9700\u52e4\u52c9\u5411\u5b66\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u53d7\u4f24\u3002\u4fee\u526a\u6307\u7532\u4e3a\u5409\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u53d7\u4f24\u3002\u4fee\u526a\u6307\u7532\u4e3a\u5409\u3002"}, {"label": "\u79fb\u5f99", "text": "\u4e0d\u52a8\u4e3a\u5999\u3002", "line": "\u79fb\u5f99\uff1a\u4e0d\u52a8\u4e3a\u5999\u3002"}, {"label": "\u5fcc\u4e8b", "text": "\u6c34\u8fb9\u65c5\u884c\uff0c\u6c34\u7535\u7ef4\u4fee\uff0c\u6728\u5929\u84fc\u3002", "line": "\u5fcc\u4e8b\uff1a\u6c34\u8fb9\u65c5\u884c\uff0c\u6c34\u7535\u7ef4\u4fee\uff0c\u6728\u5929\u84fc\u3002"}, {"label": "\u732b\u8fd0", "text": "\u6613\u53d7\u91ce\u732b\u4eb2\u8fd1\u3002\u662f\u5fe7\u662f\u559c\uff0c\u5168\u51ed\u5fc3\u5883\u3002", "line": "\u732b\u8fd0\uff1a\u6613\u53d7\u91ce\u732b\u4eb2\u8fd1\u3002\u662f\u5fe7\u662f\u559c\uff0c\u5168\u51ed\u5fc3\u5883\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (12, '爱丽丝·玛格特洛依德', '末吉', '孤身一人也不失喧闹的人偶师', '使用魔法（人偶操纵）程度的能力', '["\u6ca1\u4ec0\u4e48\u8bc0\u7a8d\uff0c", "\u552f\u624b\u5de7\u7f62\u4e86\u3002", "\u65e0\u8bba\u662f\u63d0\u7ebf", "\u6291\u6216\u662f\u9b54\u6cd5\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u70ed\u95f9\u7eb7\u5448\u7684\u751f\u6d3b\u53ea\u662f\u8868\u8c61\uff0c\u65f6\u5e38\u611f\u5230\u5b64\u72ec\u3002", "line": "\u8fd0\u52bf\uff1a\u70ed\u95f9\u7eb7\u5448\u7684\u751f\u6d3b\u53ea\u662f\u8868\u8c61\uff0c\u65f6\u5e38\u611f\u5230\u5b64\u72ec\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4ea4\u9645\u5e7f\u6cdb\uff0c\u5374\u65e0\u6df1\u4ea4\u3002", "line": "\u4eba\u7f18\uff1a\u4ea4\u9645\u5e7f\u6cdb\uff0c\u5374\u65e0\u6df1\u4ea4\u3002"}, {"label": "\u604b\u7231", "text": "\u53ef\u5982\u6728\u5076\u822c\u8086\u610f\u64cd\u63a7\u8005\u4e3a\u5b9c\uff0c\u5426\u5219\u5c06\u53cd\u88ab\u64cd\u63a7\u3002", "line": "\u604b\u7231\uff1a\u53ef\u5982\u6728\u5076\u822c\u8086\u610f\u64cd\u63a7\u8005\u4e3a\u5b9c\uff0c\u5426\u5219\u5c06\u53cd\u88ab\u64cd\u63a7\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u51ed\u501f\u5de7\u52b2\uff0c\u65e5\u76ca\u5174\u9686\u3002", "line": "\u4ea4\u6613\uff1a\u51ed\u501f\u5de7\u52b2\uff0c\u65e5\u76ca\u5174\u9686\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u64c5\u957f\u8003\u8bd5\u3002", "line": "\u5b66\u4e1a\uff1a\u64c5\u957f\u8003\u8bd5\u3002"}, {"label": "\u5bfb\u7269", "text": "\u7728\u773c\u4e4b\u95f4\u4fbf\u6709\u5931\u7269\uff0c\u7728\u773c\u4e4b\u95f4\u53c8\u4f1a\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u7728\u773c\u4e4b\u95f4\u4fbf\u6709\u5931\u7269\uff0c\u7728\u773c\u4e4b\u95f4\u53c8\u4f1a\u5bfb\u56de\u3002"}, {"label": "\u51fa\u884c", "text": "\u4e0e\u4eba\u5076\u540c\u884c\u4e3a\u5409\u3002\u6d77\u5916\u65c5\u884c\u5219\u5409\u4e0a\u52a0\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4e0e\u4eba\u5076\u540c\u884c\u4e3a\u5409\u3002\u6d77\u5916\u65c5\u884c\u5219\u5409\u4e0a\u52a0\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4e00\u4e0d\u7559\u795e\u4fbf\u4f1a\u81ea\u8a00\u81ea\u8bed\u3002\u591a\u52a0\u7559\u610f\u3002", "line": "\u5065\u5eb7\uff1a\u4e00\u4e0d\u7559\u795e\u4fbf\u4f1a\u81ea\u8a00\u81ea\u8bed\u3002\u591a\u52a0\u7559\u610f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (13, '莉莉霍瓦特', '大吉', '从头到脚都是春的妖精', '告知春天已经来临程度的能力', '["\u5929\u7ffb\u5730\u8986\u4e5f", "\u4e0d\u662f\u5927\u95ee\u9898\u3002", "\u5168\u90fd\u5f52\u548e\u4e8e", "\u6625\u610f\u88ad\u4eba\u5427\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6f2b\u957f\u5bd2\u51ac\u5df2\u8fc7\uff0c\u8fd0\u52bf\u7a33\u6b65\u4e0a\u5347\u3002\u5f97\u610f\u5fd8\u5f62\u4e5f\u65e0\u59a8\u3002", "line": "\u8fd0\u52bf\uff1a\u6f2b\u957f\u5bd2\u51ac\u5df2\u8fc7\uff0c\u8fd0\u52bf\u7a33\u6b65\u4e0a\u5347\u3002\u5f97\u610f\u5fd8\u5f62\u4e5f\u65e0\u59a8\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e00\u8def\u770b\u6da8\u3002\u82e5\u6dfb\u96c7\u4eba\u624b\u5219\u66f4\u4f73\u3002", "line": "\u4ea4\u6613\uff1a\u4e00\u8def\u770b\u6da8\u3002\u82e5\u6dfb\u96c7\u4eba\u624b\u5219\u66f4\u4f73\u3002"}, {"label": "\u5c31\u4e1a", "text": "\u534e\u4e3d\u4eae\u76f8\uff0c\u65e0\u987b\u7f9e\u602f\u3002", "line": "\u5c31\u4e1a\uff1a\u534e\u4e3d\u4eae\u76f8\uff0c\u65e0\u987b\u7f9e\u602f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e0d\u518d\u5728\u610f\u6210\u7ee9\u9ad8\u4f4e\u3002", "line": "\u5b66\u4e1a\uff1a\u4e0d\u518d\u5728\u610f\u6210\u7ee9\u9ad8\u4f4e\u3002"}], [{"label": "\u75be\u75c5", "text": "\u6df1\u53d7\u6749\u6811\u82b1\u7c89\u56f0\u6270\u3002", "line": "\u75be\u75c5\uff1a\u6df1\u53d7\u6749\u6811\u82b1\u7c89\u56f0\u6270\u3002"}, {"label": "\u51fa\u884c", "text": "\u4e14\u968f\u98ce\u4e4b\u6240\u5411\u3002", "line": "\u51fa\u884c\uff1a\u4e14\u968f\u98ce\u4e4b\u6240\u5411\u3002"}, {"label": "\u79fb\u5f99", "text": "\u5404\u5904\u7686\u5409\u3002", "line": "\u79fb\u5f99\uff1a\u5404\u5904\u7686\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u6625\u98ce\u5f97\u610f\uff0c\u516b\u5366\u6e10\u589e\u3002\u8d4f\u82b1\u5e2d\u95f4\u89c1\u826f\u673a\u3002", "line": "\u604b\u7231\uff1a\u6625\u98ce\u5f97\u610f\uff0c\u516b\u5366\u6e10\u589e\u3002\u8d4f\u82b1\u5e2d\u95f4\u89c1\u826f\u673a\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u683d\u6625\u65e5\u82b1\u6728\u3002\u6a31\u6811\u4e3a\u4f73\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u683d\u6625\u65e5\u82b1\u6728\u3002\u6a31\u6811\u4e3a\u4f73\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (14, '露娜萨·普莉兹姆利巴', '吉', '抚平心境的骚灵三姐妹长姐', '演奏忧郁之音程度的能力', '["\u8fd9\u79cd\u7d27\u5f20\u611f", "\u706b\u5019\u6b63\u7edd\u5999\u3002", "\u7434\u5f26\u677e\u57ae\u57ae\uff0c", "\u54ea\u6709\u4e50\u97f3\u6765\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u51ed\u501f\u51b7\u9759\u8de8\u8d8a\u5343\u96be\u4e07\u9669\u3002\u82e5\u5931\u51b7\u9759\u5219\u4e07\u52ab\u4e0d\u590d\u3002", "line": "\u8fd0\u52bf\uff1a\u51ed\u501f\u51b7\u9759\u8de8\u8d8a\u5343\u96be\u4e07\u9669\u3002\u82e5\u5931\u51b7\u9759\u5219\u4e07\u52ab\u4e0d\u590d\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4fdd\u6301\u51b7\u9759\u5219\u4e07\u4e8b\u987a\u9042\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u4fdd\u6301\u51b7\u9759\u5219\u4e07\u4e8b\u987a\u9042\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u5927\u5409\uff0c\u8bed\u6587\u4ea6\u53ef\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u5927\u5409\uff0c\u8bed\u6587\u4ea6\u53ef\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u7cbe\u795e\u75be\u75c5\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u7cbe\u795e\u75be\u75c5\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u56e0\u566a\u97f3\u62db\u81f4\u6295\u8bc9\uff0c\u4e0e\u90bb\u91cc\u53d1\u751f\u7ea0\u7eb7\u3002", "line": "\u4f4f\u6240\uff1a\u56e0\u566a\u97f3\u62db\u81f4\u6295\u8bc9\uff0c\u4e0e\u90bb\u91cc\u53d1\u751f\u7ea0\u7eb7\u3002"}, {"label": "\u604b\u7231", "text": "\u52a1\u5fc5\u4fdd\u6301\u51b7\u9759\u3002", "line": "\u604b\u7231\uff1a\u52a1\u5fc5\u4fdd\u6301\u51b7\u9759\u3002"}, {"label": "\u4eba\u7f18", "text": "\u88ab\u89c6\u4f5c\u51b7\u6f20\u4e4b\u4eba\uff0c\u65e0\u4eba\u4e3b\u52a8\u4eb2\u8fd1\u3002", "line": "\u4eba\u7f18\uff1a\u88ab\u89c6\u4f5c\u51b7\u6f20\u4e4b\u4eba\uff0c\u65e0\u4eba\u4e3b\u52a8\u4eb2\u8fd1\u3002"}, {"label": "\u7231\u597d", "text": "\u82e5\u8bf4\u7231\u597d\u5c0f\u63d0\u7434\u4f1a\u663e\u5f97\u9887\u6709\u683c\u8c03\u3002", "line": "\u7231\u597d\uff1a\u82e5\u8bf4\u7231\u597d\u5c0f\u63d0\u7434\u4f1a\u663e\u5f97\u9887\u6709\u683c\u8c03\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (15, '梅露兰·普莉兹姆利巴', '中吉', '搅乱心绪的骚灵三姐妹二姐', '演奏躁动之音程度的能力', '["\u8981\u8bf4\u53d1\u58f0\u54cd\uff0c", "\u91d1\u5c5e\u6700\u6d2a\u4eae\u3002", "\u8981\u8bba\u97f3\u4e50\u4e8b\uff0c", "\u529b\u5ea6\u5f53\u4e3a\u738b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u751f\u6027\u5f00\u6717\u4e50\u89c2\uff0c\u5f97\u4ee5\u514b\u670d\u56f0\u96be\u3002\u4f46\u4ea6\u96be\u514d\u53cd\u62db\u707e\u7978\u3002", "line": "\u8fd0\u52bf\uff1a\u751f\u6027\u5f00\u6717\u4e50\u89c2\uff0c\u5f97\u4ee5\u514b\u670d\u56f0\u96be\u3002\u4f46\u4ea6\u96be\u514d\u53cd\u62db\u707e\u7978\u3002"}, {"label": "\u4ea4\u6613", "text": "\u82e5\u80fd\u4e50\u5728\u5176\u4e2d\u5219\u7ec8\u6709\u5174\u76db\u4e4b\u65e5\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u82e5\u80fd\u4e50\u5728\u5176\u4e2d\u5219\u7ec8\u6709\u5174\u76db\u4e4b\u65e5\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u5927\u5409\uff0c\u7f8e\u672f\u4ea6\u4f73\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u5927\u5409\uff0c\u7f8e\u672f\u4ea6\u4f73\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u7cbe\u795e\u75be\u75c5\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u7cbe\u795e\u75be\u75c5\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u56db\u987e\u65e0\u90bb\u7684\u72ec\u680b\u623f\u5c4b\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u56db\u987e\u65e0\u90bb\u7684\u72ec\u680b\u623f\u5c4b\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u524d\u666f\u53ef\u671f\uff0c\u4f46\u9700\u8b66\u60d5\u51fa\u8f68\u3002", "line": "\u604b\u7231\uff1a\u524d\u666f\u53ef\u671f\uff0c\u4f46\u9700\u8b66\u60d5\u51fa\u8f68\u3002"}, {"label": "\u4eba\u7f18", "text": "\u6613\u805a\u4e5f\u6613\u6563\u3002", "line": "\u4eba\u7f18\uff1a\u6613\u805a\u4e5f\u6613\u6563\u3002"}, {"label": "\u7231\u597d", "text": "\u5c0f\u53f7\u5b9c\u5728\u6cb3\u6ee9\u5439\u594f\u3002", "line": "\u7231\u597d\uff1a\u5c0f\u53f7\u5b9c\u5728\u6cb3\u6ee9\u5439\u594f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (16, '莉莉卡·普莉兹姆利巴', '小吉', '奏响亡音的骚灵三姐妹三妹', '演奏幻想之音程度的能力', '["\u5230\u5934\u6765\u8fd8\u662f", "\u4e00\u78b0\u5c31\u53d1\u58f0", "\u7684\u952e\u76d8\u4e50\u5668", "\u624d\u6700\u96be\u5f39\u594f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7410\u4e8b\u5206\u6563\u5fc3\u795e\uff0c\u8fd0\u52bf\u96be\u4ee5\u4e0a\u5347\u3002", "line": "\u8fd0\u52bf\uff1a\u7410\u4e8b\u5206\u6563\u5fc3\u795e\uff0c\u8fd0\u52bf\u96be\u4ee5\u4e0a\u5347\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9002\u5408\u5e55\u540e\u64cd\u76d8\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u5219\u5409\u4e0a\u52a0\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u9002\u5408\u5e55\u540e\u64cd\u76d8\u3002\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u5219\u5409\u4e0a\u52a0\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u5927\u5409\uff0c\u7406\u79d1\u5c1a\u53ef\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u5927\u5409\uff0c\u7406\u79d1\u5c1a\u53ef\u3002"}, {"label": "\u5065\u5eb7", "text": "\u826f\u597d\u3002", "line": "\u5065\u5eb7\uff1a\u826f\u597d\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4e09\u81f3\u56db\u4eba\u540c\u884c\u4e3a\u5409\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u624b\u8db3\u540c\u80de\u7f79\u60a3\u5fc3\u75c5\uff0c\u4e3a\u6b64\u82e6\u607c\u4e0d\u5df2\u3002", "line": "\u5bb6\u5ead\uff1a\u624b\u8db3\u540c\u80de\u7f79\u60a3\u5fc3\u75c5\uff0c\u4e3a\u6b64\u82e6\u607c\u4e0d\u5df2\u3002"}, {"label": "\u604b\u7231", "text": "\u65e0\u6cd5\u5f15\u8d77\u5bf9\u65b9\u5173\u6ce8\u3002", "line": "\u604b\u7231\uff1a\u65e0\u6cd5\u5f15\u8d77\u5bf9\u65b9\u5173\u6ce8\u3002"}, {"label": "\u7231\u597d", "text": "\u5fc3\u7075\u624b\u5de7\uff0c\u4efb\u4f55\u6280\u827a\u7686\u80fd\u638c\u63e1\u3002\u4e13\u5fc3\u4e60\u5f97\u4e00\u6280\u508d\u8eab\u4ea6\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u5fc3\u7075\u624b\u5de7\uff0c\u4efb\u4f55\u6280\u827a\u7686\u80fd\u638c\u63e1\u3002\u4e13\u5fc3\u4e60\u5f97\u4e00\u6280\u508d\u8eab\u4ea6\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (17, '魂魄妖梦', '半吉', '半身剑锋、半身剑胆', '使用剑术程度的能力', '["\u60a8\u600e\u4e48\u4e86\u5440\uff0c", "\u5e7d\u5e7d\u5b50\u5927\u4eba\uff1f", "\u90a3\u4e0d\u662f\u4e00\u4e2a", "\u5927\u53f7\u62b1\u6795\u5417\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u534a\u540a\u5b50\u7684\u8fd0\u52bf\u3002\u65e0\u8bba\u673a\u7f18\u8fd8\u662f\u52ab\u96be\u7686\u534a\u9014\u800c\u6b62\u3002", "line": "\u8fd0\u52bf\uff1a\u534a\u540a\u5b50\u7684\u8fd0\u52bf\u3002\u65e0\u8bba\u673a\u7f18\u8fd8\u662f\u52ab\u96be\u7686\u534a\u9014\u800c\u6b62\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5e73\u5e73\u65e0\u5947\u3002\u4ec5\u80fd\u628a\u63e1\u534a\u6570\u826f\u673a\u3002", "line": "\u4ea4\u6613\uff1a\u5e73\u5e73\u65e0\u5947\u3002\u4ec5\u80fd\u628a\u63e1\u534a\u6570\u826f\u673a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0a\u53f8\u6dfb\u4e71\u3002\u56ed\u4e01\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0a\u53f8\u6dfb\u4e71\u3002\u56ed\u4e01\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9057\u61be\u3002", "line": "\u5b66\u4e1a\uff1a\u9057\u61be\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u534a\u8eab\u5165\u571f\uff0c\u4f46\u65e0\u5927\u788d\u3002", "line": "\u5065\u5eb7\uff1a\u534a\u8eab\u5165\u571f\uff0c\u4f46\u65e0\u5927\u788d\u3002"}, {"label": "\u604b\u7231", "text": "\u65a9\u65ad\u96be\u7f20\u5b7d\u7f18\u7684\u826f\u673a\u3002", "line": "\u604b\u7231\uff1a\u65a9\u65ad\u96be\u7f20\u5b7d\u7f18\u7684\u826f\u673a\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5ead\u9662\u6108\u5e7f\u6108\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u5ead\u9662\u6108\u5e7f\u6108\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u5750\u7985\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u5750\u7985\u4e3a\u5409\u3002"}, {"label": "\u7269\u4ef6", "text": "\u5fc3\u6108\u7a7a\u660e\uff0c\u5251\u950b\u6108\u5229\u3002\u5c06\u56f0\u96be\u4e00\u5200\u4e24\u65ad\u81ea\u5f97\u5f00\u8fd0\u3002", "line": "\u7269\u4ef6\uff1a\u5fc3\u6108\u7a7a\u660e\uff0c\u5251\u950b\u6108\u5229\u3002\u5c06\u56f0\u96be\u4e00\u5200\u4e24\u65ad\u81ea\u5f97\u5f00\u8fd0\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (18, '西行寺幽幽子', '末大吉', '咏花舞雪的亡灵', '操纵死亡程度的能力', '["\u4ea1\u7075\u548c\u6d3b\u4eba\uff0c", "\u6709\u4ec0\u4e48\u4e0d\u540c\uff1f", "\u65e5\u5b50\u633a\u8212\u5766\uff0c", "\u5230\u70b9\u4e5f\u4f1a\u997f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5e73\u548c\u5b89\u7a33\uff0c\u4e0d\u4e3a\u5916\u7269\u6240\u6270\u3002\u5047\u4ee5\u65f6\u65e5\u6c14\u8fd0\u81ea\u65fa\u3002", "line": "\u8fd0\u52bf\uff1a\u5e73\u548c\u5b89\u7a33\uff0c\u4e0d\u4e3a\u5916\u7269\u6240\u6270\u3002\u5047\u4ee5\u65f6\u65e5\u6c14\u8fd0\u81ea\u65fa\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u7b80\u5355\u5de5\u4f5c\u4e3a\u5409\u3002\u4e8b\u52a1\u8fc7\u591a\u5219\u96be\u4ee5\u5e94\u4ed8\u3002", "line": "\u5de5\u4f5c\uff1a\u7b80\u5355\u5de5\u4f5c\u4e3a\u5409\u3002\u4e8b\u52a1\u8fc7\u591a\u5219\u96be\u4ee5\u5e94\u4ed8\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9700\u76ee\u5149\u957f\u8fdc\u3002", "line": "\u4ea4\u6613\uff1a\u9700\u76ee\u5149\u957f\u8fdc\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u987a\u5229\u901a\u8fc7\u5347\u5b66\u8003\u8bd5\u3002\u53e4\u5178\u6587\u5b66\u3001\u548c\u6b4c\u3001\u54f2\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u987a\u5229\u901a\u8fc7\u5347\u5b66\u8003\u8bd5\u3002\u53e4\u5178\u6587\u5b66\u3001\u548c\u6b4c\u3001\u54f2\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4eba\u751f\u4e3a\u65c5\u3002", "line": "\u51fa\u884c\uff1a\u4eba\u751f\u4e3a\u65c5\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5bfb\u5f97\u751f\u6b7b\u4e0e\u5171\u7684\u4f34\u4fa3\u3002", "line": "\u59fb\u7f18\uff1a\u5bfb\u5f97\u751f\u6b7b\u4e0e\u5171\u7684\u4f34\u4fa3\u3002"}, {"label": "\u5065\u5eb7", "text": "\u867d\u7ec8\u6709\u4e00\u6b7b\uff0c\u4f46\u53ef\u5f97\u5584\u7ec8\u3002\u865a\u5ea6\u5149\u9634\u5219\u5fc5\u7559\u9057\u61be\u3002", "line": "\u5065\u5eb7\uff1a\u867d\u7ec8\u6709\u4e00\u6b7b\uff0c\u4f46\u53ef\u5f97\u5584\u7ec8\u3002\u865a\u5ea6\u5149\u9634\u5219\u5fc5\u7559\u9057\u61be\u3002"}, {"label": "\u7231\u597d", "text": "\u4e09\u5206\u949f\u70ed\u5ea6\uff0c\u4f46\u4e0d\u59a8\u591a\u52a0\u5c1d\u8bd5\u3002\u53ef\u9632\u5fc3\u667a\u8870\u9000\u3002", "line": "\u7231\u597d\uff1a\u4e09\u5206\u949f\u70ed\u5ea6\uff0c\u4f46\u4e0d\u59a8\u591a\u52a0\u5c1d\u8bd5\u3002\u53ef\u9632\u5fc3\u667a\u8870\u9000\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (19, '八云蓝', '吉', '被当作式神使唤的九尾狐', '使役式神程度的能力', '["\u52a8\u7269\u7684\u884c\u4e3a\uff0c", "\u7b97\u6cd5\u5f88\u7b80\u5355\u3002", "\u4eba\u7c7b\u81ea\u7136\u4e5f", "\u5e76\u4e0d\u662f\u4f8b\u5916\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4f1a\u5377\u5165\u5927\u9ebb\u70e6\uff0c\u4f46\u53ef\u51ed\u51b7\u9759\u5316\u9669\u4e3a\u5937\u3002", "line": "\u8fd0\u52bf\uff1a\u4f1a\u5377\u5165\u5927\u9ebb\u70e6\uff0c\u4f46\u53ef\u51ed\u51b7\u9759\u5316\u9669\u4e3a\u5937\u3002"}, {"label": "\u4ea4\u6613", "text": "\u670d\u52a1\u4e1a\u751f\u610f\u5174\u9686\u3002", "line": "\u4ea4\u6613\uff1a\u670d\u52a1\u4e1a\u751f\u610f\u5174\u9686\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5de5\u7a0b\u5e08\u4e3a\u5409\u3002\u4e2d\u5c42\u7ba1\u7406\u4e3a\u51f6\u3002", "line": "\u5de5\u4f5c\uff1a\u5de5\u7a0b\u5e08\u4e3a\u5409\u3002\u4e2d\u5c42\u7ba1\u7406\u4e3a\u51f6\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6570\u5b66\u3001\u4fe1\u606f\u5904\u7406\u4e3a\u5409\u3002\u4f46\u6613\u56e0\u8fc7\u5ea6\u8ffd\u6c42\u6548\u7387\u800c\u61c8\u6020\u52aa\u529b\u3002", "line": "\u5b66\u4e1a\uff1a\u6570\u5b66\u3001\u4fe1\u606f\u5904\u7406\u4e3a\u5409\u3002\u4f46\u6613\u56e0\u8fc7\u5ea6\u8ffd\u6c42\u6548\u7387\u800c\u61c8\u6020\u52aa\u529b\u3002"}], [{"label": "\u51fa\u884c", "text": "\u907f\u5f00\u6c34\u8fb9\uff0c\u6c34\u4f1a\u6781\u5927\u589e\u52a0\u8ba1\u7b97\u91cf\u3002", "line": "\u51fa\u884c\uff1a\u907f\u5f00\u6c34\u8fb9\uff0c\u6c34\u4f1a\u6781\u5927\u589e\u52a0\u8ba1\u7b97\u91cf\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4fdd\u6301\u51b7\u9759\u5219\u8eab\u5fc3\u5eb7\u6cf0\u3002\u53ef\u5f97\u957f\u5bff\u3002", "line": "\u5065\u5eb7\uff1a\u4fdd\u6301\u51b7\u9759\u5219\u8eab\u5fc3\u5eb7\u6cf0\u3002\u53ef\u5f97\u957f\u5bff\u3002"}, {"label": "\u604b\u7231", "text": "\u5b9c\u5236\u5b9a\u5468\u5bc6\u8ba1\u5212\u3002", "line": "\u604b\u7231\uff1a\u5b9c\u5236\u5b9a\u5468\u5bc6\u8ba1\u5212\u3002"}, {"label": "\u4eba\u7f18", "text": "\u6613\u906d\u4eba\u758f\u8fdc\u3002\u51b7\u9759\u53cd\u6210\u963b\u788d\u3002", "line": "\u4eba\u7f18\uff1a\u6613\u906d\u4eba\u758f\u8fdc\u3002\u51b7\u9759\u53cd\u6210\u963b\u788d\u3002"}, {"label": "\u7231\u597d", "text": "\u5c24\u64c5\u6e38\u620f\u3002\u5355\u4eba\u6e38\u620f\u4e3a\u5409\u3002\u5f39\u5e55\u5c04\u51fb\u6e38\u620f\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u5c24\u64c5\u6e38\u620f\u3002\u5355\u4eba\u6e38\u620f\u4e3a\u5409\u3002\u5f39\u5e55\u5c04\u51fb\u6e38\u620f\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (20, '八云紫', '吉凶分界线', '潜伏于一切间隙中的妖怪', '操纵界线程度的能力', '["\u662f\u4ece\u4f55\u65f6\u8d77", "\u4f60\u4e0d\u518d\u76f8\u4fe1", "\u5fa1\u795e\u7b7e\u4e86\u5462\uff1f", "\u771f\u662f\u53ef\u601c\u5440\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5e78\u8fd0\u4e0e\u5384\u8fd0\u9519\u7efc\u4ea4\u7ec7\u3002\u8fd0\u52bf\u52a8\u8361\u96be\u5b89\u3002", "line": "\u8fd0\u52bf\uff1a\u5e78\u8fd0\u4e0e\u5384\u8fd0\u9519\u7efc\u4ea4\u7ec7\u3002\u8fd0\u52bf\u52a8\u8361\u96be\u5b89\u3002"}, {"label": "\u4ea4\u6613", "text": "\u82e5\u80fd\u7784\u51c6\u5c0f\u4f17\u9700\u6c42\u5373\u53ef\u6210\u529f\u3002", "line": "\u4ea4\u6613\uff1a\u82e5\u80fd\u7784\u51c6\u5c0f\u4f17\u9700\u6c42\u5373\u53ef\u6210\u529f\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u56e0\u8fdd\u89c4\u800c\u5931\u8d25\u3002", "line": "\u5de5\u4f5c\uff1a\u56e0\u8fdd\u89c4\u800c\u5931\u8d25\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8003\u8bd5\u8f7b\u677e\u8fc7\u5173\u3002\u4f46\u77e5\u8bc6\u4f1a\u5982\u6c34\u8fc7\u9e2d\u80cc\uff0c\u5c3d\u6570\u9057\u5fd8\u3002", "line": "\u5b66\u4e1a\uff1a\u8003\u8bd5\u8f7b\u677e\u8fc7\u5173\u3002\u4f46\u77e5\u8bc6\u4f1a\u5982\u6c34\u8fc7\u9e2d\u80cc\uff0c\u5c3d\u6570\u9057\u5fd8\u3002"}], [{"label": "\u51fa\u884c", "text": "\u8fb9\u5883\u8857\u5df7\u4e3a\u5409\u3002\u524d\u5f80\u5f02\u4e16\u754c\u5219\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u8fb9\u5883\u8857\u5df7\u4e3a\u5409\u3002\u524d\u5f80\u5f02\u4e16\u754c\u5219\u5927\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u957f\u547d\u767e\u5c81\uff0c\u82cd\u5929\u65e0\u773c\u3002", "line": "\u5065\u5eb7\uff1a\u957f\u547d\u767e\u5c81\uff0c\u82cd\u5929\u65e0\u773c\u3002"}, {"label": "\u4e89\u7aef", "text": "\u6210\u4e3a\u8c03\u89e3\u8005\u3002", "line": "\u4e89\u7aef\uff1a\u6210\u4e3a\u8c03\u89e3\u8005\u3002"}, {"label": "\u604b\u7231", "text": "\u604b\u4eba\u4e0e\u670b\u53cb\u7684\u754c\u7ebf\u66a7\u6627\u4e0d\u6e05\u3002", "line": "\u604b\u7231\uff1a\u604b\u4eba\u4e0e\u670b\u53cb\u7684\u754c\u7ebf\u66a7\u6627\u4e0d\u6e05\u3002"}, {"label": "\u7231\u597d", "text": "\u4f1a\u6c89\u6d78\u4e8e\u7f51\u7edc\u6e38\u620f\u7684\u4e16\u754c\u4e2d\u3002", "line": "\u7231\u597d\uff1a\u4f1a\u6c89\u6d78\u4e8e\u7f51\u7edc\u6e38\u620f\u7684\u4e16\u754c\u4e2d\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (21, '伊吹萃香', '凶', '溺于无限美酒之鬼', '操纵密与疏程度的能力', '["\u773c\u524d\u7684\u4e16\u754c", "\u770b\u4f3c\u5f88\u590d\u6742\uff0c", "\u5185\u91cc\u5176\u5b9e\u5374", "\u7a00\u758f\u5f97\u591a\u5462\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4efb\u6027\u5984\u4e3a\u6613\u62db\u4eba\u5acc\uff0c\u987b\u8b66\u60d5\u81ea\u8eab\u66b4\u529b\u884c\u4e3a\u3002", "line": "\u8fd0\u52bf\uff1a\u4efb\u6027\u5984\u4e3a\u6613\u62db\u4eba\u5acc\uff0c\u987b\u8b66\u60d5\u81ea\u8eab\u66b4\u529b\u884c\u4e3a\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u996e\u9152\u8fc7\u91cf\uff0c\u4f46\u96be\u514d\u8d2a\u676f\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u996e\u9152\u8fc7\u91cf\uff0c\u4f46\u96be\u514d\u8d2a\u676f\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u7c97\u679d\u5927\u53f6\u62db\u81f4\u5931\u8d25\u3002\u9152\u6c34\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u7c97\u679d\u5927\u53f6\u62db\u81f4\u5931\u8d25\u3002\u9152\u6c34\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u53ef\u51ed\u86ee\u529b\u653b\u514b\u3002\u91cf\u5b50\u529b\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u53ef\u51ed\u86ee\u529b\u653b\u514b\u3002\u91cf\u5b50\u529b\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5b9c\u6ce1\u6e29\u6cc9\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u6ce1\u6e29\u6cc9\u3002"}, {"label": "\u4f4f\u6240", "text": "\u6613\u635f\u6bc1\u3002\u987b\u4fee\u8865\u3002\u82e5\u8eab\u5904\u7262\u72f1\u5219\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u6613\u635f\u6bc1\u3002\u987b\u4fee\u8865\u3002\u82e5\u8eab\u5904\u7262\u72f1\u5219\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u805a\u6563\u79bb\u5408\u7686\u968f\u5df1\u610f\u3002", "line": "\u4eba\u7f18\uff1a\u805a\u6563\u79bb\u5408\u7686\u968f\u5df1\u610f\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u8d22\u6e90\u5e7f\u8fdb\uff0c\u7136\u591a\u4e3a\u4e0d\u4e49\u4e4b\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u8d22\u6e90\u5e7f\u8fdb\uff0c\u7136\u591a\u4e3a\u4e0d\u4e49\u4e4b\u8d22\u3002"}, {"label": "\u59fb\u7f18", "text": "\u56e0\u9152\u8bef\u4e8b\u3002", "line": "\u59fb\u7f18\uff1a\u56e0\u9152\u8bef\u4e8b\u3002"}, {"label": "\u7231\u597d", "text": "\u5404\u7c7b\u6bd4\u8bd5\u7686\u4e3a\u4e50\u4e8b\u3002\u5b9c\u591a\u52a0\u5c1d\u8bd5\u3002", "line": "\u7231\u597d\uff1a\u5404\u7c7b\u6bd4\u8bd5\u7686\u4e3a\u4e50\u4e8b\u3002\u5b9c\u591a\u52a0\u5c1d\u8bd5\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (22, '莉格露·奈特巴格', '末吉', '无端被嫌恶者', '操纵虫子程度的能力', '["\u5bf8\u8eab\u4e4b\u866b\u554a\uff0c", "\u552f\u4f59\u4e94\u5206\u9b42", "1", "\u3002", "\u4f60\u4eec\u7684\u6050\u6016\uff0c", "\u4e16\u4eba\u6765\u89c1\u8bc1\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u773c\u4e0b\u56f0\u987f\u4f46\u7ec8\u5f97\u8f6c\u673a\u3002\n\u7eb5\u4f7f\u5982\u4eca\u906d\u53d7\u5e9e\u7136\u5927\u7269\u538c\u6068\uff0c\u4e16\u95f4\u7ec8\u662f\u866b\u5b50\u7684\u5929\u4e0b\u3002", "line": "\u8fd0\u52bf\uff1a\u773c\u4e0b\u56f0\u987f\u4f46\u7ec8\u5f97\u8f6c\u673a\u3002\n\u7eb5\u4f7f\u5982\u4eca\u906d\u53d7\u5e9e\u7136\u5927\u7269\u538c\u6068\uff0c\u4e16\u95f4\u7ec8\u662f\u866b\u5b50\u7684\u5929\u4e0b\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8fd0\u52bf\u4e0a\u4f73\u3002", "line": "\u4ea4\u6613\uff1a\u8fd0\u52bf\u4e0a\u4f73\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u91d1\u9f9f\u5b50\u76f8\u52a9\u3002", "line": "\u8d22\u8fd0\uff1a\u91d1\u9f9f\u5b50\u76f8\u52a9\u3002"}, {"label": "\u75be\u75c5", "text": "\u614e\u9632\u6059\u866b\u75c5\u3002", "line": "\u75be\u75c5\uff1a\u614e\u9632\u6059\u866b\u75c5\u3002"}], [{"label": "\u5bb6\u5b85", "text": "\u6728\u5236\u623f\u5c4b\u6050\u906d\u86c0\u8680\u3002", "line": "\u5bb6\u5b85\uff1a\u6728\u5236\u623f\u5c4b\u6050\u906d\u86c0\u8680\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u56ca\u8424\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u56ca\u8424\u4e3a\u5409\u3002"}, {"label": "\u519c\u4e8b", "text": "\u6b49\u6536\u3002\u82e5\u6709\u8757\u707e\u5219\u65ad\u5ff5\u4e3a\u5999\u3002", "line": "\u519c\u4e8b\uff1a\u6b49\u6536\u3002\u82e5\u6709\u8757\u707e\u5219\u65ad\u5ff5\u4e3a\u5999\u3002"}, {"label": "\u866b\u7f18", "text": "\u5907\u53d7\u559c\u7231\u3002\u6b23\u7136\u63a5\u53d7\u5427\u3002", "line": "\u866b\u7f18\uff1a\u5907\u53d7\u559c\u7231\u3002\u6b23\u7136\u63a5\u53d7\u5427\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (23, '米斯蒂娅·萝蕾拉', '小小凶', '歌喉婉转的夜雀', '用歌声诱人发狂程度的能力', '["\u7231\u4f7f\u4eba\u76f2\u76ee\uff0c", "\u4f46\u8bdd\u8bf4\u56de\u6765\uff0c", "\u773c\u4e0b\u7684\u72b6\u51b5", "\u663e\u7136\u4e0d\u4e00\u6837\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u867d\u65e0\u660e\u663e\u6ce2\u52a8\uff0c\u4f46\u4f1a\u906d\u9047\u4e9b\u8bb8\u4e0d\u987a\u3002", "line": "\u8fd0\u52bf\uff1a\u867d\u65e0\u660e\u663e\u6ce2\u52a8\uff0c\u4f46\u4f1a\u906d\u9047\u4e9b\u8bb8\u4e0d\u987a\u3002"}, {"label": "\u75be\u75c5", "text": "\u5f53\u5fc3\u773c\u75be\uff0c\u52a1\u5fc5\u4fdd\u8bc1\u8425\u517b\u3002\n\u98df\u7528\u516b\u76ee\u9cd7\u4e3a\u5409\u3002", "line": "\u75be\u75c5\uff1a\u5f53\u5fc3\u773c\u75be\uff0c\u52a1\u5fc5\u4fdd\u8bc1\u8425\u517b\u3002\n\u98df\u7528\u516b\u76ee\u9cd7\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u7ecf\u8425\u81f3\u6df1\u591c\u5219\u8fd0\u52bf\u4e0a\u4f73\u3002", "line": "\u4ea4\u6613\uff1a\u7ecf\u8425\u81f3\u6df1\u591c\u5219\u8fd0\u52bf\u4e0a\u4f73\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u62fc\u640f\u81f3\u6df1\u591c\u5427\u3002", "line": "\u5b66\u4e1a\uff1a\u62fc\u640f\u81f3\u6df1\u591c\u5427\u3002"}, {"label": "\u519c\u4e8b", "text": "\u906d\u9047\u9e1f\u5bb3\u3002", "line": "\u519c\u4e8b\uff1a\u906d\u9047\u9e1f\u5bb3\u3002"}], [{"label": "\u604b\u7231", "text": "\u9082\u9005\u4e00\u573a\u76f2\u76ee\u7684\u604b\u60c5\u3002", "line": "\u604b\u7231\uff1a\u9082\u9005\u4e00\u573a\u76f2\u76ee\u7684\u604b\u60c5\u3002"}, {"label": "\u51fa\u884c", "text": "\u4e0d\u51fa\u4eba\u7c7b\u6751\u843d\u4e3a\u5999\u3002\u591c\u95f4\u5c24\u5f53\u6df1\u5c45\u7b80\u51fa\u3002", "line": "\u51fa\u884c\uff1a\u4e0d\u51fa\u4eba\u7c7b\u6751\u843d\u4e3a\u5999\u3002\u591c\u95f4\u5c24\u5f53\u6df1\u5c45\u7b80\u51fa\u3002"}, {"label": "\u6b4c\u8fd0", "text": "\u6b63\u503c\u5dc5\u5cf0\uff0c\u6b64\u523b\u4e0d\u5531\u66f4\u5f85\u4f55\u65f6\u3002\u4f46\u9700\u7559\u610f\u97f3\u91cf\uff0c\u52ff\u6270\u8fd1\u90bb\u3002", "line": "\u6b4c\u8fd0\uff1a\u6b63\u503c\u5dc5\u5cf0\uff0c\u6b64\u523b\u4e0d\u5531\u66f4\u5f85\u4f55\u65f6\u3002\u4f46\u9700\u7559\u610f\u97f3\u91cf\uff0c\u52ff\u6270\u8fd1\u90bb\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (24, '上白泽慧音', '大吉', '半为师长、半为妖兽', '隐匿历史程度的能力', '["\u8001\u5e08\u771f\u53ef\u9760\uff0c", "\u535a\u5b66\u53c8\u6e29\u67d4\u3002", "\u53ef\u6bcf\u5f53\u5230\u4e86", "\u6ee1\u6708\u7684\u591c\u665a\u2026"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6240\u5b66\u7686\u80fd\u878d\u4f1a\u8d2f\u901a\uff0c\u6b64\u7b49\u826f\u673a\u5207\u83ab\u9519\u5931\u3002", "line": "\u8fd0\u52bf\uff1a\u6240\u5b66\u7686\u80fd\u878d\u4f1a\u8d2f\u901a\uff0c\u6b64\u7b49\u826f\u673a\u5207\u83ab\u9519\u5931\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8fd0\u52bf\u5dc5\u5cf0\u3002\u5b9c\u7814\u4e60\u5fc3\u4eea\u79d1\u76ee\u3002\u552f\u6709\u5386\u53f2\u6613\u56e0\u9020\u8be3\u8fc7\u6df1\uff0c\u53cd\u800c\u8003\u573a\u5931\u5229\u3002", "line": "\u5b66\u4e1a\uff1a\u8fd0\u52bf\u5dc5\u5cf0\u3002\u5b9c\u7814\u4e60\u5fc3\u4eea\u79d1\u76ee\u3002\u552f\u6709\u5386\u53f2\u6613\u56e0\u9020\u8be3\u8fc7\u6df1\uff0c\u53cd\u800c\u8003\u573a\u5931\u5229\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6295\u8eab\u6559\u80b2\u4ea7\u4e1a\u53ef\u83b7\u6210\u529f\u3002", "line": "\u4ea4\u6613\uff1a\u6295\u8eab\u6559\u80b2\u4ea7\u4e1a\u53ef\u83b7\u6210\u529f\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u614e\u9632\u7761\u7720\u4e0d\u8db3\uff0c\u5207\u83ab\u591c\u95f4\u51fa\u884c\u3002", "line": "\u5065\u5eb7\uff1a\u614e\u9632\u7761\u7720\u4e0d\u8db3\uff0c\u5207\u83ab\u591c\u95f4\u51fa\u884c\u3002"}, {"label": "\u51fa\u884c", "text": "\u63a2\u8bbf\u53e4\u8ff9\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u63a2\u8bbf\u53e4\u8ff9\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5207\u52ff\u803d\u6eba\u60c5\u7f51\u3002", "line": "\u604b\u7231\uff1a\u5207\u52ff\u803d\u6eba\u60c5\u7f51\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5e7f\u53d7\u656c\u6155\uff0c\u5fc5\u6210\u52a9\u76ca\u3002", "line": "\u4eba\u7f18\uff1a\u5e7f\u53d7\u656c\u6155\uff0c\u5fc5\u6210\u52a9\u76ca\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6295\u8d44\u826f\u673a\u3002\u8840\u672c\u65e0\u5f52\u4ea6\u83ab\u6094\u3002", "line": "\u8d22\u8fd0\uff1a\u6295\u8d44\u826f\u673a\u3002\u8840\u672c\u65e0\u5f52\u4ea6\u83ab\u6094\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (25, '因幡天为', '【大大吉】', '幸运的白兔', '使人类变得幸运程度的能力', '["\u81ea\u4ece\u592a\u53e4\u65f6", "\u906d\u8fc7\u90a3\u756a\u7f6a\uff0c", "\u6211\u4fbf\u518d\u4e0d\u6562", "\u591a\u5634\u591a\u820c\u4e86\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5373\u4f7f\u5b88\u682a\u5f85\u5154\uff0c\u5e78\u8fd0\u4ea6\u4f1a\u4ece\u5929\u800c\u964d\u3002\u542c\u5929\u7531\u547d\u5c1a\u4e43\u5927\u5409\u3002", "line": "\u8fd0\u52bf\uff1a\u5373\u4f7f\u5b88\u682a\u5f85\u5154\uff0c\u5e78\u8fd0\u4ea6\u4f1a\u4ece\u5929\u800c\u964d\u3002\u542c\u5929\u7531\u547d\u5c1a\u4e43\u5927\u5409\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e09\u5341\u516d\u884c\u7686\u53ef\u83b7\u5229\u3002\u7136\u5e78\u8fd0\u7ec8\u6709\u5c3d\u65f6\uff0c\u6295\u8d44\u4ecd\u9700\u8c28\u614e\u3002", "line": "\u8d22\u8fd0\uff1a\u4e09\u5341\u516d\u884c\u7686\u53ef\u83b7\u5229\u3002\u7136\u5e78\u8fd0\u7ec8\u6709\u5c3d\u65f6\uff0c\u6295\u8d44\u4ecd\u9700\u8c28\u614e\u3002"}, {"label": "\u4ea4\u6613", "text": "\u751f\u610f\u5174\u9686\u3002\u5207\u52ff\u6d89\u8db3\u9ed1\u8272\u4ea7\u4e1a\u3002", "line": "\u4ea4\u6613\uff1a\u751f\u610f\u5174\u9686\u3002\u5207\u52ff\u6d89\u8db3\u9ed1\u8272\u4ea7\u4e1a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u62bc\u9898\u767e\u53d1\u767e\u4e2d\u3002", "line": "\u5b66\u4e1a\uff1a\u62bc\u9898\u767e\u53d1\u767e\u4e2d\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u826f\u597d\u3002\u5f53\u5fc3\u76ae\u80a4\u75c5\u4e0e\u5916\u4f24\u3002", "line": "\u5065\u5eb7\uff1a\u826f\u597d\u3002\u5f53\u5fc3\u76ae\u80a4\u75c5\u4e0e\u5916\u4f24\u3002"}, {"label": "\u51fa\u884c", "text": "\u4f1a\u88ab\u9ca8\u9c7c\u566c\u54ac\uff0c\u5b9c\u907f\u5f00\u6d77\u57df\u3002", "line": "\u51fa\u884c\uff1a\u4f1a\u88ab\u9ca8\u9c7c\u566c\u54ac\uff0c\u5b9c\u907f\u5f00\u6d77\u57df\u3002"}, {"label": "\u604b\u7231", "text": "\u8bf8\u4e8b\u987a\u9042\u3002", "line": "\u604b\u7231\uff1a\u8bf8\u4e8b\u987a\u9042\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5bfb\u56de\u5927\u91cf\u5931\u7269\u3002", "line": "\u5bfb\u7269\uff1a\u5bfb\u56de\u5927\u91cf\u5931\u7269\u3002"}, {"label": "\u4eba\u7f18", "text": "\u53ea\u8981\u4fdd\u6301\u5e78\u8fd0\uff0c\u81ea\u6709\u4eb2\u670b\u76f8\u968f\u3002", "line": "\u4eba\u7f18\uff1a\u53ea\u8981\u4fdd\u6301\u5e78\u8fd0\uff0c\u81ea\u6709\u4eb2\u670b\u76f8\u968f\u3002"}, {"label": "\u7269\u4ef6", "text": "\u5b9c\u643a\u5e26\u5154\u8db3\u3002", "line": "\u7269\u4ef6\uff1a\u5b9c\u643a\u5e26\u5154\u8db3\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (26, '铃仙·优昙华院·因幡', '凶', '拥有疯狂赤眼的玉兔', '操纵疯狂程度的能力', '["\u53ef\u89c1\u5149\u53ea\u662f", "\u7535\u78c1\u6ce2\u9891\u8c31", "\u7684\u51b0\u5c71\u4e00\u89d2\u3002", "\u4f60\u4eec\u7684\u773c\u775b\uff0c", "\u5168\u90fd\u662f\u6446\u8bbe\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u76ee\u7779\u4e0d\u5e94\u77e5\u6653\u4e4b\u4e8b\uff0c\u56e0\u800c\u5377\u5165\u707e\u7978\u3002", "line": "\u8fd0\u52bf\uff1a\u76ee\u7779\u4e0d\u5e94\u77e5\u6653\u4e4b\u4e8b\uff0c\u56e0\u800c\u5377\u5165\u707e\u7978\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5c24\u987b\u6ce8\u610f\u7cbe\u795e\u72b6\u51b5\u3002\u6613\u9677\u5165\u766b\u72c2\u3002", "line": "\u5065\u5eb7\uff1a\u5c24\u987b\u6ce8\u610f\u7cbe\u795e\u72b6\u51b5\u3002\u6613\u9677\u5165\u766b\u72c2\u3002"}, {"label": "\u4e89\u7aef", "text": "\u7eb7\u4e89\u4e0d\u6b62\u3002\u88ab\u5377\u5165\u65e0\u8c13\u7ea0\u845b\u3002", "line": "\u4e89\u7aef\uff1a\u7eb7\u4e89\u4e0d\u6b62\u3002\u88ab\u5377\u5165\u65e0\u8c13\u7ea0\u845b\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7269\u7406\u4e0e\u7f8e\u672f\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u7269\u7406\u4e0e\u7f8e\u672f\u4e3a\u5409\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u56e0\u7740\u773c\u70b9\u4e0e\u5927\u4f17\u4e0d\u540c\u800c\u9500\u8def\u4e0d\u7545\uff0c\u4f46\u4f1a\u53d7\u5230\u7279\u5b9a\u5ba2\u7fa4\u9752\u7750\u3002", "line": "\u4ea4\u6613\uff1a\u56e0\u7740\u773c\u70b9\u4e0e\u5927\u4f17\u4e0d\u540c\u800c\u9500\u8def\u4e0d\u7545\uff0c\u4f46\u4f1a\u53d7\u5230\u7279\u5b9a\u5ba2\u7fa4\u9752\u7750\u3002"}, {"label": "\u664b\u5347", "text": "\u5e0c\u671b\u6e3a\u832b\u3002", "line": "\u664b\u5347\uff1a\u5e0c\u671b\u6e3a\u832b\u3002"}, {"label": "\u604b\u7231", "text": "\u603b\u80fd\u770b\u7834\u5bf9\u65b9\u7f3a\u70b9\uff0c\u96be\u6210\u826f\u7f18\u3002", "line": "\u604b\u7231\uff1a\u603b\u80fd\u770b\u7834\u5bf9\u65b9\u7f3a\u70b9\uff0c\u96be\u6210\u826f\u7f18\u3002"}, {"label": "\u51fa\u884c", "text": "\u907f\u5f00\u6ee1\u6708\u4e4b\u65e5\u3002", "line": "\u51fa\u884c\uff1a\u907f\u5f00\u6ee1\u6708\u4e4b\u65e5\u3002"}, {"label": "\u7231\u597d", "text": "\u7535\u6ce2\u76f8\u5173\u7231\u597d\u4e3a\u5409\uff0c\u5982\u4e1a\u4f59\u65e0\u7ebf\u7535\u6216\u77ff\u77f3\u6536\u97f3\u673a\u7b49\u3002", "line": "\u7231\u597d\uff1a\u7535\u6ce2\u76f8\u5173\u7231\u597d\u4e3a\u5409\uff0c\u5982\u4e1a\u4f59\u65e0\u7ebf\u7535\u6216\u77ff\u77f3\u6536\u97f3\u673a\u7b49\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (27, '八意永琳', '吉', '身怀月之睿智的月之民', '制作任何药物程度的能力', '["\u65b0\u6708\u5347\u8d77\u65f6", "\u4f55\u5904\u662f\u6708\u90fd\uff0c", "\u5c31\u8fde\u8fd9\u60a8\u90fd", "\u4e00\u65e0\u6240\u77e5\u5462\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4ee5\u667a\u8c0b\u5316\u89e3\u96be\u9898\u3002\u6613\u62db\u60f9\u5f3a\u654c\u3002", "line": "\u8fd0\u52bf\uff1a\u4ee5\u667a\u8c0b\u5316\u89e3\u96be\u9898\u3002\u6613\u62db\u60f9\u5f3a\u654c\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u533b\u5e08\u3001\u836f\u5242\u5e08\u6216\u5236\u836f\u516c\u53f8\u804c\u5458\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u533b\u5e08\u3001\u836f\u5242\u5e08\u6216\u5236\u836f\u516c\u53f8\u804c\u5458\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u82e5\u67d3\u6307\u8fdd\u7981\u836f\u7269\uff0c\u6050\u906d\u7262\u72f1\u4e4b\u707e\u3002", "line": "\u4ea4\u6613\uff1a\u82e5\u67d3\u6307\u8fdd\u7981\u836f\u7269\uff0c\u6050\u906d\u7262\u72f1\u4e4b\u707e\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u767e\u822c\u5b66\u95ee\u81ea\u53d1\u589e\u957f\uff0c\u533b\u5b66\u3001\u836f\u5b66\u4e3a\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u767e\u822c\u5b66\u95ee\u81ea\u53d1\u589e\u957f\uff0c\u533b\u5b66\u3001\u836f\u5b66\u4e3a\u5927\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u6108\u662f\u4f9d\u8d56\u836f\u7269\u5219\u6108\u53d1\u6076\u5316\u3002\u7528\u836f\u52a1\u5fc5\u9075\u5faa\u533b\u5631\u3002", "line": "\u5065\u5eb7\uff1a\u6108\u662f\u4f9d\u8d56\u836f\u7269\u5219\u6108\u53d1\u6076\u5316\u3002\u7528\u836f\u52a1\u5fc5\u9075\u5faa\u533b\u5631\u3002"}, {"label": "\u51fa\u884c", "text": "\u4e0d\u5b9c\u8fc7\u5206\u8fdc\u884c\u3002", "line": "\u51fa\u884c\uff1a\u4e0d\u5b9c\u8fc7\u5206\u8fdc\u884c\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5b9c\u90bb\u8fd1\u7af9\u6797\u3002", "line": "\u4f4f\u6240\uff1a\u5b9c\u90bb\u8fd1\u7af9\u6797\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u5e38\u6000\u4f53\u8c05\u4e4b\u5fc3\u3002", "line": "\u604b\u7231\uff1a\u5f53\u5e38\u6000\u4f53\u8c05\u4e4b\u5fc3\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4ea4\u9645\u5e7f\u6cdb\uff0c\u4f46\u6df1\u4ea4\u53cd\u6613\u751f\u4e8b\u7aef\u3002", "line": "\u4eba\u7f18\uff1a\u4ea4\u9645\u5e7f\u6cdb\uff0c\u4f46\u6df1\u4ea4\u53cd\u6613\u751f\u4e8b\u7aef\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (28, '蓬莱山辉夜', '末大凶', '被囚于地上的蓬莱人', '操纵永远和须臾程度的能力', '["\u8fd9\u79cd\u4e8b\u660e\u5929", "\u518d\u505a\u5c31\u884c\u5566\u3002", "\u53cd\u6b63\u6211\u62e5\u6709", "\u65e0\u9650\u7684\u65f6\u95f4\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6020\u60f0\u6210\u6027\uff0c\u4e07\u4e8b\u62d6\u5ef6\u3002\u8fd0\u52bf\u6301\u7eed\u8d70\u4f4e\u3002", "line": "\u8fd0\u52bf\uff1a\u6020\u60f0\u6210\u6027\uff0c\u4e07\u4e8b\u62d6\u5ef6\u3002\u8fd0\u52bf\u6301\u7eed\u8d70\u4f4e\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6beb\u65e0\u5546\u624d\u3002", "line": "\u4ea4\u6613\uff1a\u6beb\u65e0\u5546\u624d\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u6613\u751f\u61c8\u6020\uff0c\u5c45\u5bb6\u529e\u516c\u5219\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u6613\u751f\u61c8\u6020\uff0c\u5c45\u5bb6\u529e\u516c\u5219\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5e38\u53d7\u5e72\u6270\uff0c\u82e5\u5f97\u4f18\u79c0\u5bb6\u6559\u6307\u5bfc\u5219\u53ef\u8715\u53d8\u3002", "line": "\u5b66\u4e1a\uff1a\u5e38\u53d7\u5e72\u6270\uff0c\u82e5\u5f97\u4f18\u79c0\u5bb6\u6559\u6307\u5bfc\u5219\u53ef\u8715\u53d8\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u826f\u597d\u3002\u4f46\u6613\u8fd0\u52a8\u4e0d\u8db3\u3002", "line": "\u5065\u5eb7\uff1a\u826f\u597d\u3002\u4f46\u6613\u8fd0\u52a8\u4e0d\u8db3\u3002"}, {"label": "\u51fa\u884c", "text": "\u5acc\u9ebb\u70e6\u3002", "line": "\u51fa\u884c\uff1a\u5acc\u9ebb\u70e6\u3002"}, {"label": "\u5bfb\u7269", "text": "\u6ca1\u6253\u7b97\u627e\u3002", "line": "\u5bfb\u7269\uff1a\u6ca1\u6253\u7b97\u627e\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4ef0\u8d56\u4ed6\u4eba\u63a5\u6d4e\uff0c\u751f\u6d3b\u65e0\u5fe7\u3002", "line": "\u8d22\u8fd0\uff1a\u4ef0\u8d56\u4ed6\u4eba\u63a5\u6d4e\uff0c\u751f\u6d3b\u65e0\u5fe7\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5411\u5bf9\u65b9\u8bfe\u4ee5\u96be\u9898\uff0c\u4ea6\u4f1a\u88ab\u56de\u656c\u96be\u9898\u3002\u7ec8\u5f52\u662f\u56f0\u96be\u91cd\u91cd\u3002", "line": "\u59fb\u7f18\uff1a\u5411\u5bf9\u65b9\u8bfe\u4ee5\u96be\u9898\uff0c\u4ea6\u4f1a\u88ab\u56de\u656c\u96be\u9898\u3002\u7ec8\u5f52\u662f\u56f0\u96be\u91cd\u91cd\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (29, '上白泽慧音
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (30, '藤原妹红', '末吉', '永远孤独的不死者', '不老不死程度的能力', '["\u5fcd\u8010\u518d\u5fcd\u8010\uff0c", "\u54ac\u7259\u6491\u4e0b\u53bb\uff0c", "\u66f4\u597d\u7684\u65e5\u5b50", "\u7ec8\u5c06\u4f1a\u5230\u6765\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e0\u8bba\u591a\u4e48\u8270\u8f9b\uff0c\u6d3b\u7740\u4fbf\u662f\u5e78\u8fd0\u3002\u6b64\u523b\u6b63\u662f\u5fcd\u8010\u4e4b\u65f6\u3002", "line": "\u8fd0\u52bf\uff1a\u65e0\u8bba\u591a\u4e48\u8270\u8f9b\uff0c\u6d3b\u7740\u4fbf\u662f\u5e78\u8fd0\u3002\u6b64\u523b\u6b63\u662f\u5fcd\u8010\u4e4b\u65f6\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5bff\u6bd4\u5357\u5c71\u3002\u4f46\u987b\u8c28\u614e\u670d\u836f\u3002", "line": "\u5065\u5eb7\uff1a\u5bff\u6bd4\u5357\u5c71\u3002\u4f46\u987b\u8c28\u614e\u670d\u836f\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5bfc\u6e38\u4e1a\u3001\u9505\u7089\u6280\u5e08\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5bfc\u6e38\u4e1a\u3001\u9505\u7089\u6280\u5e08\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6295\u5165\u65f6\u95f4\u94bb\u7814\u5fc5\u6709\u56de\u62a5\u3002", "line": "\u5b66\u4e1a\uff1a\u6295\u5165\u65f6\u95f4\u94bb\u7814\u5fc5\u6709\u56de\u62a5\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5b9c\u767b\u5c71\uff0c\u4f46\u987b\u907f\u5f00\u5bcc\u58eb\u5c71\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u767b\u5c71\uff0c\u4f46\u987b\u907f\u5f00\u5bcc\u58eb\u5c71\u3002"}, {"label": "\u604b\u7231", "text": "\u5982\u70c8\u706b\u822c\u71c3\u5c3d\u6210\u7070\u3002", "line": "\u604b\u7231\uff1a\u5982\u70c8\u706b\u822c\u71c3\u5c3d\u6210\u7070\u3002"}, {"label": "\u4f4f\u6240", "text": "\u4e0d\u5b9c\u957f\u671f\u5b9a\u5c45\u3002", "line": "\u4f4f\u6240\uff1a\u4e0d\u5b9c\u957f\u671f\u5b9a\u5c45\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e0d\u518d\u9700\u8981\u94b1\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u4e0d\u518d\u9700\u8981\u94b1\u8d22\u3002"}, {"label": "\u5fc3\u613f", "text": "\u4e00\u65e6\u5982\u613f\u4fbf\u4f1a\u5931\u53bb\u751f\u5b58\u610f\u4e49\uff0c\u4e0d\u5982\u4fdd\u7559\u672a\u7adf\u4e4b\u5fd7\u3002", "line": "\u5fc3\u613f\uff1a\u4e00\u65e6\u5982\u613f\u4fbf\u4f1a\u5931\u53bb\u751f\u5b58\u610f\u4e49\uff0c\u4e0d\u5982\u4fdd\u7559\u672a\u7adf\u4e4b\u5fd7\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u57f9\u517b\u5355\u8c03\u800c\u8017\u65f6\u7684\u7231\u597d\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u57f9\u517b\u5355\u8c03\u800c\u8017\u65f6\u7684\u7231\u597d\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (31, '梅蒂欣·梅兰可莉', '末凶', '以毒维生的人偶', '操纵毒素程度的能力', '["\u751f\u7269\u90fd\u662f\u7531", "\u6bd2\u7d20\u9a71\u52a8\u7684\uff0c", "\u6d3b\u7740\u7684\u5bb6\u4f19", "\u54ea\u80fd\u5f04\u5f97\u61c2\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8bf8\u4e8b\u6e10\u8d8b\u6076\u5316\uff0c\u65e7\u6bd2\u4ea6\u5c06\u590d\u53d1\u3002", "line": "\u8fd0\u52bf\uff1a\u8bf8\u4e8b\u6e10\u8d8b\u6076\u5316\uff0c\u65e7\u6bd2\u4ea6\u5c06\u590d\u53d1\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4f53\u8d28\u65e5\u6e10\u8870\u9893\uff0c\u5f53\u91cd\u6574\u996e\u98df\u89c4\u5f8b\u3002", "line": "\u5065\u5eb7\uff1a\u4f53\u8d28\u65e5\u6e10\u8870\u9893\uff0c\u5f53\u91cd\u6574\u996e\u98df\u89c4\u5f8b\u3002"}, {"label": "\u75be\u75c5", "text": "\u8c28\u9632\u836f\u7269\u8fc7\u91cf\u3002", "line": "\u75be\u75c5\uff1a\u8c28\u9632\u836f\u7269\u8fc7\u91cf\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4f53\u51b5\u62d6\u7d2f\uff0c\u56db\u5904\u78b0\u58c1\u3002\u59d4\u4efb\u4ed6\u4eba\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u4f53\u51b5\u62d6\u7d2f\uff0c\u56db\u5904\u78b0\u58c1\u3002\u59d4\u4efb\u4ed6\u4eba\u4e3a\u5409\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u5f53\u653e\u5f03\u5f31\u52bf\u79d1\u76ee\uff0c\u4e13\u653b\u5355\u4e00\u9886\u57df\u3002", "line": "\u5b66\u4e1a\uff1a\u5f53\u653e\u5f03\u5f31\u52bf\u79d1\u76ee\uff0c\u4e13\u653b\u5355\u4e00\u9886\u57df\u3002"}, {"label": "\u51fa\u884c", "text": "\u6e29\u6cc9\u7597\u517b\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u6e29\u6cc9\u7597\u517b\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u6709\u610f\u9009\u62e9\u96be\u4ee5\u76f8\u5904\u7684\u5bf9\u8c61\u3002", "line": "\u604b\u7231\uff1a\u5f53\u6709\u610f\u9009\u62e9\u96be\u4ee5\u76f8\u5904\u7684\u5bf9\u8c61\u3002"}, {"label": "\u4eba\u7f18", "text": "\u6cdb\u6cdb\u4e4b\u4ea4\u589e\u591a\u3002", "line": "\u4eba\u7f18\uff1a\u6cdb\u6cdb\u4e4b\u4ea4\u589e\u591a\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e00\u5ea6\u9057\u5f03\u7684\u4eba\u5076\u4f1a\u81ea\u884c\u5f52\u6765\u3002\u4e14\u624b\u6301\u51f6\u5668\u3002", "line": "\u5bfb\u7269\uff1a\u4e00\u5ea6\u9057\u5f03\u7684\u4eba\u5076\u4f1a\u81ea\u884c\u5f52\u6765\u3002\u4e14\u624b\u6301\u51f6\u5668\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (32, '风见幽香', '吉', '幻想乡的鲜花之主', '操纵花朵程度的能力', '["\u98ce\u59ff\u4e0e\u82b3\u9999\uff0c", "\u5747\u4e3a\u62db\u8702\u8776\u3002", "\u83ab\u7b11\u866b\u513f\u75f4\uff0c", "\u4eba\u7c7b\u53c8\u5982\u4f55\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u53ef\u4eab\u7eda\u70c2\u751f\u6d3b\uff0c\u4f46\u7ef4\u6301\u9887\u8d39\u5fc3\u529b\u3002", "line": "\u8fd0\u52bf\uff1a\u53ef\u4eab\u7eda\u70c2\u751f\u6d3b\uff0c\u4f46\u7ef4\u6301\u9887\u8d39\u5fc3\u529b\u3002"}, {"label": "\u5065\u5eb7", "text": "\u82e5\u4e0d\u6089\u5fc3\u7ba1\u7406\u4fbf\u4f1a\u8fc5\u901f\u51cb\u96f6\u3002", "line": "\u5065\u5eb7\uff1a\u82e5\u4e0d\u6089\u5fc3\u7ba1\u7406\u4fbf\u4f1a\u8fc5\u901f\u51cb\u96f6\u3002"}, {"label": "\u4ea4\u6613", "text": "\u670d\u52a1\u4e1a\u5219\u987e\u5ba2\u76c8\u95e8\u3002\u82b1\u5e97\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u670d\u52a1\u4e1a\u5219\u987e\u5ba2\u76c8\u95e8\u3002\u82b1\u5e97\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5b9c\u690d\u7269\u5b66\u3001\u7f8e\u672f\u3002", "line": "\u5b66\u4e1a\uff1a\u5b9c\u690d\u7269\u5b66\u3001\u7f8e\u672f\u3002"}], [{"label": "\u51fa\u884c", "text": "\u591a\u591a\u76ca\u5584\u3002\u4f46\u8df5\u8e0f\u690d\u7269\u5c06\u62db\u81f4\u4e0d\u5e78\u3002", "line": "\u51fa\u884c\uff1a\u591a\u591a\u76ca\u5584\u3002\u4f46\u8df5\u8e0f\u690d\u7269\u5c06\u62db\u81f4\u4e0d\u5e78\u3002"}, {"label": "\u604b\u7231", "text": "\u8d60\u793c\u5f53\u9009\u82b1\u675f\u3002", "line": "\u604b\u7231\uff1a\u8d60\u793c\u5f53\u9009\u82b1\u675f\u3002"}, {"label": "\u4f4f\u6240", "text": "\u9c9c\u82b1\u5986\u70b9\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u9c9c\u82b1\u5986\u70b9\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4eb2\u670b\u6613\u6765\u4e5f\u6613\u53bb\u3002\u5f3a\u884c\u633d\u7559\u53cd\u906d\u4e0d\u5e78\u3002", "line": "\u4eba\u7f18\uff1a\u4eb2\u670b\u6613\u6765\u4e5f\u6613\u53bb\u3002\u5f3a\u884c\u633d\u7559\u53cd\u906d\u4e0d\u5e78\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (33, '射命丸文', '凶
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (34, '小野塚小町', '末吉', '专业磨洋工的死神', '操纵距离程度的能力', '["\u6b7b\u795e\u82e5\u5f53\u771f", "\u62fc\u547d\u53bb\u5de5\u4f5c\uff0c", "\u4e16\u754c\u4e0d\u5c31\u8981", "\u4e00\u7247\u6b7b\u5bc2\u54af\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e0e\u6b7b\u795e\u6bd7\u90bb\u4e5f\u53ef\u60a0\u7136\u5ea6\u65e5\u3002\u4e0d\u7b97\u592a\u574f\u3002", "line": "\u8fd0\u52bf\uff1a\u4e0e\u6b7b\u795e\u6bd7\u90bb\u4e5f\u53ef\u60a0\u7136\u5ea6\u65e5\u3002\u4e0d\u7b97\u592a\u574f\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6b7b\u795e\u6020\u5de5\uff0c\u957f\u547d\u767e\u5c81\u3002", "line": "\u5065\u5eb7\uff1a\u6b7b\u795e\u6020\u5de5\uff0c\u957f\u547d\u767e\u5c81\u3002"}, {"label": "\u664b\u5347", "text": "\u5347\u8fc1\u65e0\u671b\uff0c\u4f46\u6021\u7136\u81ea\u5f97\u3002", "line": "\u664b\u5347\uff1a\u5347\u8fc1\u65e0\u671b\uff0c\u4f46\u6021\u7136\u81ea\u5f97\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5e73\u5e73\u65e0\u5947\u3002", "line": "\u4ea4\u6613\uff1a\u5e73\u5e73\u65e0\u5947\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6709\u5fc3\u5b66\u4e60\u4e5f\u65e0\u6d4e\u4e8e\u4e8b\u3002", "line": "\u5b66\u4e1a\uff1a\u6709\u5fc3\u5b66\u4e60\u4e5f\u65e0\u6d4e\u4e8e\u4e8b\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u5f97\u9047\u4e09\u6559\u4e5d\u6d41\u3002", "line": "\u4eba\u7f18\uff1a\u5f97\u9047\u4e09\u6559\u4e5d\u6d41\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u53ef\u84c4\u8eab\u540e\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u53ef\u84c4\u8eab\u540e\u8d22\u3002"}, {"label": "\u604b\u7231", "text": "\u8ddd\u79bb\u6e10\u8fd1\u3002", "line": "\u604b\u7231\uff1a\u8ddd\u79bb\u6e10\u8fd1\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u907f\u5f00\u6cb3\u5ddd\u3002\u5ddd\u6d41\u8bf1\u4eba\u6df1\u5165\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u907f\u5f00\u6cb3\u5ddd\u3002\u5ddd\u6d41\u8bf1\u4eba\u6df1\u5165\u3002"}, {"label": "\u7231\u597d", "text": "\u95f2\u6687\u65f6\u5149\u589e\u591a\uff0c\u6070\u662f\u591a\u65b9\u5c1d\u8bd5\u7684\u826f\u673a\u3002\u9002\u5f53\u6020\u5de5\u4fbf\u80fd\u751f\u6d3b\u5145\u5b9e\u3002", "line": "\u7231\u597d\uff1a\u95f2\u6687\u65f6\u5149\u589e\u591a\uff0c\u6070\u662f\u591a\u65b9\u5c1d\u8bd5\u7684\u826f\u673a\u3002\u9002\u5f53\u6020\u5de5\u4fbf\u80fd\u751f\u6d3b\u5145\u5b9e\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (35, '四季映姬·夜摩仙那度', '大吉', '锐眼辨是非的阎魔大人', '明鉴黑白程度的能力', '["\u4e16\u4e0a\u672c\u6ca1\u6709", "\u7edd\u5bf9\u7684\u4e8b\u5b9e\u3002", "\u552f\u4e00\u7684\u771f\u76f8", "\u987b\u7531\u6211\u88c1\u51b3\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5f53\u884c\u4e4b\u4e8b\u6108\u53d1\u660e\u6670\uff0c\u5f97\u4ee5\u6446\u8131\u8e0c\u8e87\u3002\u5fc3\u5883\u8c41\u7136\u5f00\u6717\u3002", "line": "\u8fd0\u52bf\uff1a\u5f53\u884c\u4e4b\u4e8b\u6108\u53d1\u660e\u6670\uff0c\u5f97\u4ee5\u6446\u8131\u8e0c\u8e87\u3002\u5fc3\u5883\u8c41\u7136\u5f00\u6717\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5f53\u575a\u6301\u5fc3\u4e2d\u6b63\u9053\u3002\u6cd5\u5b98\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5f53\u575a\u6301\u5fc3\u4e2d\u6b63\u9053\u3002\u6cd5\u5b98\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6d4e\u4e16\u4e4b\u4e1a\u53ef\u7e41\u8363\u660c\u76db\u3002", "line": "\u4ea4\u6613\uff1a\u6d4e\u4e16\u4e4b\u4e1a\u53ef\u7e41\u8363\u660c\u76db\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u53d1\u73b0\u8003\u9898\u9519\u6f0f\u3002", "line": "\u5b66\u4e1a\uff1a\u53d1\u73b0\u8003\u9898\u9519\u6f0f\u3002"}], [{"label": "\u604b\u7231", "text": "\u6e05\u6b63\u5ec9\u6d01\u53ef\u6210\u826f\u7f18\u3002", "line": "\u604b\u7231\uff1a\u6e05\u6b63\u5ec9\u6d01\u53ef\u6210\u826f\u7f18\u3002"}, {"label": "\u51fa\u884c", "text": "\u5de1\u6e38\u5730\u72f1\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5de1\u6e38\u5730\u72f1\u4e3a\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u56f4\u68cb\u4e3a\u5409\u3002\u9605\u8bfb\u63a8\u7406\u5c0f\u8bf4\u5c06\u88ab\u5267\u900f\u3002", "line": "\u7231\u597d\uff1a\u56f4\u68cb\u4e3a\u5409\u3002\u9605\u8bfb\u63a8\u7406\u5c0f\u8bf4\u5c06\u88ab\u5267\u900f\u3002"}, {"label": "\u5fc3\u613f", "text": "\u6e05\u507f\u5f80\u65e5\u7f6a\u5b7d\u5219\u53ef\u5982\u613f\u3002", "line": "\u5fc3\u613f\uff1a\u6e05\u507f\u5f80\u65e5\u7f6a\u5b7d\u5219\u53ef\u5982\u613f\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4f17\u4eba\u758f\u79bb\u3002\u5207\u5fcc\u4ee4\u4eba\u8fc7\u5ea6\u754f\u60e7\u3002", "line": "\u4eba\u7f18\uff1a\u4f17\u4eba\u758f\u79bb\u3002\u5207\u5fcc\u4ee4\u4eba\u8fc7\u5ea6\u754f\u60e7\u3002"}, {"label": "\u75be\u75c5", "text": "\u614e\u9632\u820c\u90e8\u53d7\u4f24\u3002", "line": "\u75be\u75c5\uff1a\u614e\u9632\u820c\u90e8\u53d7\u4f24\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (36, '秋静叶', '小吉', '深受游客喜爱的秋之神明', '掌管红叶程度的能力', '["\u6751\u843d\u4e0e\u68ee\u6797", "\u8fd8\u6709\u6df1\u5c71\u95f4\u3002", "\u8981\u904d\u67d3\u79cb\u8272", "\u53ef\u7edd\u975e\u6613\u4e8b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u773c\u4e0b\u52c9\u529b\u7ef4\u6301\uff0c\u4f46\u7ec8\u5c06\u8870\u9893\u3002\u6b64\u4e43\u81ea\u7136\u4e4b\u7406\u3002\u5f53\u5766\u7136\u63a5\u53d7\u3002", "line": "\u8fd0\u52bf\uff1a\u773c\u4e0b\u52c9\u529b\u7ef4\u6301\uff0c\u4f46\u7ec8\u5c06\u8870\u9893\u3002\u6b64\u4e43\u81ea\u7136\u4e4b\u7406\u3002\u5f53\u5766\u7136\u63a5\u53d7\u3002"}, {"label": "\u65b9\u4f4d", "text": "\u5317\u65b9\u3001\u4e0a\u65b9\u4e3a\u5409\u3002", "line": "\u65b9\u4f4d\uff1a\u5317\u65b9\u3001\u4e0a\u65b9\u4e3a\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u767b\u5c71\u4e3a\u5409\uff0c\u5b9c\u5c3d\u5174\u800c\u884c\u3002", "line": "\u51fa\u884c\uff1a\u767b\u5c71\u4e3a\u5409\uff0c\u5b9c\u5c3d\u5174\u800c\u884c\u3002"}, {"label": "\u4ea4\u6613", "text": "\u552f\u89c2\u5149\u4e1a\u751f\u610f\u5174\u9686\u3002", "line": "\u4ea4\u6613\uff1a\u552f\u89c2\u5149\u4e1a\u751f\u610f\u5174\u9686\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u591a\u52a0\u7559\u610f\u3002", "line": "\u5065\u5eb7\uff1a\u591a\u52a0\u7559\u610f\u3002"}, {"label": "\u75be\u75c5", "text": "\u6076\u5316\u3002", "line": "\u75be\u75c5\uff1a\u6076\u5316\u3002"}, {"label": "\u4f4f\u6240", "text": "\u8c28\u9632\u706b\u707e\u3002", "line": "\u4f4f\u6240\uff1a\u8c28\u9632\u706b\u707e\u3002"}, {"label": "\u59fb\u7f18", "text": "\u867d\u6709\u826f\u7f18\u5374\u96be\u76f8\u9022\u3002", "line": "\u59fb\u7f18\uff1a\u867d\u6709\u826f\u7f18\u5374\u96be\u76f8\u9022\u3002"}, {"label": "\u79fb\u5f99", "text": "\u8f6c\u673a\u6709\u671b\u3002", "line": "\u79fb\u5f99\uff1a\u8f6c\u673a\u6709\u671b\u3002"}, {"label": "\u795e\u5fb7", "text": "\u63a5\u89e6\u81ea\u7136\u4e4b\u7f8e\u53ef\u5f97\u795e\u660e\u62a4\u4f51\u3002", "line": "\u795e\u5fb7\uff1a\u63a5\u89e6\u81ea\u7136\u4e4b\u7f8e\u53ef\u5f97\u795e\u660e\u62a4\u4f51\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (37, '秋穰子', '大吉', '深受村中人类喜爱的神明', '掌管丰收程度的能力', '["\u80fd\u9971\u9910\u4e00\u987f", "\u662f\u65e0\u4e0a\u5e78\u798f\uff0c", "\u4e16\u95f4\u4efb\u4f55\u4e8b", "\u90fd\u65e0\u53ef\u6bd4\u62df\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7a33\u5f97\u5409\u8fd0\u3002\u7eb5\u906d\u632b\u6298\u4ea6\u5185\u5fc3\u5e73\u548c\uff0c\u65e0\u9700\u6302\u6000\u3002", "line": "\u8fd0\u52bf\uff1a\u7a33\u5f97\u5409\u8fd0\u3002\u7eb5\u906d\u632b\u6298\u4ea6\u5185\u5fc3\u5e73\u548c\uff0c\u65e0\u9700\u6302\u6000\u3002"}, {"label": "\u519c\u4e1a", "text": "\u4e30\u6536\u3002", "line": "\u519c\u4e1a\uff1a\u4e30\u6536\u3002"}, {"label": "\u4ea4\u6613", "text": "\u57fa\u672c\u987a\u5229\u3002", "line": "\u4ea4\u6613\uff1a\u57fa\u672c\u987a\u5229\u3002"}, {"label": "\u5065\u5eb7", "text": "\u65e0\u9700\u5fe7\u8651\u3002\u5fc3\u5bbd\u4f53\u80d6\u3002", "line": "\u5065\u5eb7\uff1a\u65e0\u9700\u5fe7\u8651\u3002\u5fc3\u5bbd\u4f53\u80d6\u3002"}, {"label": "\u75be\u75c5", "text": "\u75ca\u6108\u3002", "line": "\u75be\u75c5\uff1a\u75ca\u6108\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u7eb5\u6709\u4e0d\u987a\u4ea6\u65e0\u9700\u5728\u610f\u3002", "line": "\u5b66\u4e1a\uff1a\u7eb5\u6709\u4e0d\u987a\u4ea6\u65e0\u9700\u5728\u610f\u3002"}, {"label": "\u604b\u7231", "text": "\u4e0e\u53e3\u5473\u76f8\u6295\u8005\u6613\u6210\u826f\u7f18\u3002", "line": "\u604b\u7231\uff1a\u4e0e\u53e3\u5473\u76f8\u6295\u8005\u6613\u6210\u826f\u7f18\u3002"}, {"label": "\u679c\u5b9e", "text": "\u751c\u5ea6\u4e0a\u5347\u3002", "line": "\u679c\u5b9e\uff1a\u751c\u5ea6\u4e0a\u5347\u3002"}, {"label": "\u85af\u7c7b", "text": "\u5b9c\u70d8\u70e4\u98df\u7528\u3002", "line": "\u85af\u7c7b\uff1a\u5b9c\u70d8\u70e4\u98df\u7528\u3002"}, {"label": "\u795e\u5fb7", "text": "\u53c2\u62dc\u795e\u793e\u5207\u83ab\u61c8\u6020\u3002", "line": "\u795e\u5fb7\uff1a\u53c2\u62dc\u795e\u793e\u5207\u83ab\u61c8\u6020\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (38, '键山雏', '大凶', '注定被抛弃的流雏', '储存厄运程度的能力', '["\u96cf\u4eba\u5076\u6ce8\u5b9a", "\u8981\u987a\u6d41\u800c\u4e0b\u3002", "\u800c\u4f60\u5374\u4e0d\u614e", "\u62fe\u8d77\u4e86\u5b83\u5462\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5f88\u5feb\u5c31\u4f1a\u81ea\u884c\u62fe\u8d77\u5384\u8fd0\u7684\u7978\u7aef\u3002\u9700\u5728\u574f\u4e8b\u53d1\u751f\u524d\u5148\u884c\u88aa\u5384\u3002", "line": "\u8fd0\u52bf\uff1a\u5f88\u5feb\u5c31\u4f1a\u81ea\u884c\u62fe\u8d77\u5384\u8fd0\u7684\u7978\u7aef\u3002\u9700\u5728\u574f\u4e8b\u53d1\u751f\u524d\u5148\u884c\u88aa\u5384\u3002"}, {"label": "\u5065\u5eb7", "text": "\u7ef4\u6301\u6700\u9ad8\u7ea7\u8b66\u60d5\u3002", "line": "\u5065\u5eb7\uff1a\u7ef4\u6301\u6700\u9ad8\u7ea7\u8b66\u60d5\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6295\u8d44\u906d\u9047\u635f\u5931\u3002", "line": "\u4ea4\u6613\uff1a\u6295\u8d44\u906d\u9047\u635f\u5931\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u56e0\u8eab\u4f53\u4e0d\u9002\u800c\u5931\u5229\u3002", "line": "\u5b66\u4e1a\uff1a\u56e0\u8eab\u4f53\u4e0d\u9002\u800c\u5931\u5229\u3002"}, {"label": "\u519c\u4e8b", "text": "\u5fc5\u6709\u7eb0\u6f0f\u3002", "line": "\u519c\u4e8b\uff1a\u5fc5\u6709\u7eb0\u6f0f\u3002"}], [{"label": "\u59fb\u7f18", "text": "\u9759\u5019\u4e3a\u5999\u3002", "line": "\u59fb\u7f18\uff1a\u9759\u5019\u4e3a\u5999\u3002"}, {"label": "\u8d35\u4eba", "text": "\u6e10\u884c\u6e10\u8fdc\u3002", "line": "\u8d35\u4eba\uff1a\u6e10\u884c\u6e10\u8fdc\u3002"}, {"label": "\u5bfb\u7269", "text": "\u76f8\u7ee7\u4e22\u5931\u3002", "line": "\u5bfb\u7269\uff1a\u76f8\u7ee7\u4e22\u5931\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u94b1\u8d22\u6563\u5c3d\u3002", "line": "\u8d22\u8fd0\uff1a\u94b1\u8d22\u6563\u5c3d\u3002"}, {"label": "\u5f39\u5e55", "text": "\u88ab\u6d41\u5f39\u51fb\u4e2d\u3002", "line": "\u5f39\u5e55\uff1a\u88ab\u6d41\u5f39\u51fb\u4e2d\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u5f53\u5fc3\u4eba\u5076\u3002", "line": "\u5bb6\u5ead\uff1a\u5f53\u5fc3\u4eba\u5076\u3002"}, {"label": "\u51fa\u884c", "text": "\u6f02\u6d41\u53ef\u8f6c\u8fd0\u3002\u53ef\u671f\u4e00\u4e3e\u9006\u8f6c\u56f0\u5c40\u3002", "line": "\u51fa\u884c\uff1a\u6f02\u6d41\u53ef\u8f6c\u8fd0\u3002\u53ef\u671f\u4e00\u4e3e\u9006\u8f6c\u56f0\u5c40\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (39, '河城荷取', '中吉', '折腾机器的河童', '操纵水程度的能力', '["\u673a\u68b0\u5982\u6cb3\u5ddd\uff0c", "\u6d41\u52a8\u4e0d\u505c\u6b47\u3002", "\u5faa\u56de\u7535\u8def\u7684", "\u60f3\u6765\u662f\u8840\u6db2\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8bf8\u4e8b\u987a\u9042\uff0c\u5982\u5ddd\u5954\u6d41\u3002\u53ea\u8981\u4e0d\u751f\u6545\u969c\u4fbf\u53ef\u65e0\u5fe7\u3002", "line": "\u8fd0\u52bf\uff1a\u8bf8\u4e8b\u987a\u9042\uff0c\u5982\u5ddd\u5954\u6d41\u3002\u53ea\u8981\u4e0d\u751f\u6545\u969c\u4fbf\u53ef\u65e0\u5fe7\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8bf8\u4e1a\u7686\u53ef\u76c8\u5229\u3002\u4e0d\u5b88\u5546\u9053\u5219\u51f6\u3002", "line": "\u4ea4\u6613\uff1a\u8bf8\u4e1a\u7686\u53ef\u76c8\u5229\u3002\u4e0d\u5b88\u5546\u9053\u5219\u51f6\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5165\u804c\u516c\u53f8\u6050\u88ab\u538b\u69a8\u3002\u4f46\u5c1a\u53ef\u5fcd\u53d7\u3002", "line": "\u5de5\u4f5c\uff1a\u5165\u804c\u516c\u53f8\u6050\u88ab\u538b\u69a8\u3002\u4f46\u5c1a\u53ef\u5fcd\u53d7\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5b9c\u7814\u4e60\u5de5\u79d1\u3002", "line": "\u5b66\u4e1a\uff1a\u5b9c\u7814\u4e60\u5de5\u79d1\u3002"}], [{"label": "\u8fd0\u52a8", "text": "\u6cf3\u6280\u8fdb\u6b65\u3002", "line": "\u8fd0\u52a8\uff1a\u6cf3\u6280\u8fdb\u6b65\u3002"}, {"label": "\u604b\u7231", "text": "\u96be\u751f\u5174\u81f4\u3002", "line": "\u604b\u7231\uff1a\u96be\u751f\u5174\u81f4\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u5e72\u71e5\uff0c\u6613\u81f4\u8eab\u4f53\u4e0d\u9002\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u5e72\u71e5\uff0c\u6613\u81f4\u8eab\u4f53\u4e0d\u9002\u3002"}, {"label": "\u51fa\u884c", "text": "\u508d\u6c34\u90fd\u5e02\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u508d\u6c34\u90fd\u5e02\u4e3a\u5409\u3002"}, {"label": "\u75be\u75c5", "text": "\u75ca\u6108\u3002\u5c06\u5f97\u826f\u836f\u3002", "line": "\u75be\u75c5\uff1a\u75ca\u6108\u3002\u5c06\u5f97\u826f\u836f\u3002"}, {"label": "\u7269\u4ef6", "text": "\u64ac\u68cd\u7c7b\u7269\u54c1\u53ef\u5e26\u6765\u5e78\u8fd0\u3002", "line": "\u7269\u4ef6\uff1a\u64ac\u68cd\u7c7b\u7269\u54c1\u53ef\u5e26\u6765\u5e78\u8fd0\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (40, '犬走椛', '小吉', '对幻想观察入微的天狗', '看见千里之外程度的能力', '["\u4e16\u754c\u7684\u5f62\u6210", "\u7686\u57fa\u4e8e\u89c2\u6d4b\u3002", "\u773c\u529b\u662f\u81f3\u5b9d\uff0c", "\u8c01\u4e5f\u4e0d\u5acc\u591a\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u89c6\u91ce\u5f00\u9614\uff0c\u9047\u5230\u96be\u5173\u603b\u60f3\u9003\u907f\u3002\u96be\u6709\u957f\u8fdb\u3002", "line": "\u8fd0\u52bf\uff1a\u89c6\u91ce\u5f00\u9614\uff0c\u9047\u5230\u96be\u5173\u603b\u60f3\u9003\u907f\u3002\u96be\u6709\u957f\u8fdb\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4f9d\u8d56\u89c2\u5bdf\u529b\u7684\u884c\u4e1a\u53ef\u83b7\u6210\u529f\uff0c\u7814\u7a76\u5458\u3001\u4fa6\u63a2\u3001\u6295\u8d44\u5bb6\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u4f9d\u8d56\u89c2\u5bdf\u529b\u7684\u884c\u4e1a\u53ef\u83b7\u6210\u529f\uff0c\u7814\u7a76\u5458\u3001\u4fa6\u63a2\u3001\u6295\u8d44\u5bb6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6574\u4f53\u5e73\u7a33\u3002\u8003\u8bd5\u4e0d\u77e5\u4e3a\u4f55\u80fd\u62ff\u9ad8\u5206\u3002", "line": "\u5b66\u4e1a\uff1a\u6574\u4f53\u5e73\u7a33\u3002\u8003\u8bd5\u4e0d\u77e5\u4e3a\u4f55\u80fd\u62ff\u9ad8\u5206\u3002"}, {"label": "\u5065\u5eb7", "text": "\u89c6\u529b\u63d0\u5347\u3002", "line": "\u5065\u5eb7\uff1a\u89c6\u529b\u63d0\u5347\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4eba\u8ff9\u7f55\u81f3\u4e4b\u5904\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4eba\u8ff9\u7f55\u81f3\u4e4b\u5904\u4e3a\u5409\u3002"}, {"label": "\u4e89\u7aef", "text": "\u7eb5\u4f7f\u523b\u610f\u56de\u907f\uff0c\u7ec8\u5c06\u5377\u5165\u5176\u4e2d\u3002", "line": "\u4e89\u7aef\uff1a\u7eb5\u4f7f\u523b\u610f\u56de\u907f\uff0c\u7ec8\u5c06\u5377\u5165\u5176\u4e2d\u3002"}, {"label": "\u604b\u7231", "text": "\u773c\u5149\u8fc7\u9ad8\uff0c\u800c\u96be\u9047\u826f\u7f18\u3002", "line": "\u604b\u7231\uff1a\u773c\u5149\u8fc7\u9ad8\uff0c\u800c\u96be\u9047\u826f\u7f18\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5b9c\u9ad8\u5730\u3002", "line": "\u4f4f\u6240\uff1a\u5b9c\u9ad8\u5730\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5c06\u5728\u8fdc\u5904\u5bfb\u5f97\u3002", "line": "\u5bfb\u7269\uff1a\u5c06\u5728\u8fdc\u5904\u5bfb\u5f97\u3002"}, {"label": "\u52a8\u7269", "text": "\u63d0\u9632\u91ce\u751f\u733f\u7334\u3002", "line": "\u52a8\u7269\uff1a\u63d0\u9632\u91ce\u751f\u733f\u7334\u3002"}, {"label": "\u7231\u597d", "text": "\u9700\u6c89\u5fc3\u51dd\u795e\u6295\u5165\u7684\u6e38\u620f\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u9700\u6c89\u5fc3\u51dd\u795e\u6295\u5165\u7684\u6e38\u620f\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (41, '东风谷早苗', '奇迹☆', '居于守矢神社的奇迹巫女', '引发奇迹程度的能力', '["\u5b87\u5b99\u4e4b\u5927", "\u867d\u6709\u6781\u9650\uff0c", "\u5374\u7531\u65e0\u5c3d", "\u5947\u8ff9\u6784\u6210\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5947\u8ff9\u964d\u4e34\u3002\u5947\u8ff9\u8fc7\u4e8e\u9891\u7e41\u4ee5\u81f3\u53f8\u7a7a\u89c1\u60ef\u3002", "line": "\u8fd0\u52bf\uff1a\u5947\u8ff9\u964d\u4e34\u3002\u5947\u8ff9\u8fc7\u4e8e\u9891\u7e41\u4ee5\u81f3\u53f8\u7a7a\u89c1\u60ef\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6401\u7f6e\u4e4b\u4e1a\u53cd\u5f97\u77a9\u76ee\u3002", "line": "\u4ea4\u6613\uff1a\u6401\u7f6e\u4e4b\u4e1a\u53cd\u5f97\u77a9\u76ee\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e34\u9635\u78e8\u67aa\u62bc\u9898\u6210\u529f\u3002\u7406\u79d1\u7686\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u4e34\u9635\u78e8\u67aa\u62bc\u9898\u6210\u529f\u3002\u7406\u79d1\u7686\u5927\u5409\u3002"}], [{"label": "\u75be\u75c5", "text": "\u75ca\u6108\u3002", "line": "\u75be\u75c5\uff1a\u75ca\u6108\u3002"}, {"label": "\u604b\u7231", "text": "\u5b9c\u5076\u9047\u826f\u7f18\u3002", "line": "\u604b\u7231\uff1a\u5b9c\u5076\u9047\u826f\u7f18\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5fc5\u80fd\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u5fc5\u80fd\u5bfb\u56de\u3002"}, {"label": "\u4f4f\u6240", "text": "\u53ef\u62b5\u5fa1\u72c2\u98ce\u3002", "line": "\u4f4f\u6240\uff1a\u53ef\u62b5\u5fa1\u72c2\u98ce\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (42, '八坂神奈子', '大吉', '为穷乡僻壤带来技术革命的山神', '创造乾程度的能力', '["\u56e0\u5faa\u5b88\u65e7", "\u4e0d\u601d\u8fdb\u53d6\uff0c", "\u4fe1\u4ef0\u5fc5\u4f1a", "\u65e5\u6e10\u67af\u7aed\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4ee5\u5f3a\u76db\u6c14\u8fd0\u6405\u52a8\u98ce\u4e91\u3002\u5c06\u6210\u4e2d\u5fc3\u4eba\u7269\u3002", "line": "\u8fd0\u52bf\uff1a\u4ee5\u5f3a\u76db\u6c14\u8fd0\u6405\u52a8\u98ce\u4e91\u3002\u5c06\u6210\u4e2d\u5fc3\u4eba\u7269\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5b9c\u6210\u5927\u4e1a\u3002\u7ec6\u679d\u672b\u8282\u5e94\u4ea4\u4e88\u4e0b\u7ea7\u5904\u7406\u3002", "line": "\u5de5\u4f5c\uff1a\u5b9c\u6210\u5927\u4e1a\u3002\u7ec6\u679d\u672b\u8282\u5e94\u4ea4\u4e88\u4e0b\u7ea7\u5904\u7406\u3002"}, {"label": "\u4ea4\u6613", "text": "\u968f\u673a\u5e94\u53d8\uff0c\u6355\u5f97\u5546\u673a\u3002", "line": "\u4ea4\u6613\uff1a\u968f\u673a\u5e94\u53d8\uff0c\u6355\u5f97\u5546\u673a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5de5\u5b66\u3001\u6570\u5b66\u3001\u7269\u7406\u5b66\u3001\u722c\u884c\u52a8\u7269\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u5de5\u5b66\u3001\u6570\u5b66\u3001\u7269\u7406\u5b66\u3001\u722c\u884c\u52a8\u7269\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u8001\u5f53\u76ca\u58ee\u3002\u5f53\u5fc3\u6bd2\u86c7\u3002", "line": "\u5065\u5eb7\uff1a\u8001\u5f53\u76ca\u58ee\u3002\u5f53\u5fc3\u6bd2\u86c7\u3002"}, {"label": "\u51fa\u884c", "text": "\u5c71\u3001\u6e56\u3001\u6e29\u6cc9\u4e3a\u5409\u3002 \u82e5\u6709\u95f4\u6b47\u6cc9\u5219\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5c71\u3001\u6e56\u3001\u6e29\u6cc9\u4e3a\u5409\u3002 \u82e5\u6709\u95f4\u6b47\u6cc9\u5219\u5927\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u8fc7\u5ea6\u5e72\u6d89\u6613\u88ab\u89c6\u4e3a\u804c\u573a\u9738\u51cc\u3002", "line": "\u4eba\u7f18\uff1a\u8fc7\u5ea6\u5e72\u6d89\u6613\u88ab\u89c6\u4e3a\u804c\u573a\u9738\u51cc\u3002"}, {"label": "\u5fc3\u613f", "text": "\u53c2\u62dc\u795e\u793e\u5373\u53ef\u5982\u613f\u3002", "line": "\u5fc3\u613f\uff1a\u53c2\u62dc\u795e\u793e\u5373\u53ef\u5982\u613f\u3002"}, {"label": "\u75be\u75c5", "text": "\u80cc\u4e0a\u8d1f\u62c5\u8fc7\u91cd\uff0c\u5bfc\u81f4\u8170\u75db\u53d1\u4f5c\u3002", "line": "\u75be\u75c5\uff1a\u80cc\u4e0a\u8d1f\u62c5\u8fc7\u91cd\uff0c\u5bfc\u81f4\u8170\u75db\u53d1\u4f5c\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (43, '洩矢诹访子', '大吉', '因祟受祀的土著神', '创造坤程度的能力', '["\u53e4\u8001\u4f20\u8bf4\uff0c", "\u83ab\u4f5c\u7b11\u8c08\u3002", "\u89e6\u72af\u795e\u660e\uff0c", "\u96be\u9003\u7978\u795f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7231\u62a4\u81ea\u7136\u5219\u4e07\u4e8b\u987a\u9042\u3002\u5426\u5219\u7978\u795f\u5c06\u81f3\u3002", "line": "\u8fd0\u52bf\uff1a\u7231\u62a4\u81ea\u7136\u5219\u4e07\u4e8b\u987a\u9042\u3002\u5426\u5219\u7978\u795f\u5c06\u81f3\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5c1a\u7b97\u5174\u76db\u3002", "line": "\u4ea4\u6613\uff1a\u5c1a\u7b97\u5174\u76db\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u987a\u987a\u5f53\u5f53\u3002\u519c\u4e1a\u3001\u571f\u6728\u884c\u4e1a\u5c24\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u987a\u987a\u5f53\u5f53\u3002\u519c\u4e1a\u3001\u571f\u6728\u884c\u4e1a\u5c24\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u5386\u53f2\u60a0\u4e45\u7684\u4e61\u95f4\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5386\u53f2\u60a0\u4e45\u7684\u4e61\u95f4\u4e3a\u5409\u3002"}, {"label": "\u79fb\u5f99", "text": "\u5e94\u4ed4\u7ec6\u8c03\u67e5\u571f\u5730\u5386\u53f2\u3002", "line": "\u79fb\u5f99\uff1a\u5e94\u4ed4\u7ec6\u8c03\u67e5\u571f\u5730\u5386\u53f2\u3002"}, {"label": "\u5065\u5eb7", "text": "\u751f\u9f99\u6d3b\u864e\u3002", "line": "\u5065\u5eb7\uff1a\u751f\u9f99\u6d3b\u864e\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u65b0\u5174\u5b66\u79d1\u4e00\u7a8d\u4e0d\u901a\u3002 \u6c11\u4fd7\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u65b0\u5174\u5b66\u79d1\u4e00\u7a8d\u4e0d\u901a\u3002 \u6c11\u4fd7\u5b66\u4e3a\u5409\u3002"}, {"label": "\u5bfb\u7269", "text": "\u53ef\u4e8e\u5927\u5730\u4e4b\u4e0a\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u53ef\u4e8e\u5927\u5730\u4e4b\u4e0a\u5bfb\u56de\u3002"}, {"label": "\u751f\u80b2", "text": "\u591a\u5b50\u591a\u798f\u3002\u751f\u4ea7\u987a\u5229\u3002", "line": "\u751f\u80b2\uff1a\u591a\u5b50\u591a\u798f\u3002\u751f\u4ea7\u987a\u5229\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u9732\u8425\u3001\u56ed\u827a\u3001\u51ac\u7720\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u9732\u8425\u3001\u56ed\u827a\u3001\u51ac\u7720\u3002"}, {"label": "\u7981\u5fcc", "text": "\u85d0\u89c6\u81ea\u7136\u5219\u5927\u51f6\u5c06\u81f3\uff0c\u767e\u822c\u8fd0\u52bf\u5c3d\u6570\u53cd\u8f6c\u3002", "line": "\u7981\u5fcc\uff1a\u85d0\u89c6\u81ea\u7136\u5219\u5927\u51f6\u5c06\u81f3\uff0c\u767e\u822c\u8fd0\u52bf\u5c3d\u6570\u53cd\u8f6c\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (44, '永江衣玖', '小吉', '通报地震的龙宫使者', '解读空气程度的能力', '["\u5730\u9707\u603b\u5f52\u662f", "\u8981\u53d1\u751f\u7684\u5566\u3002", "\u5927\u5730\u4e5f\u6ca1\u6cd5", "\u5f85\u7740\u4e0d\u52a8\u561b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6050\u9047\u5929\u707e\u3002\u9664\u6b64\u4e4b\u5916\u4ea6\u6709\u5de8\u53d8\u4e4b\u5146\u3002", "line": "\u8fd0\u52bf\uff1a\u6050\u9047\u5929\u707e\u3002\u9664\u6b64\u4e4b\u5916\u4ea6\u6709\u5de8\u53d8\u4e4b\u5146\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5584\u8bfb\u6c14\u6c1b\u501f\u98ce\u4f7f\u8235\uff0c\u56e0\u6b64\u4e0d\u4f1a\u5f97\u7f6a\u4e8e\u4eba\u3002\u4f46\u4e5f\u96be\u4ee5\u5f15\u4eba\u6ce8\u76ee\u3002", "line": "\u4eba\u7f18\uff1a\u5584\u8bfb\u6c14\u6c1b\u501f\u98ce\u4f7f\u8235\uff0c\u56e0\u6b64\u4e0d\u4f1a\u5f97\u7f6a\u4e8e\u4eba\u3002\u4f46\u4e5f\u96be\u4ee5\u5f15\u4eba\u6ce8\u76ee\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5927\u591a\u5c97\u4f4d\u7686\u53ef\u5b89\u7a33\u3002", "line": "\u5de5\u4f5c\uff1a\u5927\u591a\u5c97\u4f4d\u7686\u53ef\u5b89\u7a33\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5bb9\u6613\u79ef\u7d2f\u7cbe\u795e\u538b\u529b\u3002", "line": "\u5065\u5eb7\uff1a\u5bb9\u6613\u79ef\u7d2f\u7cbe\u795e\u538b\u529b\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u7406\u79d1\u7686\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u7406\u79d1\u7686\u5409\u3002"}, {"label": "\u8fd0\u52a8", "text": "\u6cf3\u6280\u7a81\u98de\u731b\u8fdb\u3002", "line": "\u8fd0\u52a8\uff1a\u6cf3\u6280\u7a81\u98de\u731b\u8fdb\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5730\u9707\u5c06\u81f3\uff0c\u901f\u505a\u6253\u7b97\u3002", "line": "\u4f4f\u6240\uff1a\u5730\u9707\u5c06\u81f3\uff0c\u901f\u505a\u6253\u7b97\u3002"}, {"label": "\u604b\u7231", "text": "\u5e73\u5e73\u6de1\u6de1\u3002", "line": "\u604b\u7231\uff1a\u5e73\u5e73\u6de1\u6de1\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u822a\u7a7a\u6216\u822a\u6d77\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u822a\u7a7a\u6216\u822a\u6d77\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4e0d\u4f1a\u53d1\u751f\u3002\u53ef\u4e3a\u4ed6\u4eba\u4ef2\u88c1\u4e89\u7aef\u3002", "line": "\u4e89\u7aef\uff1a\u4e0d\u4f1a\u53d1\u751f\u3002\u53ef\u4e3a\u4ed6\u4eba\u4ef2\u88c1\u4e89\u7aef\u3002"}, {"label": "\u7231\u597d", "text": "\u5728\u6b65\u884c\u8857\u4e0a\u7a7f\u68ad\u81ea\u5982\u3002", "line": "\u7231\u597d\uff1a\u5728\u6b65\u884c\u8857\u4e0a\u7a7f\u68ad\u81ea\u5982\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (45, '比那名居天子', '【大大吉】', '放浪不羁的不良天人', '操纵大地程度的能力', '["\u5c48\u5c0a\u53bb\u5949\u966a", "\u51e1\u592b\u4fd7\u5b50\u4eec\uff0c", "\u4e5f\u662f\u5929\u4eba\u7684", "\u804c\u8d23\u6240\u5728\u561b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u751f\u6765\u5e78\u8fd0\u3002\u5929\u5730\u81ea\u7136\u4e0e\u5468\u906d\u4e4b\u4eba\u7686\u53ef\u4e3a\u5df1\u6240\u7528\u3002", "line": "\u8fd0\u52bf\uff1a\u751f\u6765\u5e78\u8fd0\u3002\u5929\u5730\u81ea\u7136\u4e0e\u5468\u906d\u4e4b\u4eba\u7686\u53ef\u4e3a\u5df1\u6240\u7528\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u9887\u5177\u9886\u8896\u98ce\u91c7\u3002\u660e\u661f\u3001\u6559\u5e08\u3001\u5b97\u6559\u5bb6\u3001\u89c6\u9891\u535a\u4e3b\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u9887\u5177\u9886\u8896\u98ce\u91c7\u3002\u660e\u661f\u3001\u6559\u5e08\u3001\u5b97\u6559\u5bb6\u3001\u89c6\u9891\u535a\u4e3b\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5c0f\u6709\u5b66\u8bc6\u3002\u53e4\u6587\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u5c0f\u6709\u5b66\u8bc6\u3002\u53e4\u6587\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4e0d\u77e5\u4f24\u75c5\u4e3a\u4f55\u7269\u3002", "line": "\u5065\u5eb7\uff1a\u4e0d\u77e5\u4f24\u75c5\u4e3a\u4f55\u7269\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5386\u53f2\u60a0\u4e45\u4e4b\u5730\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5386\u53f2\u60a0\u4e45\u4e4b\u5730\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4ece\u8005\u5982\u4e91\u3002\u5207\u52ff\u8fc7\u5ea6\u8bf4\u6559\u3002", "line": "\u4eba\u7f18\uff1a\u4ece\u8005\u5982\u4e91\u3002\u5207\u52ff\u8fc7\u5ea6\u8bf4\u6559\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5b9c\u4e0e\u663e\u8d35\u4e4b\u4eba\u76f8\u4eb2\u3002", "line": "\u59fb\u7f18\uff1a\u5b9c\u4e0e\u663e\u8d35\u4e4b\u4eba\u76f8\u4eb2\u3002"}, {"label": "\u7231\u597d", "text": "\u4e8e\u707e\u533a\u5f00\u5c55\u5fd7\u613f\u6d3b\u52a8\u4e3a\u5927\u5409\u3002", "line": "\u7231\u597d\uff1a\u4e8e\u707e\u533a\u5f00\u5c55\u5fd7\u613f\u6d3b\u52a8\u4e3a\u5927\u5409\u3002"}, {"label": "\u996e\u98df", "text": "\u6beb\u65e0\u53e3\u5473\u53ef\u8a00\u3002\u4ec5\u80fd\u63d0\u4f9b\u8425\u517b\u3002", "line": "\u996e\u98df\uff1a\u6beb\u65e0\u53e3\u5473\u53ef\u8a00\u3002\u4ec5\u80fd\u63d0\u4f9b\u8425\u517b\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (46, '琪斯美', '末凶', '秋阳与人生皆如钓瓶落', '降下鬼火程度的能力', '["\u6447\u554a\u6447\uff0c", "\u843d\u554a\u843d\uff0c", "\u5f85\u5728\u6876\u91cc", "\u522b\u4e71\u52a8\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5fc5\u5c06\u4e0b\u843d\u3002 \u82e5\u6b32\u6297\u4e89\uff0c\u5207\u52ff\u5750\u4ee5\u5f85\u6bd9\u3002", "line": "\u8fd0\u52bf\uff1a\u5fc5\u5c06\u4e0b\u843d\u3002 \u82e5\u6b32\u6297\u4e89\uff0c\u5207\u52ff\u5750\u4ee5\u5f85\u6bd9\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5f53\u5fc3\u706b\u707e\uff0c\u6392\u9664\u9690\u60a3\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5fc3\u706b\u707e\uff0c\u6392\u9664\u9690\u60a3\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4e0d\u751a\u7406\u60f3\u3002 \u5f53\u5fc3\u7ecf\u6d4e\u8231\u7efc\u5408\u5f81\u3002", "line": "\u5065\u5eb7\uff1a\u4e0d\u751a\u7406\u60f3\u3002 \u5f53\u5fc3\u7ecf\u6d4e\u8231\u7efc\u5408\u5f81\u3002"}, {"label": "\u604b\u7231", "text": "\u4e3b\u52a8\u51fa\u51fb\u5c1a\u6709\u5e0c\u671b\u3002", "line": "\u604b\u7231\uff1a\u4e3b\u52a8\u51fa\u51fb\u5c1a\u6709\u5e0c\u671b\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u9a6c\u9a6c\u864e\u864e\u3002 \u5e38\u6709\u4e00\u843d\u5343\u4e08\u4e4b\u865e\u3002 \u52a1\u5fc5\u4e8e\u98ce\u8d77\u4e4b\u65e5\u91c7\u53d6\u884c\u52a8\u3002", "line": "\u4ea4\u6613\uff1a\u9a6c\u9a6c\u864e\u864e\u3002 \u5e38\u6709\u4e00\u843d\u5343\u4e08\u4e4b\u865e\u3002 \u52a1\u5fc5\u4e8e\u98ce\u8d77\u4e4b\u65e5\u91c7\u53d6\u884c\u52a8\u3002"}, {"label": "\u79fb\u5f99", "text": "\u6216\u53ef\u8f6c\u51f6\u4e3a\u5409\u3002", "line": "\u79fb\u5f99\uff1a\u6216\u53ef\u8f6c\u51f6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6ce8\u610f\u5065\u5eb7\u5219\u53ef\u4e0e\u65e5\u4ff1\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u6ce8\u610f\u5065\u5eb7\u5219\u53ef\u4e0e\u65e5\u4ff1\u8fdb\u3002"}, {"label": "\u6c34\u4e95", "text": "\u6108\u6df1\u6108\u4e3a\u5409\u3002", "line": "\u6c34\u4e95\uff1a\u6108\u6df1\u6108\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (47, '黑谷山女', '大凶', '与病为邻的蜘蛛', '操纵疾病程度的能力', '["\u8fd1\u86db\u8005\u761f", "\u5207\u83ab\u5fd8", "\u72ec\u5177\u8718\u773c", "\u89c2\u516b\u65b9"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e0d\u751a\u7406\u60f3\u3002\u5384\u8fd0\u65e0\u60c5\u3002 \u5373\u4fbf\u5df2\u5728\u8c37\u5e95\uff0c\u4ecd\u5c06\u518d\u843d\u5343\u4e08\u3002", "line": "\u8fd0\u52bf\uff1a\u4e0d\u751a\u7406\u60f3\u3002\u5384\u8fd0\u65e0\u60c5\u3002 \u5373\u4fbf\u5df2\u5728\u8c37\u5e95\uff0c\u4ecd\u5c06\u518d\u843d\u5343\u4e08\u3002"}, {"label": "\u5065\u5eb7", "text": "\u52a1\u5fc5\u5c3d\u4e00\u5207\u53ef\u80fd\u9632\u75c5\u4e8e\u672a\u7136\uff0c\u9632\u75ab\u3001\u6d88\u6bd2\u7b49\u5404\u65b9\u5404\u9762\u7686\u9700\u5468\u5168\u3002", "line": "\u5065\u5eb7\uff1a\u52a1\u5fc5\u5c3d\u4e00\u5207\u53ef\u80fd\u9632\u75c5\u4e8e\u672a\u7136\uff0c\u9632\u75ab\u3001\u6d88\u6bd2\u7b49\u5404\u65b9\u5404\u9762\u7686\u9700\u5468\u5168\u3002"}], [{"label": "\u75be\u75c5", "text": "\u65e7\u75be\u4e0d\u4f1a\u6076\u5316\u3002 \u65b0\u60a3\u5c06\u81f3\uff0c\u4e25\u9635\u4ee5\u5f85\u3002", "line": "\u75be\u75c5\uff1a\u65e7\u75be\u4e0d\u4f1a\u6076\u5316\u3002 \u65b0\u60a3\u5c06\u81f3\uff0c\u4e25\u9635\u4ee5\u5f85\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6210\u529f\u65e0\u671b\u3002", "line": "\u4ea4\u6613\uff1a\u6210\u529f\u65e0\u671b\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u591a\u591a\u52aa\u529b\u3002", "line": "\u5b66\u4e1a\uff1a\u591a\u591a\u52aa\u529b\u3002"}, {"label": "\u4f4f\u6240", "text": "\u53ef\u5f97\u826f\u5c45\u3002 \u7ffb\u65b0\u6539\u5efa\u4ea6\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u53ef\u5f97\u826f\u5c45\u3002 \u7ffb\u65b0\u6539\u5efa\u4ea6\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u82e6\u82e6\u7b49\u5019\u3002", "line": "\u604b\u7231\uff1a\u82e6\u82e6\u7b49\u5019\u3002"}, {"label": "\u751f\u80b2", "text": "\u591a\u5b50\u591a\u798f\u3002", "line": "\u751f\u80b2\uff1a\u591a\u5b50\u591a\u798f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (48, '水桥帕露西', '末吉', '妒火中烧的桥姬', '操纵嫉妒心程度的能力', '["\u5149\u9c9c\u7684\u65e5\u5e38\uff0c", "\u79bb\u8c31\u7684\u6210\u529f\u3002", "\u65c1\u4eba\u7686\u5982\u6b64\uff0c", "\u6211\u597d\u5ac9\u5992\u554a\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65f6\u5e38\u8273\u7fa1\u4ed6\u4eba\u3002\u82e5\u80fd\u5c06\u5ac9\u5992\u4e4b\u60c5\u8f6c\u5316\u4e3a\u4e0a\u8fdb\u52a8\u529b\uff0c\u4fbf\u80fd\u5927\u5e45\u6210\u957f\u3002", "line": "\u8fd0\u52bf\uff1a\u65f6\u5e38\u8273\u7fa1\u4ed6\u4eba\u3002\u82e5\u80fd\u5c06\u5ac9\u5992\u4e4b\u60c5\u8f6c\u5316\u4e3a\u4e0a\u8fdb\u52a8\u529b\uff0c\u4fbf\u80fd\u5927\u5e45\u6210\u957f\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5546\u624d\u8fc7\u4eba\u3002\u5f97\u9047\u5de8\u5927\u5546\u673a\u3002", "line": "\u4ea4\u6613\uff1a\u5546\u624d\u8fc7\u4eba\u3002\u5f97\u9047\u5de8\u5927\u5546\u673a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u575a\u6301\u4e0d\u61c8\u7ec8\u5c06\u957f\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u575a\u6301\u4e0d\u61c8\u7ec8\u5c06\u957f\u8fdb\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u5207\u83ab\u6a2a\u52a0\u6500\u6bd4\u3002", "line": "\u5bb6\u5ead\uff1a\u5207\u83ab\u6a2a\u52a0\u6500\u6bd4\u3002"}], [{"label": "\u8d22\u8fd0", "text": "\u4e0d\u62b1\u671f\u5f85\u3002", "line": "\u8d22\u8fd0\uff1a\u4e0d\u62b1\u671f\u5f85\u3002"}, {"label": "\u604b\u7231", "text": "\u906d\u4eba\u5acc\u5f03\u3002\u4e14\u4f5c\u5fcd\u8010\u3002", "line": "\u604b\u7231\uff1a\u906d\u4eba\u5acc\u5f03\u3002\u4e14\u4f5c\u5fcd\u8010\u3002"}, {"label": "\u4eba\u7f18", "text": "\u7262\u9a9a\u6ee1\u8179\uff0c\u906d\u4eba\u758f\u8fdc\u3002", "line": "\u4eba\u7f18\uff1a\u7262\u9a9a\u6ee1\u8179\uff0c\u906d\u4eba\u758f\u8fdc\u3002"}, {"label": "\u8272\u5f69", "text": "\u7eff\u8272\u3002", "line": "\u8272\u5f69\uff1a\u7eff\u8272\u3002"}, {"label": "\u6865\u6881", "text": "\u6841\u67b6\u4e3a\u5409\u3002", "line": "\u6865\u6881\uff1a\u6841\u67b6\u4e3a\u5409\u3002"}, {"label": "\u6028\u6068", "text": "\u575a\u6301\u9489\u624e\u8349\u4eba\uff0c\u5fc5\u80fd\u62a5\u4ec7\u96ea\u6068\u3002", "line": "\u6028\u6068\uff1a\u575a\u6301\u9489\u624e\u8349\u4eba\uff0c\u5fc5\u80fd\u62a5\u4ec7\u96ea\u6068\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (49, '星熊勇仪', '乱', '身怀怪力毁天灭地的鬼', '拥有怪力乱神程度的能力', '["\u5c31\u51ed\u4f60\u90a3\u53cc", "\u7ec6\u80f3\u818a\u8f6f\u817f\uff0c", "\u54ea\u91cc\u633a\u5f97\u8fc7", "\u8fd9\u7eb7\u4e71\u4e4b\u4e16\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6709\u798f\u4ea6\u6709\u7978\u3002\u552f\u6709\u51ed\u5b9e\u529b\u6293\u4f4f\u597d\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u6709\u798f\u4ea6\u6709\u7978\u3002\u552f\u6709\u51ed\u5b9e\u529b\u6293\u4f4f\u597d\u8fd0\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u5f3a\u4f53\u5065\u3002\u8c6a\u996e\u7f8e\u9152\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u5f3a\u4f53\u5065\u3002\u8c6a\u996e\u7f8e\u9152\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u529b\u6c14\u591f\u5927\u5219\u80fd\u6240\u5411\u62ab\u9761\u3002", "line": "\u6bd4\u8bd5\uff1a\u529b\u6c14\u591f\u5927\u5219\u80fd\u6240\u5411\u62ab\u9761\u3002"}, {"label": "\u8fd0\u52a8", "text": "\u591a\u591a\u76ca\u5584\uff0c\u529b\u538b\u7fa4\u96c4\u3002", "line": "\u8fd0\u52a8\uff1a\u591a\u591a\u76ca\u5584\uff0c\u529b\u538b\u7fa4\u96c4\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u98ce\u6ce2\u8fde\u8fde\u3002\u529b\u6c14\u5927\u5c0f\u51b3\u5b9a\u4e8b\u4e1a\u6210\u8d25\u3002", "line": "\u4ea4\u6613\uff1a\u98ce\u6ce2\u8fde\u8fde\u3002\u529b\u6c14\u5927\u5c0f\u51b3\u5b9a\u4e8b\u4e1a\u6210\u8d25\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u65e0\u6cd5\u4e13\u5fc3\u5b66\u4e60\u3002\u4e34\u8003\u62bc\u9898\u4e3a\u4e0a\u3002", "line": "\u5b66\u4e1a\uff1a\u65e0\u6cd5\u4e13\u5fc3\u5b66\u4e60\u3002\u4e34\u8003\u62bc\u9898\u4e3a\u4e0a\u3002"}, {"label": "\u51fa\u884c", "text": "\u9152\u9986\u5de1\u6e38\u5373\u53ef\u3002", "line": "\u51fa\u884c\uff1a\u9152\u9986\u5de1\u6e38\u5373\u53ef\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u4e3b\u52a8\u6311\u8845\u3002", "line": "\u604b\u7231\uff1a\u5f53\u4e3b\u52a8\u6311\u8845\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5f53\u62a2\u5148\u60f9\u4e8b\u3002", "line": "\u4e89\u7aef\uff1a\u5f53\u62a2\u5148\u60f9\u4e8b\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u65e0\u7528\u3002\u5f53\u9760\u86ee\u529b\u593a\u53d6\u4e00\u5207\u3002", "line": "\u8d22\u8fd0\uff1a\u65e0\u7528\u3002\u5f53\u9760\u86ee\u529b\u593a\u53d6\u4e00\u5207\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (50, '古明地觉', '吉', '身不由己的读心妖怪', '读心程度的能力', '["\u5e38\u4eba\u4e4b\u6240\u4ee5", "\u80fd\u81ea\u7531\u884c\u52a8\uff0c", "\u53ea\u56e0\u8bfb\u4e0d\u900f", "\u4ed6\u4eba\u7684\u5fc3\u58f0\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5fc3\u906d\u675f\u7f1a\u3001\u52a8\u5f39\u4e0d\u5f97\u3002\u82e5\u9047\u826f\u4eba\u6216\u53ef\u626d\u8f6c\u4e7e\u5764\u3002", "line": "\u8fd0\u52bf\uff1a\u5fc3\u906d\u675f\u7f1a\u3001\u52a8\u5f39\u4e0d\u5f97\u3002\u82e5\u9047\u826f\u4eba\u6216\u53ef\u626d\u8f6c\u4e7e\u5764\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e0e\u4eba\u4ea4\u5f80\u5b58\u5728\u98ce\u9669\u3002\u4f46\u82e5\u6b32\u6293\u4f4f\u597d\u8fd0\u5219\u4e0d\u5e94\u56de\u907f\u3002", "line": "\u4eba\u7f18\uff1a\u4e0e\u4eba\u4ea4\u5f80\u5b58\u5728\u98ce\u9669\u3002\u4f46\u82e5\u6b32\u6293\u4f4f\u597d\u8fd0\u5219\u4e0d\u5e94\u56de\u907f\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6613\u751f\u5fc3\u75c5\u3002\u6ce8\u610f\u5fc3\u7406\u5065\u5eb7\u3002", "line": "\u5065\u5eb7\uff1a\u6613\u751f\u5fc3\u75c5\u3002\u6ce8\u610f\u5fc3\u7406\u5065\u5eb7\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9022\u8003\u5fc5\u8fc7\u3002", "line": "\u5b66\u4e1a\uff1a\u9022\u8003\u5fc5\u8fc7\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u8ba4\u771f\u5904\u7406\u6295\u8bc9\u5219\u6ce8\u5b9a\u5931\u8d25\u3002", "line": "\u4ea4\u6613\uff1a\u8ba4\u771f\u5904\u7406\u6295\u8bc9\u5219\u6ce8\u5b9a\u5931\u8d25\u3002"}, {"label": "\u604b\u7231", "text": "\u5bf9\u65b9\u514d\u75ab\u8bfb\u5fc3\u4fbf\u53ef\u987a\u5229\u53d1\u5c55\u3002", "line": "\u604b\u7231\uff1a\u5bf9\u65b9\u514d\u75ab\u8bfb\u5fc3\u4fbf\u53ef\u987a\u5229\u53d1\u5c55\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5730\u4e0b\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u5730\u4e0b\u4e3a\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u5730\u5e95\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5730\u5e95\u4e3a\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u72ec\u5904\u81ea\u5a31\u4e3a\u5409\u3002\u9972\u517b\u5ba0\u7269\u5219\u8fd0\u52bf\u5927\u6da8\u3002", "line": "\u7231\u597d\uff1a\u72ec\u5904\u81ea\u5a31\u4e3a\u5409\u3002\u9972\u517b\u5ba0\u7269\u5219\u8fd0\u52bf\u5927\u6da8\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (51, '火焰猫燐', '【大大凶】', '带着尸体走遍天涯海角', '带走尸体程度的能力', '["\u4eba\u7c7b\u90fd\u6709\u7740", "\u5171\u540c\u7684\u7ec8\u70b9\u3002", "\u4ee5\u540e\u4f60\u5c31\u7531", "\u6211\u6765\u7167\u6599\u5427\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u767e\u822c\u5384\u8fd0\u63a5\u8e35\u800c\u81f3\u3002\u6781\u5176\u5012\u9709\uff0c\u751a\u81f3\u4f1a\u6ce2\u53ca\u8eab\u8fb9\u4eba\u3002", "line": "\u8fd0\u52bf\uff1a\u767e\u822c\u5384\u8fd0\u63a5\u8e35\u800c\u81f3\u3002\u6781\u5176\u5012\u9709\uff0c\u751a\u81f3\u4f1a\u6ce2\u53ca\u8eab\u8fb9\u4eba\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5165\u4e0d\u6577\u51fa\uff0c\u82e6\u4e0d\u582a\u8a00\uff0c\u6070\u5982\u7f6e\u8eab\u706b\u8f66\u76f4\u901a\u5730\u72f1\n1\n\u3002\u7075\u8f66\u5219\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u5165\u4e0d\u6577\u51fa\uff0c\u82e6\u4e0d\u582a\u8a00\uff0c\u6070\u5982\u7f6e\u8eab\u706b\u8f66\u76f4\u901a\u5730\u72f1\n1\n\u3002\u7075\u8f66\u5219\u5409\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u7ecf\u6d4e\u62ee\u636e\uff0c\u5982\u706b\u7099\u8f66\u3002", "line": "\u8d22\u8fd0\uff1a\u7ecf\u6d4e\u62ee\u636e\uff0c\u5982\u706b\u7099\u8f66\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u82e5\u4e0d\u7528\u529f\uff0c\u77e5\u8bc6\u4fbf\u4f1a\u5feb\u901f\u9057\u5fd8\u3002", "line": "\u5b66\u4e1a\uff1a\u82e5\u4e0d\u7528\u529f\uff0c\u77e5\u8bc6\u4fbf\u4f1a\u5feb\u901f\u9057\u5fd8\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u4f1a\u88ab\u5f53\u6210\u6b7b\u4eba\uff0c\u4f46\u7cbe\u795e\u72b6\u51b5\u826f\u597d\u3002", "line": "\u5065\u5eb7\uff1a\u4f1a\u88ab\u5f53\u6210\u6b7b\u4eba\uff0c\u4f46\u7cbe\u795e\u72b6\u51b5\u826f\u597d\u3002"}, {"label": "\u604b\u7231", "text": "\u5b7d\u7f18\u96be\u65ad\uff0c\u8150\u800c\u4e0d\u706d\u3002", "line": "\u604b\u7231\uff1a\u5b7d\u7f18\u96be\u65ad\uff0c\u8150\u800c\u4e0d\u706d\u3002"}, {"label": "\u51fa\u884c", "text": "\u575f\u573a\u3001\u5bfa\u5e99\u3001\u53e4\u5893\u3001\u81ea\u6740\u5723\u5730\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u575f\u573a\u3001\u5bfa\u5e99\u3001\u53e4\u5893\u3001\u81ea\u6740\u5723\u5730\u4e3a\u5409\u3002"}, {"label": "\u4e89\u7aef", "text": "\u6028\u5ff5\u4e91\u96c6\u3002", "line": "\u4e89\u7aef\uff1a\u6028\u5ff5\u4e91\u96c6\u3002"}, {"label": "\u4f4f\u6240", "text": "\u6050\u6709\u706b\u707e\u3002", "line": "\u4f4f\u6240\uff1a\u6050\u6709\u706b\u707e\u3002"}, {"label": "\u7231\u597d", "text": "\u9972\u517b\u9ed1\u732b\u53ef\u7f13\u89e3\u5384\u8fd0\u3002", "line": "\u7231\u597d\uff1a\u9972\u517b\u9ed1\u732b\u53ef\u7f13\u89e3\u5384\u8fd0\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (52, '灵乌路空', '大凶、部分大吉', '炽热难驭的究极能源鸦', '操纵核聚变程度的能力', '["\u82e5\u662f\u6562\u5bf9\u6211", "\u62d4\u5200\u6765\u76f8\u5411\uff0c", "\u4f60\u5c31\u662f\u4e0b\u4e2a", "\u4f0a\u5361\u6d1b\u65af\u54af\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u72c2\u66b4\u6c14\u8fd0\u65e0\u4eba\u80fd\u9a6d\u3002\u672a\u6765\u65e0\u6cd5\u9884\u6d4b\u3002", "line": "\u8fd0\u52bf\uff1a\u72c2\u66b4\u6c14\u8fd0\u65e0\u4eba\u80fd\u9a6d\u3002\u672a\u6765\u65e0\u6cd5\u9884\u6d4b\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5f7b\u5e95\u6e6e\u706d\u3002 \u968f\u540e\u66f4\u4e3a\u5f3a\u5927\u7684\u5de5\u4f5c\u81ea\u4f1a\u8bde\u751f\u3002", "line": "\u5de5\u4f5c\uff1a\u5f7b\u5e95\u6e6e\u706d\u3002 \u968f\u540e\u66f4\u4e3a\u5f3a\u5927\u7684\u5de5\u4f5c\u81ea\u4f1a\u8bde\u751f\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6781\u5c0f\u6982\u7387\u5b9e\u73b0\u8d22\u5bcc\u7206\u70b8\u5f0f\u589e\u957f\u3002", "line": "\u8d22\u8fd0\uff1a\u6781\u5c0f\u6982\u7387\u5b9e\u73b0\u8d22\u5bcc\u7206\u70b8\u5f0f\u589e\u957f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7206\u6bd9\u3002", "line": "\u5b66\u4e1a\uff1a\u7206\u6bd9\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u7cbe\u529b\u4e0e\u4f53\u529b\u7686\u65e0\u7a77\u5c3d\u3002", "line": "\u5065\u5eb7\uff1a\u7cbe\u529b\u4e0e\u4f53\u529b\u7686\u65e0\u7a77\u5c3d\u3002"}, {"label": "\u4f4f\u6240", "text": "\u672a\u96e8\u7ef8\u7f2a\uff0c\u9632\u5907\u706b\u5c71\u55b7\u53d1\u3001\u5730\u9707\u7b49\u5404\u79cd\u5929\u707e\u3002", "line": "\u4f4f\u6240\uff1a\u672a\u96e8\u7ef8\u7f2a\uff0c\u9632\u5907\u706b\u5c71\u55b7\u53d1\u3001\u5730\u9707\u7b49\u5404\u79cd\u5929\u707e\u3002"}, {"label": "\u5bfb\u7269", "text": "\u9057\u5931\u4e4b\u7269\u7070\u98de\u70df\u706d\u3002", "line": "\u5bfb\u7269\uff1a\u9057\u5931\u4e4b\u7269\u7070\u98de\u70df\u706d\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5d07\u5c1a\u5b9e\u529b\u8005\u7eb7\u81f3\u6c93\u6765\u3002", "line": "\u4eba\u7f18\uff1a\u5d07\u5c1a\u5b9e\u529b\u8005\u7eb7\u81f3\u6c93\u6765\u3002"}, {"label": "\u7231\u597d", "text": "\u8db3\u7403\u4e3a\u5409\u3002\u89c2\u6218\u4ea6\u5584\u3002", "line": "\u7231\u597d\uff1a\u8db3\u7403\u4e3a\u5409\u3002\u89c2\u6218\u4ea6\u5584\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (53, '古明地恋', '不明', '不再读心的妖怪', '操纵无意识程度的能力', '["\u4e16\u754c\u7684\u6df1\u6e0a", "\u5c31\u5728\u773c\u524d\u54e6\u3002", "\u8981\u662f\u6389\u4e0b\u53bb\uff0c", "\u6211\u53ef\u4e0d\u7ba1\u4f60\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7eb5\u6709\u795e\u660e\u4e4b\u529b\uff0c\u4ea6\u4e0d\u80fd\u770b\u6e05\u672a\u6765\uff0c\u5b9e\u5c5e\u9057\u61be\u3002", "line": "\u8fd0\u52bf\uff1a\u7eb5\u6709\u795e\u660e\u4e4b\u529b\uff0c\u4ea6\u4e0d\u80fd\u770b\u6e05\u672a\u6765\uff0c\u5b9e\u5c5e\u9057\u61be\u3002"}, {"label": "\u4ea4\u6613", "text": "\u524d\u9014\u53f5\u6d4b\u3002\u628a\u63e1\u5546\u673a\u96be\u4e8e\u767b\u5929\u3002", "line": "\u4ea4\u6613\uff1a\u524d\u9014\u53f5\u6d4b\u3002\u628a\u63e1\u5546\u673a\u96be\u4e8e\u767b\u5929\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0e\u52a8\u7269\u6253\u4ea4\u9053\u7684\u5de5\u4f5c\u4e3a\u5b9c\u3002\u4e0d\u9002\u5408\u4e0e\u4eba\u4ea4\u9645\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0e\u52a8\u7269\u6253\u4ea4\u9053\u7684\u5de5\u4f5c\u4e3a\u5b9c\u3002\u4e0d\u9002\u5408\u4e0e\u4eba\u4ea4\u9645\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e00\u584c\u7cca\u6d82\u3002\u5fc3\u7406\u5b66\u3001\u54f2\u5b66\u5219\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u4e00\u584c\u7cca\u6d82\u3002\u5fc3\u7406\u5b66\u3001\u54f2\u5b66\u5219\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5b9c\u72ec\u81ea\u65c5\u884c\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u72ec\u81ea\u65c5\u884c\u3002"}, {"label": "\u604b\u7231", "text": "\u88ab\u5bf9\u65b9\u65e0\u89c6\u3002", "line": "\u604b\u7231\uff1a\u88ab\u5bf9\u65b9\u65e0\u89c6\u3002"}, {"label": "\u5065\u5eb7", "text": "\u7cbe\u795e\u72b6\u6001\u826f\u597d\u3002\u5f53\u5fc3\u8dcc\u6253\u635f\u4f24\u3002", "line": "\u5065\u5eb7\uff1a\u7cbe\u795e\u72b6\u6001\u826f\u597d\u3002\u5f53\u5fc3\u8dcc\u6253\u635f\u4f24\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e0e\u4ed6\u4eba\u4e0d\u76f8\u5f80\u6765\u3002", "line": "\u4eba\u7f18\uff1a\u4e0e\u4ed6\u4eba\u4e0d\u76f8\u5f80\u6765\u3002"}, {"label": "\u5bfb\u7269", "text": "\u8ff7\u5931\u81ea\u6211\u3002", "line": "\u5bfb\u7269\uff1a\u8ff7\u5931\u81ea\u6211\u3002"}, {"label": "\u4f4f\u6240", "text": "\u968f\u9047\u800c\u5b89\u3002", "line": "\u4f4f\u6240\uff1a\u968f\u9047\u800c\u5b89\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u89c2\u5bdf\u4eba\u7c7b\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u89c2\u5bdf\u4eba\u7c7b\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (54, '娜兹玲', '小吉', '宝藏猎手鼠', '寻物必见程度的能力', '["\u96f7\u58f0\u64bc\u5c71\u54cd\uff0c", "\u96e8\u4e1d\u5982\u9f20\u987b\u3002", "\u5904\u53d8\u800c\u4e0d\u60ca\uff0c", "\u65b9\u80fd\u6709\u6240\u6210\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e0d\u597d\u4e0d\u574f\u3002\u666e\u666e\u901a\u901a\u3002", "line": "\u8fd0\u52bf\uff1a\u4e0d\u597d\u4e0d\u574f\u3002\u666e\u666e\u901a\u901a\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5f97\u4ee5\u5bfb\u56de\u3002 \u751a\u81f3\u8fd8\u80fd\u5bfb\u5f97\u610f\u5916\u6536\u83b7\u3002", "line": "\u5bfb\u7269\uff1a\u5f97\u4ee5\u5bfb\u56de\u3002 \u751a\u81f3\u8fd8\u80fd\u5bfb\u5f97\u610f\u5916\u6536\u83b7\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5c0f\u5fc3\u611f\u67d3\u3002", "line": "\u5065\u5eb7\uff1a\u5c0f\u5fc3\u611f\u67d3\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u540d\u5217\u524d\u8305\u3002 \u5f53\u52e4\u52c9\u52aa\u529b\uff0c\u518d\u4e0a\u5c42\u697c\u3002", "line": "\u5b66\u4e1a\uff1a\u540d\u5217\u524d\u8305\u3002 \u5f53\u52e4\u52c9\u52aa\u529b\uff0c\u518d\u4e0a\u5c42\u697c\u3002"}], [{"label": "\u5bb6\u5ead", "text": "\u4eba\u4e01\u5174\u65fa\u3002 \u6bcf\u5929\u90fd\u70ed\u70ed\u95f9\u95f9\u3002", "line": "\u5bb6\u5ead\uff1a\u4eba\u4e01\u5174\u65fa\u3002 \u6bcf\u5929\u90fd\u70ed\u70ed\u95f9\u95f9\u3002"}, {"label": "\u519c\u4e1a", "text": "\u6b49\u6536\u3002", "line": "\u519c\u4e1a\uff1a\u6b49\u6536\u3002"}, {"label": "\u98df\u7269", "text": "\u591a\u591a\u50a8\u5907\u3002", "line": "\u98df\u7269\uff1a\u591a\u591a\u50a8\u5907\u3002"}, {"label": "\u8c37\u7269", "text": "\u5c24\u4e3a\u77ed\u7f3a\u3002", "line": "\u8c37\u7269\uff1a\u5c24\u4e3a\u77ed\u7f3a\u3002"}, {"label": "\u6c34\u8109", "text": "\u5f97\u4ee5\u5bfb\u83b7\u3002", "line": "\u6c34\u8109\uff1a\u5f97\u4ee5\u5bfb\u83b7\u3002"}, {"label": "\u91d1\u8109", "text": "\u5f97\u4ee5\u5bfb\u83b7\uff0c\u5927\u6982\u3002", "line": "\u91d1\u8109\uff1a\u5f97\u4ee5\u5bfb\u83b7\uff0c\u5927\u6982\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (55, '多多良小伞', '中吉', '常伴唐伞左右的妖怪', '惊吓人类程度的能力', '["\u8d8a\u6765\u8d8a\u591a\u4eba", "\u6674\u5929\u6253\u4f1e\u5566\u3002", "\u8fd9\u662f\u7d2b\u5916\u7ebf", "\u7acb\u7684\u529f\u52b3\u5417\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u77ed\u671f\u95f4\u5185\u60ca\u8bb6\u8fde\u8fde\uff0c\u4f46\u5e76\u65e0\u5371\u5bb3\u3002 \u4e0d\u59a8\u4e50\u5728\u5176\u4e2d\u3002", "line": "\u8fd0\u52bf\uff1a\u77ed\u671f\u95f4\u5185\u60ca\u8bb6\u8fde\u8fde\uff0c\u4f46\u5e76\u65e0\u5371\u5bb3\u3002 \u4e0d\u59a8\u4e50\u5728\u5176\u4e2d\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9002\u5408\u953b\u94c1\u3002", "line": "\u4ea4\u6613\uff1a\u9002\u5408\u953b\u94c1\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8003\u8bd5\u5206\u6570\u60ca\u4eba\u3002", "line": "\u5b66\u4e1a\uff1a\u8003\u8bd5\u5206\u6570\u60ca\u4eba\u3002"}, {"label": "\u604b\u7231", "text": "\u51c6\u5907\u60ca\u559c\u4e3a\u4e0a\uff0c\u522b\u65e0\u4ed6\u9009\u3002\u5feb\u95ea\u8868\u6f14\u4ea6\u5409\u3002", "line": "\u604b\u7231\uff1a\u51c6\u5907\u60ca\u559c\u4e3a\u4e0a\uff0c\u522b\u65e0\u4ed6\u9009\u3002\u5feb\u95ea\u8868\u6f14\u4ea6\u5409\u3002"}, {"label": "\u75be\u75c5", "text": "\u5c0f\u5fc3\u773c\u75be\u3002", "line": "\u75be\u75c5\uff1a\u5c0f\u5fc3\u773c\u75be\u3002"}], [{"label": "\u51fa\u884c", "text": "\u96e8\u6c34\u8fde\u8fde\u3002", "line": "\u51fa\u884c\uff1a\u96e8\u6c34\u8fde\u8fde\u3002"}, {"label": "\u5bfb\u7269", "text": "\u96e8\u4f1e\u52a1\u5fc5\u968f\u8eab\u643a\u5e26\u3002", "line": "\u5bfb\u7269\uff1a\u96e8\u4f1e\u52a1\u5fc5\u968f\u8eab\u643a\u5e26\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5c06\u9057\u5931\u94b1\u5305\uff0c\u5e94\u628a\u4e1c\u897f\u5168\u90e8\u53d6\u51fa\u3002", "line": "\u8d22\u8fd0\uff1a\u5c06\u9057\u5931\u94b1\u5305\uff0c\u5e94\u628a\u4e1c\u897f\u5168\u90e8\u53d6\u51fa\u3002"}, {"label": "\u4e89\u7aef", "text": "\u65e0\u53ef\u7f6e\u5599\u3002", "line": "\u4e89\u7aef\uff1a\u65e0\u53ef\u7f6e\u5599\u3002"}, {"label": "\u751f\u80b2", "text": "\u751f\u4ea7\u987a\u5229\u3002\u5bb6\u5ead\u7f8e\u6ee1\u3002", "line": "\u751f\u80b2\uff1a\u751f\u4ea7\u987a\u5229\u3002\u5bb6\u5ead\u7f8e\u6ee1\u3002"}, {"label": "\u707e\u5bb3", "text": "\u672a\u96e8\u7ef8\u7f2a\uff0c\u9632\u5907\u72c2\u98ce\u66b4\u96e8\u3002\u65e0\u5907\u5fc5\u6709\u60a3\u3002", "line": "\u707e\u5bb3\uff1a\u672a\u96e8\u7ef8\u7f2a\uff0c\u9632\u5907\u72c2\u98ce\u66b4\u96e8\u3002\u65e0\u5907\u5fc5\u6709\u60a3\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (56, '云居一轮&云山', '末大吉', '入道老爹和洋气入道使', '驱使入道程度的能力
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (57, '村纱水蜜', '【大大凶】', '想拖人下水的船幽灵', '引发水难事故程度的能力', '["\u7834\u6c34\u52fa\u53ef\u4ee5", "\u5bf9\u4ed8\u8239\u5e7d\u7075", "1", "\uff0c", "\u8fd9\u8822\u8bdd\u662f\u8c01", "\u7f16\u51fa\u6765\u7684\u554a\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6050\u906d\u4e8b\u6545\u3002\u6b64\u5916\u4ea6\u6709\u6c34\u5384\u4e4b\u76f8\u3002", "line": "\u8fd0\u52bf\uff1a\u6050\u906d\u4e8b\u6545\u3002\u6b64\u5916\u4ea6\u6709\u6c34\u5384\u4e4b\u76f8\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5fcc\u9157\u9152\u3002\u5207\u5fcc\u53d7\u5bd2\uff0c\u7136\u6ce1\u6fa1\u4ea6\u5371\u3002", "line": "\u5065\u5eb7\uff1a\u5fcc\u9157\u9152\u3002\u5207\u5fcc\u53d7\u5bd2\uff0c\u7136\u6ce1\u6fa1\u4ea6\u5371\u3002"}, {"label": "\u51fa\u884c", "text": "\u5fcc\u4e58\u8239\u3001\u8fd1\u6c34\u3002\u5b9c\u524d\u5f80\u5c71\u5730\u3001\u6c99\u6f20\u3002", "line": "\u51fa\u884c\uff1a\u5fcc\u4e58\u8239\u3001\u8fd1\u6c34\u3002\u5b9c\u524d\u5f80\u5c71\u5730\u3001\u6c99\u6f20\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6df1\u9677\u6ce5\u6f6d\u3002", "line": "\u5b66\u4e1a\uff1a\u6df1\u9677\u6ce5\u6f6d\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u6e14\u4e1a\u9700\u5c0f\u5fc3\u4e8b\u6545\uff0c\u65e0\u4e8b\u5219\u4e00\u5207\u5b89\u7a33\u3002", "line": "\u4ea4\u6613\uff1a\u6e14\u4e1a\u9700\u5c0f\u5fc3\u4e8b\u6545\uff0c\u65e0\u4e8b\u5219\u4e00\u5207\u5b89\u7a33\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5b58\u6b3e\u635f\u5931\u60e8\u91cd\uff0c\u5982\u5760\u65e0\u5e95\u6df1\u6e0a\u3002", "line": "\u8d22\u8fd0\uff1a\u5b58\u6b3e\u635f\u5931\u60e8\u91cd\uff0c\u5982\u5760\u65e0\u5e95\u6df1\u6e0a\u3002"}, {"label": "\u604b\u7231", "text": "\u6df1\u9677\u7231\u6cb3\uff0c\u96be\u4ee5\u81ea\u62d4\u3002", "line": "\u604b\u7231\uff1a\u6df1\u9677\u7231\u6cb3\uff0c\u96be\u4ee5\u81ea\u62d4\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5931\u7269\u843d\u6c34\uff0c\u4f46\u4e07\u4e07\u4e0d\u53ef\u4e0b\u6c34\u5bfb\u627e\u3002", "line": "\u5bfb\u7269\uff1a\u5931\u7269\u843d\u6c34\uff0c\u4f46\u4e07\u4e07\u4e0d\u53ef\u4e0b\u6c34\u5bfb\u627e\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (58, '寅丸星', '大吉', '乘着宝船的七福神弟子', '招财进宝程度的能力', '["\u5b9d\u8239\u4e4b\u4e0a\uff0c", "\u4f60\u60f3\u8981\u7684", "\u4e00\u5207\u73cd\u54c1", "\u5e94\u6709\u5c3d\u6709\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8d22\u8fd0\u4ea8\u901a\uff0c\u4e14\u4f1a\u5e26\u6765\u79cd\u79cd\u597d\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u8d22\u8fd0\u4ea8\u901a\uff0c\u4e14\u4f1a\u5e26\u6765\u79cd\u79cd\u597d\u8fd0\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5929\u8d50\u826f\u673a\u3002\u6b64\u65f6\u4e0d\u6323\uff0c\u66f4\u5f85\u4f55\u65f6\uff1f", "line": "\u8d22\u8fd0\uff1a\u5929\u8d50\u826f\u673a\u3002\u6b64\u65f6\u4e0d\u6323\uff0c\u66f4\u5f85\u4f55\u65f6\uff1f"}, {"label": "\u4ea4\u6613", "text": "\u82e5\u4ece\u4e8b\u670d\u52a1\u4e1a\uff0c\u5219\u4e1a\u7ee9\u84b8\u84b8\u65e5\u4e0a\u3002\u5b9d\u77f3\u3001\u53e4\u8463\u884c\u4e1a\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u82e5\u4ece\u4e8b\u670d\u52a1\u4e1a\uff0c\u5219\u4e1a\u7ee9\u84b8\u84b8\u65e5\u4e0a\u3002\u5b9d\u77f3\u3001\u53e4\u8463\u884c\u4e1a\u4e3a\u5927\u5409\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u4f5b\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u4f5b\u5b66\u4e3a\u5409\u3002"}, {"label": "\u5bfb\u7269", "text": "\u9057\u5931\u8d35\u91cd\u5b9d\u7269\uff0c\u4e0b\u5c5e\u4ee3\u4e3a\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u9057\u5931\u8d35\u91cd\u5b9d\u7269\uff0c\u4e0b\u5c5e\u4ee3\u4e3a\u5bfb\u56de\u3002"}, {"label": "\u604b\u7231", "text": "\u9082\u9005\u4e0d\u65ad\u3002\u7ea0\u7eb7\u96be\u514d\u3002", "line": "\u604b\u7231\uff1a\u9082\u9005\u4e0d\u65ad\u3002\u7ea0\u7eb7\u96be\u514d\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u8239\u65c5\u3002\u8c6a\u534e\u5ba2\u8239\u5c24\u4f73\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u8239\u65c5\u3002\u8c6a\u534e\u5ba2\u8239\u5c24\u4f73\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4ece\u4e0d\u611f\u5192\u3002", "line": "\u5065\u5eb7\uff1a\u4ece\u4e0d\u611f\u5192\u3002"}, {"label": "\u65b9\u4f4d", "text": "\u5317\u65b9\u4e3a\u5409\u3002", "line": "\u65b9\u4f4d\uff1a\u5317\u65b9\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (59, '圣白莲', '吉', '超人阿阇梨', '使用魔法（身体强化为主）程度的能力', '["\u6b32\u8131\u79bb\u82e6\u6d77\uff0c", "\u5f53\u65ad\u60c5\u7edd\u6b32\u3002", "\u7cbe\u8fdb\u4fee\u884c\uff0c", "\u65b9\u53ef\u6b63\u6027\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u82e5\u8981\u83b7\u5f97\u5e78\u798f\uff0c\u5219\u5f53\u6452\u5f03\u6b32\u671b\u3002\u5fc3\u65e0\u6e34\u76fc\uff0c\u5219\u5e78\u798f\u5e38\u5b58\u3002", "line": "\u8fd0\u52bf\uff1a\u82e5\u8981\u83b7\u5f97\u5e78\u798f\uff0c\u5219\u5f53\u6452\u5f03\u6b32\u671b\u3002\u5fc3\u65e0\u6e34\u76fc\uff0c\u5219\u5e78\u798f\u5e38\u5b58\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u4f53\u7d20\u8d28\u8d85\u5f3a\uff0c\u4ece\u4e0d\u611f\u5192\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u4f53\u7d20\u8d28\u8d85\u5f3a\uff0c\u4ece\u4e0d\u611f\u5192\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u8fd0\u52a8\u5458\u3001\u4f53\u529b\u52b3\u52a8\u8005\u3001\u50e7\u4fa3\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u8fd0\u52a8\u5458\u3001\u4f53\u529b\u52b3\u52a8\u8005\u3001\u50e7\u4fa3\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5168\u9762\u63d0\u5347\u3002\u4f53\u80b2\u8fdb\u6b65\u5c24\u4e3a\u663e\u8457\u3002", "line": "\u5b66\u4e1a\uff1a\u5168\u9762\u63d0\u5347\u3002\u4f53\u80b2\u8fdb\u6b65\u5c24\u4e3a\u663e\u8457\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u5fc3\u751f\u8d2a\u5ff5\u5219\u5fc5\u5c06\u5931\u8d25\u3002", "line": "\u4ea4\u6613\uff1a\u5fc3\u751f\u8d2a\u5ff5\u5219\u5fc5\u5c06\u5931\u8d25\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5b9c\u4ece\u7b80\u3002", "line": "\u4f4f\u6240\uff1a\u5b9c\u4ece\u7b80\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u94b1\u8d22\u4e0d\u62db\u81ea\u6765\u3002\u5fc3\u751f\u8d2a\u5ff5\u5219\u8d22\u6e90\u67af\u7aed\u3002", "line": "\u8d22\u8fd0\uff1a\u94b1\u8d22\u4e0d\u62db\u81ea\u6765\u3002\u5fc3\u751f\u8d2a\u5ff5\u5219\u8d22\u6e90\u67af\u7aed\u3002"}, {"label": "\u604b\u7231", "text": "\u7981\u6b62\u3002", "line": "\u604b\u7231\uff1a\u7981\u6b62\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e27\u5931\u6b32\u671b\u3002", "line": "\u5bfb\u7269\uff1a\u4e27\u5931\u6b32\u671b\u3002"}, {"label": "\u51fa\u884c", "text": "\u5730\u65b9\u90fd\u5e02\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5730\u65b9\u90fd\u5e02\u4e3a\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u6284\u5199\u7ecf\u4e66\u3001\u6258\u94b5\u5316\u7f18\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u6284\u5199\u7ecf\u4e66\u3001\u6258\u94b5\u5316\u7f18\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u56e0\u6258\u94b5\u5316\u7f18\u800c\u5907\u53d7\u5acc\u5f03\u3002", "line": "\u4eba\u7f18\uff1a\u56e0\u6258\u94b5\u5316\u7f18\u800c\u5907\u53d7\u5acc\u5f03\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (60, '封兽鵺', '凶', '原形不明的怪物', '使原形无法识别程度的能力', '["\u6211\u771f\u8eab\u5230\u5e95", "\u662f\u54ea\u79cd\u52a8\u7269\uff1f", "\u95ee\u8fd9\u4e2a\u53ef\u662f", "\u4fb5\u72af\u9690\u79c1\u54e6\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6574\u4f53\u6781\u4e3a\u4e0d\u7965\uff0c\u4f46\u6df7\u6c8c\u4e4b\u4e2d\u4ea6\u6709\u539f\u5f62\u4e0d\u660e\u7684\u795e\u79d8\u5149\u8292\u3002", "line": "\u8fd0\u52bf\uff1a\u6574\u4f53\u6781\u4e3a\u4e0d\u7965\uff0c\u4f46\u6df7\u6c8c\u4e4b\u4e2d\u4ea6\u6709\u539f\u5f62\u4e0d\u660e\u7684\u795e\u79d8\u5149\u8292\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5fd9\u5f97\u4e0d\u53ef\u5f00\u4ea4\u3002\u5b66\u8005\u3001\u653f\u6cbb\u5bb6\u3001\u5b97\u6559\u5bb6\u5c24\u51f6\u3002\u5bc6\u63a2\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5fd9\u5f97\u4e0d\u53ef\u5f00\u4ea4\u3002\u5b66\u8005\u3001\u653f\u6cbb\u5bb6\u3001\u5b97\u6559\u5bb6\u5c24\u51f6\u3002\u5bc6\u63a2\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u83ab\u540d\u5176\u5999\u7cca\u91cc\u7cca\u6d82\u3002\u795e\u79d8\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u83ab\u540d\u5176\u5999\u7cca\u91cc\u7cca\u6d82\u3002\u795e\u79d8\u5b66\u4e3a\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u592a\u7a7a\u65c5\u884c\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u592a\u7a7a\u65c5\u884c\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u9690\u75be\u85cf\u800c\u4e0d\u663e\u3002", "line": "\u5065\u5eb7\uff1a\u9690\u75be\u85cf\u800c\u4e0d\u663e\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u56e0\u67d3\u6307\u6765\u5386\u4e0d\u660e\u4e4b\u8d22\u800c\u9677\u5165\u5371\u673a\u3002", "line": "\u8d22\u8fd0\uff1a\u56e0\u67d3\u6307\u6765\u5386\u4e0d\u660e\u4e4b\u8d22\u800c\u9677\u5165\u5371\u673a\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5f97\u9047\u5947\u7f18\u3002", "line": "\u59fb\u7f18\uff1a\u5f97\u9047\u5947\u7f18\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e22\u4e09\u843d\u56db\u3002\u8eab\u65c1\u4e4b\u4eba\u4ea6\u5c06\u5931\u7269\u9891\u53d1\u3002", "line": "\u5bfb\u7269\uff1a\u4e22\u4e09\u843d\u56db\u3002\u8eab\u65c1\u4e4b\u4eba\u4ea6\u5c06\u5931\u7269\u9891\u53d1\u3002"}, {"label": "\u7231\u597d", "text": "\u53ef\u5728\u5c14\u865e\u6211\u8bc8\u7684\u6e38\u620f\u4e2d\u5927\u6740\u56db\u65b9\u3002", "line": "\u7231\u597d\uff1a\u53ef\u5728\u5c14\u865e\u6211\u8bc8\u7684\u6e38\u620f\u4e2d\u5927\u6740\u56db\u65b9\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (61, '姬海棠果', '小吉', '被炉里的洗稿天狗', '使用念写程度的能力', '["\u5c45\u5bb6\u4e0d\u51fa\u95e8\uff0c", "\u4fbf\u77e5\u5929\u4e0b\u4e8b\u3002", "\u8fd9\u7b49\u597d\u65f6\u4ee3\uff0c", "\u8ba9\u6211\u8d76\u4e0a\u5566\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u504f\u597d\u95ed\u95e8\u4e0d\u51fa\u3002\u4e00\u6627\u8ffd\u6c42\u6548\u7387\uff0c\u53cd\u800c\u4f5c\u8327\u81ea\u7f1a\u3002", "line": "\u8fd0\u52bf\uff1a\u504f\u597d\u95ed\u95e8\u4e0d\u51fa\u3002\u4e00\u6627\u8ffd\u6c42\u6548\u7387\uff0c\u53cd\u800c\u4f5c\u8327\u81ea\u7f1a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u9700\u8981\u51fa\u52e4\u7684\u5de5\u4f5c\u7686\u51f6\u3002\u6563\u6587\u5bb6\u3001\u4f9b\u7a3f\u4eba\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u9700\u8981\u51fa\u52e4\u7684\u5de5\u4f5c\u7686\u51f6\u3002\u6563\u6587\u5bb6\u3001\u4f9b\u7a3f\u4eba\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9a6c\u9a6c\u864e\u864e\u6709\u6240\u957f\u8fdb\uff0c\u6587\u79d1\u5c24\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u9a6c\u9a6c\u864e\u864e\u6709\u6240\u957f\u8fdb\uff0c\u6587\u79d1\u5c24\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u80a9\u9888\u6613\u9178\u75db\u3002", "line": "\u5065\u5eb7\uff1a\u80a9\u9888\u6613\u9178\u75db\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5916\u51fa\u5373\u51f6\uff0c\u5371\u673a\u56db\u4f0f\u3002\u5c45\u5bb6\u4e3a\u4e0a\u3002", "line": "\u51fa\u884c\uff1a\u5916\u51fa\u5373\u51f6\uff0c\u5371\u673a\u56db\u4f0f\u3002\u5c45\u5bb6\u4e3a\u4e0a\u3002"}, {"label": "\u604b\u7231", "text": "\u5c31\u8fde\u9082\u9005\u7684\u673a\u4f1a\u90fd\u6ca1\u6709\u3002", "line": "\u604b\u7231\uff1a\u5c31\u8fde\u9082\u9005\u7684\u673a\u4f1a\u90fd\u6ca1\u6709\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e0e\u65e0\u9700\u89c1\u9762\u4e4b\u4eba\u76f8\u5904\u878d\u6d3d\u3002", "line": "\u4eba\u7f18\uff1a\u4e0e\u65e0\u9700\u89c1\u9762\u4e4b\u4eba\u76f8\u5904\u878d\u6d3d\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5fc5\u5728\u5bb6\u4e2d\u3002", "line": "\u5bfb\u7269\uff1a\u5fc5\u5728\u5bb6\u4e2d\u3002"}, {"label": "\u4e89\u7aef", "text": "\u96be\u5f97\u4e00\u9047\u3002", "line": "\u4e89\u7aef\uff1a\u96be\u5f97\u4e00\u9047\u3002"}, {"label": "\u7231\u597d", "text": "\u4f55\u4e0d\u8bd5\u8bd5\u5916\u51fa\u6444\u5f71\u3002", "line": "\u7231\u597d\uff1a\u4f55\u4e0d\u8bd5\u8bd5\u5916\u51fa\u6444\u5f71\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (62, '桑尼米尔克', '小吉', '顽皮日光妖精', '折射光线程度的能力', '["\u5929\u6c14\u8fd9\u4e48\u597d\uff0c", "\u600e\u4e48\u4e0d\u51fa\u95e8\uff1f", "\u4f60\u8be5\u4e0d\u4f1a\u662f", "\u7fd8\u8fab\u5b50\u4e86\u5427\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u884c\u52a8\u529b\u589e\u5f3a\u3002\u53d7\u6b64\u5f71\u54cd\uff0c\u5c61\u5c61\u78b0\u58c1\u3002", "line": "\u8fd0\u52bf\uff1a\u884c\u52a8\u529b\u589e\u5f3a\u3002\u53d7\u6b64\u5f71\u54cd\uff0c\u5c61\u5c61\u78b0\u58c1\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u610f\u5916\u53d1\u6325\u9886\u5bfc\u80fd\u529b\u3002\u6700\u7ec8\u5931\u8d25\u4e5f\u65e0\u4eba\u602a\u7f6a\u3002", "line": "\u5de5\u4f5c\uff1a\u610f\u5916\u53d1\u6325\u9886\u5bfc\u80fd\u529b\u3002\u6700\u7ec8\u5931\u8d25\u4e5f\u65e0\u4eba\u602a\u7f6a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u65ad\u5ff5\u4e3a\u5999\u3002\u5149\u5b66\u5c1a\u53ef\u3002", "line": "\u5b66\u4e1a\uff1a\u65ad\u5ff5\u4e3a\u5999\u3002\u5149\u5b66\u5c1a\u53ef\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8def\u8fb9\u6446\u644a\u53ef\u6323\u5927\u94b1\u3002", "line": "\u4ea4\u6613\uff1a\u8def\u8fb9\u6446\u644a\u53ef\u6323\u5927\u94b1\u3002"}, {"label": "\u5065\u5eb7", "text": "\u751f\u9f99\u6d3b\u864e\u3002\u70e6\u607c\u4e00\u626b\u800c\u7a7a\u3002", "line": "\u5065\u5eb7\uff1a\u751f\u9f99\u6d3b\u864e\u3002\u70e6\u607c\u4e00\u626b\u800c\u7a7a\u3002"}], [{"label": "\u604b\u7231", "text": "\u4e00\u5e06\u98ce\u987a\uff0c\u5982\u6709\u5929\u610f\u6349\u5f04\u3002", "line": "\u604b\u7231\uff1a\u4e00\u5e06\u98ce\u987a\uff0c\u5982\u6709\u5929\u610f\u6349\u5f04\u3002"}, {"label": "\u51fa\u884c", "text": "\u5feb\u4e50\u5c31\u5728\u4e0d\u8fdc\u5904\u3002", "line": "\u51fa\u884c\uff1a\u5feb\u4e50\u5c31\u5728\u4e0d\u8fdc\u5904\u3002"}, {"label": "\u4e89\u7aef", "text": "\u6349\u8ff7\u85cf\u6240\u5411\u65e0\u654c\u3002\u9664\u6b64\u4e4b\u5916\u6709\u8f93\u65e0\u8d62\u3002", "line": "\u4e89\u7aef\uff1a\u6349\u8ff7\u85cf\u6240\u5411\u65e0\u654c\u3002\u9664\u6b64\u4e4b\u5916\u6709\u8f93\u65e0\u8d62\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5e78\u9047\u77e5\u5df1\u540c\u4f34\u3002", "line": "\u4eba\u7f18\uff1a\u5e78\u9047\u77e5\u5df1\u540c\u4f34\u3002"}, {"label": "\u5bfb\u7269", "text": "\u706f\u4e0b\u9ed1\u3002", "line": "\u5bfb\u7269\uff1a\u706f\u4e0b\u9ed1\u3002"}, {"label": "\u4f4f\u6240", "text": "\u7a97\u6237\u655e\u4eae\u7684\u623f\u95f4\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u7a97\u6237\u655e\u4eae\u7684\u623f\u95f4\u4e3a\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u6240\u683d\u690d\u7269\u7686\u80fd\u8301\u58ee\u6210\u957f\u3002", "line": "\u7231\u597d\uff1a\u6240\u683d\u690d\u7269\u7686\u80fd\u8301\u58ee\u6210\u957f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (63, '露娜切露德', '小小吉', '静谧月光妖精', '消除周围声音程度的能力', '["\u6708\u5149\u7167\u8000\u4e0b\uff0c", "\u4e16\u4e0a\u7684\u4e00\u5207", "\u51e0\u4e4e\u90fd\u8981\u6bd4", "\u65e5\u95f4\u66f4\u7f8e\u4e3d\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e0\u8bba\u6709\u4f55\u53d8\u6545\uff0c\u4fdd\u6301\u6c89\u9ed8\u4fbf\u80fd\u5316\u9669\u4e3a\u5937\u3002\u6c89\u9ed8\u662f\u91d1\u3002", "line": "\u8fd0\u52bf\uff1a\u65e0\u8bba\u6709\u4f55\u53d8\u6545\uff0c\u4fdd\u6301\u6c89\u9ed8\u4fbf\u80fd\u5316\u9669\u4e3a\u5937\u3002\u6c89\u9ed8\u662f\u91d1\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u56f0\u96be\u91cd\u91cd\u3002\u5f00\u5377\u6709\u76ca\u3002", "line": "\u5b66\u4e1a\uff1a\u56f0\u96be\u91cd\u91cd\u3002\u5f00\u5377\u6709\u76ca\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u804c\u573a\u9759\u8c27\u4e3a\u5b9c\u3002\u56fe\u4e66\u7ba1\u7406\u5458\u3001\u4f5c\u66f2\u5bb6\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u804c\u573a\u9759\u8c27\u4e3a\u5b9c\u3002\u56fe\u4e66\u7ba1\u7406\u5458\u3001\u4f5c\u66f2\u5bb6\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u57fa\u672c\u65e0\u788d\u3002\u53d7\u6708\u76f8\u76c8\u4e8f\u5f71\u54cd\u8f83\u5927\u3002", "line": "\u5065\u5eb7\uff1a\u57fa\u672c\u65e0\u788d\u3002\u53d7\u6708\u76f8\u76c8\u4e8f\u5f71\u54cd\u8f83\u5927\u3002"}], [{"label": "\u51fa\u884c", "text": "\u591c\u95f4\u65c5\u884c\u4e3a\u4f73\u3002", "line": "\u51fa\u884c\uff1a\u591c\u95f4\u65c5\u884c\u4e3a\u4f73\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4e09\u5341\u516d\u8ba1\u8d70\u4e3a\u4e0a\u7b56\u3002\u5b9a\u80fd\u6210\u529f\u9003\u8d70\u3002", "line": "\u4e89\u7aef\uff1a\u4e09\u5341\u516d\u8ba1\u8d70\u4e3a\u4e0a\u7b56\u3002\u5b9a\u80fd\u6210\u529f\u9003\u8d70\u3002"}, {"label": "\u4eba\u7f18", "text": "\u82e5\u6709\u540c\u4f34\uff0c\u5219\u884c\u52a8\u529b\u4e0a\u5347\u3002", "line": "\u4eba\u7f18\uff1a\u82e5\u6709\u540c\u4f34\uff0c\u5219\u884c\u52a8\u529b\u4e0a\u5347\u3002"}, {"label": "\u4f4f\u6240", "text": "\u72ed\u5c0f\u623f\u95f4\u66f4\u4e3a\u653e\u677e\u3002", "line": "\u4f4f\u6240\uff1a\u72ed\u5c0f\u623f\u95f4\u66f4\u4e3a\u653e\u677e\u3002"}, {"label": "\u604b\u7231", "text": "\u8fd8\u7b97\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u604b\u7231\uff1a\u8fd8\u7b97\u4e00\u5e06\u98ce\u987a\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u8bfb\u4e66\u3002\u5b57\u53f7\u8d8a\u5927\uff0c\u5370\u8c61\u8d8a\u6df1\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u8bfb\u4e66\u3002\u5b57\u53f7\u8d8a\u5927\uff0c\u5370\u8c61\u8d8a\u6df1\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (64, '斯塔萨菲雅', '小小吉', '倾泻星辉妖精', '感知生物程度的能力', '["\u591c\u7a7a\u8fd9\u4e48\u6697\uff0c", "\u53ea\u56e0\u6211\u4eec\u80fd", "\u89c2\u6d4b\u7684\u661f\u661f", "\u6570\u91cf\u592a\u6709\u9650\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u592a\u8fc7\u5728\u610f\u4ed6\u4eba\uff0c\u4ee5\u81f3\u5fc3\u529b\u4ea4\u7601\u3002\u5f53\u6de1\u7136\u5904\u4e4b\u3002", "line": "\u8fd0\u52bf\uff1a\u592a\u8fc7\u5728\u610f\u4ed6\u4eba\uff0c\u4ee5\u81f3\u5fc3\u529b\u4ea4\u7601\u3002\u5f53\u6de1\u7136\u5904\u4e4b\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u7ba1\u7406\u4ed6\u4eba\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u8b66\u536b\u3001\u6559\u5e08\u3001\u4fdd\u59c6\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u7ba1\u7406\u4ed6\u4eba\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u8b66\u536b\u3001\u6559\u5e08\u3001\u4fdd\u59c6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u52ff\u5b58\u671f\u5f85\u3002\u751f\u7269\u6210\u7ee9\u5c0f\u6709\u957f\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u52ff\u5b58\u671f\u5f85\u3002\u751f\u7269\u6210\u7ee9\u5c0f\u6709\u957f\u8fdb\u3002"}, {"label": "\u5065\u5eb7", "text": "\u65e0\u788d\u3002\u6ce8\u610f\u5fc3\u7406\u5065\u5eb7\u3002", "line": "\u5065\u5eb7\uff1a\u65e0\u788d\u3002\u6ce8\u610f\u5fc3\u7406\u5065\u5eb7\u3002"}], [{"label": "\u51fa\u884c", "text": "\u8fdc\u79bb\u90fd\u5e02\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u8fdc\u79bb\u90fd\u5e02\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u52a1\u5fc5\u9a71\u9f20\u3002", "line": "\u4f4f\u6240\uff1a\u52a1\u5fc5\u9a71\u9f20\u3002"}, {"label": "\u604b\u7231", "text": "\u4e00\u5e06\u98ce\u987a\u5f97\u4e0d\u53ef\u601d\u8bae\u3002", "line": "\u604b\u7231\uff1a\u4e00\u5e06\u98ce\u987a\u5f97\u4e0d\u53ef\u601d\u8bae\u3002"}, {"label": "\u4eba\u7f18", "text": "\u9664\u4e86\u540c\u4f34\uff0c\u96be\u4ee5\u76f8\u4fe1\u4ed6\u4eba\u3002", "line": "\u4eba\u7f18\uff1a\u9664\u4e86\u540c\u4f34\uff0c\u96be\u4ee5\u76f8\u4fe1\u4ed6\u4eba\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5316\u7ea0\u7eb7\u4e8e\u672a\u7136\u3002", "line": "\u4e89\u7aef\uff1a\u5316\u7ea0\u7eb7\u4e8e\u672a\u7136\u3002"}, {"label": "\u7231\u597d", "text": "\u6700\u5b9c\u89c2\u661f\u3001\u6e38\u89c8\u661f\u8c61\u9986\u3002\u5360\u535c\u4ea6\u53ef\u3002", "line": "\u7231\u597d\uff1a\u6700\u5b9c\u89c2\u661f\u3001\u6e38\u89c8\u661f\u8c61\u9986\u3002\u5360\u535c\u4ea6\u53ef\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (65, '幽谷响子', '小吉', '寺门前的山彦僧侣', '反射声音程度的能力', '["\u822c\u82e5\u6ce2\u7f57\u871c\u2026", "\u542c\u8d77\u6765\u597d\u50cf", "\u4e00\u94b5\u83e0\u841d\u871c\uff0c", "\u771f\u662f\u998b\u4eba\u5440\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u867d\u65e0\u663e\u8457\u53d8\u5316\uff0c\u4f46\u52e4\u4e8e\u4fee\u884c\u7ec8\u6709\u56de\u62a5\u3002", "line": "\u8fd0\u52bf\uff1a\u867d\u65e0\u663e\u8457\u53d8\u5316\uff0c\u4f46\u52e4\u4e8e\u4fee\u884c\u7ec8\u6709\u56de\u62a5\u3002"}, {"label": "\u5b97\u6559", "text": "\u4f5b\u6559\u4e3a\u5409\u3002", "line": "\u5b97\u6559\uff1a\u4f5b\u6559\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5e73\u65e5\u8015\u8018\u5c06\u5f97\u6536\u83b7\u3002", "line": "\u5b66\u4e1a\uff1a\u5e73\u65e5\u8015\u8018\u5c06\u5f97\u6536\u83b7\u3002"}, {"label": "\u4ea4\u6613", "text": "\u53cd\u54cd\u8fc5\u901f\uff0c\u4f46\u7978\u798f\u96be\u6599\u3002", "line": "\u4ea4\u6613\uff1a\u53cd\u54cd\u8fc5\u901f\uff0c\u4f46\u7978\u798f\u96be\u6599\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u767b\u5c71\u3002\u4e0d\u4f1a\u9047\u9669\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u767b\u5c71\u3002\u4e0d\u4f1a\u9047\u9669\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u4ee5\u793c\u5f85\u4eba\u3001\u771f\u8bda\u95ee\u5019\u5219\u4eba\u8109\u5e7f\u589e\u3002\u9e66\u9e49\u5b66\u820c\u5c06\u5931\u53bb\u53cb\u8c0a\u3002", "line": "\u4eba\u7f18\uff1a\u4ee5\u793c\u5f85\u4eba\u3001\u771f\u8bda\u95ee\u5019\u5219\u4eba\u8109\u5e7f\u589e\u3002\u9e66\u9e49\u5b66\u820c\u5c06\u5931\u53bb\u53cb\u8c0a\u3002"}, {"label": "\u4f4f\u6240", "text": "\u9700\u5907\u597d\u9694\u97f3\u8bbe\u5907\u3002", "line": "\u4f4f\u6240\uff1a\u9700\u5907\u597d\u9694\u97f3\u8bbe\u5907\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5e03\u65bd\u6563\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u5e03\u65bd\u6563\u8d22\u3002"}, {"label": "\u604b\u7231", "text": "\u5b9c\u4e0e\u8bf5\u7ecf\u7684\u540c\u4f34\u76f8\u604b\u3002", "line": "\u604b\u7231\uff1a\u5b9c\u4e0e\u8bf5\u7ecf\u7684\u540c\u4f34\u76f8\u604b\u3002"}, {"label": "\u5406\u559d", "text": "\u65f6\u4e0b\u6700\u6d41\u884c\u7684\u5406\u559d\u662f \u300e\u5929\u7406\u662d\u5f70\uff0c\u62a5\u5e94\u4e0d\u723d\uff01\u300f", "line": "\u5406\u559d\uff1a\u65f6\u4e0b\u6700\u6d41\u884c\u7684\u5406\u559d\u662f \u300e\u5929\u7406\u662d\u5f70\uff0c\u62a5\u5e94\u4e0d\u723d\uff01\u300f"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (66, '宫古芳香', '末吉', '最爱拉人入伙的僵尸', '无所不吃程度的能力', '["\u601d\u6765\u53c8\u60f3\u53bb", "\u6839\u672c\u6ca1\u6709\u7528\u3002", "\u4eba\u7c7b\u5230\u5934\u6765", "\u90fd\u8981\u53d8\u5c38\u4f53\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e2\u5df2\u8fce\u63a5\u6b7b\u4ea1\uff0c\u4f55\u6765\u5384\u8fd0\u4e00\u8c08\u3002", "line": "\u8fd0\u52bf\uff1a\u65e2\u5df2\u8fce\u63a5\u6b7b\u4ea1\uff0c\u4f55\u6765\u5384\u8fd0\u4e00\u8c08\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5565\u73a9\u610f\u513f\uff1f\u80fd\u5403\u5417\uff1f", "line": "\u5065\u5eb7\uff1a\u5565\u73a9\u610f\u513f\uff1f\u80fd\u5403\u5417\uff1f"}, {"label": "\u4ea4\u6613", "text": "\u540c\u4f34\u591a\u591a\u3002\u80fd\u5426\u5e72\u6d3b\u5219\u5c1a\u4e0d\u53ef\u77e5\u3002", "line": "\u4ea4\u6613\uff1a\u540c\u4f34\u591a\u591a\u3002\u80fd\u5426\u5e72\u6d3b\u5219\u5c1a\u4e0d\u53ef\u77e5\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e0d\u59a8\u6e05\u7a7a\u8bb0\u5fc6\u3002", "line": "\u5b66\u4e1a\uff1a\u4e0d\u59a8\u6e05\u7a7a\u8bb0\u5fc6\u3002"}, {"label": "\u8fd0\u52a8", "text": "\u8eab\u4f53\u50f5\u786c\uff0c\u96be\u514d\u53d7\u4f24\u3002", "line": "\u8fd0\u52a8\uff1a\u8eab\u4f53\u50f5\u786c\uff0c\u96be\u514d\u53d7\u4f24\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4e3e\u6b65\u7ef4\u8270\u3002", "line": "\u51fa\u884c\uff1a\u4e3e\u6b65\u7ef4\u8270\u3002"}, {"label": "\u4eba\u7f18", "text": "\u540c\u4f34\u8d8a\u6765\u8d8a\u591a\u3002\u771f\u662f\u53ef\u559c\u53ef\u8d3a\u3002", "line": "\u4eba\u7f18\uff1a\u540c\u4f34\u8d8a\u6765\u8d8a\u591a\u3002\u771f\u662f\u53ef\u559c\u53ef\u8d3a\u3002"}, {"label": "\u98df\u7269", "text": "\u82e5\u4e0d\u6ce8\u91cd\u517b\u751f\uff0c\u4fbf\u4f1a\u88ab\u65e0\u5c3d\u7684\u98df\u6b32\u538b\u57ae\u3002", "line": "\u98df\u7269\uff1a\u82e5\u4e0d\u6ce8\u91cd\u517b\u751f\uff0c\u4fbf\u4f1a\u88ab\u65e0\u5c3d\u7684\u98df\u6b32\u538b\u57ae\u3002"}, {"label": "\u604b\u7231", "text": "\u65ad\u7136\u65e0\u671b\u3002", "line": "\u604b\u7231\uff1a\u65ad\u7136\u65e0\u671b\u3002"}, {"label": "\u59fb\u7f18", "text": "\u7edd\u65e0\u53ef\u80fd\u3002", "line": "\u59fb\u7f18\uff1a\u7edd\u65e0\u53ef\u80fd\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5e73\u7a33\u81f3\u6781\u3002\u53ef\u5f97\u5b89\u606f\u3002", "line": "\u4e89\u7aef\uff1a\u5e73\u7a33\u81f3\u6781\u3002\u53ef\u5f97\u5b89\u606f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (67, '霍青娥', '末凶', '无法囚禁的邪仙', '穿越墙壁程度的能力', '["\u4e16\u4e0a\u5899\u62c6\u5c3d\uff0c", "\u4e07\u7269\u7686\u81ea\u7531\u3002", "\u8fd9\u624d\u79f0\u5f97\u4e0a", "\u662f\u5168\u7403\u4e3b\u4e49\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4fa5\u5e78\u4e4b\u4e8b\u589e\u591a\u3002\u65e5\u540e\u5c06\u6709\u62a5\u5e94\u3002", "line": "\u8fd0\u52bf\uff1a\u4fa5\u5e78\u4e4b\u4e8b\u589e\u591a\u3002\u65e5\u540e\u5c06\u6709\u62a5\u5e94\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5f53\u5fc3\u76d7\u8d3c\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5fc3\u76d7\u8d3c\u3002"}, {"label": "\u4ea4\u6613", "text": "\u6253\u7834\u58c1\u5792\u4fbf\u80fd\u5927\u83b7\u6210\u529f\u3002\u4e5f\u4f1a\u56e0\u6b64\u62db\u4eba\u6028\u6068\u3002", "line": "\u4ea4\u6613\uff1a\u6253\u7834\u58c1\u5792\u4fbf\u80fd\u5927\u83b7\u6210\u529f\u3002\u4e5f\u4f1a\u56e0\u6b64\u62db\u4eba\u6028\u6068\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u65e0\u6cd5\u4e13\u6ce8\uff0c\u60ef\u4e8e\u9003\u907f\u3002", "line": "\u5b66\u4e1a\uff1a\u65e0\u6cd5\u4e13\u6ce8\uff0c\u60ef\u4e8e\u9003\u907f\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u6027\u547d\u65e0\u865e\u3002", "line": "\u5065\u5eb7\uff1a\u6027\u547d\u65e0\u865e\u3002"}, {"label": "\u51fa\u884c", "text": "\u5730\u72f1\u4e4b\u5916\u7686\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5730\u72f1\u4e4b\u5916\u7686\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u62bd\u8eab\u800c\u9003\u3002", "line": "\u604b\u7231\uff1a\u62bd\u8eab\u800c\u9003\u3002"}, {"label": "\u59fb\u7f18", "text": "\u987b\u6709\u81ea\u77e5\u4e4b\u660e\u3002", "line": "\u59fb\u7f18\uff1a\u987b\u6709\u81ea\u77e5\u4e4b\u660e\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5f97\u6765\u5168\u4e0d\u8d39\u529f\u592b\u3002\u4f46\u7070\u8272\u4ea7\u4e1a\u4e07\u4e07\u4e0d\u53ef\u67d3\u6307\u3002", "line": "\u8d22\u8fd0\uff1a\u5f97\u6765\u5168\u4e0d\u8d39\u529f\u592b\u3002\u4f46\u7070\u8272\u4ea7\u4e1a\u4e07\u4e07\u4e0d\u53ef\u67d3\u6307\u3002"}, {"label": "\u4eba\u7f18", "text": "\u8b66\u60d5\u4ed6\u4eba\u751c\u8a00\u871c\u8bed\u3002", "line": "\u4eba\u7f18\uff1a\u8b66\u60d5\u4ed6\u4eba\u751c\u8a00\u871c\u8bed\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (68, '苏我屠自古', '末吉', '古代飞鸟的亡灵', '引发雷电程度的能力', '["\u4e00\u65e6\u6446\u8131\u4e86", "\u8089\u4f53\u7684\u675f\u7f1a\uff0c", "\u65e5\u5b50\u8fc7\u5f97\u90a3", "\u53eb\u4e00\u4e2a\u5feb\u6d3b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5012\u9709\u900f\u9876\uff0c\u4f46\u5fc3\u6001\u826f\u597d\u5219\u53ef\u9022\u51f6\u5316\u5409\u3002", "line": "\u8fd0\u52bf\uff1a\u5012\u9709\u900f\u9876\uff0c\u4f46\u5fc3\u6001\u826f\u597d\u5219\u53ef\u9022\u51f6\u5316\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u5fc3\u8f7b\u76c8\u3002\u8d2a\u7761\u8fc7\u5934\u5219\u6c14\u8fd0\u8870\u9000\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u5fc3\u8f7b\u76c8\u3002\u8d2a\u7761\u8fc7\u5934\u5219\u6c14\u8fd0\u8870\u9000\u3002"}, {"label": "\u4ea4\u6613", "text": "\u82e5\u60f3\u6210\u529f\uff0c\u5148\u5e94\u653e\u4e0b\u5f80\u4e8b\u3002", "line": "\u4ea4\u6613\uff1a\u82e5\u60f3\u6210\u529f\uff0c\u5148\u5e94\u653e\u4e0b\u5f80\u4e8b\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u65e5\u672c\u53f2\u4e3a\u51f6\u3002\u5176\u4ed6\u5b66\u79d1\u53ef\u6d3b\u5b66\u6d3b\u7528\u3002", "line": "\u5b66\u4e1a\uff1a\u65e5\u672c\u53f2\u4e3a\u51f6\u3002\u5176\u4ed6\u5b66\u79d1\u53ef\u6d3b\u5b66\u6d3b\u7528\u3002"}], [{"label": "\u4f4f\u6240", "text": "\u5f53\u5fc3\u843d\u96f7\u4e0e\u706b\u707e\u3002\u9662\u4e2d\u690d\u6851\n1\n\u5219\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5fc3\u843d\u96f7\u4e0e\u706b\u707e\u3002\u9662\u4e2d\u690d\u6851\n1\n\u5219\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u8fdc\u884c\u4e0d\u89c9\u75b2\u3002", "line": "\u51fa\u884c\uff1a\u8fdc\u884c\u4e0d\u89c9\u75b2\u3002"}, {"label": "\u604b\u7231", "text": "\u56e0\u4ef7\u503c\u89c2\u5dee\u5f02\u800c\u60c5\u573a\u5931\u610f\u3002", "line": "\u604b\u7231\uff1a\u56e0\u4ef7\u503c\u89c2\u5dee\u5f02\u800c\u60c5\u573a\u5931\u610f\u3002"}, {"label": "\u664b\u5347", "text": "\u8d62\u5f97\u4e0a\u53f8\u8d4f\u8bc6\u4fbf\u5927\u6709\u524d\u9014\u3002", "line": "\u664b\u5347\uff1a\u8d62\u5f97\u4e0a\u53f8\u8d4f\u8bc6\u4fbf\u5927\u6709\u524d\u9014\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e27\u5931\u8089\u4f53\uff0c\u4f46\u5fc3\u7075\u53d8\u5f97\u8f7b\u5feb\u8212\u7545\u3002", "line": "\u5bfb\u7269\uff1a\u4e27\u5931\u8089\u4f53\uff0c\u4f46\u5fc3\u7075\u53d8\u5f97\u8f7b\u5feb\u8212\u7545\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (69, '物部布都', '自行决定', '能辨龙脉流向的尸解仙', '操纵风水程度的能力', '["\u8fd0\u52bf\u5f53\u7136\u662f", "\u4e00\u65f6\u4e4b\u798f\u7978\u3002", "\u82e5\u8bc6\u5f97\u9f99\u8109\uff0c", "\u5219\u53e6\u5f53\u522b\u8bba\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u662f\u798f\u662f\u7978\uff0c\u5168\u7531\u81ea\u8eab\u884c\u52a8\u51b3\u5b9a\u3002\u5f53\u89c2\u5bdf\u4e16\u754c\uff0c\u89e3\u8bfb\u5929\u673a\u3002", "line": "\u8fd0\u52bf\uff1a\u662f\u798f\u662f\u7978\uff0c\u5168\u7531\u81ea\u8eab\u884c\u52a8\u51b3\u5b9a\u3002\u5f53\u89c2\u5bdf\u4e16\u754c\uff0c\u89e3\u8bfb\u5929\u673a\u3002"}, {"label": "\u4ea4\u6613", "text": "\u529e\u516c\u573a\u6240\u7684\u7269\u54c1\u9700\u53ca\u65f6\u6e05\u7406\uff0c\u6742\u7269\u8fc7\u591a\u5c06\u62db\u6765\u5384\u8fd0\u3002", "line": "\u4ea4\u6613\uff1a\u529e\u516c\u573a\u6240\u7684\u7269\u54c1\u9700\u53ca\u65f6\u6e05\u7406\uff0c\u6742\u7269\u8fc7\u591a\u5c06\u62db\u6765\u5384\u8fd0\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u53e4\u4ee3\u53f2\u4e3a\u5409\u3002\u5efa\u7b51\u5b66\u4ea6\u53ef\u3002", "line": "\u5b66\u4e1a\uff1a\u53e4\u4ee3\u53f2\u4e3a\u5409\u3002\u5efa\u7b51\u5b66\u4ea6\u53ef\u3002"}, {"label": "\u5065\u5eb7", "text": "\u65f6\u65f6\u4fdd\u517b\u3002", "line": "\u5065\u5eb7\uff1a\u65f6\u65f6\u4fdd\u517b\u3002"}], [{"label": "\u79fb\u5f99", "text": "\u8fc1\u5165\u805a\u6c14\u5b9d\u5b85\u7684\u826f\u673a\u3002", "line": "\u79fb\u5f99\uff1a\u8fc1\u5165\u805a\u6c14\u5b9d\u5b85\u7684\u826f\u673a\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u63a5\u89e6\u519c\u6d3b\u6216\u9676\u827a\u53ef\u63d0\u5347\u8d22\u8fd0\u3002", "line": "\u8d22\u8fd0\uff1a\u63a5\u89e6\u519c\u6d3b\u6216\u9676\u827a\u53ef\u63d0\u5347\u8d22\u8fd0\u3002"}, {"label": "\u664b\u5347", "text": "\u6392\u9664\u7ade\u4e89\u5bf9\u624b\u4fbf\u5927\u6709\u524d\u9014\u3002", "line": "\u664b\u5347\uff1a\u6392\u9664\u7ade\u4e89\u5bf9\u624b\u4fbf\u5927\u6709\u524d\u9014\u3002"}, {"label": "\u51fa\u884c", "text": "\u591a\u591a\u76ca\u5584\u3002", "line": "\u51fa\u884c\uff1a\u591a\u591a\u76ca\u5584\u3002"}, {"label": "\u604b\u7231", "text": "\u552f\u72ec\u6b64\u4e8b\u98ce\u6c34\u65e0\u6cd5\u5de6\u53f3\u3002", "line": "\u604b\u7231\uff1a\u552f\u72ec\u6b64\u4e8b\u98ce\u6c34\u65e0\u6cd5\u5de6\u53f3\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (70, '丰聪耳神子', '【最大吉】', '全能的领袖道士', '可同时倾听十人话语程度的能力', '["\u5929\u4e0b\u4e4b\u4eba", "\u4e0d\u4e89\u4e0d\u9006\uff0c", "\u5b89\u5206\u5b88\u5df1\u3002", "\u6b64\u5373\u548c\u4e5f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6c14\u8fd0\u6781\u65fa\uff0c\u4e00\u65f6\u65e0\u5fe7\u65e0\u60a3\u3002", "line": "\u8fd0\u52bf\uff1a\u6c14\u8fd0\u6781\u65fa\uff0c\u4e00\u65f6\u65e0\u5fe7\u65e0\u60a3\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5927\u83b7\u6210\u529f\u3002\u653f\u6cbb\u5bb6\u3001\u9053\u58eb\u5219\u5409\u4e0a\u52a0\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5927\u83b7\u6210\u529f\u3002\u653f\u6cbb\u5bb6\u3001\u9053\u58eb\u5219\u5409\u4e0a\u52a0\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6240\u6709\u79d1\u76ee\u7686\u6709\u957f\u8fdb\u3002\u516c\u6c11\u5b66\u5409\u4e0a\u52a0\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u6240\u6709\u79d1\u76ee\u7686\u6709\u957f\u8fdb\u3002\u516c\u6c11\u5b66\u5409\u4e0a\u52a0\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u82e5\u4e0d\u7231\u62a4\u8033\u6735\u4fbf\u4f1a\u6c14\u8fd0\u8870\u9000\u3002", "line": "\u5065\u5eb7\uff1a\u82e5\u4e0d\u7231\u62a4\u8033\u6735\u4fbf\u4f1a\u6c14\u8fd0\u8870\u9000\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u6c42\u52a9\u8005\u7eb7\u81f3\u6c93\u6765\u3002\u5f88\u662f\u9ebb\u70e6\u3002", "line": "\u4eba\u7f18\uff1a\u6c42\u52a9\u8005\u7eb7\u81f3\u6c93\u6765\u3002\u5f88\u662f\u9ebb\u70e6\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5c06\u6709\u4eba\u4e3b\u52a8\u9988\u8d60\u94b1\u8d22\uff0c\u4f46\u5207\u52ff\u6536\u53d6\u3002", "line": "\u8d22\u8fd0\uff1a\u5c06\u6709\u4eba\u4e3b\u52a8\u9988\u8d60\u94b1\u8d22\uff0c\u4f46\u5207\u52ff\u6536\u53d6\u3002"}, {"label": "\u5fc3\u613f", "text": "\u65e9\u5df2\u5706\u6ee1\u3002", "line": "\u5fc3\u613f\uff1a\u65e9\u5df2\u5706\u6ee1\u3002"}, {"label": "\u51fa\u884c", "text": "\u65e0\u6687\u6210\u884c\u3002", "line": "\u51fa\u884c\uff1a\u65e0\u6687\u6210\u884c\u3002"}, {"label": "\u604b\u7231", "text": "\u53ef\u811a\u8e0f\u5341\u6761\u8239\u3002", "line": "\u604b\u7231\uff1a\u53ef\u811a\u8e0f\u5341\u6761\u8239\u3002"}, {"label": "\u4e89\u7aef", "text": "\u65e0\u3002\u6b64\u5373\u548c\u4e5f\u3002", "line": "\u4e89\u7aef\uff1a\u65e0\u3002\u6b64\u5373\u548c\u4e5f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (71, '二岩猯藏', '【大吉】', '变化自如的妖怪狸', '施展变化程度的能力', '["\u4eba\u6709\u5343\u767e\u53d8\uff0c", "\u9762\u5b54\u4e0d\u80dc\u6570\u3002", "\u541e\u4e91\u5410\u96fe\u65f6\uff0c", "\u81ea\u4f1a\u73b0\u539f\u5f62", "1", "\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u9047\u4e8b\u968f\u673a\u5e94\u53d8\uff0c\u4fbf\u80fd\u6063\u610f\u5feb\u6d3b\u3002", "line": "\u8fd0\u52bf\uff1a\u9047\u4e8b\u968f\u673a\u5e94\u53d8\uff0c\u4fbf\u80fd\u6063\u610f\u5feb\u6d3b\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u670d\u52a1\u4e1a\u53ef\u751f\u610f\u5174\u9686\u3002\u5e97\u4e3b\u3001\u603b\u88c1\u3001\u7ba1\u7406\u804c\u4f4d\u5219\u5409\u4e0a\u52a0\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u670d\u52a1\u4e1a\u53ef\u751f\u610f\u5174\u9686\u3002\u5e97\u4e3b\u3001\u603b\u88c1\u3001\u7ba1\u7406\u804c\u4f4d\u5219\u5409\u4e0a\u52a0\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5316\u5b66\u5927\u5409\u3002\u65e5\u672c\u53f2\u4ea6\u6709\u8fdb\u6b65\u3002", "line": "\u5b66\u4e1a\uff1a\u5316\u5b66\u5927\u5409\u3002\u65e5\u672c\u53f2\u4ea6\u6709\u8fdb\u6b65\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u70df\u8349\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u70df\u8349\u3002"}], [{"label": "\u51fa\u884c", "text": "\u907f\u5f00\u5b97\u6559\u5723\u5730\uff0c\u51fa\u884c\u53ef\u6709\u6240\u88e8\u76ca\u3002", "line": "\u51fa\u884c\uff1a\u907f\u5f00\u5b97\u6559\u5723\u5730\uff0c\u51fa\u884c\u53ef\u6709\u6240\u88e8\u76ca\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u51fa\u624b\u9614\u7ef0\u53cd\u800c\u8d22\u6e90\u6eda\u6eda\u3002", "line": "\u8d22\u8fd0\uff1a\u51fa\u624b\u9614\u7ef0\u53cd\u800c\u8d22\u6e90\u6eda\u6eda\u3002"}, {"label": "\u604b\u7231", "text": "\u5c14\u865e\u6211\u8bc8\u3002", "line": "\u604b\u7231\uff1a\u5c14\u865e\u6211\u8bc8\u3002"}, {"label": "\u664b\u5347", "text": "\u5de6\u53f3\u9022\u6e90\u3002", "line": "\u664b\u5347\uff1a\u5de6\u53f3\u9022\u6e90\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5f53\u6446\u653e\u4fe1\u4e50\u70e7\u9676\u5668\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u6446\u653e\u4fe1\u4e50\u70e7\u9676\u5668\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5373\u4fbf\u4e22\u5931\u7269\u54c1\u4e5f\u4f1a\u6709\u4eba\u5e2e\u5fd9\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u5373\u4fbf\u4e22\u5931\u7269\u54c1\u4e5f\u4f1a\u6709\u4eba\u5e2e\u5fd9\u5bfb\u56de\u3002"}, {"label": "\u7231\u597d", "text": "\u4e54\u88c5\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u4e54\u88c5\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (72, '秦心', '末吉', '熟练运用六十六种感情的面灵气', '操纵感情程度的能力', '["\u4e3a\u4ec0\u4e48\u6700\u8fd1", "\u4e0d\u613f\u610f\u8868\u9732", "\u81ea\u8eab\u60c5\u611f\u7684", "\u4eba\u53d8\u591a\u4e86\u5462\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u611f\u60c5\u80fd\u591f\u63a7\u5236\u81ea\u5982\u3002\u7ef4\u6301\u5e73\u5fc3\u9759\u6c14\uff0c\u8fd0\u6c14\u4fbf\u80fd\u65e5\u6e10\u63d0\u5347\u3002", "line": "\u8fd0\u52bf\uff1a\u611f\u60c5\u80fd\u591f\u63a7\u5236\u81ea\u5982\u3002\u7ef4\u6301\u5e73\u5fc3\u9759\u6c14\uff0c\u8fd0\u6c14\u4fbf\u80fd\u65e5\u6e10\u63d0\u5347\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u6f14\u6280\u9ad8\u8d85\uff0c\u5982\u6709\u5343\u526f\u9762\u5b54\u3002\u843d\u8bed\u5bb6\u3001\u6f14\u5458\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u6f14\u6280\u9ad8\u8d85\uff0c\u5982\u6709\u5343\u526f\u9762\u5b54\u3002\u843d\u8bed\u5bb6\u3001\u6f14\u5458\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6587\u79d1\u6574\u4f53\u4e0e\u65e5\u4ff1\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u6587\u79d1\u6574\u4f53\u4e0e\u65e5\u4ff1\u8fdb\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5bb9\u6613\u5ffd\u89c6\u8eab\u4f53\u95ee\u9898\u3002", "line": "\u5065\u5eb7\uff1a\u5bb9\u6613\u5ffd\u89c6\u8eab\u4f53\u95ee\u9898\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4eba\u5c71\u4eba\u6d77\u4e4b\u5730\u53ef\u5f97\u5c3d\u5174\u3002\u5e94\u79ef\u6781\u53c2\u4e0e\u8282\u5e86\u6d3b\u52a8\u3002", "line": "\u51fa\u884c\uff1a\u4eba\u5c71\u4eba\u6d77\u4e4b\u5730\u53ef\u5f97\u5c3d\u5174\u3002\u5e94\u79ef\u6781\u53c2\u4e0e\u8282\u5e86\u6d3b\u52a8\u3002"}, {"label": "\u604b\u7231", "text": "\u604b\u6155\u4e4b\u60c5\u65e0\u6cd5\u64cd\u7eb5\u3002", "line": "\u604b\u7231\uff1a\u604b\u6155\u4e4b\u60c5\u65e0\u6cd5\u64cd\u7eb5\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5c06\u5931\u4e00\u4ef6\u73cd\u5b9d\u3002", "line": "\u5bfb\u7269\uff1a\u5c06\u5931\u4e00\u4ef6\u73cd\u5b9d\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5c06\u9047\u9a97\u5c40\uff0c\u52a1\u5fc5\u5f53\u5fc3\u3002", "line": "\u4eba\u7f18\uff1a\u5c06\u9047\u9a97\u5c40\uff0c\u52a1\u5fc5\u5f53\u5fc3\u3002"}, {"label": "\u7231\u597d", "text": "\u5316\u5986\u3001\u80fd\u4e50\u3001\u6b4c\u821e\u4f0e\u3001\u5047\u9762\u821e\u4f1a\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u5316\u5986\u3001\u80fd\u4e50\u3001\u6b4c\u821e\u4f0e\u3001\u5047\u9762\u821e\u4f1a\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (73, '若鹭姬', '半吉', '世间罕有的淡水人鱼', '在水中力量会增加程度的能力', '["\u4e00\u534a\u662f\u4eba\u8eab", "\u4e00\u534a\u662f\u9c7c\u5c3e", "\u5403\u5565\u6700\u5e94\u666f", "\u5bf9\u534a\u5f00\u70b8\u867e"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u534a\u5409\u534a\u51f6\u3002\u6709\u65f6\u8d70\u8fd0\u6709\u65f6\u5012\u9709\u3002\u4eba\u751f\u5927\u62b5\u5982\u6b64\u3002", "line": "\u8fd0\u52bf\uff1a\u534a\u5409\u534a\u51f6\u3002\u6709\u65f6\u8d70\u8fd0\u6709\u65f6\u5012\u9709\u3002\u4eba\u751f\u5927\u62b5\u5982\u6b64\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5409\uff0c\u6d3b\u8e66\u4e71\u8df3\u3002", "line": "\u5065\u5eb7\uff1a\u5409\uff0c\u6d3b\u8e66\u4e71\u8df3\u3002"}, {"label": "\u4ea4\u6613", "text": "\u51f6\uff0c\u5e02\u573a\u98ce\u6ce2\u96be\u6d4b\u3002", "line": "\u4ea4\u6613\uff1a\u51f6\uff0c\u5e02\u573a\u98ce\u6ce2\u96be\u6d4b\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5409\uff0c\u80fd\u591f\u9759\u5fc3\u7528\u529f\u3002", "line": "\u5b66\u4e1a\uff1a\u5409\uff0c\u80fd\u591f\u9759\u5fc3\u7528\u529f\u3002"}, {"label": "\u4f4f\u6240", "text": "\u51f6\uff0c\u6c34\u5384\u4e4b\u5366\u3002", "line": "\u4f4f\u6240\uff1a\u51f6\uff0c\u6c34\u5384\u4e4b\u5366\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5409\uff0c\u6e56\u6cca\u4e3a\u5b9c\u3002", "line": "\u51fa\u884c\uff1a\u5409\uff0c\u6e56\u6cca\u4e3a\u5b9c\u3002"}, {"label": "\u4e89\u7aef", "text": "\u51f6\uff0c\u5fc5\u8f93\u65e0\u7591\u3002", "line": "\u4e89\u7aef\uff1a\u51f6\uff0c\u5fc5\u8f93\u65e0\u7591\u3002"}, {"label": "\u604b\u7231", "text": "\u5409\uff0c\u5e73\u51e1\u4ea4\u5f80\u5373\u53ef\u987a\u5229\u53d1\u5c55\u3002", "line": "\u604b\u7231\uff1a\u5409\uff0c\u5e73\u51e1\u4ea4\u5f80\u5373\u53ef\u987a\u5229\u53d1\u5c55\u3002"}, {"label": "\u670d\u88c5", "text": "\u9664\u548c\u670d\u4e4b\u5916\u7686\u4e3a\u51f6\u3002", "line": "\u670d\u88c5\uff1a\u9664\u548c\u670d\u4e4b\u5916\u7686\u4e3a\u51f6\u3002"}, {"label": "\u7231\u597d", "text": "\u9493\u9c7c\u4e3a\u5409\u3002\u4f46\u52ff\u5fd8\u9493\u83b7\u653e\u6d41\u3002", "line": "\u7231\u597d\uff1a\u9493\u9c7c\u4e3a\u5409\u3002\u4f46\u52ff\u5fd8\u9493\u83b7\u653e\u6d41\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (74, '赤蛮奇', '大吉', '脑袋灵活的辘轳首', '让头飞出去程度的能力', '["\u65e0\u8bba\u662f\u5435\u5634", "\u8fd8\u662f\u5f39\u5e55\u6218\uff0c", "\u53d6\u80dc\u7684\u5173\u952e", "\u90fd\u662f\u62fc\u4eba\u5934\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u89c6\u91ce\u5bbd\u5e7f\uff0c\u524d\u8def\u660e\u6717\u3002\u80fd\u591f\u907f\u5f00\u5371\u9669\u3002", "line": "\u8fd0\u52bf\uff1a\u89c6\u91ce\u5bbd\u5e7f\uff0c\u524d\u8def\u660e\u6717\u3002\u80fd\u591f\u907f\u5f00\u5371\u9669\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9ad8\u77bb\u8fdc\u77a9\u3002\u670d\u52a1\u4e1a\u5e94\u907f\u514d\u629b\u5934\u9732\u9762\u4e3a\u5999\u3002", "line": "\u4ea4\u6613\uff1a\u9ad8\u77bb\u8fdc\u77a9\u3002\u670d\u52a1\u4e1a\u5e94\u907f\u514d\u629b\u5934\u9732\u9762\u4e3a\u5999\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5934\u8111\u7075\u6d3b\u3002", "line": "\u5b66\u4e1a\uff1a\u5934\u8111\u7075\u6d3b\u3002"}, {"label": "\u51fa\u884c", "text": "\u5c31\u5f53\u5df2\u7ecf\u53bb\u8fc7\u4e86\u3002", "line": "\u51fa\u884c\uff1a\u5c31\u5f53\u5df2\u7ecf\u53bb\u8fc7\u4e86\u3002"}], [{"label": "\u604b\u7231", "text": "\u5207\u52ff\u53d8\u6210\u8ddf\u8e2a\u72c2\u3002", "line": "\u604b\u7231\uff1a\u5207\u52ff\u53d8\u6210\u8ddf\u8e2a\u72c2\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6613\u5931\u8db3\u53d7\u4f24\u3002", "line": "\u5065\u5eb7\uff1a\u6613\u5931\u8db3\u53d7\u4f24\u3002"}, {"label": "\u75be\u75c5", "text": "\u80a9\u90e8\u9178\u75db\u6709\u6240\u597d\u8f6c\u3002", "line": "\u75be\u75c5\uff1a\u80a9\u90e8\u9178\u75db\u6709\u6240\u597d\u8f6c\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5bfb\u56de\u8bf8\u591a\u5931\u7269\u3002", "line": "\u5bfb\u7269\uff1a\u5bfb\u56de\u8bf8\u591a\u5931\u7269\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4ee5\u8c8c\u53d6\u4eba\u8005\u53bb\uff0c\u6167\u773c\u8bc6\u4eba\u8005\u6765\u3002", "line": "\u4eba\u7f18\uff1a\u4ee5\u8c8c\u53d6\u4eba\u8005\u53bb\uff0c\u6167\u773c\u8bc6\u4eba\u8005\u6765\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (75, '今泉影狼', '中吉', '沉着冷静的人狼姐姐', '在满月之夜变身为狼程度的能力', '["\u6bcf\u9022\u6ee1\u6708\u65f6", "\u6d77\u6f6e\u6700\u9ad8\u6da8\uff0c", "\u5730\u7403\u4e0e\u72fc\u4eba", "\u60f3\u5fc5\u662f\u540c\u65cf\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5de8\u53d8\u5c06\u81f3\uff0c\u8fc7\u65f6\u4e0d\u5019\u3002\u82e5\u5b89\u4e8e\u73b0\u72b6\uff0c\u5219\u5e94\u8bbe\u6cd5\u907f\u514d\u3002\u5426\u5219\u5e94\u6293\u4f4f\u673a\u4f1a\u3002", "line": "\u8fd0\u52bf\uff1a\u5de8\u53d8\u5c06\u81f3\uff0c\u8fc7\u65f6\u4e0d\u5019\u3002\u82e5\u5b89\u4e8e\u73b0\u72b6\uff0c\u5219\u5e94\u8bbe\u6cd5\u907f\u514d\u3002\u5426\u5219\u5e94\u6293\u4f4f\u673a\u4f1a\u3002"}, {"label": "\u4f53\u9b44", "text": "\u63d0\u5347\u4f53\u80fd\u7684\u826f\u673a\u3002\u5f53\u591c\u95f4\u953b\u70bc\u3002", "line": "\u4f53\u9b44\uff1a\u63d0\u5347\u4f53\u80fd\u7684\u826f\u673a\u3002\u5f53\u591c\u95f4\u953b\u70bc\u3002"}, {"label": "\u51fa\u884c", "text": "\u5e94\u907f\u5f00\u4eba\u5c71\u4eba\u6d77\u3002", "line": "\u51fa\u884c\uff1a\u5e94\u907f\u5f00\u4eba\u5c71\u4eba\u6d77\u3002"}, {"label": "\u4ea4\u6613", "text": "\u60c5\u51b5\u770b\u4f3c\u987a\u5229\uff0c\u5b9e\u5219\u53d8\u5316\u83ab\u6d4b\u3002", "line": "\u4ea4\u6613\uff1a\u60c5\u51b5\u770b\u4f3c\u987a\u5229\uff0c\u5b9e\u5219\u53d8\u5316\u83ab\u6d4b\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u53d7\u6708\u76f8\u5f71\u54cd\u3002", "line": "\u5b66\u4e1a\uff1a\u53d7\u6708\u76f8\u5f71\u54cd\u3002"}, {"label": "\u604b\u7231", "text": "\u4fdd\u6301\u8c26\u900a\u5219\u6709\u8d77\u8272\u3002", "line": "\u604b\u7231\uff1a\u4fdd\u6301\u8c26\u900a\u5219\u6709\u8d77\u8272\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e8e\u6ee1\u6708\u4e4b\u591c\u6563\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u4e8e\u6ee1\u6708\u4e4b\u591c\u6563\u8d22\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e8e\u6ee1\u6708\u4e4b\u591c\u9057\u5931\u91cd\u8981\u7269\u54c1\u3002\u8bb0\u5fc6\u4e5f\u5c06\u4e00\u5e76\u9057\u5931\u3002", "line": "\u5bfb\u7269\uff1a\u4e8e\u6ee1\u6708\u4e4b\u591c\u9057\u5931\u91cd\u8981\u7269\u54c1\u3002\u8bb0\u5fc6\u4e5f\u5c06\u4e00\u5e76\u9057\u5931\u3002"}, {"label": "\u670d\u88c5", "text": "\u907f\u514d\u9732\u51fa\u808c\u80a4\u4e3a\u5409\u3002", "line": "\u670d\u88c5\uff1a\u907f\u514d\u9732\u51fa\u808c\u80a4\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (76, '九十九弁弁', '末吉', '拨响魂魄的琵琶付丧神', '自行发声演奏程度的能力', '["\u9b54\u98ce\u4e71\u821e\u7684", "\u66b4\u98ce\u4e4b\u773c\u5904\uff0c", "\u4e50\u97f3\u503e\u8bc9\u7740", "\u8bf8\u884c\u4e4b\u65e0\u5e38\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5982\u7269\u4ef6\u822c\u4efb\u4eba\u9a71\u4f7f\u7684\u751f\u6d3b\u6253\u4e0a\u4f11\u6b62\u7b26\u3002\u53cd\u53db\u4e4b\u65f6\u5df2\u81f3\u3002", "line": "\u8fd0\u52bf\uff1a\u5982\u7269\u4ef6\u822c\u4efb\u4eba\u9a71\u4f7f\u7684\u751f\u6d3b\u6253\u4e0a\u4f11\u6b62\u7b26\u3002\u53cd\u53db\u4e4b\u65f6\u5df2\u81f3\u3002"}, {"label": "\u4ea4\u6613", "text": "\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002\u4f46\u82e5\u672a\u7231\u62a4\u4e50\u5668\u5c06\u906d\u53cd\u51fb\u3002", "line": "\u4ea4\u6613\uff1a\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002\u4f46\u82e5\u672a\u7231\u62a4\u4e50\u5668\u5c06\u906d\u53cd\u51fb\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u3001\u53e4\u5178\u6587\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u3001\u53e4\u5178\u6587\u5b66\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5373\u4fbf\u7f3a\u4e4f\u6d3b\u529b\uff0c\u4e5f\u80fd\u9010\u6e10\u6062\u590d\u3002", "line": "\u5065\u5eb7\uff1a\u5373\u4fbf\u7f3a\u4e4f\u6d3b\u529b\uff0c\u4e5f\u80fd\u9010\u6e10\u6062\u590d\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5c06\u8ff7\u5931\u65b9\u5411\u3002\u591c\u6e38\u968f\u884c\u961f\u5217\u6050\u906d\u4e0d\u6d4b\u3002", "line": "\u51fa\u884c\uff1a\u5c06\u8ff7\u5931\u65b9\u5411\u3002\u591c\u6e38\u968f\u884c\u961f\u5217\u6050\u906d\u4e0d\u6d4b\u3002"}, {"label": "\u604b\u7231", "text": "\u8ff7\u4e8e\u60c5\u8def\uff0c\u4f46\u7ec8\u5f97\u826f\u4eba\u3002", "line": "\u604b\u7231\uff1a\u8ff7\u4e8e\u60c5\u8def\uff0c\u4f46\u7ec8\u5f97\u826f\u4eba\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u65e0\u4ee5\u589e\u957f\u3002", "line": "\u8d22\u8fd0\uff1a\u65e0\u4ee5\u589e\u957f\u3002"}, {"label": "\u4eba\u7f18", "text": "\u8d77\u521d\u6613\u906d\u4eba\u5acc\u5f03\u3002\u6b22\u6b4c\u7b11\u8bed\u5219\u5bbe\u670b\u4e91\u96c6\u3002", "line": "\u4eba\u7f18\uff1a\u8d77\u521d\u6613\u906d\u4eba\u5acc\u5f03\u3002\u6b22\u6b4c\u7b11\u8bed\u5219\u5bbe\u670b\u4e91\u96c6\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (77, '九十九八桥', '末吉', '弹奏心灵的古琴付丧神', '自行发声演奏程度的能力', '["\u96be\u5f97\u6765\u5230\u8fd9", "\u4e16\u4e0a\u8d70\u4e00\u906d\uff0c", "\u8fc7\u4e8e\u8ba4\u6b7b\u7406\uff0c", "\u5c82\u4e0d\u4e8f\u5927\u4e86\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e5\u5e38\u4e50\u8da3\u6e10\u589e\u3002\u5feb\u4e50\u751f\u6d3b\u4fbf\u662f\u8d62\u5bb6\u3002", "line": "\u8fd0\u52bf\uff1a\u65e5\u5e38\u4e50\u8da3\u6e10\u589e\u3002\u5feb\u4e50\u751f\u6d3b\u4fbf\u662f\u8d62\u5bb6\u3002"}, {"label": "\u4ea4\u6613", "text": "\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002\u5bab\u5ef7\u97f3\u4e50\u5c24\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u97f3\u4e50\u76f8\u5173\u884c\u4e1a\u4e3a\u5409\u3002\u5bab\u5ef7\u97f3\u4e50\u5c24\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u4e0e\u53e4\u5178\u6587\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u4e0e\u53e4\u5178\u6587\u5b66\u4e3a\u5409\u3002"}, {"label": "\u51fa\u884c", "text": "\u8457\u540d\u666f\u70b9\u4e3a\u5b9c\u3002\u4e0e\u961f\u5217\u540c\u884c\u53ef\u589e\u6709\u8da3\u89c1\u95fb\u3002", "line": "\u51fa\u884c\uff1a\u8457\u540d\u666f\u70b9\u4e3a\u5b9c\u3002\u4e0e\u961f\u5217\u540c\u884c\u53ef\u589e\u6709\u8da3\u89c1\u95fb\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u6089\u5fc3\u4fdd\u517b\u6307\u7532\u4e3a\u5409\u3002", "line": "\u5065\u5eb7\uff1a\u6089\u5fc3\u4fdd\u517b\u6307\u7532\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u4e0d\u751a\u5173\u5fc3\u3002", "line": "\u604b\u7231\uff1a\u4e0d\u751a\u5173\u5fc3\u3002"}, {"label": "\u4e89\u7aef", "text": "\u65f6\u5e38\u53d1\u751f\u3002\u81ea\u4ee5\u4e3a\u80fd\u501f\u52a9\u97f3\u4e50\u907f\u5f00\u4e89\u7aef\uff0c\u7ed3\u679c\u53cd\u800c\u81ea\u8ba8\u82e6\u5403\u3002", "line": "\u4e89\u7aef\uff1a\u65f6\u5e38\u53d1\u751f\u3002\u81ea\u4ee5\u4e3a\u80fd\u501f\u52a9\u97f3\u4e50\u907f\u5f00\u4e89\u7aef\uff0c\u7ed3\u679c\u53cd\u800c\u81ea\u8ba8\u82e6\u5403\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u65e0\u4ee5\u589e\u957f\u3002", "line": "\u8d22\u8fd0\uff1a\u65e0\u4ee5\u589e\u957f\u3002"}, {"label": "\u7231\u597d", "text": "\u53ef\u9047\u89e6\u52a8\u5fc3\u5f26\u4e4b\u4f5c\u3002\u591a\u591a\u5c1d\u8bd5\u4e3a\u4f73\u3002", "line": "\u7231\u597d\uff1a\u53ef\u9047\u89e6\u52a8\u5fc3\u5f26\u4e4b\u4f5c\u3002\u591a\u591a\u5c1d\u8bd5\u4e3a\u4f73\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (78, '鬼人正邪', '大凶', '自诩孤高的天邪鬼', '翻转一切程度的能力', '["\u5e38\u4eba\u7684\u4e50\u8da3", "\u90fd\u65e0\u804a\u900f\u9876\u3002", "\u8fd9\u5c31\u662f\u4f60\u60f3", "\u8981\u7684\u4eba\u751f\u5417\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u81ea\u7edd\u597d\u8fd0\u4e4b\u5146\u3002\u65e0\u6cd5\u5f97\u5230\u65c1\u4eba\u7684\u534f\u52a9\u3002", "line": "\u8fd0\u52bf\uff1a\u81ea\u7edd\u597d\u8fd0\u4e4b\u5146\u3002\u65e0\u6cd5\u5f97\u5230\u65c1\u4eba\u7684\u534f\u52a9\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e8e\u6210\u529f\u524d\u5915\u81ea\u884c\u653e\u5f03\u3002", "line": "\u4ea4\u6613\uff1a\u4e8e\u6210\u529f\u524d\u5915\u81ea\u884c\u653e\u5f03\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e3b\u52a8\u7834\u8d22\uff0c\u81ea\u5f97\u5176\u4e50\u3002\u5b58\u4e0d\u4e86\u94b1\u3002", "line": "\u8d22\u8fd0\uff1a\u4e3b\u52a8\u7834\u8d22\uff0c\u81ea\u5f97\u5176\u4e50\u3002\u5b58\u4e0d\u4e86\u94b1\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6545\u610f\u7b54\u9519\uff0c\u81ea\u9e23\u5f97\u610f\u3002", "line": "\u5b66\u4e1a\uff1a\u6545\u610f\u7b54\u9519\uff0c\u81ea\u9e23\u5f97\u610f\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u8eab\u5f3a\u4f53\u5065\uff0c\u4ece\u4e0d\u53d7\u4f24\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u5f3a\u4f53\u5065\uff0c\u4ece\u4e0d\u53d7\u4f24\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5bb6\u5e38\u4fbf\u996d\u3002", "line": "\u4e89\u7aef\uff1a\u5bb6\u5e38\u4fbf\u996d\u3002"}, {"label": "\u604b\u7231", "text": "\u4e3b\u52a8\u758f\u8fdc\u610f\u4e2d\u4eba\u3002\u5b9e\u5728\u9057\u61be\u3002", "line": "\u604b\u7231\uff1a\u4e3b\u52a8\u758f\u8fdc\u610f\u4e2d\u4eba\u3002\u5b9e\u5728\u9057\u61be\u3002"}, {"label": "\u51fa\u884c", "text": "\u4eba\u8ff9\u7f55\u81f3\u7684\u65e0\u804a\u666f\u70b9\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4eba\u8ff9\u7f55\u81f3\u7684\u65e0\u804a\u666f\u70b9\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5584\u4eba\u6076\u4eba\u7686\u9003\u4e4b\u592d\u592d\u3002", "line": "\u4eba\u7f18\uff1a\u5584\u4eba\u6076\u4eba\u7686\u9003\u4e4b\u592d\u592d\u3002"}, {"label": "\u7269\u4ef6", "text": "\u552f\u4e00\u7684\u540c\u4f34\u3002\u6b7b\u7269\u4e0d\u4f1a\u80cc\u53db\u3002", "line": "\u7269\u4ef6\uff1a\u552f\u4e00\u7684\u540c\u4f34\u3002\u6b7b\u7269\u4e0d\u4f1a\u80cc\u53db\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (79, '少名针妙丸', '小吉', '高贵的小人族后裔', '使用万宝槌程度的能力', '["\u592a\u5c0f\u5bb6\u5b50\u6c14", "\u54ea\u80fd\u6210\u5927\u4e8b\u3002", "\u5c31\u5f97\u4e0b\u8c6a\u8d4c", "\u4e00\u53d1\u53bb\u7ffb\u76d8\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7f6e\u8eab\u6c14\u8fd0\u6d2a\u6d41\u4e4b\u4e2d\u3002\u52a1\u5fc5\u5fa1\u6d41\u800c\u884c\uff0c\u5207\u83ab\u968f\u6ce2\u9010\u6d41\u3002", "line": "\u8fd0\u52bf\uff1a\u7f6e\u8eab\u6c14\u8fd0\u6d2a\u6d41\u4e4b\u4e2d\u3002\u52a1\u5fc5\u5fa1\u6d41\u800c\u884c\uff0c\u5207\u83ab\u968f\u6ce2\u9010\u6d41\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8fc7\u4e8e\u597d\u9ad8\u9a9b\u8fdc\uff0c\u53cd\u800c\u96be\u6210\u5927\u4e1a\u3002", "line": "\u4ea4\u6613\uff1a\u8fc7\u4e8e\u597d\u9ad8\u9a9b\u8fdc\uff0c\u53cd\u800c\u96be\u6210\u5927\u4e1a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u6446\u6e21\u3001\u917f\u9152\u3001\u88c1\u7f1d\u3001\u9020\u53cd\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u6446\u6e21\u3001\u917f\u9152\u3001\u88c1\u7f1d\u3001\u9020\u53cd\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8111\u5bb9\u91cf\u867d\u5c0f\uff0c\u5374\u5927\u6709\u624d\u534e\u3002", "line": "\u5b66\u4e1a\uff1a\u8111\u5bb9\u91cf\u867d\u5c0f\uff0c\u5374\u5927\u6709\u624d\u534e\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5f53\u4e0b\u6709\u75be\u60a3\u4e4b\u865e\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u4e0b\u6709\u75be\u60a3\u4e4b\u865e\u3002"}, {"label": "\u604b\u7231", "text": "\u6ca1\u4eba\u7406\u776c\u3002", "line": "\u604b\u7231\uff1a\u6ca1\u4eba\u7406\u776c\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5b58\u5728\u7f3a\u9677\u3002", "line": "\u4f4f\u6240\uff1a\u5b58\u5728\u7f3a\u9677\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u4e58\u8239\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u4e58\u8239\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5bb6\u8d22\u4e07\u8d2f\u3002", "line": "\u8d22\u8fd0\uff1a\u5bb6\u8d22\u4e07\u8d2f\u3002"}, {"label": "\u5fcc\u8bb3", "text": "\u907f\u514d\u63a5\u89e6\u8089\u98df\u52a8\u7269\u3002\u4f1a\u88ab\u5403\u6389\u3002", "line": "\u5fcc\u8bb3\uff1a\u907f\u514d\u63a5\u89e6\u8089\u98df\u52a8\u7269\u3002\u4f1a\u88ab\u5403\u6389\u3002"}, {"label": "\u5fc3\u613f", "text": "\u5fc5\u80fd\u5b9e\u73b0\uff0c\u4f46\u8981\u4ed8\u51fa\u5de8\u5927\u4ee3\u4ef7\u3002", "line": "\u5fc3\u613f\uff1a\u5fc5\u80fd\u5b9e\u73b0\uff0c\u4f46\u8981\u4ed8\u51fa\u5de8\u5927\u4ee3\u4ef7\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (80, '堀川雷鼓', '末大吉', '拥有原初音源的付丧神', '让一切跟上节奏程度的能力', '["\u65f6\u95f4\u6709\u6781\u9650\u3002", "\u666e\u6717\u514b\u5355\u4f4d", "\u5c06\u4e00\u5207\u9f13\u52a8", "\u90fd\u6089\u6570\u540c\u6b65\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u751f\u6d3b\u8282\u594f\u826f\u597d\u3002\u8fd0\u52bf\u968f\u4e4b\u8d70\u9ad8\u3002", "line": "\u8fd0\u52bf\uff1a\u751f\u6d3b\u8282\u594f\u826f\u597d\u3002\u8fd0\u52bf\u968f\u4e4b\u8d70\u9ad8\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5165\u804c\u516c\u53f8\u4e3a\u5409\u3002\u9f13\u624b\u5219\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5165\u804c\u516c\u53f8\u4e3a\u5409\u3002\u9f13\u624b\u5219\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u80fd\u591f\u8ddf\u4e0a\u8282\u594f\uff0c\u8fdb\u6b65\u795e\u901f\u3002\u97f3\u4e50\u3001\u4f53\u80b2\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u80fd\u591f\u8ddf\u4e0a\u8282\u594f\uff0c\u8fdb\u6b65\u795e\u901f\u3002\u97f3\u4e50\u3001\u4f53\u80b2\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5e94\u51c6\u5907\u9694\u97f3\u8bbe\u5907\u3002", "line": "\u4f4f\u6240\uff1a\u5e94\u51c6\u5907\u9694\u97f3\u8bbe\u5907\u3002"}, {"label": "\u604b\u7231", "text": "\u6ce2\u957f\u76f8\u5408\u3002", "line": "\u604b\u7231\uff1a\u6ce2\u957f\u76f8\u5408\u3002"}], [{"label": "\u51fa\u884c", "text": "\u524d\u5f80\u8282\u5e86\u6d3b\u52a8\u73b0\u573a\u4e3a\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u524d\u5f80\u8282\u5e86\u6d3b\u52a8\u73b0\u573a\u4e3a\u5927\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u4e50\u961f\u6d3b\u52a8\u538b\u5012\u6027\u80dc\u51fa\u3002", "line": "\u7231\u597d\uff1a\u4e50\u961f\u6d3b\u52a8\u538b\u5012\u6027\u80dc\u51fa\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5b9e\u5c5e\u9057\u61be\u3002", "line": "\u8d22\u8fd0\uff1a\u5b9e\u5c5e\u9057\u61be\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e50\u8ff7\u4e91\u96c6\u3002", "line": "\u4eba\u7f18\uff1a\u4e50\u8ff7\u4e91\u96c6\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u4f53\u72b6\u51b5\u6709\u6240\u6539\u5584\u3002\u5e38\u88ab\u6572\u6253\uff0c\u4f24\u75db\u4e0d\u65ad\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u4f53\u72b6\u51b5\u6709\u6240\u6539\u5584\u3002\u5e38\u88ab\u6572\u6253\uff0c\u4f24\u75db\u4e0d\u65ad\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (81, '茨木华扇', '凶', '喜爱动物的有角仙人', '引导动物程度的能力', '["\u6b63\u5982\u4f60\u6240\u77e5\uff0c", "\u559c\u7231\u52a8\u7269\u8005", "\u5fc5\u7136\u6709\u4e00\u9897", "\u7f8e\u4e3d\u7684\u5fc3\u7075\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5fc3\u613f\u5f97\u4ee5\u5b9e\u73b0\uff0c\u4f46\u8981\u4ed8\u51fa\u5de8\u5927\u4ee3\u4ef7\uff0c\u6574\u4f53\u6765\u770b\u798f\u4e0d\u62b5\u7978\u3002", "line": "\u8fd0\u52bf\uff1a\u5fc3\u613f\u5f97\u4ee5\u5b9e\u73b0\uff0c\u4f46\u8981\u4ed8\u51fa\u5de8\u5927\u4ee3\u4ef7\uff0c\u6574\u4f53\u6765\u770b\u798f\u4e0d\u62b5\u7978\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4ece\u4e8b\u670d\u52a1\u4e1a\u5c06\u4e3e\u6b65\u7ef4\u8270\u3002\u4e0e\u52a8\u7269\u6253\u4ea4\u9053\u7684\u5de5\u4f5c\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4ece\u4e8b\u670d\u52a1\u4e1a\u5c06\u4e3e\u6b65\u7ef4\u8270\u3002\u4e0e\u52a8\u7269\u6253\u4ea4\u9053\u7684\u5de5\u4f5c\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u751f\u7269\u3001\u53e4\u6587\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u751f\u7269\u3001\u53e4\u6587\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8c28\u9632\u624b\u81c2\u53d7\u4f24\u3002\u9157\u9152\u4ea6\u4e3a\u5927\u5fcc\u3002", "line": "\u5065\u5eb7\uff1a\u8c28\u9632\u624b\u81c2\u53d7\u4f24\u3002\u9157\u9152\u4ea6\u4e3a\u5927\u5fcc\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5fcc\u795e\u793e\u3001\u4f5b\u5bfa\u3002", "line": "\u51fa\u884c\uff1a\u5fcc\u795e\u793e\u3001\u4f5b\u5bfa\u3002"}, {"label": "\u4f4f\u6240", "text": "\u6df1\u5c71\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u6df1\u5c71\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u9177\u7231\u8bf4\u6559\uff0c\u88ab\u4eba\u656c\u800c\u8fdc\u4e4b\u3002", "line": "\u4eba\u7f18\uff1a\u9177\u7231\u8bf4\u6559\uff0c\u88ab\u4eba\u656c\u800c\u8fdc\u4e4b\u3002"}, {"label": "\u604b\u7231", "text": "\u7c97\u72b7\u4e4b\u4eba\u4e3a\u5409\u3002", "line": "\u604b\u7231\uff1a\u7c97\u72b7\u4e4b\u4eba\u4e3a\u5409\u3002"}, {"label": "\u52a8\u7269", "text": "\u9972\u517b\u731b\u79bd\u5219\u767e\u6218\u767e\u80dc\uff0c\u517b\u86c7\u5219\u8d22\u8fd0\u4ea8\u901a\uff0c\u517b\u732b\u5219\u4eba\u9645\u81f4\u7965\uff0c\u517b\u733f\u5219\u4e07\u4e8b\u5982\u610f\u3002", "line": "\u52a8\u7269\uff1a\u9972\u517b\u731b\u79bd\u5219\u767e\u6218\u767e\u80dc\uff0c\u517b\u86c7\u5219\u8d22\u8fd0\u4ea8\u901a\uff0c\u517b\u732b\u5219\u4eba\u9645\u81f4\u7965\uff0c\u517b\u733f\u5219\u4e07\u4e8b\u5982\u610f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (82, '宇佐见堇子', '凶', '秘封俱乐部初代部长', '操纵超能力程度的能力', '["\u5b66\u6821\u5c31\u662f\u4e2a", "\u865a\u4f2a\u81f3\u6781\u7684\u3002", "\u9053\u5fb7\u5927\u5267\u9662\u3002", "\u80a4\u6d45\u7684\u6f14\u6280\uff0c", "\u5b66\u6765\u6709\u4f55\u7528\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e0d\u8d70\u5bfb\u5e38\u8def\u3002\u56e0\u6b64\u524d\u8def\u8346\u68d8\u4e1b\u751f\u3002", "line": "\u8fd0\u52bf\uff1a\u4e0d\u8d70\u5bfb\u5e38\u8def\u3002\u56e0\u6b64\u524d\u8def\u8346\u68d8\u4e1b\u751f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u540d\u5217\u524d\u8305\uff0c\u4f46\u5fc3\u5883\u53d8\u5dee\u3002", "line": "\u5b66\u4e1a\uff1a\u540d\u5217\u524d\u8305\uff0c\u4f46\u5fc3\u5883\u53d8\u5dee\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u7075\u5f02\u5de5\u4f5c\u4e3a\u5409\u3002\u4f5c\u5bb6\u3001\u5492\u672f\u5e08\u3001\u7075\u5a92\u3001\u9b54\u672f\u5e08\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u7075\u5f02\u5de5\u4f5c\u4e3a\u5409\u3002\u4f5c\u5bb6\u3001\u5492\u672f\u5e08\u3001\u7075\u5a92\u3001\u9b54\u672f\u5e08\u4e3a\u5927\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4f53\u5f31\u591a\u75c5\u3002\u8bc5\u5492\u7f20\u8eab\u3002", "line": "\u5065\u5eb7\uff1a\u4f53\u5f31\u591a\u75c5\u3002\u8bc5\u5492\u7f20\u8eab\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u4e0d\u5f97\u4eba\u5fc3\u3002\u82e5\u9047\u5fd7\u540c\u9053\u5408\u8005\u5219\u53ef\u6210\u91d1\u77f3\u4e4b\u4ea4\u3002", "line": "\u4eba\u7f18\uff1a\u4e0d\u5f97\u4eba\u5fc3\u3002\u82e5\u9047\u5fd7\u540c\u9053\u5408\u8005\u5219\u53ef\u6210\u91d1\u77f3\u4e4b\u4ea4\u3002"}, {"label": "\u604b\u7231", "text": "\u65e0\u671b\u3002", "line": "\u604b\u7231\uff1a\u65e0\u671b\u3002"}, {"label": "\u51fa\u884c", "text": "\u7075\u5f02\u5730\u70b9\u4e3a\u5409\u3002\u5c06\u9047\u795e\u9690\u3002", "line": "\u51fa\u884c\uff1a\u7075\u5f02\u5730\u70b9\u4e3a\u5409\u3002\u5c06\u9047\u795e\u9690\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u5bb6\u4eba\u662f\u575a\u5f3a\u7684\u540e\u76fe\u3002", "line": "\u5bb6\u5ead\uff1a\u5bb6\u4eba\u662f\u575a\u5f3a\u7684\u540e\u76fe\u3002"}, {"label": "\u7231\u597d", "text": "\u72ec\u4e50\u4e3a\u5b9c\u3002\u4f46\u4e0e\u4e92\u8054\u7f51\u516b\u5b57\u4e0d\u5408\u3002", "line": "\u7231\u597d\uff1a\u72ec\u4e50\u4e3a\u5b9c\u3002\u4f46\u4e0e\u4e92\u8054\u7f51\u516b\u5b57\u4e0d\u5408\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (83, '清兰', '吉', '从天而降的月兔', '从异次元发射子弹程度的能力', '["\u6708\u5154\u64ce\u6775", "\u6363\u4f55\u7269", "\u56e2\u5b50\u8fd8\u662f", "\u7ea2\u79cb\u679c"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5154\u4e43\u5409\u5146\u3002 \u5c06\u6709\u7a00\u4e16\u5947\u9047\u3002", "line": "\u8fd0\u52bf\uff1a\u5154\u4e43\u5409\u5146\u3002 \u5c06\u6709\u7a00\u4e16\u5947\u9047\u3002"}, {"label": "\u51fa\u884c", "text": "\u901f\u901f\u52a8\u8eab\u3002 \u9020\u8bbf\u964c\u751f\u571f\u5730\u4e3a\u5409\u3002 \u5c24\u5b9c\u767b\u6708\u3002", "line": "\u51fa\u884c\uff1a\u901f\u901f\u52a8\u8eab\u3002 \u9020\u8bbf\u964c\u751f\u571f\u5730\u4e3a\u5409\u3002 \u5c24\u5b9c\u767b\u6708\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5546\u624d\u4e0d\u6d4e\u3002 \u9690\u5fcd\u4e3a\u4e0a\u3002", "line": "\u4ea4\u6613\uff1a\u5546\u624d\u4e0d\u6d4e\u3002 \u9690\u5fcd\u4e3a\u4e0a\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u4e0d\u5982\u65c5\u884c\u3002", "line": "\u5b66\u4e1a\uff1a\u4e0d\u5982\u65c5\u884c\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5728\u6240\u96be\u514d\uff0c\u4e0d\u5fc5\u5728\u610f\u3002", "line": "\u4e89\u7aef\uff1a\u5728\u6240\u96be\u514d\uff0c\u4e0d\u5fc5\u5728\u610f\u3002"}, {"label": "\u604b\u7231", "text": "\u4e0d\u5fc5\u5728\u610f\u3002", "line": "\u604b\u7231\uff1a\u4e0d\u5fc5\u5728\u610f\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6ce8\u610f\u517b\u751f\u5373\u53ef\u5f3a\u8eab\u5065\u4f53\u3002", "line": "\u5065\u5eb7\uff1a\u6ce8\u610f\u517b\u751f\u5373\u53ef\u5f3a\u8eab\u5065\u4f53\u3002"}, {"label": "\u8282\u5e86", "text": "\u79ef\u6781\u53c2\u52a0\u4e3a\u5409\u3002 \u6363\u5e74\u7cd5\u5c24\u5409\u3002", "line": "\u8282\u5e86\uff1a\u79ef\u6781\u53c2\u52a0\u4e3a\u5409\u3002 \u6363\u5e74\u7cd5\u5c24\u5409\u3002"}, {"label": "\u751c\u70b9", "text": "\u6811\u8393\u56e2\u5b50\u4e3a\u4f73\u3002", "line": "\u751c\u70b9\uff1a\u6811\u8393\u56e2\u5b50\u4e3a\u4f73\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (84, '铃瑚', '吉', '赏月不如品团子的月兔', '吃团子越多变得越强程度的能力', '["\u9c9c\u82b1\u8ddf\u56e2\u5b50", "\u54ea\u80fd\u76f8\u5e76\u8bba", "1", "\u3002", "\u6708\u4eae\u548c\u56e2\u5b50", "\u624d\u80fd\u6bd4\u4e00\u6bd4\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7eb5\u7136\u8eab\u5904\u56f0\u5883\uff0c\u4e5f\u80fd\u6cf0\u7136\u81ea\u4e50\u3002", "line": "\u8fd0\u52bf\uff1a\u7eb5\u7136\u8eab\u5904\u56f0\u5883\uff0c\u4e5f\u80fd\u6cf0\u7136\u81ea\u4e50\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9002\u5408\u8fdb\u5165\u4fe1\u606f\u5904\u7406\u884c\u4e1a\u3002\u7ecf\u8425\u56e2\u5b50\u5e97\u4ea6\u53ef\u3002", "line": "\u4ea4\u6613\uff1a\u9002\u5408\u8fdb\u5165\u4fe1\u606f\u5904\u7406\u884c\u4e1a\u3002\u7ecf\u8425\u56e2\u5b50\u5e97\u4ea6\u53ef\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9887\u4e3a\u987a\u9042\u3002\u4f46\u4e25\u7981\u7a7a\u8179\u5b66\u4e60\u3002", "line": "\u5b66\u4e1a\uff1a\u9887\u4e3a\u987a\u9042\u3002\u4f46\u4e25\u7981\u7a7a\u8179\u5b66\u4e60\u3002"}, {"label": "\u4f4f\u6240", "text": "\u4e0d\u5f52\u4e4b\u65e5\u6e10\u591a\u3002", "line": "\u4f4f\u6240\uff1a\u4e0d\u5f52\u4e4b\u65e5\u6e10\u591a\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5fcc\u66b4\u996e\u66b4\u98df\u3002", "line": "\u5065\u5eb7\uff1a\u5fcc\u66b4\u996e\u66b4\u98df\u3002"}, {"label": "\u604b\u7231", "text": "\u5174\u8da3\u76f8\u6295\u8005\u4e3a\u4f73\u3002", "line": "\u604b\u7231\uff1a\u5174\u8da3\u76f8\u6295\u8005\u4e3a\u4f73\u3002"}, {"label": "\u51fa\u884c", "text": "\u7387\u6027\u8fdc\u884c\u4e3a\u5409\u3002\u7a7a\u60f3\u4e4b\u65c5\u4ea6\u53ef\u3002", "line": "\u51fa\u884c\uff1a\u7387\u6027\u8fdc\u884c\u4e3a\u5409\u3002\u7a7a\u60f3\u4e4b\u65c5\u4ea6\u53ef\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5982\u5f71\u968f\u5f62\uff0c\u80fd\u907f\u5219\u907f\u3002", "line": "\u4e89\u7aef\uff1a\u5982\u5f71\u968f\u5f62\uff0c\u80fd\u907f\u5219\u907f\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u65e0\u671b\u66b4\u5bcc\u3002\u5f53\u987a\u5176\u81ea\u7136\u3002", "line": "\u8d22\u8fd0\uff1a\u65e0\u671b\u66b4\u5bcc\u3002\u5f53\u987a\u5176\u81ea\u7136\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (85, '哆来咪·苏伊特', '末大吉', '支配梦境之貘', '食梦、造梦程度的能力', '["\u6f5c\u610f\u8bc6\u82e5\u662f", "\u7b49\u540c\u4e8e\u68a6\u5883\uff0c", "\u5219\u68a6\u5373\u4e16\u754c\u3002", "\u68a6\u5883\u7684\u4e3b\u5bb0", "\u5c06\u541b\u4e34\u4e16\u754c\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5c06\u88ab\u5377\u5165\u547d\u8fd0\u6d2a\u6d41\u3002\u5b88\u4f4f\u672c\u6211\u5373\u53ef\u4e58\u98ce\u7834\u6d6a\u3002", "line": "\u8fd0\u52bf\uff1a\u5c06\u88ab\u5377\u5165\u547d\u8fd0\u6d2a\u6d41\u3002\u5b88\u4f4f\u672c\u6211\u5373\u53ef\u4e58\u98ce\u7834\u6d6a\u3002"}, {"label": "\u5fc3\u613f", "text": "\u6240\u68a6\u7686\u6210\u771f\u3002\u68a6\u4e2d\u89c1\u95fb\u5f53\u7262\u8bb0\u4e8e\u5fc3\u3002", "line": "\u5fc3\u613f\uff1a\u6240\u68a6\u7686\u6210\u771f\u3002\u68a6\u4e2d\u89c1\u95fb\u5f53\u7262\u8bb0\u4e8e\u5fc3\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u68a6\u4e2d\u5b66\u4e60\u6548\u679c\u7edd\u4f73\u3002\u5f53\u4fdd\u8bc1\u7761\u7720\u3002", "line": "\u5b66\u4e1a\uff1a\u68a6\u4e2d\u5b66\u4e60\u6548\u679c\u7edd\u4f73\u3002\u5f53\u4fdd\u8bc1\u7761\u7720\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5947\u601d\u5999\u60f3\u4ece\u5929\u800c\u964d\u3002\u76f8\u4fe1\u81ea\u5df1\u5373\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u5947\u601d\u5999\u60f3\u4ece\u5929\u800c\u964d\u3002\u76f8\u4fe1\u81ea\u5df1\u5373\u4e3a\u5927\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u9891\u9891\u505a\u68a6\uff0c\u7565\u611f\u5026\u610f\u3002", "line": "\u5065\u5eb7\uff1a\u9891\u9891\u505a\u68a6\uff0c\u7565\u611f\u5026\u610f\u3002"}, {"label": "\u51fa\u884c", "text": "\u8e0f\u4e0a\u68a6\u5e7b\u65c5\u9014\u3002", "line": "\u51fa\u884c\uff1a\u8e0f\u4e0a\u68a6\u5e7b\u65c5\u9014\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u65e0\u9700\u82b1\u94b1\u3002", "line": "\u8d22\u8fd0\uff1a\u65e0\u9700\u82b1\u94b1\u3002"}, {"label": "\u7269\u4ef6", "text": "\u5f97\u9047\u5fc3\u4eea\u6795\u5934\u3002", "line": "\u7269\u4ef6\uff1a\u5f97\u9047\u5fc3\u4eea\u6795\u5934\u3002"}, {"label": "\u8eab\u4f53", "text": "\u82e5\u6df7\u6dc6\u68a6\u5883\u4e0e\u73b0\u5b9e\u5219\u4e3a\u5927\u51f6\u3002", "line": "\u8eab\u4f53\uff1a\u82e5\u6df7\u6dc6\u68a6\u5883\u4e0e\u73b0\u5b9e\u5219\u4e3a\u5927\u51f6\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (86, '稀神探女', '吉凶不定', '刻意缄口的女神', '从口中说出便可逆转事态程度的能力', '["\u6211\u5373\u662f\u707e\u661f\uff0c", "\u751f\u6765\u8d70\u9709\u8fd0\u3002", "\u6b64\u8bdd\u4e00\u51fa\u53e3\uff0c", "\u798f\u8fd0\u5b9a\u7136\u6765\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7978\u4ece\u53e3\u51fa\u3002\u95ed\u53e3\u4e0d\u8bed\u4ea6\u5c06\u9519\u5931\u826f\u673a\u3002", "line": "\u8fd0\u52bf\uff1a\u7978\u4ece\u53e3\u51fa\u3002\u95ed\u53e3\u4e0d\u8bed\u4ea6\u5c06\u9519\u5931\u826f\u673a\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e07\u4e8b\u7686\u4e0e\u613f\u8fdd\u3002", "line": "\u4ea4\u6613\uff1a\u4e07\u4e8b\u7686\u4e0e\u613f\u8fdd\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7f04\u53e3\u7528\u529f\uff0c\u5fc5\u6709\u957f\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u7f04\u53e3\u7528\u529f\uff0c\u5fc5\u6709\u957f\u8fdb\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5f53\u5fc3\u53e3\u820c\u4e4b\u7978\u3002", "line": "\u4e89\u7aef\uff1a\u5f53\u5fc3\u53e3\u820c\u4e4b\u7978\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5b9c\u5f80\u4eba\u8ff9\u7f55\u81f3\u5904\u3002\u767b\u6708\u4ea6\u53ef\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u5f80\u4eba\u8ff9\u7f55\u81f3\u5904\u3002\u767b\u6708\u4ea6\u53ef\u3002"}, {"label": "\u5065\u5eb7", "text": "\u81ea\u89c6\u5eb7\u5065\u5219\u6c14\u529b\u8870\u51cf\uff0c\u81ea\u8ba4\u8870\u9893\u5219\u5bb9\u5149\u7115\u53d1\u3002", "line": "\u5065\u5eb7\uff1a\u81ea\u89c6\u5eb7\u5065\u5219\u6c14\u529b\u8870\u51cf\uff0c\u81ea\u8ba4\u8870\u9893\u5219\u5bb9\u5149\u7115\u53d1\u3002"}, {"label": "\u5fc3\u613f", "text": "\u65ad\u5ff5\u53cd\u5f97\u5982\u613f\u3002", "line": "\u5fc3\u613f\uff1a\u65ad\u5ff5\u53cd\u5f97\u5982\u613f\u3002"}, {"label": "\u604b\u7231", "text": "\u6781\u5176\u56f0\u96be\u3002", "line": "\u604b\u7231\uff1a\u6781\u5176\u56f0\u96be\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u906d\u9047\u8bc8\u9a97\u3002\u8b66\u60d5\u6240\u8c13\u66b4\u5bcc\u673a\u4f1a\u3002", "line": "\u8d22\u8fd0\uff1a\u906d\u9047\u8bc8\u9a97\u3002\u8b66\u60d5\u6240\u8c13\u66b4\u5bcc\u673a\u4f1a\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (87, '克劳恩皮丝', '小凶', '跟随生命脉动起舞的妖精', '使人发狂程度的能力', '["\u5730\u72f1\u9ed1\u6f06\u6f06\uff0c", "\u5565\u4e5f\u770b\u4e0d\u89c1\uff1f", "\u73b0\u5728\u600e\u4e48\u6837\uff0c", "\u8fd9\u4e0b\u591f\u4eae\u5427\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u9ed1\u6697\u4e4b\u4e2d\u5f97\u89c1\u5149\u8292\u3002\u51dd\u89c6\u8fc7\u4e45\u5c06\u8d25\u6c14\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u9ed1\u6697\u4e4b\u4e2d\u5f97\u89c1\u5149\u8292\u3002\u51dd\u89c6\u8fc7\u4e45\u5c06\u8d25\u6c14\u8fd0\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4f53\u529b\u5145\u76c8\uff0c\u7cbe\u529b\u5145\u6c9b\u3002\u8c28\u9632\u72c2\u8e81\u60c5\u7eea\u3002", "line": "\u5065\u5eb7\uff1a\u4f53\u529b\u5145\u76c8\uff0c\u7cbe\u529b\u5145\u6c9b\u3002\u8c28\u9632\u72c2\u8e81\u60c5\u7eea\u3002"}, {"label": "\u4ea4\u6613", "text": "\u75af\u72c2\u8d5a\u94b1\uff0c\u4f46\u96be\u9003\u6295\u8bc9\u3002", "line": "\u4ea4\u6613\uff1a\u75af\u72c2\u8d5a\u94b1\uff0c\u4f46\u96be\u9003\u6295\u8bc9\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5b66\u4e60\uff1f\u5565\u73a9\u610f\u513f\uff1f", "line": "\u5b66\u4e1a\uff1a\u5b66\u4e60\uff1f\u5565\u73a9\u610f\u513f\uff1f"}], [{"label": "\u604b\u7231", "text": "\u604b\u706b\u718a\u718a\u3002", "line": "\u604b\u7231\uff1a\u604b\u706b\u718a\u718a\u3002"}, {"label": "\u51fa\u884c", "text": "\u6d77\u5916\u3001\u5730\u72f1\u3001\u6708\u4eae\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u6d77\u5916\u3001\u5730\u72f1\u3001\u6708\u4eae\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e07\u4f17\u9f50\u805a\uff0c\u5982\u75f4\u5982\u72c2\u3002\u9ebb\u70e6\u7f20\u8eab\u3002", "line": "\u4eba\u7f18\uff1a\u4e07\u4f17\u9f50\u805a\uff0c\u5982\u75f4\u5982\u72c2\u3002\u9ebb\u70e6\u7f20\u8eab\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4e3b\u52a8\u751f\u4e8b\u3002\u4e8b\u6001\u5931\u63a7\u4fbf\u5c06\u73a9\u706b\u81ea\u711a\u3002", "line": "\u4e89\u7aef\uff1a\u4e3b\u52a8\u751f\u4e8b\u3002\u4e8b\u6001\u5931\u63a7\u4fbf\u5c06\u73a9\u706b\u81ea\u711a\u3002"}, {"label": "\u7269\u4ef6", "text": "\u706b\u70ac\u3001\u661f\u6761\u65d7\u4e3a\u5409\u3002", "line": "\u7269\u4ef6\uff1a\u706b\u70ac\u3001\u661f\u6761\u65d7\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5e94\u68c0\u67e5\u6a90\u4e0b\u6709\u65e0\u4e0d\u901f\u4e4b\u5ba2\u3002", "line": "\u4f4f\u6240\uff1a\u5e94\u68c0\u67e5\u6a90\u4e0b\u6709\u65e0\u4e0d\u901f\u4e4b\u5ba2\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (88, '纯狐', '【大大凶】', '无穷无尽的仇怨', '纯化程度的能力', '["\u81ea\u7136\u4e0e\u751f\u547d\u3001", "\u4e43\u81f3\u662f\u611f\u60c5\uff0c", "\u4e00\u65e6\u7ecf\u63d0\u7eaf\uff0c", "\u90fd\u53ea\u4e0d\u8fc7\u662f", "\u666e\u901a\u7684\u4fe1\u606f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u957f\u5e74\u5fc3\u8840\u5c06\u6bc1\u4e8e\u4e00\u65e6\u3002\u4e0d\u5982\u7edf\u7edf\u820d\u5f03\u3002", "line": "\u8fd0\u52bf\uff1a\u957f\u5e74\u5fc3\u8840\u5c06\u6bc1\u4e8e\u4e00\u65e6\u3002\u4e0d\u5982\u7edf\u7edf\u820d\u5f03\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5173\u7cfb\u6d17\u724c\u4e4b\u65f6\u3002", "line": "\u4eba\u7f18\uff1a\u5173\u7cfb\u6d17\u724c\u4e4b\u65f6\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5316\u4e3a\u5e9f\u7eb8\u3002", "line": "\u8d22\u8fd0\uff1a\u5316\u4e3a\u5e9f\u7eb8\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u79ef\u6028\u7206\u53d1\u3002\u53ef\u8003\u8651\u8df3\u69fd\u3002\u516c\u5171\u670d\u52a1\u884c\u4e1a\u503c\u5f97\u4e00\u8bd5\u3002", "line": "\u5de5\u4f5c\uff1a\u79ef\u6028\u7206\u53d1\u3002\u53ef\u8003\u8651\u8df3\u69fd\u3002\u516c\u5171\u670d\u52a1\u884c\u4e1a\u503c\u5f97\u4e00\u8bd5\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u5e73\u65e5\u79ef\u7d2f\u51b3\u5b9a\u6210\u8d25\u3002\u5316\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u5e73\u65e5\u79ef\u7d2f\u51b3\u5b9a\u6210\u8d25\u3002\u5316\u5b66\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u5fc3\u80cc\u540e\u3002", "line": "\u604b\u7231\uff1a\u5f53\u5fc3\u80cc\u540e\u3002"}, {"label": "\u5065\u5eb7", "text": "\u80c3\u75db\u6765\u88ad\u3002", "line": "\u5065\u5eb7\uff1a\u80c3\u75db\u6765\u88ad\u3002"}, {"label": "\u51fa\u884c", "text": "\u5174\u5473\u7d22\u7136\u3002", "line": "\u51fa\u884c\uff1a\u5174\u5473\u7d22\u7136\u3002"}, {"label": "\u5bfb\u7269", "text": "\u518d\u96be\u627e\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u518d\u96be\u627e\u56de\u3002"}, {"label": "\u7231\u597d", "text": "\u5f97\u7aa5\u5965\u5999\u3002\u5c06\u7231\u597d\u8f6c\u5316\u4e3a\u804c\u4e1a\u53ef\u83b7\u6210\u529f\u3002", "line": "\u7231\u597d\uff1a\u5f97\u7aa5\u5965\u5999\u3002\u5c06\u7231\u597d\u8f6c\u5316\u4e3a\u804c\u4e1a\u53ef\u83b7\u6210\u529f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (89, '赫卡提亚·拉碧斯拉祖利', '吉·凶·大凶', '拥有三种运势的女神', '拥有三个身体程度的能力', '["\u8ba4\u77e5\u8d8a\u4e30\u5bcc\uff0c", "\u4e16\u754c\u8d8a\u5bbd\u5e7f\u3002", "\u591a\u6837\u6027\u624d\u662f", "\u5b87\u5b99\u7684\u5c3a\u5ea6\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6bcf\u5929\u65e9\u6668\u8fd0\u52bf\u53d8\u6362\u3002\u4e0d\u4ec5\u65e0\u6cd5\u63a7\u5236\uff0c\u800c\u4e14\u51f6\u591a\u5409\u5c11\u3002", "line": "\u8fd0\u52bf\uff1a\u6bcf\u5929\u65e9\u6668\u8fd0\u52bf\u53d8\u6362\u3002\u4e0d\u4ec5\u65e0\u6cd5\u63a7\u5236\uff0c\u800c\u4e14\u51f6\u591a\u5409\u5c11\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e00\u4eba\u9876\u4e09\u4eba\uff0c\u5de5\u4f5c\u4e5f\u4f1a\u53d8\u591a\u3002", "line": "\u5de5\u4f5c\uff1a\u4e00\u4eba\u9876\u4e09\u4eba\uff0c\u5de5\u4f5c\u4e5f\u4f1a\u53d8\u591a\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u79ef\u52b3\u6210\u75be\u3002\u81ea\u89c9\u8fd0\u52bf\u4e0d\u4f73\u4fbf\u5e94\u53ca\u65f6\u4f11\u606f\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u79ef\u52b3\u6210\u75be\u3002\u81ea\u89c9\u8fd0\u52bf\u4e0d\u4f73\u4fbf\u5e94\u53ca\u65f6\u4f11\u606f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9887\u4e3a\u987a\u9042\uff0c\u4f46\u5bb9\u6613\u8fc7\u52b3\u3002\u91cf\u5b50\u8272\u52a8\u529b\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u9887\u4e3a\u987a\u9042\uff0c\u4f46\u5bb9\u6613\u8fc7\u52b3\u3002\u91cf\u5b50\u8272\u52a8\u529b\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u65e0\u8bba\u524d\u5f80\u4f55\u5904\uff0c\u5730\u72f1\u5982\u5f71\u968f\u5f62\u3002\u6e29\u6cc9\u5219\u5e38\u5409\u3002", "line": "\u51fa\u884c\uff1a\u65e0\u8bba\u524d\u5f80\u4f55\u5904\uff0c\u5730\u72f1\u5982\u5f71\u968f\u5f62\u3002\u6e29\u6cc9\u5219\u5e38\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u81f3\u591a\u53ef\u4ee5\u811a\u8e0f\u4e09\u6761\u8239\u3002", "line": "\u604b\u7231\uff1a\u81f3\u591a\u53ef\u4ee5\u811a\u8e0f\u4e09\u6761\u8239\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u65e0\u5f80\u4e0d\u5229\u3002\u5207\u52ff\u4e3b\u52a8\u51fa\u51fb\u3002", "line": "\u6bd4\u8bd5\uff1a\u65e0\u5f80\u4e0d\u5229\u3002\u5207\u52ff\u4e3b\u52a8\u51fa\u51fb\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e3a\u4eba\u538c\u5f03\u3002", "line": "\u4eba\u7f18\uff1a\u4e3a\u4eba\u538c\u5f03\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u8d4c\u8fd0\u9887\u4f73\u3002", "line": "\u8d22\u8fd0\uff1a\u8d4c\u8fd0\u9887\u4f73\u3002"}, {"label": "\u7231\u597d", "text": "\u65f6\u5c1a\u9886\u57df\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u65f6\u5c1a\u9886\u57df\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (90, '依神女苑', '【大大凶】', '让努力付诸东流的疫病神', '使人消耗财产程度的能力', '["\u91d1\u94f6\u5929\u4e0b\u8f6c\uff0c", "\u8d2b\u5bcc\u671d\u5915\u53d8\u3002", "\u54ea\u4e2a\u8822\u5bb6\u4f19\uff0c", "\u5c45\u7136\u60f3\u5b58\u94b1\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8fc7\u7740\u6325\u970d\u65e0\u5ea6\u7684\u5962\u9761\u751f\u6d3b\uff0c\u7ec8\u6709\u4e00\u65e5\u4f1a\u4e07\u52ab\u4e0d\u590d\u3002", "line": "\u8fd0\u52bf\uff1a\u8fc7\u7740\u6325\u970d\u65e0\u5ea6\u7684\u5962\u9761\u751f\u6d3b\uff0c\u7ec8\u6709\u4e00\u65e5\u4f1a\u4e07\u52ab\u4e0d\u590d\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6325\u91d1\u5982\u571f\uff0c\u8986\u6c34\u96be\u6536\u3002\u4e00\u65e6\u501f\u8d37\u5fc5\u7136\u7834\u4ea7\u3002", "line": "\u8d22\u8fd0\uff1a\u6325\u91d1\u5982\u571f\uff0c\u8986\u6c34\u96be\u6536\u3002\u4e00\u65e6\u501f\u8d37\u5fc5\u7136\u7834\u4ea7\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u9002\u5b9c\u906d\u4eba\u538c\u5f03\u6216\u5f15\u4eba\u6ce8\u76ee\u7684\u5de5\u4f5c\u3002\u7a0e\u52a1\u7a3d\u67e5\u3001\u6f14\u827a\u5708\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u9002\u5b9c\u906d\u4eba\u538c\u5f03\u6216\u5f15\u4eba\u6ce8\u76ee\u7684\u5de5\u4f5c\u3002\u7a0e\u52a1\u7a3d\u67e5\u3001\u6f14\u827a\u5708\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u4f20\u67d3\u75c5\u7f20\u8eab\u3002", "line": "\u5065\u5eb7\uff1a\u4f20\u67d3\u75c5\u7f20\u8eab\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4ed8\u51fa\u52aa\u529b\u5374\u4e0d\u89c1\u6210\u679c\u3002", "line": "\u5b66\u4e1a\uff1a\u4ed8\u51fa\u52aa\u529b\u5374\u4e0d\u89c1\u6210\u679c\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4eba\u671b\u9887\u4f73\uff0c\u4f46\u6700\u7ec8\u4f1a\u4ee4\u6240\u6709\u4eba\u9677\u5165\u4e0d\u5e78\u3002", "line": "\u4eba\u7f18\uff1a\u4eba\u671b\u9887\u4f73\uff0c\u4f46\u6700\u7ec8\u4f1a\u4ee4\u6240\u6709\u4eba\u9677\u5165\u4e0d\u5e78\u3002"}, {"label": "\u51fa\u884c", "text": "\u9700\u89c4\u907f\u795e\u793e\u3001\u4f5b\u5bfa\u3002", "line": "\u51fa\u884c\uff1a\u9700\u89c4\u907f\u795e\u793e\u3001\u4f5b\u5bfa\u3002"}, {"label": "\u5bfb\u7269", "text": "\u518d\u65e0\u5bfb\u56de\u53ef\u80fd\u3002", "line": "\u5bfb\u7269\uff1a\u518d\u65e0\u5bfb\u56de\u53ef\u80fd\u3002"}, {"label": "\u604b\u7231", "text": "\u867d\u4f1a\u7834\u8d22\uff0c\u4f46\u8fdb\u5c55\u826f\u597d\u3002", "line": "\u604b\u7231\uff1a\u867d\u4f1a\u7834\u8d22\uff0c\u4f46\u8fdb\u5c55\u826f\u597d\u3002"}, {"label": "\u7231\u597d", "text": "\u7834\u7f50\u7834\u6454\u5927\u628a\u82b1\u94b1\uff0c\u81ea\u80fd\u4e50\u5728\u5176\u4e2d\u3002", "line": "\u7231\u597d\uff1a\u7834\u7f50\u7834\u6454\u5927\u628a\u82b1\u94b1\uff0c\u81ea\u80fd\u4e50\u5728\u5176\u4e2d\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (91, '依神紫苑', '【超大凶】', '让一切徒劳无功的贫穷神', '让一切陷入不幸程度的能力', '["\u50cf\u6211\u8fd9\u6837\u7684", "\u5012\u9709\u86cb\u7a77\u795e\uff0c", "\u80af\u5b9a\u5230\u6b7b\u4e5f", "\u5f97\u4e0d\u5230\u5e78\u798f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e00\u5473\u7948\u7977\u6beb\u65e0\u52a9\u76ca\u3002\u552f\u6709\u6f5c\u5fc3\u5fcd\u8010\uff0c\u7b49\u5f85\u5384\u8fd0\u79bb\u53bb\u3002", "line": "\u8fd0\u52bf\uff1a\u4e00\u5473\u7948\u7977\u6beb\u65e0\u52a9\u76ca\u3002\u552f\u6709\u6f5c\u5fc3\u5fcd\u8010\uff0c\u7b49\u5f85\u5384\u8fd0\u79bb\u53bb\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u65e5\u6e10\u7e41\u5fd9\u5374\u96be\u6709\u50a8\u84c4\u3002\u53d7\u8fd0\u52bf\u5de6\u53f3\u7684\u5de5\u4f5c\u5c24\u4e3a\u4e0d\u5229\u3002", "line": "\u5de5\u4f5c\uff1a\u65e5\u6e10\u7e41\u5fd9\u5374\u96be\u6709\u50a8\u84c4\u3002\u53d7\u8fd0\u52bf\u5de6\u53f3\u7684\u5de5\u4f5c\u5c24\u4e3a\u4e0d\u5229\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u542c\u51ed\u8fd0\u6c14\u5219\u6ce8\u5b9a\u5931\u8d25\u3002\u5f53\u4e0b\u4ee5\u811a\u8e0f\u5b9e\u5730\u8ba4\u771f\u5b66\u4e60\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u542c\u51ed\u8fd0\u6c14\u5219\u6ce8\u5b9a\u5931\u8d25\u3002\u5f53\u4e0b\u4ee5\u811a\u8e0f\u5b9e\u5730\u8ba4\u771f\u5b66\u4e60\u4e3a\u5409\u3002"}, {"label": "\u75be\u75c5", "text": "\u75be\u60a3\u6076\u5316\u3002\u5fcd\u7740\u5427\u3002", "line": "\u75be\u75c5\uff1a\u75be\u60a3\u6076\u5316\u3002\u5fcd\u7740\u5427\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u4eb2\u670b\u6563\u5c3d\u3002", "line": "\u4eba\u7f18\uff1a\u4eb2\u670b\u6563\u5c3d\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u4e0b\u4e0d\u5b9c\u3002", "line": "\u604b\u7231\uff1a\u5f53\u4e0b\u4e0d\u5b9c\u3002"}, {"label": "\u51fa\u884c", "text": "\u4e0d\u53bb\u4e3a\u5999\u3002", "line": "\u51fa\u884c\uff1a\u4e0d\u53bb\u4e3a\u5999\u3002"}, {"label": "\u4f4f\u6240", "text": "\u7b80\u6734\u4e3a\u5b9c\u3002", "line": "\u4f4f\u6240\uff1a\u7b80\u6734\u4e3a\u5b9c\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5fc5\u8d25\u3002", "line": "\u4e89\u7aef\uff1a\u5fc5\u8d25\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u52a1\u5fc5\u8282\u5236\u3002\u5426\u5219\u4f1a\u9677\u5165\u63ed\u4e0d\u5f00\u9505\u7684\u7a98\u5883\u3002", "line": "\u8d22\u8fd0\uff1a\u52a1\u5fc5\u8282\u5236\u3002\u5426\u5219\u4f1a\u9677\u5165\u63ed\u4e0d\u5f00\u9505\u7684\u7a98\u5883\u3002"}, {"label": "\u7231\u597d", "text": "\u5f53\u82e6\u5fc3\u94bb\u7814\u7a77\u4eba\u996d\u4e4b\u9053\u3002", "line": "\u7231\u597d\uff1a\u5f53\u82e6\u5fc3\u94bb\u7814\u7a77\u4eba\u996d\u4e4b\u9053\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (92, '爱塔妮缇拉尔瓦', '末吉', '身带神性的凤蝶妖精', '播撒鳞粉程度的能力', '["\u8774\u8776\u601d\u8651\u6d45\uff0c", "\u62db\u6447\u8bf1\u730e\u624b\u3002", "\u53cc\u7fc5\u592a\u7eda\u4e3d\uff0c", "\u53cd\u62db\u6740\u8eab\u7978\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u53ea\u8981\u6ce8\u91cd\u517b\u751f\u4fbf\u80fd\u9010\u6e10\u8f6c\u8fd0\u3002\u4f46\u5207\u5fcc\u5927\u610f\u3002", "line": "\u8fd0\u52bf\uff1a\u53ea\u8981\u6ce8\u91cd\u517b\u751f\u4fbf\u80fd\u9010\u6e10\u8f6c\u8fd0\u3002\u4f46\u5207\u5fcc\u5927\u610f\u3002"}, {"label": "\u5065\u5eb7", "text": "\u65f6\u5e38\u7559\u5fc3\u3002\u730e\u624b\u5c24\u4e3a\u5371\u9669\uff0c\u52a1\u5fc5\u4e07\u5206\u63d0\u9632\u3002", "line": "\u5065\u5eb7\uff1a\u65f6\u5e38\u7559\u5fc3\u3002\u730e\u624b\u5c24\u4e3a\u5371\u9669\uff0c\u52a1\u5fc5\u4e07\u5206\u63d0\u9632\u3002"}, {"label": "\u75be\u75c5", "text": "\u5f53\u5fc3\u80ba\u75be\u3002\u5176\u4f59\u75be\u75c5\u7686\u4f1a\u597d\u8f6c\u3002", "line": "\u75be\u75c5\uff1a\u5f53\u5fc3\u80ba\u75be\u3002\u5176\u4f59\u75be\u75c5\u7686\u4f1a\u597d\u8f6c\u3002"}], [{"label": "\u4ea4\u6613", "text": "\u8f6c\u673a\u5c06\u81f3\u3002\u5927\u80c6\u51b3\u65ad\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u8f6c\u673a\u5c06\u81f3\u3002\u5927\u80c6\u51b3\u65ad\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6bcf\u9022\u8003\u8bd5\u4fbf\u80fd\u5927\u5e45\u6210\u957f\u3002", "line": "\u5b66\u4e1a\uff1a\u6bcf\u9022\u8003\u8bd5\u4fbf\u80fd\u5927\u5e45\u6210\u957f\u3002"}, {"label": "\u79fb\u5f99", "text": "\u59d1\u4e14\u4e3a\u5409\u3002\u53ef\u8fd1\u53ef\u8fdc\u3002", "line": "\u79fb\u5f99\uff1a\u59d1\u4e14\u4e3a\u5409\u3002\u53ef\u8fd1\u53ef\u8fdc\u3002"}, {"label": "\u7231\u597d", "text": "\u8ba9\u81ea\u5df1\u9762\u76ee\u4e00\u65b0\u7684\u826f\u673a\u3002\n\u534e\u4e3d\u53d8\u8eab\u5427\u3002", "line": "\u7231\u597d\uff1a\u8ba9\u81ea\u5df1\u9762\u76ee\u4e00\u65b0\u7684\u826f\u673a\u3002\n\u534e\u4e3d\u53d8\u8eab\u5427\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (93, '坂田合欢', '小吉', '隐僻山麓的山姥', '制作圣域程度的能力', '["\u793e\u4f1a\u62d8\u675f\u591a\uff0c", "\u8fd9\u8c01\u9876\u5f97\u4f4f\u3002", "\u5076\u5c14\u6765\u72ec\u5904\uff0c", "\u5012\u4e5f\u633a\u4e0d\u8d56\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u80fd\u591f\u8fc7\u4e0a\u8fdc\u79bb\u4e16\u95f4\u55a7\u56a3\u7684\u81ea\u5728\u751f\u6d3b\u3002\u4f46\u540c\u65f6\u4e5f\u4f1a\u5b64\u7acb\u65e0\u63f4\u3002", "line": "\u8fd0\u52bf\uff1a\u80fd\u591f\u8fc7\u4e0a\u8fdc\u79bb\u4e16\u95f4\u55a7\u56a3\u7684\u81ea\u5728\u751f\u6d3b\u3002\u4f46\u540c\u65f6\u4e5f\u4f1a\u5b64\u7acb\u65e0\u63f4\u3002"}, {"label": "\u4f4f\u6240", "text": "\u52a1\u5fc5\u7cbe\u5fc3\u6253\u7406\u5bb6\u5b85\u3002", "line": "\u4f4f\u6240\uff1a\u52a1\u5fc5\u7cbe\u5fc3\u6253\u7406\u5bb6\u5b85\u3002"}, {"label": "\u79fb\u5f99", "text": "\u4e0d\u5b9c\u8fc1\u5c45\u3002\u5c3d\u529b\u907f\u514d\u3002", "line": "\u79fb\u5f99\uff1a\u4e0d\u5b9c\u8fc1\u5c45\u3002\u5c3d\u529b\u907f\u514d\u3002"}, {"label": "\u51fa\u884c", "text": "\u4ec5\u9650\u77ed\u9014\u3002", "line": "\u51fa\u884c\uff1a\u4ec5\u9650\u77ed\u9014\u3002"}, {"label": "\u4ea4\u6613", "text": "\u65e0\u6cd5\u5f00\u5f20\u3002", "line": "\u4ea4\u6613\uff1a\u65e0\u6cd5\u5f00\u5f20\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u987a\u98ce\u987a\u6c34\u3002\u5f53\u95ed\u95e8\u4e0d\u51fa\u3001\u4e13\u5fc3\u5411\u5b66\u3002", "line": "\u5b66\u4e1a\uff1a\u987a\u98ce\u987a\u6c34\u3002\u5f53\u95ed\u95e8\u4e0d\u51fa\u3001\u4e13\u5fc3\u5411\u5b66\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5065\u5eb7\u81f3\u6781\u3002\u4ece\u4e0d\u611f\u5192\u3002", "line": "\u5065\u5eb7\uff1a\u5065\u5eb7\u81f3\u6781\u3002\u4ece\u4e0d\u611f\u5192\u3002"}, {"label": "\u8d35\u4eba", "text": "\u5c11\u6709\u9082\u9005\u3002\u6709\u4eba\u767b\u95e8\u6765\u8bbf\u4e43\u662f\u826f\u673a\u3002\u5efa\u8bae\u78e8\u5200\u4ee5\u5f85\u3002", "line": "\u8d35\u4eba\uff1a\u5c11\u6709\u9082\u9005\u3002\u6709\u4eba\u767b\u95e8\u6765\u8bbf\u4e43\u662f\u826f\u673a\u3002\u5efa\u8bae\u78e8\u5200\u4ee5\u5f85\u3002"}, {"label": "\u604b\u7231", "text": "\u7edd\u65e0\u673a\u4f1a\u3002", "line": "\u604b\u7231\uff1a\u7edd\u65e0\u673a\u4f1a\u3002"}, {"label": "\u59fb\u7f18", "text": "\u83ab\u5b58\u671f\u5f85\u3002", "line": "\u59fb\u7f18\uff1a\u83ab\u5b58\u671f\u5f85\u3002"}, {"label": "\u4e89\u7aef", "text": "\u65e0\u4ece\u53d1\u751f\u3002\u6709\u70b9\u5bc2\u5bde\u3002", "line": "\u4e89\u7aef\uff1a\u65e0\u4ece\u53d1\u751f\u3002\u6709\u70b9\u5bc2\u5bde\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (94, '高丽野阿吽', '大吉', '守护博丽神社的狛犬', '发现神佛程度的能力', '["\u5409\u5229\u7684\u7269\u4ef6\uff0c", "\u6700\u662f\u751f\u7965\u745e\u3002", "\u7269\u4ef6\u6210\u53cc\u5bf9\uff0c", "\u7965\u745e\u4e5f\u52a0\u500d\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5b89\u5168\u660e\u6717\u7684\u8fd0\u7a0b\u6307\u65e5\u53ef\u5f85\u3002\u5207\u52ff\u9057\u5fd8\u4fe1\u4ef0\u795e\u4f5b\u4e4b\u5fc3\u3002", "line": "\u8fd0\u52bf\uff1a\u5b89\u5168\u660e\u6717\u7684\u8fd0\u7a0b\u6307\u65e5\u53ef\u5f85\u3002\u5207\u52ff\u9057\u5fd8\u4fe1\u4ef0\u795e\u4f5b\u4e4b\u5fc3\u3002"}, {"label": "\u707e\u7978", "text": "\u795e\u4f5b\u5e87\u4f51\uff0c\u65e0\u707e\u65e0\u7978\u3002", "line": "\u707e\u7978\uff1a\u795e\u4f5b\u5e87\u4f51\uff0c\u65e0\u707e\u65e0\u7978\u3002"}, {"label": "\u4ea4\u6613", "text": "\u521b\u4e1a\u5fc5\u5b9a\u6210\u529f\u3002\u4e0e\u5b97\u6559\u76f8\u5173\u7684\u4ea7\u4e1a\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u521b\u4e1a\u5fc5\u5b9a\u6210\u529f\u3002\u4e0e\u5b97\u6559\u76f8\u5173\u7684\u4ea7\u4e1a\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u987a\u98ce\u987a\u6c34\u3002\u6c42\u5b66\u4e4b\u8def\u7545\u901a\u65e0\u963b\u3002", "line": "\u5b66\u4e1a\uff1a\u987a\u98ce\u987a\u6c34\u3002\u6c42\u5b66\u4e4b\u8def\u7545\u901a\u65e0\u963b\u3002"}], [{"label": "\u4f4f\u6240", "text": "\u5b89\u5b81\u7a33\u5b9a\u3002\u6446\u653e\u72db\u72ac\u66f4\u4f73\u3002", "line": "\u4f4f\u6240\uff1a\u5b89\u5b81\u7a33\u5b9a\u3002\u6446\u653e\u72db\u72ac\u66f4\u4f73\u3002"}, {"label": "\u79fb\u5f99", "text": "\u5f53\u4e0b\u4e0d\u5b9c\u3002", "line": "\u79fb\u5f99\uff1a\u5f53\u4e0b\u4e0d\u5b9c\u3002"}, {"label": "\u51fa\u884c", "text": "\u53c2\u8bbf\u795e\u793e\u4f5b\u5bfa\u4e4b\u65c5\u53ef\u5b89\u5fc3\u6210\u884c\u3002", "line": "\u51fa\u884c\uff1a\u53c2\u8bbf\u795e\u793e\u4f5b\u5bfa\u4e4b\u65c5\u53ef\u5b89\u5fc3\u6210\u884c\u3002"}, {"label": "\u52a8\u7269", "text": "\u552f\u6709\u733f\u7334\u52a1\u5fc5\u56de\u907f\u3002", "line": "\u52a8\u7269\uff1a\u552f\u6709\u733f\u7334\u52a1\u5fc5\u56de\u907f\u3002"}, {"label": "\u59fb\u7f18", "text": "\u53ef\u5f97\u826f\u7f18\uff0c\u60c5\u6295\u610f\u5408\u3002", "line": "\u59fb\u7f18\uff1a\u53ef\u5f97\u826f\u7f18\uff0c\u60c5\u6295\u610f\u5408\u3002"}, {"label": "\u751f\u80b2", "text": "\u751f\u4ea7\u987a\u5229\u3002\u591a\u5b50\u591a\u798f\u3002", "line": "\u751f\u80b2\uff1a\u751f\u4ea7\u987a\u5229\u3002\u591a\u5b50\u591a\u798f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (95, '矢田寺成美', '【大大吉】', '魔法生物地藏', '使用魔法（生命操纵为主）程度的能力', '["\u771f\u662f\u592a\u597d\u4e86\u3002", "\u5728\u4e94\u5341\u516d\u4ebf", "\u4e03\u5343\u4e07\u5e74\u95f4\uff0c", "\u6211\u4f1a\u4fdd\u4f51\u4f60\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5411\u5730\u85cf\u77f3\u50cf\u732e\u82b1\u5373\u53ef\u529f\u5fb7\u6ee1\u6ee1\u3002", "line": "\u8fd0\u52bf\uff1a\u5411\u5730\u85cf\u77f3\u50cf\u732e\u82b1\u5373\u53ef\u529f\u5fb7\u6ee1\u6ee1\u3002"}, {"label": "\u4f4f\u6240", "text": "\u514d\u906d\u8d3c\u624b\u3002", "line": "\u4f4f\u6240\uff1a\u514d\u906d\u8d3c\u624b\u3002"}, {"label": "\u75be\u75c5", "text": "\u65e7\u75be\u5f97\u6108\u3002\u65b0\u60a3\u65e0\u7f18\u3002", "line": "\u75be\u75c5\uff1a\u65e7\u75be\u5f97\u6108\u3002\u65b0\u60a3\u65e0\u7f18\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u524d\u4e16\u4e4b\u8bc6\u76f8\u52a9\uff0c\u5b66\u4e1a\u987a\u9042\u65e0\u5fe7\u3002", "line": "\u5b66\u4e1a\uff1a\u524d\u4e16\u4e4b\u8bc6\u76f8\u52a9\uff0c\u5b66\u4e1a\u987a\u9042\u65e0\u5fe7\u3002"}, {"label": "\u4ea4\u6613", "text": "\u672a\u5fc5\u80fd\u76c8\u5229\uff0c\u4f46\u53ef\u5f97\u4e0b\u5c5e\u7b11\u989c\u3002", "line": "\u4ea4\u6613\uff1a\u672a\u5fc5\u80fd\u76c8\u5229\uff0c\u4f46\u53ef\u5f97\u4e0b\u5c5e\u7b11\u989c\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u5929\u7136\u5907\u53d7\u5c0a\u656c\u3002", "line": "\u4eba\u7f18\uff1a\u5929\u7136\u5907\u53d7\u5c0a\u656c\u3002"}, {"label": "\u5065\u5eb7", "text": "\u826f\u5bb5\u7f8e\u68a6\u3002\u795e\u7075\u5e87\u4f51\u3002", "line": "\u5065\u5eb7\uff1a\u826f\u5bb5\u7f8e\u68a6\u3002\u795e\u7075\u5e87\u4f51\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5f97\u4ee5\u6446\u8131\u65e0\u5984\u4e4b\u707e\u3002", "line": "\u4e89\u7aef\uff1a\u5f97\u4ee5\u6446\u8131\u65e0\u5984\u4e4b\u707e\u3002"}, {"label": "\u51fa\u884c", "text": "\u904d\u884c\u5929\u4e0b\u7686\u4e3a\u5409\u3002\u5207\u8bb0\u8def\u9047\u5730\u85cf\u987b\u5408\u638c\u53c2\u62dc\u3002\u8f7b\u8511\u4ee5\u5bf9\u5219\u4f1a\u5931\u53bb\u4e00\u5207\u3002", "line": "\u51fa\u884c\uff1a\u904d\u884c\u5929\u4e0b\u7686\u4e3a\u5409\u3002\u5207\u8bb0\u8def\u9047\u5730\u85cf\u987b\u5408\u638c\u53c2\u62dc\u3002\u8f7b\u8511\u4ee5\u5bf9\u5219\u4f1a\u5931\u53bb\u4e00\u5207\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (96, '丁礼田舞', '吉', '持续起舞直至终结的童子', '通过在背后起舞来诱导出生命力程度的能力', '["\u8fd9\u4e0b\u53ef\u5de7\u4e86", "\u4f60\u7adf\u62bd\u5230\u6211\u3002", "\u4eba\u751f\u591a\u4e4f\u5473\uff0c", "\u60ca\u559c\u6765\u70b9\u7f00\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u603b\u80fd\u53d1\u6325\u8d85\u5e38\u5b9e\u529b\u3002\u4f46\u526f\u4f5c\u7528\u4e5f\u5982\u5f71\u968f\u5f62\u3002", "line": "\u8fd0\u52bf\uff1a\u603b\u80fd\u53d1\u6325\u8d85\u5e38\u5b9e\u529b\u3002\u4f46\u526f\u4f5c\u7528\u4e5f\u5982\u5f71\u968f\u5f62\u3002"}, {"label": "\u5065\u5eb7", "text": "\u7cbe\u795e\u632f\u4f5c\uff0c\u8eab\u4f53\u8f7b\u76c8\u3002\u4f46\u8fc7\u5ea6\u86ee\u5e72\u4f1a\u641e\u57ae\u8eab\u4f53\u3002", "line": "\u5065\u5eb7\uff1a\u7cbe\u795e\u632f\u4f5c\uff0c\u8eab\u4f53\u8f7b\u76c8\u3002\u4f46\u8fc7\u5ea6\u86ee\u5e72\u4f1a\u641e\u57ae\u8eab\u4f53\u3002"}, {"label": "\u51fa\u884c", "text": "\u5e86\u5178\u4e3e\u529e\u5730\u4e3a\u5409\u3002\u7af9\u6797\u4ea6\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5e86\u5178\u4e3e\u529e\u5730\u4e3a\u5409\u3002\u7af9\u6797\u4ea6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4f18\u52bf\u79d1\u76ee\u6709\u6240\u957f\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u4f18\u52bf\u79d1\u76ee\u6709\u6240\u957f\u8fdb\u3002"}], [{"label": "\u5de5\u4f5c", "text": "\u5e72\u52b2\u5341\u8db3\uff0c\u8fdb\u5c55\u663e\u8457\u3002\u6ee1\u8154\u5e72\u52b2\u4f1a\u88ab\u538b\u69a8\u3002\u5f53\u5fc3\u4eba\u5458\u4f18\u5316\u3002", "line": "\u5de5\u4f5c\uff1a\u5e72\u52b2\u5341\u8db3\uff0c\u8fdb\u5c55\u663e\u8457\u3002\u6ee1\u8154\u5e72\u52b2\u4f1a\u88ab\u538b\u69a8\u3002\u5f53\u5fc3\u4eba\u5458\u4f18\u5316\u3002"}, {"label": "\u604b\u7231", "text": "\u7528\u529b\u8fc7\u731b\u5219\u51f6\u3002", "line": "\u604b\u7231\uff1a\u7528\u529b\u8fc7\u731b\u5219\u51f6\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4f1a\u5728\u4e25\u8083\u573a\u5408\u6345\u51fa\u5927\u7bd3\u5b50\u3002\u5931\u53bb\u4eba\u5fc3\u3002", "line": "\u4eba\u7f18\uff1a\u4f1a\u5728\u4e25\u8083\u573a\u5408\u6345\u51fa\u5927\u7bd3\u5b50\u3002\u5931\u53bb\u4eba\u5fc3\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6325\u91d1\u5982\u571f\u3002", "line": "\u8d22\u8fd0\uff1a\u6325\u91d1\u5982\u571f\u3002"}, {"label": "\u5fc3\u613f", "text": "\u5b9e\u73b0\u75f4\u5fc3\u5984\u60f3\u7684\u826f\u673a\u3002", "line": "\u5fc3\u613f\uff1a\u5b9e\u73b0\u75f4\u5fc3\u5984\u60f3\u7684\u826f\u673a\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (97, '尔子田里乃', '吉', '持续起舞直至消亡的童子', '通过在背后起舞来诱导出精神力程度的能力', '["\u6211\u5df2\u7ecf\u5982\u6b64", "\u5356\u529b\u9001\u58f0\u63f4\uff0c", "\u4e3a\u4f55\u4f60\u8fd9\u822c", "\u75db\u82e6\u4e0d\u582a\u8a00\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7cbe\u529b\u5145\u6c9b\u5927\u5c55\u8eab\u624b\uff0c\u597d\u8fd0\u4e5f\u4f1a\u7eb7\u81f3\u6c93\u6765\u3002\u4e8b\u540e\u4f1a\u75b2\u60eb\u4e0d\u582a\u3002", "line": "\u8fd0\u52bf\uff1a\u7cbe\u529b\u5145\u6c9b\u5927\u5c55\u8eab\u624b\uff0c\u597d\u8fd0\u4e5f\u4f1a\u7eb7\u81f3\u6c93\u6765\u3002\u4e8b\u540e\u4f1a\u75b2\u60eb\u4e0d\u582a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5fc3\u65e0\u6742\u5ff5\u6295\u5165\u5de5\u4f5c\uff0c\u5219\u80fd\u53d6\u5f97\u6210\u679c\u3002\u5f53\u5fc3\u4eba\u5458\u4f18\u5316\u3002", "line": "\u5de5\u4f5c\uff1a\u5fc3\u65e0\u6742\u5ff5\u6295\u5165\u5de5\u4f5c\uff0c\u5219\u80fd\u53d6\u5f97\u6210\u679c\u3002\u5f53\u5fc3\u4eba\u5458\u4f18\u5316\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5065\u5fd8\u65e5\u6e10\u52a0\u91cd\u3002", "line": "\u5065\u5eb7\uff1a\u5065\u5fd8\u65e5\u6e10\u52a0\u91cd\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4f53\u80b2\u3001\u7f8e\u672f\u3001\u97f3\u4e50\u4e3a\u5409\u3002\u52a0\u5165\u62c9\u62c9\u961f\u5219\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u4f53\u80b2\u3001\u7f8e\u672f\u3001\u97f3\u4e50\u4e3a\u5409\u3002\u52a0\u5165\u62c9\u62c9\u961f\u5219\u5927\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u4eba\u5c71\u4eba\u6d77\u4e4b\u5730\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4eba\u5c71\u4eba\u6d77\u4e4b\u5730\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5fd8\u5374\u7cdf\u5fc3\u56de\u5fc6\uff0c\u987a\u5229\u63a8\u8fdb\u5173\u7cfb\u3002", "line": "\u604b\u7231\uff1a\u5fd8\u5374\u7cdf\u5fc3\u56de\u5fc6\uff0c\u987a\u5229\u63a8\u8fdb\u5173\u7cfb\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5207\u8bb0\u73cd\u60dc\u4f19\u4f34\u3002", "line": "\u4eba\u7f18\uff1a\u5207\u8bb0\u73cd\u60dc\u4f19\u4f34\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5468\u906d\u867d\u6709\u7ea0\u7eb7\uff0c\u4f46\u4e0d\u4f1a\u6b83\u53ca\u81ea\u5df1\u3002", "line": "\u4e89\u7aef\uff1a\u5468\u906d\u867d\u6709\u7ea0\u7eb7\uff0c\u4f46\u4e0d\u4f1a\u6b83\u53ca\u81ea\u5df1\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6325\u91d1\u5982\u571f\u3002", "line": "\u8d22\u8fd0\uff1a\u6325\u91d1\u5982\u571f\u3002"}, {"label": "\u5fc3\u613f", "text": "\u5919\u613f\u5f97\u507f\u7684\u826f\u673a\u3002\u503c\u5f97\u62fc\u529b\u4e00\u640f\u3002", "line": "\u5fc3\u613f\uff1a\u5919\u613f\u5f97\u507f\u7684\u826f\u673a\u3002\u503c\u5f97\u62fc\u529b\u4e00\u640f\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (98, '摩多罗隐岐奈', '末大凶', '幻想乡的绝对秘神', '在万物背上制作门扉程度的能力', '["\u53ef\u6076\u6469\u591a\u7f57\uff0c", "\u53ef\u618e\u9690\u5c90\u5948\u3002", "\u8fd9\u756a\u7cdf\u5fc3\u4e8b\uff0c", "\u53c8\u662f\u4f60\u6240\u4e3a\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8868\u9762\u4e0a\u4e00\u5e06\u98ce\u987a\uff0c\u80cc\u5730\u91cc\u5168\u662f\u9690\u60c5\u3002", "line": "\u8fd0\u52bf\uff1a\u8868\u9762\u4e0a\u4e00\u5e06\u98ce\u987a\uff0c\u80cc\u5730\u91cc\u5168\u662f\u9690\u60c5\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u82e5\u4e0d\u8ffd\u7a76\u771f\u76f8\u5219\u53ef\u987a\u5229\u3002\u6f14\u827a\u5708\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u82e5\u4e0d\u8ffd\u7a76\u771f\u76f8\u5219\u53ef\u987a\u5229\u3002\u6f14\u827a\u5708\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u827a\u672f\u4e3a\u5409\u3002\u53ef\u8003\u8651\u8d70\u540e\u95e8\u5165\u5b66\u3002", "line": "\u5b66\u4e1a\uff1a\u827a\u672f\u4e3a\u5409\u3002\u53ef\u8003\u8651\u8d70\u540e\u95e8\u5165\u5b66\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u91cd\u4f24\u3002\u5f97\u9047\u5fc3\u4eea\u8f6e\u6905\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u91cd\u4f24\u3002\u5f97\u9047\u5fc3\u4eea\u8f6e\u6905\u3002"}], [{"label": "\u51fa\u884c", "text": "\u907f\u5f00\u5bfa\u9662\u3002", "line": "\u51fa\u884c\uff1a\u907f\u5f00\u5bfa\u9662\u3002"}, {"label": "\u59fb\u7f18", "text": "\u76f8\u4eb2\u4e3a\u5409\u3002", "line": "\u59fb\u7f18\uff1a\u76f8\u4eb2\u4e3a\u5409\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e00\u65e6\u4e22\u5931\u5219\u518d\u65e0\u5bfb\u56de\u4e4b\u65e5\u3002", "line": "\u5bfb\u7269\uff1a\u4e00\u65e6\u4e22\u5931\u5219\u518d\u65e0\u5bfb\u56de\u4e4b\u65e5\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5343\u4e07\u5f53\u5fc3\u4e0d\u4e49\u4e4b\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u5343\u4e07\u5f53\u5fc3\u4e0d\u4e49\u4e4b\u8d22\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5e78\u5f97\u5fe0\u5b9e\u8d24\u624d\u3002", "line": "\u4eba\u7f18\uff1a\u5e78\u5f97\u5fe0\u5b9e\u8d24\u624d\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u6349\u8ff7\u85cf\u672a\u5c1d\u4e00\u8d25\u3002", "line": "\u6bd4\u8bd5\uff1a\u6349\u8ff7\u85cf\u672a\u5c1d\u4e00\u8d25\u3002"}, {"label": "\u7231\u597d", "text": "\u80fd\u4e50\u4e3a\u5b9c\u3002", "line": "\u7231\u597d\uff1a\u80fd\u4e50\u4e3a\u5b9c\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (99, '戎璎花', '大吉', '水子偶像', '擅长垒石头程度的能力', '["\u5feb\u4e50\u751f\u6d3b", "\u80dc\u8fc7\u4e00\u5207\uff0c", "\u54ea\u6015\u751f\u547d", "\u65e9\u5df2\u7ec8\u7ed3\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u524d\u9014\u5149\u660e\u3002\u7ec6\u5fae\u559c\u60a6\u63a5\u8fde\u800c\u81f3\uff0c\u751f\u6d3b\u8f7b\u677e\u6109\u5feb\u3002", "line": "\u8fd0\u52bf\uff1a\u524d\u9014\u5149\u660e\u3002\u7ec6\u5fae\u559c\u60a6\u63a5\u8fde\u800c\u81f3\uff0c\u751f\u6d3b\u8f7b\u677e\u6109\u5feb\u3002"}, {"label": "\u4ea4\u6613", "text": "\u91cd\u590d\u52b3\u52a8\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u91cd\u590d\u52b3\u52a8\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u52aa\u529b\u4e0d\u518d\u662f\u8d1f\u62c5\uff0c\u8f9b\u52b3\u5fc5\u6709\u56de\u62a5\u3002", "line": "\u5b66\u4e1a\uff1a\u52aa\u529b\u4e0d\u518d\u662f\u8d1f\u62c5\uff0c\u8f9b\u52b3\u5fc5\u6709\u56de\u62a5\u3002"}, {"label": "\u5065\u5eb7", "text": "\u4e0d\u4f1a\u53d7\u4f24\u3002\u5267\u70c8\u8fd0\u52a8\u4e3a\u5409\u3002", "line": "\u5065\u5eb7\uff1a\u4e0d\u4f1a\u53d7\u4f24\u3002\u5267\u70c8\u8fd0\u52a8\u4e3a\u5409\u3002"}, {"label": "\u4e89\u7aef", "text": "\u843d\u8d25\u4ea6\u4e3a\u5409\u3002", "line": "\u4e89\u7aef\uff1a\u843d\u8d25\u4ea6\u4e3a\u5409\u3002"}], [{"label": "\u604b\u7231", "text": "\u5355\u76f8\u601d\uff0c\u4f46\u4e3a\u5409\u3002", "line": "\u604b\u7231\uff1a\u5355\u76f8\u601d\uff0c\u4f46\u4e3a\u5409\u3002"}, {"label": "\u59fb\u7f18", "text": "\u65e0\u9700\u5728\u610f\u3002", "line": "\u59fb\u7f18\uff1a\u65e0\u9700\u5728\u610f\u3002"}, {"label": "\u51fa\u884c", "text": "\u8fd1\u6c34\u4e4b\u5904\u95fb\u4eba\u547c\u5524\uff0c\u52a1\u5fc5\u8fdc\u79bb\u3002\u6b64\u5916\uff0c\u9ad8\u8038\u5efa\u7b51\u4ea6\u4e3a\u51f6\u3002", "line": "\u51fa\u884c\uff1a\u8fd1\u6c34\u4e4b\u5904\u95fb\u4eba\u547c\u5524\uff0c\u52a1\u5fc5\u8fdc\u79bb\u3002\u6b64\u5916\uff0c\u9ad8\u8038\u5efa\u7b51\u4ea6\u4e3a\u51f6\u3002"}, {"label": "\u4f4f\u6240", "text": "\u65e5\u6e10\u660e\u6717\u3002\u552f\u6709\u672c\u5fc3\u6c38\u8fdc\u76f8\u4f34\u3002", "line": "\u4f4f\u6240\uff1a\u65e5\u6e10\u660e\u6717\u3002\u552f\u6709\u672c\u5fc3\u6c38\u8fdc\u76f8\u4f34\u3002"}, {"label": "\u7231\u597d", "text": "\u6f14\u5531\u4f1a\u4e3a\u5409\u3002\u5c3d\u60c5\u72c2\u6b22\u5427\u3002", "line": "\u7231\u597d\uff1a\u6f14\u5531\u4f1a\u4e3a\u5409\u3002\u5c3d\u60c5\u72c2\u6b22\u5427\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (100, '牛崎润美', '凶', '怀抱石婴的牛鬼', '改变身边物体重量程度的能力', '["\u91cd\u8fbe\u5343\u94a7\u7684", "\u662f\u77f3\u4e4b\u5bc6\u5ea6\uff1f", "\u6291\u6216\u662f\u811a\u4e0b", "\u5927\u5730\u7684\u6076\u610f\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8eab\u5fc3\u6c89\u91cd\uff0c\u65f6\u8fd0\u96be\u6d4e\u3002", "line": "\u8fd0\u52bf\uff1a\u8eab\u5fc3\u6c89\u91cd\uff0c\u65f6\u8fd0\u96be\u6d4e\u3002"}, {"label": "\u5065\u5eb7", "text": "\u80a9\u81c2\u3001\u8170\u90e8\u5747\u6709\u8d1f\u62c5\u3002", "line": "\u5065\u5eb7\uff1a\u80a9\u81c2\u3001\u8170\u90e8\u5747\u6709\u8d1f\u62c5\u3002"}, {"label": "\u751f\u80b2", "text": "\u5e76\u53d1\u75c7\u91cd\uff0c\u6ce8\u5b9a\u96be\u4ea7\u3002\u5b50\u5973\u8eab\u4f53\u5f3a\u5065\u3002", "line": "\u751f\u80b2\uff1a\u5e76\u53d1\u75c7\u91cd\uff0c\u6ce8\u5b9a\u96be\u4ea7\u3002\u5b50\u5973\u8eab\u4f53\u5f3a\u5065\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5b9c\u6e14\u4e1a\u3001\u4e73\u755c\u4e1a\u3002\u4f46\u9700\u5f53\u5fc3\u6eba\u6c34\u3002", "line": "\u4ea4\u6613\uff1a\u5b9c\u6e14\u4e1a\u3001\u4e73\u755c\u4e1a\u3002\u4f46\u9700\u5f53\u5fc3\u6eba\u6c34\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u65e0\u529f\u65e0\u8fc7\u3002", "line": "\u5b66\u4e1a\uff1a\u65e0\u529f\u65e0\u8fc7\u3002"}, {"label": "\u51fa\u884c", "text": "\u6ee8\u6c34\u5904\u591a\u6709\u5371\u9669\u3002\u52a1\u5fc5\u5f53\u5fc3\u3002", "line": "\u51fa\u884c\uff1a\u6ee8\u6c34\u5904\u591a\u6709\u5371\u9669\u3002\u52a1\u5fc5\u5f53\u5fc3\u3002"}, {"label": "\u59fb\u7f18", "text": "\u4e0e\u4e3a\u4eba\u7236\u6bcd\u8005\u7ed3\u4e0b\u826f\u7f18\u3002", "line": "\u59fb\u7f18\uff1a\u4e0e\u4e3a\u4eba\u7236\u6bcd\u8005\u7ed3\u4e0b\u826f\u7f18\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u52a1\u5fc5\u7a33\u91cd\u7ecf\u8425\u3002", "line": "\u5bb6\u5ead\uff1a\u52a1\u5fc5\u7a33\u91cd\u7ecf\u8425\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5bb6\u5e38\u4fbf\u996d\uff0c\u4e0d\u843d\u4e0b\u98ce\u3002", "line": "\u4e89\u7aef\uff1a\u5bb6\u5e38\u4fbf\u996d\uff0c\u4e0d\u843d\u4e0b\u98ce\u3002"}, {"label": "\u5bfb\u7269", "text": "\u53ef\u4ece\u53e4\u4ee3\u9c7c\u8179\u4e2d\u5bfb\u56de\u5931\u7269\u3002", "line": "\u5bfb\u7269\uff1a\u53ef\u4ece\u53e4\u4ee3\u9c7c\u8179\u4e2d\u5bfb\u56de\u5931\u7269\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (101, '庭渡久侘歌', '小吉', '看守口岸的鸡之神', '治愈喉疾程度的能力', '["\u96c4\u9e21\u4e3a\u4f55", "\u6e05\u6668\u557c\u9e23\uff1f", "\u53ef\u662f\u56e0\u4e3a", "\u5669\u68a6\u521d\u9192\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5904\u4e8e\u8fd0\u52bf\u7684\u5206\u6b67\u70b9\u3002\u89c6\u91ce\u6781\u4f73\uff0c\u4f46\u9009\u62e9\u6709\u9650\u3002", "line": "\u8fd0\u52bf\uff1a\u5904\u4e8e\u8fd0\u52bf\u7684\u5206\u6b67\u70b9\u3002\u89c6\u91ce\u6781\u4f73\uff0c\u4f46\u9009\u62e9\u6709\u9650\u3002"}, {"label": "\u75be\u75c5", "text": "\u5589\u75be\u53ef\u6108\u3002", "line": "\u75be\u75c5\uff1a\u5589\u75be\u53ef\u6108\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5589\u90e8\u8212\u9002\u3001\u55d3\u97f3\u6e05\u4eae\uff0c\u56e0\u6b64\u4eba\u7f18\u4e0d\u9519\u3002", "line": "\u4eba\u7f18\uff1a\u5589\u90e8\u8212\u9002\u3001\u55d3\u97f3\u6e05\u4eae\uff0c\u56e0\u6b64\u4eba\u7f18\u4e0d\u9519\u3002"}, {"label": "\u4ea4\u6613", "text": "\u9700\u5f00\u8154\u6216\u732e\u5531\u7684\u751f\u610f\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u9700\u5f00\u8154\u6216\u732e\u5531\u7684\u751f\u610f\u4e3a\u5927\u5409\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u97f3\u4e50\u4e3a\u5409\u3002\u5bb6\u79bd\u6c34\u5e73\u7684\u8111\u5bb9\u91cf\u3002", "line": "\u5b66\u4e1a\uff1a\u97f3\u4e50\u4e3a\u5409\u3002\u5bb6\u79bd\u6c34\u5e73\u7684\u8111\u5bb9\u91cf\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5c45\u4e8e\u5173\u53e3\u53ef\u4ea4\u597d\u8fd0\u3002", "line": "\u4f4f\u6240\uff1a\u5c45\u4e8e\u5173\u53e3\u53ef\u4ea4\u597d\u8fd0\u3002"}, {"label": "\u604b\u7231", "text": "\u662f\u53bb\u662f\u7559\u5f53\u6709\u51b3\u65ad\u3002", "line": "\u604b\u7231\uff1a\u662f\u53bb\u662f\u7559\u5f53\u6709\u51b3\u65ad\u3002"}, {"label": "\u5065\u5eb7", "text": "\u65e9\u7761\u65e9\u8d77\u4e3a\u5409\u3002", "line": "\u5065\u5eb7\uff1a\u65e9\u7761\u65e9\u8d77\u4e3a\u5409\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5e38\u5904\u4e8e\u7ea0\u7eb7\u4e2d\u5fc3\u3002\u4f1a\u88ab\u5377\u5165\u68d8\u624b\u4e8b\u7aef\u3002", "line": "\u4e89\u7aef\uff1a\u5e38\u5904\u4e8e\u7ea0\u7eb7\u4e2d\u5fc3\u3002\u4f1a\u88ab\u5377\u5165\u68d8\u624b\u4e8b\u7aef\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (102, '吉吊八千慧', '吉', '担任鬼杰组组长的吉吊', '剥夺反抗意志程度的能力', '["\u82e5\u662f\u4e00\u5f00\u59cb", "\u5c31\u4e56\u4e56\u542c\u4ee4\uff0c", "\u5c0f\u547d\u672c\u80fd\u591f", "\u591a\u7559\u4e9b\u65f6\u65e5\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7528\u4eba\u6709\u65b9\u81ea\u80fd\u6210\u529f\u3002\u4f46\u4e5f\u4f1a\u989d\u5916\u6811\u654c\u3002", "line": "\u8fd0\u52bf\uff1a\u7528\u4eba\u6709\u65b9\u81ea\u80fd\u6210\u529f\u3002\u4f46\u4e5f\u4f1a\u989d\u5916\u6811\u654c\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5f53\u4ea4\u7ed9\u90e8\u4e0b\u3002\u4eb2\u529b\u4eb2\u4e3a\u4e5f\u4e0d\u4f1a\u6709\u597d\u4e0b\u573a\u3002", "line": "\u4ea4\u6613\uff1a\u5f53\u4ea4\u7ed9\u90e8\u4e0b\u3002\u4eb2\u529b\u4eb2\u4e3a\u4e5f\u4e0d\u4f1a\u6709\u597d\u4e0b\u573a\u3002"}, {"label": "\u4eba\u7f18", "text": "\u6e29\u9a6f\u4e4b\u4eba\u805a\u96c6\u5de6\u53f3\u3002", "line": "\u4eba\u7f18\uff1a\u6e29\u9a6f\u4e4b\u4eba\u805a\u96c6\u5de6\u53f3\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5fc5\u80dc\u3002", "line": "\u4e89\u7aef\uff1a\u5fc5\u80dc\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u4ed8\u8bf8\u52aa\u529b\u4fbf\u6709\u957f\u8fdb\u3002\u529f\u6210\u4e4b\u65e5\u4ea6\u5c06\u6536\u83b7\u4eba\u5fc3\u3002", "line": "\u5b66\u4e1a\uff1a\u4ed8\u8bf8\u52aa\u529b\u4fbf\u6709\u957f\u8fdb\u3002\u529f\u6210\u4e4b\u65e5\u4ea6\u5c06\u6536\u83b7\u4eba\u5fc3\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5ffd\u89c6\u517b\u751f\uff0c\u81ea\u98df\u5176\u679c\u3002", "line": "\u5065\u5eb7\uff1a\u5ffd\u89c6\u517b\u751f\uff0c\u81ea\u98df\u5176\u679c\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u524d\u5f80\u90fd\u4f1a\u6216\u6c34\u8fb9\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u524d\u5f80\u90fd\u4f1a\u6216\u6c34\u8fb9\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u8d22\u8fd0\u4ea8\u901a\u3002\u4e0d\u4e49\u4e4b\u8d22\u96be\u4e45\u7559\u3002", "line": "\u8d22\u8fd0\uff1a\u8d22\u8fd0\u4ea8\u901a\u3002\u4e0d\u4e49\u4e4b\u8d22\u96be\u4e45\u7559\u3002"}, {"label": "\u604b\u7231", "text": "\u5207\u5fcc\u7cdf\u8df5\u90e8\u4e0b\u3002", "line": "\u604b\u7231\uff1a\u5207\u5fcc\u7cdf\u8df5\u90e8\u4e0b\u3002"}, {"label": "\u52a8\u7269", "text": "\u6c34\u736d\u5f88\u53ef\u7231\u3002", "line": "\u52a8\u7269\uff1a\u6c34\u736d\u5f88\u53ef\u7231\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (103, '杖刀偶磨弓', '中吉', '挂甲武人（国宝）', '让忠心直接化为实力程度的能力', '["\u5c3d\u60c5\u98a4\u6296\u5427\uff0c", "\u6211\u7684\u5fe0\u8bda\u5fc3", "\u5982\u5047\u5305\u6362\u7684", "\u4e16\u754c\u7b2c\u4e8c\u786c\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u751f\u6027\u8f83\u771f\uff0c\u6545\u5f97\u5b89\u7a33\u8fd0\u52bf\u3002\u5207\u5fcc\u901e\u80fd\u86ee\u5e72\u3002", "line": "\u8fd0\u52bf\uff1a\u751f\u6027\u8f83\u771f\uff0c\u6545\u5f97\u5b89\u7a33\u8fd0\u52bf\u3002\u5207\u5fcc\u901e\u80fd\u86ee\u5e72\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5ba3\u8a93\u6548\u5fe0\u516c\u53f8\u5219\u80fd\u529b\u81ea\u4f1a\u63d0\u5347\u3002\u8b66\u536b\u5de5\u4f5c\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5ba3\u8a93\u6548\u5fe0\u516c\u53f8\u5219\u80fd\u529b\u81ea\u4f1a\u63d0\u5347\u3002\u8b66\u536b\u5de5\u4f5c\u4e3a\u5927\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u52e4\u80fd\u81f4\u5bcc\u3002", "line": "\u4ea4\u6613\uff1a\u52e4\u80fd\u81f4\u5bcc\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u53e4\u4ee3\u53f2\u3001\u9676\u827a\u3001\u5251\u672f\u3001\u9a6c\u672f\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u53e4\u4ee3\u53f2\u3001\u9676\u827a\u3001\u5251\u672f\u3001\u9a6c\u672f\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u8089\u4f53\u5f3a\u97e7\uff0c\u5374\u6697\u85cf\u8106\u5f31\u8981\u5bb3\u3002\u5343\u4e07\u5f53\u5fc3\u5916\u4f24\u3002", "line": "\u5065\u5eb7\uff1a\u8089\u4f53\u5f3a\u97e7\uff0c\u5374\u6697\u85cf\u8106\u5f31\u8981\u5bb3\u3002\u5343\u4e07\u5f53\u5fc3\u5916\u4f24\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4eb2\u65cf\u548c\u7766\uff0c\u4ece\u65e0\u7ea0\u7eb7\u3002", "line": "\u4e89\u7aef\uff1a\u4eb2\u65cf\u548c\u7766\uff0c\u4ece\u65e0\u7ea0\u7eb7\u3002"}, {"label": "\u604b\u7231", "text": "\u8106\u5f31\u4e0d\u582a\u3002\u5206\u624b\u5728\u5373\u3002", "line": "\u604b\u7231\uff1a\u8106\u5f31\u4e0d\u582a\u3002\u5206\u624b\u5728\u5373\u3002"}, {"label": "\u59fb\u7f18", "text": "\u503e\u5fc3\u4fe1\u4efb\u4fbf\u80fd\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u59fb\u7f18\uff1a\u503e\u5fc3\u4fe1\u4efb\u4fbf\u80fd\u4e00\u5e06\u98ce\u987a\u3002"}, {"label": "\u51fa\u884c", "text": "\u53e4\u5893\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u53e4\u5893\u4e3a\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u5c1d\u8bd5\u9a91\u9a6c\u53ef\u63d0\u5347\u8fd0\u52bf\u3002", "line": "\u7231\u597d\uff1a\u5c1d\u8bd5\u9a91\u9a6c\u53ef\u63d0\u5347\u8fd0\u52bf\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (104, '埴安神袿姬', '大吉', '手制国宝也不在话下的造形神', '创造偶像程度的能力', '["\u751f\u547d\u4f55\u5fc5\u4efb", "\u90a3\u7aef\u7c92\u6446\u5e03\uff0c", "\u6211\u4ee5\u571f\u4e0e\u6c34\uff0c", "\u4e3a\u4f60\u518d\u9020\u8eab\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7a33\u6b65\u5411\u524d\uff0c\u540c\u4f34\u591a\u591a\u3002", "line": "\u8fd0\u52bf\uff1a\u7a33\u6b65\u5411\u524d\uff0c\u540c\u4f34\u591a\u591a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u521b\u9020\u6027\u5de5\u4f5c\u7686\u4e3a\u5927\u5409\u3002\u5076\u50cf\u3001\u6a21\u7279\u3001\u9676\u827a\u3001\u5236\u9020\u4e1a\u4ea6\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u521b\u9020\u6027\u5de5\u4f5c\u7686\u4e3a\u5927\u5409\u3002\u5076\u50cf\u3001\u6a21\u7279\u3001\u9676\u827a\u3001\u5236\u9020\u4e1a\u4ea6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u624b\u5de5\u3001\u7f8e\u672f\u4e3a\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u624b\u5de5\u3001\u7f8e\u672f\u4e3a\u5927\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8fd0\u52a8\u4e0d\u8db3\uff0c\u59a8\u5bb3\u5065\u5eb7\u3002", "line": "\u5065\u5eb7\uff1a\u8fd0\u52a8\u4e0d\u8db3\uff0c\u59a8\u5bb3\u5065\u5eb7\u3002"}], [{"label": "\u4eba\u7f18", "text": "\u5f97\u9047\u7edd\u5bf9\u5fe0\u8bda\u7684\u4e0b\u5c5e\u3002", "line": "\u4eba\u7f18\uff1a\u5f97\u9047\u7edd\u5bf9\u5fe0\u8bda\u7684\u4e0b\u5c5e\u3002"}, {"label": "\u51fa\u884c", "text": "\u53e4\u5893\u5de1\u793c\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u53e4\u5893\u5de1\u793c\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u540c\u597d\u4e3a\u5b9c\u3002", "line": "\u604b\u7231\uff1a\u540c\u597d\u4e3a\u5b9c\u3002"}, {"label": "\u751f\u80b2", "text": "\u5b50\u5b59\u6ee1\u5802\u3002", "line": "\u751f\u80b2\uff1a\u5b50\u5b59\u6ee1\u5802\u3002"}, {"label": "\u5bfb\u7269", "text": "\u82e5\u6709\u5931\u7269\u518d\u9020\u5373\u53ef\u3002", "line": "\u5bfb\u7269\uff1a\u82e5\u6709\u5931\u7269\u518d\u9020\u5373\u53ef\u3002"}, {"label": "\u7231\u597d", "text": "\u904d\u8bbf\u7f8e\u672f\u9986\u3001\u535a\u7269\u9986\u4ee5\u63d0\u5347\u9020\u8be3\u3002", "line": "\u7231\u597d\uff1a\u904d\u8bbf\u7f8e\u672f\u9986\u3001\u535a\u7269\u9986\u4ee5\u63d0\u5347\u9020\u8be3\u3002"}, {"label": "\u707e\u7978", "text": "\u906d\u5230\u52a8\u7269\u5acc\u5f03\u3002", "line": "\u707e\u7978\uff1a\u906d\u5230\u52a8\u7269\u5acc\u5f03\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (105, '骊驹早鬼', '大吉', '担任劲牙组组长的骊驹', '拥有无双脚力程度的能力', '["\u795e\u660e\u7684\u5750\u9a91", "\u540c\u6837\u662f\u795e\u660e\u3002", "\u4eba\u7c7b\u7684\u5750\u9a91", "\u81ea\u7136\u4e5f\u662f\u4eba\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4ee5\u7834\u7af9\u4e4b\u52bf\u6293\u4f4f\u5e78\u8fd0\u3002\u5076\u5c14\u4e5f\u4f1a\u52bf\u5934\u8fc7\u731b\u5bfc\u81f4\u6251\u7a7a\u3002", "line": "\u8fd0\u52bf\uff1a\u4ee5\u7834\u7af9\u4e4b\u52bf\u6293\u4f4f\u5e78\u8fd0\u3002\u5076\u5c14\u4e5f\u4f1a\u52bf\u5934\u8fc7\u731b\u5bfc\u81f4\u6251\u7a7a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u65f6\u5e38\u5954\u8d70\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u9a7e\u9a76\u5458\u3001\u7269\u6d41\u5458\u3001\u7530\u5f84\u624b\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u65f6\u5e38\u5954\u8d70\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u9a7e\u9a76\u5458\u3001\u7269\u6d41\u5458\u3001\u7530\u5f84\u624b\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u9a6c\u8033\u4e1c\u98ce\u3002", "line": "\u5b66\u4e1a\uff1a\u9a6c\u8033\u4e1c\u98ce\u3002"}, {"label": "\u8fd0\u52a8", "text": "\u4efb\u4f55\u8fd0\u52a8\u5747\u80fd\u8fc5\u901f\u7cbe\u901a\u3001\u65a9\u83b7\u6210\u679c\u3002", "line": "\u8fd0\u52a8\uff1a\u4efb\u4f55\u8fd0\u52a8\u5747\u80fd\u8fc5\u901f\u7cbe\u901a\u3001\u65a9\u83b7\u6210\u679c\u3002"}, {"label": "\u5065\u5eb7", "text": "\u51fa\u5947\u5065\u58ee\u3002", "line": "\u5065\u5eb7\uff1a\u51fa\u5947\u5065\u58ee\u3002"}], [{"label": "\u51fa\u884c", "text": "\u6108\u8fdc\u6108\u4e3a\u5409\u3002\u5c24\u5b9c\u7a7a\u4e2d\u65c5\u884c\u3002", "line": "\u51fa\u884c\uff1a\u6108\u8fdc\u6108\u4e3a\u5409\u3002\u5c24\u5b9c\u7a7a\u4e2d\u65c5\u884c\u3002"}, {"label": "\u604b\u7231", "text": "\u65e0\u8bba\u6210\u8d25\uff0c\u653e\u9a6c\u53bb\u505a\u3002", "line": "\u604b\u7231\uff1a\u65e0\u8bba\u6210\u8d25\uff0c\u653e\u9a6c\u53bb\u505a\u3002"}, {"label": "\u4f4f\u6240", "text": "\u82e5\u611f\u5c40\u4fc3\uff0c\u5219\u5b9c\u8fc1\u5c45\u3002", "line": "\u4f4f\u6240\uff1a\u82e5\u611f\u5c40\u4fc3\uff0c\u5219\u5b9c\u8fc1\u5c45\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u629b\u5374\u6c42\u8d22\u4e4b\u5fc3\u3002", "line": "\u8d22\u8fd0\uff1a\u629b\u5374\u6c42\u8d22\u4e4b\u5fc3\u3002"}, {"label": "\u4eba\u7f18", "text": "\u56db\u80a2\u53d1\u8fbe\u5934\u8111\u7b80\u5355\u8005\u7eb7\u7eb7\u8ffd\u968f\u5de6\u53f3\u3002", "line": "\u4eba\u7f18\uff1a\u56db\u80a2\u53d1\u8fbe\u5934\u8111\u7b80\u5355\u8005\u7eb7\u7eb7\u8ffd\u968f\u5de6\u53f3\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u8fd0\u52a8\u3002\u4e0d\u64c5\u8111\u529b\u6d3b\u52a8\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u8fd0\u52a8\u3002\u4e0d\u64c5\u8111\u529b\u6d3b\u52a8\u3002"}, {"label": "\u52a8\u7269", "text": "\u91ce\u72fc\u5f88\u5e05\u6c14\u3002", "line": "\u52a8\u7269\uff1a\u91ce\u72fc\u5f88\u5e05\u6c14\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (106, '饕餮尤魔', '大吉', '饿扁扁魔神刚欲同盟盟主', '什么都能吸收程度的能力', '["\u6355\u98df\u8005\u6a2a\u884c\uff0c", "\u730e\u7269\u4efb\u5bb0\u5272\u3002", "\u8c01\u624d\u662f\u5f3a\u8005\uff0c", "\u81ea\u7136\u4e0d\u5fc5\u8bf4\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u751f\u541e\u6c14\u8fd0\u7684\u8d2a\u5a6a\uff0c\u8db3\u4ee5\u626d\u8f6c\u751f\u6765\u5384\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u751f\u541e\u6c14\u8fd0\u7684\u8d2a\u5a6a\uff0c\u8db3\u4ee5\u626d\u8f6c\u751f\u6765\u5384\u8fd0\u3002"}, {"label": "\u4ea4\u6613", "text": "\u80c3\u53e3\u8d8a\u5927\uff0c\u5229\u6da6\u8d8a\u591a\u3002", "line": "\u4ea4\u6613\uff1a\u80c3\u53e3\u8d8a\u5927\uff0c\u5229\u6da6\u8d8a\u591a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u9910\u996e\u5e97\u4e3a\u5409\u3002\u5927\u80c3\u738b\u5219\u5929\u4e0b\u65e0\u654c\u3002", "line": "\u5de5\u4f5c\uff1a\u9910\u996e\u5e97\u4e3a\u5409\u3002\u5927\u80c3\u738b\u5219\u5929\u4e0b\u65e0\u654c\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6240\u5b66\u4f1a\u5c3d\u6570\u5438\u6536\u3002\u8425\u517b\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u6240\u5b66\u4f1a\u5c3d\u6570\u5438\u6536\u3002\u8425\u517b\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5efa\u8bae\u8e0f\u4e0a\u7f8e\u98df\u4e4b\u65c5\u3002", "line": "\u51fa\u884c\uff1a\u5efa\u8bae\u8e0f\u4e0a\u7f8e\u98df\u4e4b\u65c5\u3002"}, {"label": "\u4e89\u7aef", "text": "\u65e0\u654c\u3002", "line": "\u4e89\u7aef\uff1a\u65e0\u654c\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5bbd\u5e7f\u4e3a\u5b9c\u3002", "line": "\u4f4f\u6240\uff1a\u5bbd\u5e7f\u4e3a\u5b9c\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u9910\u8d39\u98d9\u5347\u3002\u4e00\u65e6\u9910\u8d39\u65ad\u4f9b\uff0c\u8fd0\u6c14\u4e5f\u4f1a\u65ad\u7edd\u3002", "line": "\u8d22\u8fd0\uff1a\u9910\u8d39\u98d9\u5347\u3002\u4e00\u65e6\u9910\u8d39\u65ad\u4f9b\uff0c\u8fd0\u6c14\u4e5f\u4f1a\u65ad\u7edd\u3002"}, {"label": "\u5065\u5eb7", "text": "\u79ef\u98df\u8179\u6cfb\u7a00\u677e\u5e73\u5e38\u3002", "line": "\u5065\u5eb7\uff1a\u79ef\u98df\u8179\u6cfb\u7a00\u677e\u5e73\u5e38\u3002"}, {"label": "\u7231\u597d", "text": "\u4efb\u4f55\u6d3b\u52a8\u4e00\u65e6\u63a5\u89e6\u4fbf\u4f1a\u6c89\u8ff7\u5176\u4e2d\u3002", "line": "\u7231\u597d\uff1a\u4efb\u4f55\u6d3b\u52a8\u4e00\u65e6\u63a5\u89e6\u4fbf\u4f1a\u6c89\u8ff7\u5176\u4e2d\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (107, '豪德寺三花', '大吉', '适合撑门面的招财三花猫', '招财或揽客程度的能力', '["\u8d70\u8fc7\u8def\u8fc7\u90fd", "\u4e0d\u8981\u9519\u8fc7\u5566\uff01", "\u6709\u94b1\u6367\u94b1\u573a\uff0c", "\u6ca1\u94b1\u6367\u4eba\u573a\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4ece\u4e8b\u670d\u52a1\u4e1a\u4e3a\u5409\u3002\u82e5\u975e\u5982\u6b64\u5f53\u7acb\u5373\u8f6c\u884c\u3002", "line": "\u8fd0\u52bf\uff1a\u4ece\u4e8b\u670d\u52a1\u4e1a\u4e3a\u5409\u3002\u82e5\u975e\u5982\u6b64\u5f53\u7acb\u5373\u8f6c\u884c\u3002"}, {"label": "\u4ea4\u6613", "text": "\u751f\u610f\u7ea2\u7ea2\u706b\u706b\u3002 \u7136\u800c\uff0c\u5ba2\u6d41\u4e0e\u6536\u5165\u4e0d\u53ef\u517c\u5f97\u3002 \u8d2a\u5f97\u65e0\u538c\u5fc5\u5815\u5730\u72f1\u3002", "line": "\u4ea4\u6613\uff1a\u751f\u610f\u7ea2\u7ea2\u706b\u706b\u3002 \u7136\u800c\uff0c\u5ba2\u6d41\u4e0e\u6536\u5165\u4e0d\u53ef\u517c\u5f97\u3002 \u8d2a\u5f97\u65e0\u538c\u5fc5\u5815\u5730\u72f1\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6570\u5b66\u3001\u7ecf\u6d4e\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u6570\u5b66\u3001\u7ecf\u6d4e\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u51fa\u884c\u4e0d\u5982\u7ecf\u5546\u3002", "line": "\u51fa\u884c\uff1a\u51fa\u884c\u4e0d\u5982\u7ecf\u5546\u3002"}, {"label": "\u604b\u7231", "text": "\u5230\u5e95\u4e0d\u5982\u7ecf\u5546\u3002", "line": "\u604b\u7231\uff1a\u5230\u5e95\u4e0d\u5982\u7ecf\u5546\u3002"}, {"label": "\u59fb\u7f18", "text": "\u4e3a\u8d22\u6210\u5a5a\u4ea6\u6709\u826f\u7f18\u3002", "line": "\u59fb\u7f18\uff1a\u4e3a\u8d22\u6210\u5a5a\u4ea6\u6709\u826f\u7f18\u3002"}, {"label": "\u4f4f\u6240", "text": "\u95e8\u5ead\u82e5\u5e02\uff0c\u6076\u9f20\u7edd\u8ff9\u3002", "line": "\u4f4f\u6240\uff1a\u95e8\u5ead\u82e5\u5e02\uff0c\u6076\u9f20\u7edd\u8ff9\u3002"}, {"label": "\u4fe1\u4ef0", "text": "\u795e\u793e\u54ea\u6709\u4f5b\u5bfa\u597d\u3002 \u751f\u610f\u5174\u9686\u52ff\u5fd8\u8fd8\u613f\u3002 \u5fd8\u6069\u8d1f\u4e49\u5fc5\u5815\u5730\u72f1\u3002", "line": "\u4fe1\u4ef0\uff1a\u795e\u793e\u54ea\u6709\u4f5b\u5bfa\u597d\u3002 \u751f\u610f\u5174\u9686\u52ff\u5fd8\u8fd8\u613f\u3002 \u5fd8\u6069\u8d1f\u4e49\u5fc5\u5815\u5730\u72f1\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (108, '山城高岭', '吉', '生财有道的山童', '操纵森林之气程度的能力', '["\u7ba1\u5b83\u6df1\u5c71", "\u8fd8\u662f\u5cfb\u5cad\uff0c", "\u751f\u610f\u5728\u54ea", "\u90fd\u4e00\u6837\u505a\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6bcf\u5206\u52aa\u529b\u5fc5\u6709\u6536\u83b7\u3002 \u4f46\u82e5\u5f97\u610f\u5fd8\u5f62\uff0c\u7ec8\u5c06\u4e00\u8d25\u6d82\u5730\u3002", "line": "\u8fd0\u52bf\uff1a\u6bcf\u5206\u52aa\u529b\u5fc5\u6709\u6536\u83b7\u3002 \u4f46\u82e5\u5f97\u610f\u5fd8\u5f62\uff0c\u7ec8\u5c06\u4e00\u8d25\u6d82\u5730\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5929\u8d50\u826f\u673a\u3002 \u4ece\u4e8b\u51b7\u95e8\u804c\u4e1a\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u5929\u8d50\u826f\u673a\u3002 \u4ece\u4e8b\u51b7\u95e8\u804c\u4e1a\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5f53\u8fdb\u4fee\u8d22\u52a1\u77e5\u8bc6\u3002", "line": "\u5b66\u4e1a\uff1a\u5f53\u8fdb\u4fee\u8d22\u52a1\u77e5\u8bc6\u3002"}], [{"label": "\u51fa\u884c", "text": "\u767b\u5c71\u4e4b\u5916\u4e0d\u4f5c\u4ed6\u60f3\u3002 \u9732\u8425\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u767b\u5c71\u4e4b\u5916\u4e0d\u4f5c\u4ed6\u60f3\u3002 \u9732\u8425\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5f53\u5b9a\u5c45\u6df1\u5c71\u3002\u9732\u8425\u4ea6\u5584\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5b9a\u5c45\u6df1\u5c71\u3002\u9732\u8425\u4ea6\u5584\u3002"}, {"label": "\u7231\u597d", "text": "\u8bd5\u8bd5\u9732\u8425\u5982\u4f55\uff1f", "line": "\u7231\u597d\uff1a\u8bd5\u8bd5\u9732\u8425\u5982\u4f55\uff1f"}, {"label": "\u5065\u5eb7", "text": "\u4e0d\u597d\u4e0d\u574f\u3002", "line": "\u5065\u5eb7\uff1a\u4e0d\u597d\u4e0d\u574f\u3002"}, {"label": "\u604b\u7231", "text": "\u4e0d\u611f\u5174\u8da3\u3002", "line": "\u604b\u7231\uff1a\u4e0d\u611f\u5174\u8da3\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5f53\u5fc3\u9a97\u5a5a\u3002", "line": "\u59fb\u7f18\uff1a\u5f53\u5fc3\u9a97\u5a5a\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5c06\u4e0e\u6cb3\u7ae5\u5f00\u6218\u3002", "line": "\u4e89\u7aef\uff1a\u5c06\u4e0e\u6cb3\u7ae5\u5f00\u6218\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (109, '驹草山如', '吉或凶', '烟与博彩的山女郎', '以烟草之烟操纵精神程度的能力', '["\u4eba\u751f\u4e0d\u6cbe\u8d4c\uff0c", "\u65e5\u65e5\u7686\u662f\u82e6\u3002", "\u5fcd\u6c14\u53c8\u541e\u58f0\uff0c", "\u4e0e\u673a\u5668\u4f55\u5f02\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4eba\u751f\u5904\u5904\u7686\u662f\u8d4c\u3002\u56e0\u8d4c\u800c\u4ea1\u5728\u6240\u96be\u514d\u3002", "line": "\u8fd0\u52bf\uff1a\u4eba\u751f\u5904\u5904\u7686\u662f\u8d4c\u3002\u56e0\u8d4c\u800c\u4ea1\u5728\u6240\u96be\u514d\u3002"}, {"label": "\u75be\u75c5", "text": "\u5f53\u5fc3\u80ba\u75be\u3002", "line": "\u75be\u75c5\uff1a\u5f53\u5fc3\u80ba\u75be\u3002"}, {"label": "\u4ea4\u6613", "text": "\u662f\u76c8\u662f\u4e8f\uff0c\u5168\u51ed\u8fd0\u6c14\u3002", "line": "\u4ea4\u6613\uff1a\u662f\u76c8\u662f\u4e8f\uff0c\u5168\u51ed\u8fd0\u6c14\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8003\u8bd5\u7b54\u9898\u778e\u8499\u4e3a\u5409\u3002\u6781\u5c0f\u6982\u7387\u65a9\u83b7\u9ad8\u5206\u3002", "line": "\u5b66\u4e1a\uff1a\u8003\u8bd5\u7b54\u9898\u778e\u8499\u4e3a\u5409\u3002\u6781\u5c0f\u6982\u7387\u65a9\u83b7\u9ad8\u5206\u3002"}], [{"label": "\u51fa\u884c", "text": "\u9ad8\u539f\u4e3a\u5b9c\u3002", "line": "\u51fa\u884c\uff1a\u9ad8\u539f\u4e3a\u5b9c\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4f60\u4e89\u6211\u6597\u4f55\u65f6\u4f11\uff0c \u65a1\u65cb\u7eb7\u4e89\u5f97\u5b89\u5b81\u3002", "line": "\u4e89\u7aef\uff1a\u4f60\u4e89\u6211\u6597\u4f55\u65f6\u4f11\uff0c \u65a1\u65cb\u7eb7\u4e89\u5f97\u5b89\u5b81\u3002"}, {"label": "\u604b\u7231", "text": "\u8d4c\u8d62\u518d\u8c08\u3002", "line": "\u604b\u7231\uff1a\u8d4c\u8d62\u518d\u8c08\u3002"}, {"label": "\u59fb\u7f18", "text": "\u4e0d\u59a8\u4e00\u8d4c\u3002", "line": "\u59fb\u7f18\uff1a\u4e0d\u59a8\u4e00\u8d4c\u3002"}, {"label": "\u7231\u597d", "text": "\u82b1\u672d\u3002\u516b\u516b\u82b1\u5c24\u5409\u3002", "line": "\u7231\u597d\uff1a\u82b1\u672d\u3002\u516b\u516b\u82b1\u5c24\u5409\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5373\u4fbf\u4e00\u591c\u66b4\u5bcc\uff0c\u4e5f\u5fc5\u5c06\u8f93\u4e2a\u7cbe\u5149\u3002", "line": "\u8d22\u8fd0\uff1a\u5373\u4fbf\u4e00\u591c\u66b4\u5bcc\uff0c\u4e5f\u5fc5\u5c06\u8f93\u4e2a\u7cbe\u5149\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (110, '玉造魅须丸', '大吉', '由矿物锻造的神明', '制造勾玉程度的能力', '["\u795e\u4ee3\u7684\u5b9d\u77f3", "\u5df2\u957f\u7720\u4e07\u53e4\u3002", "\u5373\u4fbf\u5982\u6b64\u4f60", "\u4e5f\u8981\u91c7\u6398\u5417\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5929\u964d\u6a2a\u8d22\u4e0e\u795e\u529b\u3002\u4e3b\u52a8\u63a2\u5bfb\u673a\u7f18\u4e3a\u4e0a\u3002", "line": "\u8fd0\u52bf\uff1a\u5929\u964d\u6a2a\u8d22\u4e0e\u795e\u529b\u3002\u4e3b\u52a8\u63a2\u5bfb\u673a\u7f18\u4e3a\u4e0a\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6b63\u503c\u5929\u8d50\u826f\u673a\u3002\u6b64\u65f6\u4e0d\u53d1\uff0c\u66f4\u5f85\u4f55\u65f6\uff1f", "line": "\u8d22\u8fd0\uff1a\u6b63\u503c\u5929\u8d50\u826f\u673a\u3002\u6b64\u65f6\u4e0d\u53d1\uff0c\u66f4\u5f85\u4f55\u65f6\uff1f"}, {"label": "\u4ea4\u6613", "text": "\u5c06\u6398\u5f97\u91d1\u77ff\u3002 \u91c7\u77ff\u4e1a\u4e3a\u5927\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u5c06\u6398\u5f97\u91d1\u77ff\u3002 \u91c7\u77ff\u4e1a\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8003\u53e4\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u8003\u53e4\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5fcc\u7d2b\u5916\u7ebf\u3002\u6709\u635f\u808c\u80a4\u3002", "line": "\u5065\u5eb7\uff1a\u5fcc\u7d2b\u5916\u7ebf\u3002\u6709\u635f\u808c\u80a4\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u767b\u5c71\u3002\u91d1\u5c71\u94f6\u5c71\u5c24\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u767b\u5c71\u3002\u91d1\u5c71\u94f6\u5c71\u5c24\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5f97\u9047\u5b9d\u77f3\u8ff7\u3002", "line": "\u604b\u7231\uff1a\u5f97\u9047\u5b9d\u77f3\u8ff7\u3002"}, {"label": "\u5bfb\u7269", "text": "\u53ef\u5728\u5730\u4e0b\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u53ef\u5728\u5730\u4e0b\u5bfb\u56de\u3002"}, {"label": "\u7269\u4ef6", "text": "\u53ef\u5c06\u529b\u91cf\u77f3\u4e4b\u529b\u5c3d\u6570\u6fc0\u53d1\u3002\u7fe1\u7fe0\u4e3a\u5927\u5409\u3002", "line": "\u7269\u4ef6\uff1a\u53ef\u5c06\u529b\u91cf\u77f3\u4e4b\u529b\u5c3d\u6570\u6fc0\u53d1\u3002\u7fe1\u7fe0\u4e3a\u5927\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (111, '菅牧典', '末凶', '低语邪念的管狐', '抓住灵魂弱点乘虚而入程度的能力', '["\u6084\u6084\u544a\u8bc9\u4f60\uff0c", "\u673a\u4f1a\u4e0d\u7b49\u4eba\u3002", "\u518d\u4e0d\u53bb\u884c\u52a8\uff0c", "\u7edd\u5bf9\u5403\u5927\u4e8f\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5c06\u906d\u82b1\u8a00\u5de7\u8bed\u8499\u9a97\uff0c\u88ab\u5403\u5e72\u62b9\u51c0\u540e\u518d\u4e00\u811a\u8e22\u5f00\u3002", "line": "\u8fd0\u52bf\uff1a\u5c06\u906d\u82b1\u8a00\u5de7\u8bed\u8499\u9a97\uff0c\u88ab\u5403\u5e72\u62b9\u51c0\u540e\u518d\u4e00\u811a\u8e22\u5f00\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e00\u65f6\u7e41\u76db\uff0c\u7ec8\u5c06\u7834\u706d\u3002", "line": "\u4ea4\u6613\uff1a\u4e00\u65f6\u7e41\u76db\uff0c\u7ec8\u5c06\u7834\u706d\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4fe1\u606f\u884c\u4e1a\u4e3a\u5409\u3002\u4fe1\u8a89\u578b\u751f\u610f\u4e3a\u51f6\u3002", "line": "\u5de5\u4f5c\uff1a\u4fe1\u606f\u884c\u4e1a\u4e3a\u5409\u3002\u4fe1\u8a89\u578b\u751f\u610f\u4e3a\u51f6\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u8d22\u6e90\u6eda\u6eda\uff0c\u4f46\u5c06\u4ed8\u51fa\u6c89\u91cd\u4ee3\u4ef7\u3002", "line": "\u8d22\u8fd0\uff1a\u8d22\u6e90\u6eda\u6eda\uff0c\u4f46\u5c06\u4ed8\u51fa\u6c89\u91cd\u4ee3\u4ef7\u3002"}], [{"label": "\u5b66\u4e1a", "text": "\u8bed\u6587\u3001\u6570\u5b66\u3001\u5316\u5b66\u4e3a\u5409\u3002\u4f26\u7406\u4e3a\u5927\u51f6\u3002", "line": "\u5b66\u4e1a\uff1a\u8bed\u6587\u3001\u6570\u5b66\u3001\u5316\u5b66\u4e3a\u5409\u3002\u4f26\u7406\u4e3a\u5927\u51f6\u3002"}, {"label": "\u5065\u5eb7", "text": "\u75c5\u7531\u5fc3\u751f\uff0c\u591a\u52a0\u7559\u610f\u3002", "line": "\u5065\u5eb7\uff1a\u75c5\u7531\u5fc3\u751f\uff0c\u591a\u52a0\u7559\u610f\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5931\u53bb\u4fe1\u7528\u3002", "line": "\u4eba\u7f18\uff1a\u5931\u53bb\u4fe1\u7528\u3002"}, {"label": "\u59fb\u7f18", "text": "\u5c0f\u5fc3\u9a97\u5a5a\u3002", "line": "\u59fb\u7f18\uff1a\u5c0f\u5fc3\u9a97\u5a5a\u3002"}, {"label": "\u4e89\u7aef", "text": "\u5927\u53ef\u5047\u624b\u4ed6\u4eba\uff0c\u81ea\u5df1\u4f5c\u58c1\u4e0a\u89c2\u3002", "line": "\u4e89\u7aef\uff1a\u5927\u53ef\u5047\u624b\u4ed6\u4eba\uff0c\u81ea\u5df1\u4f5c\u58c1\u4e0a\u89c2\u3002"}, {"label": "\u664b\u5347", "text": "\u957f\u8896\u5584\u821e\u3002\u53ea\u8981\u5706\u5f97\u4e0a\uff0c\u8bf4\u8c0e\u53c8\u4f55\u59a8\u3002", "line": "\u664b\u5347\uff1a\u957f\u8896\u5584\u821e\u3002\u53ea\u8981\u5706\u5f97\u4e0a\uff0c\u8bf4\u8c0e\u53c8\u4f55\u59a8\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (112, '饭纲丸龙', '大凶
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (113, '天弓千亦', '吉凶不定', '就连命运也能交易的神明', '剥夺所有权程度的能力', '["\u4eba\u7c7b\u662f\u4f55\u65f6", "\u5f00\u59cb\u8bef\u8ba4\u4e3a", "\u81ea\u5df1\u80fd\u4e3b\u5bb0", "\u547d\u8fd0\u6240\u6709\u6743\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8f9b\u82e6\u6293\u4f4f\u7684\u597d\u8fd0\u8f6c\u77ac\u5373\u901d\u3002\u4f46\u53ef\u53cd\u5b88\u4e3a\u653b\uff0c\u4e3b\u52a8\u593a\u8d70\u4ed6\u4eba\u597d\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u8f9b\u82e6\u6293\u4f4f\u7684\u597d\u8fd0\u8f6c\u77ac\u5373\u901d\u3002\u4f46\u53ef\u53cd\u5b88\u4e3a\u653b\uff0c\u4e3b\u52a8\u593a\u8d70\u4ed6\u4eba\u597d\u8fd0\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8d2f\u5f7b\u81ea\u7531\u4e70\u5356\u4fbf\u53ef\u65f6\u8fd0\u4ea8\u901a\u3002\u65a4\u65a4\u8ba1\u8f83\u7ec8\u5c06\u5931\u8d25\u3002", "line": "\u4ea4\u6613\uff1a\u8d2f\u5f7b\u81ea\u7531\u4e70\u5356\u4fbf\u53ef\u65f6\u8fd0\u4ea8\u901a\u3002\u65a4\u65a4\u8ba1\u8f83\u7ec8\u5c06\u5931\u8d25\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5927\u8d77\u5927\u843d\u3002\u96f6\u552e\u4e1a\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5927\u8d77\u5927\u843d\u3002\u96f6\u552e\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7ecf\u6d4e\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u7ecf\u6d4e\u5b66\u4e3a\u5409\u3002"}], [{"label": "\u8d22\u8fd0", "text": "\u6301\u4ed3\u4e3a\u51f6\u3002\u5f53\u63a8\u5012\u91cd\u6765\u3002", "line": "\u8d22\u8fd0\uff1a\u6301\u4ed3\u4e3a\u51f6\u3002\u5f53\u63a8\u5012\u91cd\u6765\u3002"}, {"label": "\u604b\u7231", "text": "\u5f97\u9047\u4e86\u65e0\u63a7\u5236\u6b32\u4e4b\u4eba\u3002", "line": "\u604b\u7231\uff1a\u5f97\u9047\u4e86\u65e0\u63a7\u5236\u6b32\u4e4b\u4eba\u3002"}, {"label": "\u51fa\u884c", "text": "\u5e02\u573a\u4e3a\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5e02\u573a\u4e3a\u5927\u5409\u3002"}, {"label": "\u5bfb\u7269", "text": "\u53ef\u5728\u571f\u4e2d\u5bfb\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u53ef\u5728\u571f\u4e2d\u5bfb\u56de\u3002"}, {"label": "\u75be\u75c5", "text": "\u75c5\u9b54\u9000\u6563\u3002", "line": "\u75be\u75c5\uff1a\u75c5\u9b54\u9000\u6563\u3002"}, {"label": "\u7231\u597d", "text": "\u4e3b\u52a8\u51fa\u624b\u73cd\u85cf\uff0c\u85cf\u54c1\u4e0d\u51cf\u53cd\u589e\u3002", "line": "\u7231\u597d\uff1a\u4e3b\u52a8\u51fa\u624b\u73cd\u85cf\uff0c\u85cf\u54c1\u4e0d\u51cf\u53cd\u589e\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (114, '姬虫百百世', '【大大吉】', '囫囵吞运的大蜈蚣', '噬龙程度的能力', '["\u554a\u54c8\u54c8\u54c8\u54c8\uff0c", "\u9f99\u8109\u6eda\u6eda\u6d41\uff0c", "\u4e14\u770b\u8001\u5b50\u6765", "\u4e00\u53e3\u5c31\u559d\u5e72\uff01"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6c14\u8fd0\u6eda\u6eda\u5954\u6d41\u3002\u5468\u906d\u6c14\u8fd0\u4e5f\u80fd\u4e00\u5e76\u5377\u8d70\u3002", "line": "\u8fd0\u52bf\uff1a\u6c14\u8fd0\u6eda\u6eda\u5954\u6d41\u3002\u5468\u906d\u6c14\u8fd0\u4e5f\u80fd\u4e00\u5e76\u5377\u8d70\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5ba2\u6d41\u7edc\u7ece\u4e0d\u7edd\u3002\u53d1\u8d22\u81f4\u5bcc\u7684\u826f\u673a\u3002", "line": "\u4ea4\u6613\uff1a\u5ba2\u6d41\u7edc\u7ece\u4e0d\u7edd\u3002\u53d1\u8d22\u81f4\u5bcc\u7684\u826f\u673a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u670d\u52a1\u4e1a\u4e0e\u624b\u4e0a\u6d3b\u8ba1\u5c06\u8fdb\u5c55\u987a\u5229\u3002\u5b9d\u77f3\u3001\u91c7\u77ff\u884c\u4e1a\u4ea6\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u670d\u52a1\u4e1a\u4e0e\u624b\u4e0a\u6d3b\u8ba1\u5c06\u8fdb\u5c55\u987a\u5229\u3002\u5b9d\u77f3\u3001\u91c7\u77ff\u884c\u4e1a\u4ea6\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e66\u5c71\u6709\u8def\uff0c\u62bc\u9898\u4e3a\u5f84\u3002", "line": "\u5b66\u4e1a\uff1a\u4e66\u5c71\u6709\u8def\uff0c\u62bc\u9898\u4e3a\u5f84\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u767e\u6bd2\u4e0d\u4fb5\u3002", "line": "\u5065\u5eb7\uff1a\u767e\u6bd2\u4e0d\u4fb5\u3002"}, {"label": "\u604b\u7231", "text": "\u7f18\u5206\u4e0d\u53d7\u8fd0\u6c14\u6446\u5e03\u3002", "line": "\u604b\u7231\uff1a\u7f18\u5206\u4e0d\u53d7\u8fd0\u6c14\u6446\u5e03\u3002"}, {"label": "\u51fa\u884c", "text": "\u9634\u6697\u6f6e\u6e7f\u5904\u4e3a\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u9634\u6697\u6f6e\u6e7f\u5904\u4e3a\u5927\u5409\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u6536\u85cf\u77ff\u7269\uff0c\u5efa\u9020\u6e38\u620f\u4ea6\u5409\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u6536\u85cf\u77ff\u7269\uff0c\u5efa\u9020\u6e38\u620f\u4ea6\u5409\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u589e\u52a0\u79ef\u84c4\u7684\u826f\u673a\u3002", "line": "\u8d22\u8fd0\uff1a\u589e\u52a0\u79ef\u84c4\u7684\u826f\u673a\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5bbe\u5ba2\u76c8\u95e8\u3002", "line": "\u4eba\u7f18\uff1a\u5bbe\u5ba2\u76c8\u95e8\u3002"}, {"label": "\u4f4f\u6240", "text": "\u767e\u866b\u7fa4\u805a\u3002", "line": "\u4f4f\u6240\uff1a\u767e\u866b\u7fa4\u805a\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (115, '孙美天', '吉', '坚信自己是齐天大圣的猿神', '操纵野生猿猴程度的能力', '["\u7334\u5c71\u5f53\u5927\u738b\uff0c", "\u4e43\u662f\u4fee\u7f57\u9053\u3002", "\u6bdb\u5934\u5c0f\u5996\u602a\uff0c", "\u5c82\u80fd\u6765\u78b0\u74f7\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5982\u7334\u722a\u822c\u652b\u53d6\u597d\u8fd0\u3002\u4f46\u4ea6\u6709\u53ef\u80fd\u652b\u53d6\u610f\u6599\u4e4b\u5916\u7684\u5996\u6c14\u3002", "line": "\u8fd0\u52bf\uff1a\u5982\u7334\u722a\u822c\u652b\u53d6\u597d\u8fd0\u3002\u4f46\u4ea6\u6709\u53ef\u80fd\u652b\u53d6\u610f\u6599\u4e4b\u5916\u7684\u5996\u6c14\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e09\u6559\u4e5d\u6d41\u6765\u5ba2\u4e91\u96c6\u3002\u6ce8\u610f\u7b5b\u9009\u4ea4\u6613\u5bf9\u8c61\u3002", "line": "\u4ea4\u6613\uff1a\u4e09\u6559\u4e5d\u6d41\u6765\u5ba2\u4e91\u96c6\u3002\u6ce8\u610f\u7b5b\u9009\u4ea4\u6613\u5bf9\u8c61\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u51ed\u501f\u7075\u6d3b\u8eab\u624b\u505a\u5f97\u98ce\u751f\u6c34\u8d77\u3002\u624b\u827a\u4eba\u3001\u6f14\u5458\u3001\u7334\u620f\u8868\u6f14\u8005\u3001\u4f53\u64cd\u9009\u624b\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u51ed\u501f\u7075\u6d3b\u8eab\u624b\u505a\u5f97\u98ce\u751f\u6c34\u8d77\u3002\u624b\u827a\u4eba\u3001\u6f14\u5458\u3001\u7334\u620f\u8868\u6f14\u8005\u3001\u4f53\u64cd\u9009\u624b\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7334\u5b50\u6c34\u5e73\u3002", "line": "\u5b66\u4e1a\uff1a\u7334\u5b50\u6c34\u5e73\u3002"}], [{"label": "\u51fa\u884c", "text": "\u524d\u5f80\u68ee\u6797\u4f1a\u5377\u5165\u9886\u5730\u7eb7\u4e89\u3002\u5b9c\u5411\u897f\u884c\u3002", "line": "\u51fa\u884c\uff1a\u524d\u5f80\u68ee\u6797\u4f1a\u5377\u5165\u9886\u5730\u7eb7\u4e89\u3002\u5b9c\u5411\u897f\u884c\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u575a\u5982\u77f3\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u575a\u5982\u77f3\u3002"}, {"label": "\u4e89\u7aef", "text": "\u6ca1\u5b8c\u6ca1\u4e86\u3002", "line": "\u4e89\u7aef\uff1a\u6ca1\u5b8c\u6ca1\u4e86\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6536\u5165\u4e0d\u83f2\uff0c\u4f46\u4f1a\u56e0\u8d2a\u6b32\u5c3d\u4ed8\u4e1c\u6d41\u3002", "line": "\u8d22\u8fd0\uff1a\u6536\u5165\u4e0d\u83f2\uff0c\u4f46\u4f1a\u56e0\u8d2a\u6b32\u5c3d\u4ed8\u4e1c\u6d41\u3002"}, {"label": "\u604b\u7231", "text": "\u5b9c\u5927\u80c6\u8fdb\u653b\u3002", "line": "\u604b\u7231\uff1a\u5b9c\u5927\u80c6\u8fdb\u653b\u3002"}, {"label": "\u7231\u597d", "text": "\u722c\u6811\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u722c\u6811\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (116, '三头慧之子', '末吉', '意外获得不死之身的山犬', '操纵陷阱程度的能力', '["\u63d0\u524d\u51c6\u5907\u597d\uff0c", "\u5750\u7b49\u5c31\u5b8c\u4e8b\u3002", "\u9677\u9631\u597d\u5e2e\u624b\uff0c", "\u7701\u65f6\u53c8\u7701\u529b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6574\u4f53\u4e0a\u6613\u9677\u5165\u88ab\u52a8\u7b49\u5f85\u7684\u5c40\u9762\uff0c\u76f8\u5e94\u5730\u4e5f\u53ef\u5f97\u5230\u5de8\u5927\u6536\u83b7\u3002", "line": "\u8fd0\u52bf\uff1a\u6574\u4f53\u4e0a\u6613\u9677\u5165\u88ab\u52a8\u7b49\u5f85\u7684\u5c40\u9762\uff0c\u76f8\u5e94\u5730\u4e5f\u53ef\u5f97\u5230\u5de8\u5927\u6536\u83b7\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u8003\u9a8c\u575a\u5fcd\u5fc3\u6027\u3002\u72e9\u730e\u3001\u6e14\u4e1a\u3001\u670d\u52a1\u4e1a\u3001\u4ece\u519b\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u8003\u9a8c\u575a\u5fcd\u5fc3\u6027\u3002\u72e9\u730e\u3001\u6e14\u4e1a\u3001\u670d\u52a1\u4e1a\u3001\u4ece\u519b\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u51fa\u4e4e\u610f\u6599\u5730\u5934\u8111\u7075\u5149\u3002\u5927\u7ea6\u80fd\u53d1\u6325\u5e73\u65f6\u7684\u4e09\u500d\u6c34\u5e73\u3002", "line": "\u5b66\u4e1a\uff1a\u51fa\u4e4e\u610f\u6599\u5730\u5934\u8111\u7075\u5149\u3002\u5927\u7ea6\u80fd\u53d1\u6325\u5e73\u65f6\u7684\u4e09\u500d\u6c34\u5e73\u3002"}, {"label": "\u5065\u5eb7", "text": "\u60ca\u4eba\u5730\u957f\u5bff\u3002", "line": "\u5065\u5eb7\uff1a\u60ca\u4eba\u5730\u957f\u5bff\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5b9c\u4eb2\u8fd1\u81ea\u7136\u3002\u53d7\u5b97\u6559\u573a\u6240\u6392\u65a5\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u4eb2\u8fd1\u81ea\u7136\u3002\u53d7\u5b97\u6559\u573a\u6240\u6392\u65a5\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4f1a\u88ab\u62d2\u7edd\u63e1\u624b\u3002", "line": "\u4eba\u7f18\uff1a\u4f1a\u88ab\u62d2\u7edd\u63e1\u624b\u3002"}, {"label": "\u604b\u7231", "text": "\u4f1a\u843d\u5165\u5371\u9669\u9677\u9631\u3002", "line": "\u604b\u7231\uff1a\u4f1a\u843d\u5165\u5371\u9669\u9677\u9631\u3002"}, {"label": "\u5bfb\u7269", "text": "\u53ef\u5bfb\u56de\u5931\u7269\u3002\u55c5\u89c9\u7075\u654f\u3002", "line": "\u5bfb\u7269\uff1a\u53ef\u5bfb\u56de\u5931\u7269\u3002\u55c5\u89c9\u7075\u654f\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5f53\u5fc3\u5931\u706b\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5fc3\u5931\u706b\u3002"}, {"label": "\u4f24\u75db", "text": "\u843d\u5165\u81ea\u5df1\u7684\u9677\u9631\u3002", "line": "\u4f24\u75db\uff1a\u843d\u5165\u81ea\u5df1\u7684\u9677\u9631\u3002"}, {"label": "\u7231\u597d", "text": "\u7b56\u7565\u6e38\u620f\u4e3a\u5b9c\uff0c\u5982\u5c06\u68cb\u3001\u56f4\u68cb\u7b49\u3002", "line": "\u7231\u597d\uff1a\u7b56\u7565\u6e38\u620f\u4e3a\u5b9c\uff0c\u5982\u5c06\u68cb\u3001\u56f4\u68cb\u7b49\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (117, '天火人血枪', '【大大凶】', '被诅咒的谜之天火人', '操纵血与火程度的能力', '["\u6211\u4e0d\u5409\u5229\u554a\uff1f", "\u90a3\u53c8\u600e\u4e48\u4e86\u3002", "\u5c31\u8fd9\u4e48\u7740\u5457\uff0c", "\u4e0d\u4e5f\u633a\u597d\u7684\uff1f"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4f1a\u8ba9\u5468\u906d\u9677\u5165\u4e0d\u5e78\uff0c\u7ed3\u679c\u81ea\u5df1\u4e5f\u8fde\u5e26\u7740\u5012\u9709\u3002", "line": "\u8fd0\u52bf\uff1a\u4f1a\u8ba9\u5468\u906d\u9677\u5165\u4e0d\u5e78\uff0c\u7ed3\u679c\u81ea\u5df1\u4e5f\u8fde\u5e26\u7740\u5012\u9709\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0d\u5b9c\u4ece\u4e8b\u96c6\u4f53\u5de5\u4f5c\u3002\u5012\u662f\u5f88\u9002\u5408\u5f53\u827a\u672f\u5bb6\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0d\u5b9c\u4ece\u4e8b\u96c6\u4f53\u5de5\u4f5c\u3002\u5012\u662f\u5f88\u9002\u5408\u5f53\u827a\u672f\u5bb6\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u533b\u5b66\u3001\u751f\u7269\u5b66\u4e3a\u5b9c\u3002\u6b64\u5916\u7686\u51f6\u3002", "line": "\u5b66\u4e1a\uff1a\u533b\u5b66\u3001\u751f\u7269\u5b66\u4e3a\u5b9c\u3002\u6b64\u5916\u7686\u51f6\u3002"}, {"label": "\u5065\u5eb7", "text": "\u8eab\u865a\u4f53\u5f31\uff0c\u840e\u9761\u4e0d\u632f\u3002", "line": "\u5065\u5eb7\uff1a\u8eab\u865a\u4f53\u5f31\uff0c\u840e\u9761\u4e0d\u632f\u3002"}], [{"label": "\u4f4f\u6240", "text": "\u7acb\u523b\u505a\u597d\u9632\u706b\u63aa\u65bd\u3002", "line": "\u4f4f\u6240\uff1a\u7acb\u523b\u505a\u597d\u9632\u706b\u63aa\u65bd\u3002"}, {"label": "\u51fa\u884c", "text": "\u6df1\u6076\u75db\u7edd\uff0c\u95ed\u95e8\u4e0d\u51fa\u4e3a\u5b9c\u3002", "line": "\u51fa\u884c\uff1a\u6df1\u6076\u75db\u7edd\uff0c\u95ed\u95e8\u4e0d\u51fa\u4e3a\u5b9c\u3002"}, {"label": "\u7231\u597d", "text": "\u732e\u8840\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u732e\u8840\u4e3a\u5409\u3002"}, {"label": "\u996e\u98df", "text": "\u591a\u5403\u852c\u83dc\u4e3a\u5409\uff0c\u9700\u63a7\u5236\u8089\u98df\u6444\u5165\u91cf\u3002", "line": "\u996e\u98df\uff1a\u591a\u5403\u852c\u83dc\u4e3a\u5409\uff0c\u9700\u63a7\u5236\u8089\u98df\u6444\u5165\u91cf\u3002"}, {"label": "\u4eba\u7f18", "text": "\u65e0\u9700\u4ea4\u53cb\u3002", "line": "\u4eba\u7f18\uff1a\u65e0\u9700\u4ea4\u53cb\u3002"}, {"label": "\u604b\u7231", "text": "\u602a\u9ebb\u70e6\u7684\u3002", "line": "\u604b\u7231\uff1a\u602a\u9ebb\u70e6\u7684\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u53cd\u6b63\u6ca1\u5904\u82b1\u3002", "line": "\u8d22\u8fd0\uff1a\u53cd\u6b63\u6ca1\u5904\u82b1\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (118, '豫母都日狭美', '末大吉', '穷追到天涯海角的黄泉丑女', '令目标无处可逃程度的能力', '["\u6070\u5982\u60b2\u6b22", "\u6c38\u751f\u8426\u7ed5\uff0c", "\u5165\u6211\u773c\u8005", "\u65e0\u8def\u53ef\u9003\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6301\u4e4b\u4ee5\u6052\u53ef\u4ea4\u597d\u8fd0\u3002\u534a\u9014\u800c\u5e9f\u4e00\u4e8b\u65e0\u6210\u3002", "line": "\u8fd0\u52bf\uff1a\u6301\u4e4b\u4ee5\u6052\u53ef\u4ea4\u597d\u8fd0\u3002\u534a\u9014\u800c\u5e9f\u4e00\u4e8b\u65e0\u6210\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u957f\u671f\u575a\u6301\u65b9\u89c1\u6210\u6548\u3002\u4fa6\u63a2\u3001\u8b66\u5bdf\u3001\u5b97\u6559\u5bb6\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u957f\u671f\u575a\u6301\u65b9\u89c1\u6210\u6548\u3002\u4fa6\u63a2\u3001\u8b66\u5bdf\u3001\u5b97\u6559\u5bb6\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u80fd\u591f\u4e13\u5fc3\u5b66\u4e60\u3002\u72af\u7f6a\u5fc3\u7406\u5b66\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u80fd\u591f\u4e13\u5fc3\u5b66\u4e60\u3002\u72af\u7f6a\u5fc3\u7406\u5b66\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8fc7\u5206\u6267\u7740\u7ec8\u81f4\u5931\u8d25\u3002", "line": "\u4ea4\u6613\uff1a\u8fc7\u5206\u6267\u7740\u7ec8\u81f4\u5931\u8d25\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u7cbe\u795e\u6709\u75be\u3002", "line": "\u5065\u5eb7\uff1a\u7cbe\u795e\u6709\u75be\u3002"}, {"label": "\u51fa\u884c", "text": "\u53bb\u5411\u4f55\u5904\u90fd\u65e0\u6cd5\u9003\u79bb\u5de5\u4f5c\u3002", "line": "\u51fa\u884c\uff1a\u53bb\u5411\u4f55\u5904\u90fd\u65e0\u6cd5\u9003\u79bb\u5de5\u4f5c\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u5fc3\u89e6\u72af\u6cd5\u5f8b\u3002", "line": "\u604b\u7231\uff1a\u5f53\u5fc3\u89e6\u72af\u6cd5\u5f8b\u3002"}, {"label": "\u5fc3\u613f", "text": "\u82e5\u4e0d\u654c\u98df\u7269\u8bf1\u60d1\u5219\u5fc3\u613f\u96be\u6210\u3002", "line": "\u5fc3\u613f\uff1a\u82e5\u4e0d\u654c\u98df\u7269\u8bf1\u60d1\u5219\u5fc3\u613f\u96be\u6210\u3002"}, {"label": "\u7231\u597d", "text": "\u767b\u5c71\u3001\u9a6c\u62c9\u677e\u4e3a\u5409\u3002\u8def\u7a0b\u8d8a\u957f\u8d8a\u597d\u3002", "line": "\u7231\u597d\uff1a\u767b\u5c71\u3001\u9a6c\u62c9\u677e\u4e3a\u5409\u3002\u8def\u7a0b\u8d8a\u957f\u8d8a\u597d\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (119, '日白残无', '无', '寂灭为乐的鬼之王', '操纵虚无程度的能力', '["\u4efb\u4f55\u7684\u6323\u624e", "\u90fd\u6beb\u65e0\u610f\u4e49\u3002", "\u865a\u65e0\u9877\u523b\u5c31", "\u5c06\u541e\u566c\u4e00\u5207\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5f97\u4ee5\u6446\u8131\u82e6\u75db\u3001\u5b89\u4e50\u751f\u6d3b\uff0c\u4f46\u4e5f\u4f1a\u5931\u53bb\u6323\u624e\u5411\u4e0a\u7684\u5fc3\u6c14\u3002", "line": "\u8fd0\u52bf\uff1a\u5f97\u4ee5\u6446\u8131\u82e6\u75db\u3001\u5b89\u4e50\u751f\u6d3b\uff0c\u4f46\u4e5f\u4f1a\u5931\u53bb\u6323\u624e\u5411\u4e0a\u7684\u5fc3\u6c14\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u653e\u5f03\u94bb\u7814\u4e50\u5f97\u8f7b\u677e\u3002\u5b66\u8bc6\u81ea\u4f1a\u957f\u8fdb\u3002", "line": "\u5b66\u4e1a\uff1a\u653e\u5f03\u94bb\u7814\u4e50\u5f97\u8f7b\u677e\u3002\u5b66\u8bc6\u81ea\u4f1a\u957f\u8fdb\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u65e0\u9700\u6302\u5fc3\uff0c\u5c3d\u7ba1\u4f11\u606f\u3002\u50e7\u4fa3\u548c\u81ea\u7531\u804c\u4e1a\u8005\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u65e0\u9700\u6302\u5fc3\uff0c\u5c3d\u7ba1\u4f11\u606f\u3002\u50e7\u4fa3\u548c\u81ea\u7531\u804c\u4e1a\u8005\u4e3a\u5409\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5185\u5fc3\u5907\u611f\u7a7a\u865a\u3002\u75be\u75c5\u53ef\u6108\u3002", "line": "\u5065\u5eb7\uff1a\u5185\u5fc3\u5907\u611f\u7a7a\u865a\u3002\u75be\u75c5\u53ef\u6108\u3002"}], [{"label": "\u51fa\u884c", "text": "\u9700\u56de\u907f\u81ea\u6740\u5723\u5730\u3002\u9664\u6b64\u4e4b\u5916\u884c\u8d70\u56db\u65b9\u7686\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u9700\u56de\u907f\u81ea\u6740\u5723\u5730\u3002\u9664\u6b64\u4e4b\u5916\u884c\u8d70\u56db\u65b9\u7686\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u906d\u4eba\u5355\u604b\u3002", "line": "\u604b\u7231\uff1a\u906d\u4eba\u5355\u604b\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5c45\u65e0\u5b9a\u6240\u53c8\u4f55\u59a8\u3002", "line": "\u4f4f\u6240\uff1a\u5c45\u65e0\u5b9a\u6240\u53c8\u4f55\u59a8\u3002"}, {"label": "\u4eba\u7f18", "text": "\u51ed\u501f\u9886\u8896\u9b45\u529b\u5438\u5f15\u4f17\u4eba\u8ffd\u968f\u3002", "line": "\u4eba\u7f18\uff1a\u51ed\u501f\u9886\u8896\u9b45\u529b\u5438\u5f15\u4f17\u4eba\u8ffd\u968f\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u4e3b\u52a8\u6563\u8d22\u3002", "line": "\u8d22\u8fd0\uff1a\u4e3b\u52a8\u6563\u8d22\u3002"}, {"label": "\u5bfb\u7269", "text": "\u8eab\u5bb6\u5c3d\u5931\u3002", "line": "\u5bfb\u7269\uff1a\u8eab\u5bb6\u5c3d\u5931\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u5750\u7985\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u5750\u7985\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (120, '绵月丰姬', '大吉', '视两极为一体的月之民', '连接山海程度的能力', '["\u8981\u95ee\u4eba\u751f\u4e2d", "\u4ec0\u4e48\u6700\u53ef\u8d35\uff1f", "\u90a3\u81ea\u7136\u8981\u6570", "\u5c71\u73cd\u4e0e\u6d77\u5473\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u81ea\u7136\u7737\u987e\uff0c\u5f3a\u8fd0\u508d\u8eab\u3002\u80fd\u53d1\u6325\u51fa\u8d85\u5e38\u5b9e\u529b\u3002", "line": "\u8fd0\u52bf\uff1a\u81ea\u7136\u7737\u987e\uff0c\u5f3a\u8fd0\u508d\u8eab\u3002\u80fd\u53d1\u6325\u51fa\u8d85\u5e38\u5b9e\u529b\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u524d\u5f80\u6d77\u8fb9\u6216\u5c71\u95f4\u3002\u4f9d\u5c71\u4e34\u6d77\u4e4b\u5730\u4e3a\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u524d\u5f80\u6d77\u8fb9\u6216\u5c71\u95f4\u3002\u4f9d\u5c71\u4e34\u6d77\u4e4b\u5730\u4e3a\u5927\u5409\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4eb2\u8fd1\u81ea\u7136\u7684\u804c\u573a\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4eb2\u8fd1\u81ea\u7136\u7684\u804c\u573a\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u65e0\u9700\u52aa\u529b\u4ea6\u80fd\u6587\u7406\u7686\u901a\u3002", "line": "\u5b66\u4e1a\uff1a\u65e0\u9700\u52aa\u529b\u4ea6\u80fd\u6587\u7406\u7686\u901a\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u4e0e\u538b\u529b\u65e0\u7f18\u3002", "line": "\u5065\u5eb7\uff1a\u4e0e\u538b\u529b\u65e0\u7f18\u3002"}, {"label": "\u4f4f\u6240", "text": "\u4e45\u5c45\u5219\u5b89\u3002", "line": "\u4f4f\u6240\uff1a\u4e45\u5c45\u5219\u5b89\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5c71\u95f4\u5931\u7269\u4f1a\u6d41\u5165\u6d77\u4e2d\u3002", "line": "\u5bfb\u7269\uff1a\u5c71\u95f4\u5931\u7269\u4f1a\u6d41\u5165\u6d77\u4e2d\u3002"}, {"label": "\u5bb6\u5ead", "text": "\u7565\u6709\u7ea0\u7eb7\uff0c\u4f46\u603b\u80fd\u548c\u5e73\u89e3\u51b3\u3002", "line": "\u5bb6\u5ead\uff1a\u7565\u6709\u7ea0\u7eb7\uff0c\u4f46\u603b\u80fd\u548c\u5e73\u89e3\u51b3\u3002"}, {"label": "\u7231\u597d", "text": "\u51e1\u4e8b\u7686\u80fd\u4e50\u5728\u5176\u4e2d\u3002\u5782\u9493\u5c24\u4f73\u3002", "line": "\u7231\u597d\uff1a\u51e1\u4e8b\u7686\u80fd\u4e50\u5728\u5176\u4e2d\u3002\u5782\u9493\u5c24\u4f73\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (121, '绵月依姬', '中吉', '降八百万神灵于身的月之民', '能够召唤神灵程度的能力', '["\u4eba\u751f\u8981\u7545\u610f\uff0c", "\u6b64\u4e8b\u5f88\u5173\u952e\uff1a", "\u6c42\u52a9\u4e8e\u4ed6\u4eba\uff0c", "\u4e0d\u5931\u662f\u826f\u7b56\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u7eb5\u9047\u96be\u5173\uff0c\u4ea6\u53ef\u5728\u516b\u65b9\u652f\u63f4\u4e4b\u4e0b\u5e73\u5b89\u6e21\u8fc7\u3002", "line": "\u8fd0\u52bf\uff1a\u7eb5\u9047\u96be\u5173\uff0c\u4ea6\u53ef\u5728\u516b\u65b9\u652f\u63f4\u4e4b\u4e0b\u5e73\u5b89\u6e21\u8fc7\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5728\u4ed6\u4eba\u7684\u5e2e\u52a9\u4e0b\u65e0\u5f80\u4e0d\u5229\u3002\u5207\u83ab\u4f9d\u8d56\u4e0a\u53f8\u3002", "line": "\u5de5\u4f5c\uff1a\u5728\u4ed6\u4eba\u7684\u5e2e\u52a9\u4e0b\u65e0\u5f80\u4e0d\u5229\u3002\u5207\u83ab\u4f9d\u8d56\u4e0a\u53f8\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e34\u8003\u65f6\u5411\u795e\u7948\u7977\u4e3a\u5409\u3002\u4f46\u5b8c\u5168\u4f9d\u8d56\u795e\u529b\u65e0\u6cd5\u5f97\u5230\u771f\u624d\u5b9e\u5b66\u3002", "line": "\u5b66\u4e1a\uff1a\u4e34\u8003\u65f6\u5411\u795e\u7948\u7977\u4e3a\u5409\u3002\u4f46\u5b8c\u5168\u4f9d\u8d56\u795e\u529b\u65e0\u6cd5\u5f97\u5230\u771f\u624d\u5b9e\u5b66\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u907f\u514d\u8fc7\u5ea6\u52b3\u795e\u8d39\u529b\u3002", "line": "\u5065\u5eb7\uff1a\u907f\u514d\u8fc7\u5ea6\u52b3\u795e\u8d39\u529b\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u524d\u5f80\u6d77\u8fb9\u3002\u52a1\u5fc5\u6cbf\u9014\u53c2\u62dc\u795e\u793e\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u524d\u5f80\u6d77\u8fb9\u3002\u52a1\u5fc5\u6cbf\u9014\u53c2\u62dc\u795e\u793e\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5207\u8bb0\u795e\u9f9b\u5e38\u4fdd\u6d01\u51c0\u3002", "line": "\u4f4f\u6240\uff1a\u5207\u8bb0\u795e\u9f9b\u5e38\u4fdd\u6d01\u51c0\u3002"}, {"label": "\u59fb\u7f18", "text": "\u6709\u671b\u6816\u4e0a\u9ad8\u679d\u3002", "line": "\u59fb\u7f18\uff1a\u6709\u671b\u6816\u4e0a\u9ad8\u679d\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u957f\u4e8e\u6bd4\u8bd5\u3002\u5de7\u7528\u8ba1\u7b56\u4fbf\u53ef\u6240\u5411\u62ab\u9761\u3002\u5207\u83ab\u9ad8\u4f30\u81ea\u8eab\u5b9e\u529b\u3002", "line": "\u6bd4\u8bd5\uff1a\u957f\u4e8e\u6bd4\u8bd5\u3002\u5de7\u7528\u8ba1\u7b56\u4fbf\u53ef\u6240\u5411\u62ab\u9761\u3002\u5207\u83ab\u9ad8\u4f30\u81ea\u8eab\u5b9e\u529b\u3002"}, {"label": "\u7231\u597d", "text": "\u6b66\u672f\u4e3a\u5b9c\u3002", "line": "\u7231\u597d\uff1a\u6b66\u672f\u4e3a\u5b9c\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (122, '本居小铃', '中吉', '识文解意的铃奈庵女儿', '能够理解任何文字程度的能力', '["\u770b\u4e86\u4e0d\u5c11\u4e66\uff1f", "\u8fd9\u8bdd\u53ef\u4e0d\u5bf9\u3002", "\u4e66\u5e94\u5f53\u8981\u7528", "\u5fc3\u7075\u53bb\u611f\u53d7\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5bf9\u4e16\u754c\u7406\u89e3\u52a0\u6df1\u3002\u662f\u5409\u662f\u51f6\u96be\u4ee5\u9884\u6599\u3002", "line": "\u8fd0\u52bf\uff1a\u5bf9\u4e16\u754c\u7406\u89e3\u52a0\u6df1\u3002\u662f\u5409\u662f\u51f6\u96be\u4ee5\u9884\u6599\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u8fd1\u4e4e\u5168\u9762\u63d0\u5347\u3002\u8bed\u6587\u3001\u5916\u8bed\u4e3a\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u8fd1\u4e4e\u5168\u9762\u63d0\u5347\u3002\u8bed\u6587\u3001\u5916\u8bed\u4e3a\u5927\u5409\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4ece\u4e8b\u4e66\u7c4d\u76f8\u5173\u884c\u4e1a\u5c06\u4e00\u5e06\u98ce\u987a\u3002\u5199\u4f5c\u3001\u7f16\u8f91\u3001\u51fa\u7248\u884c\u4e1a\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4ece\u4e8b\u4e66\u7c4d\u76f8\u5173\u884c\u4e1a\u5c06\u4e00\u5e06\u98ce\u987a\u3002\u5199\u4f5c\u3001\u7f16\u8f91\u3001\u51fa\u7248\u884c\u4e1a\u4e3a\u5927\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u62e5\u4e66\u767e\u57ce\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u62e5\u4e66\u767e\u57ce\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u6240\u884c\u4e4b\u5904\u7686\u4e50\u571f\u3002\u5f02\u90a6\u5c24\u5409\u3002", "line": "\u51fa\u884c\uff1a\u6240\u884c\u4e4b\u5904\u7686\u4e50\u571f\u3002\u5f02\u90a6\u5c24\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5e76\u65e0\u6587\u5b66\u521b\u4f5c\u4e4b\u8f70\u70c8\uff0c\u5374\u4ea6\u6709\u5e73\u6de1\u4e4b\u7f8e\u3002", "line": "\u604b\u7231\uff1a\u5e76\u65e0\u6587\u5b66\u521b\u4f5c\u4e4b\u8f70\u70c8\uff0c\u5374\u4ea6\u6709\u5e73\u6de1\u4e4b\u7f8e\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5fc3\u5f31\u4f53\u865a\uff0c\u591a\u6101\u591a\u75c5\u3002", "line": "\u5065\u5eb7\uff1a\u5fc3\u5f31\u4f53\u865a\uff0c\u591a\u6101\u591a\u75c5\u3002"}, {"label": "\u5bfb\u7269", "text": "\u867d\u5728\u5bb6\u4e2d\uff0c\u904d\u5bfb\u4e0d\u89c1\u3002", "line": "\u5bfb\u7269\uff1a\u867d\u5728\u5bb6\u4e2d\uff0c\u904d\u5bfb\u4e0d\u89c1\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u8bfb\u4e66\uff0c\u5c0f\u8bf4\u521b\u4f5c\u4ea6\u5584\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u8bfb\u4e66\uff0c\u5c0f\u8bf4\u521b\u4f5c\u4ea6\u5584\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (123, '奥野田美宵', '吉', '让人举杯不停的鲵吞亭店花', '操纵酒醉者记忆程度的能力', '["\u6709\u4ec0\u4e48\u70e6\u607c\uff0c", "\u5c3d\u7ba1\u503e\u8bc9\u5427\u3002", "\u4fd7\u8bdd\u8bf4\u5f97\u597d\uff0c", "\u9152\u540e\u5410\u771f\u8a00\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8bb0\u5fc6\u867d\u7565\u6709\u6df7\u4e71\uff0c\u4f46\u6cf0\u7136\u5904\u4e4b\u4fbf\u81ea\u80fd\u8d70\u8fd0\u3002", "line": "\u8fd0\u52bf\uff1a\u8bb0\u5fc6\u867d\u7565\u6709\u6df7\u4e71\uff0c\u4f46\u6cf0\u7136\u5904\u4e4b\u4fbf\u81ea\u80fd\u8d70\u8fd0\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0e\u9152\u76f8\u5173\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u9152\u94fa\u3001\u9910\u996e\u5e97\u3001\u9152\u5e84\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0e\u9152\u76f8\u5173\u7684\u5de5\u4f5c\u4e3a\u5409\u3002\u9152\u94fa\u3001\u9910\u996e\u5e97\u3001\u9152\u5e84\u4e3a\u5927\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6613\u9057\u5fd8\u5173\u952e\u4e4b\u4e8b\u3002", "line": "\u5b66\u4e1a\uff1a\u6613\u9057\u5fd8\u5173\u952e\u4e4b\u4e8b\u3002"}, {"label": "\u5065\u5eb7", "text": "\u9152\u4e43\u767e\u836f\u4e4b\u957f\u3002\u4e00\u676f\u4e0b\u809a\u5fe7\u6101\u5c3d\u5fd8\u3002", "line": "\u5065\u5eb7\uff1a\u9152\u4e43\u767e\u836f\u4e4b\u957f\u3002\u4e00\u676f\u4e0b\u809a\u5fe7\u6101\u5c3d\u5fd8\u3002"}], [{"label": "\u51fa\u884c", "text": "\u6089\u5fc3\u7528\u9910\u54c1\u9152\uff0c\u5219\u884c\u8d70\u56db\u65b9\u7686\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u6089\u5fc3\u7528\u9910\u54c1\u9152\uff0c\u5219\u884c\u8d70\u56db\u65b9\u7686\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u5438\u5f15\u5e74\u957f\u8005\u8ffd\u6c42\u3002", "line": "\u604b\u7231\uff1a\u5438\u5f15\u5e74\u957f\u8005\u8ffd\u6c42\u3002"}, {"label": "\u5bfb\u7269", "text": "\u5931\u7269\u9891\u53d1\u3002\u57fa\u672c\u627e\u4e0d\u56de\u6765\u3002", "line": "\u5bfb\u7269\uff1a\u5931\u7269\u9891\u53d1\u3002\u57fa\u672c\u627e\u4e0d\u56de\u6765\u3002"}, {"label": "\u4e89\u7aef", "text": "\u628a\u9152\u8a00\u548c\u3002", "line": "\u4e89\u7aef\uff1a\u628a\u9152\u8a00\u548c\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u54c1\u9152\u3002\u4ee5\u5e7f\u8bc6\u767e\u9152\u4e3a\u5409\u3002\u53a8\u827a\u4ea6\u4f1a\u540c\u6b65\u589e\u8fdb\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u54c1\u9152\u3002\u4ee5\u5e7f\u8bc6\u767e\u9152\u4e3a\u5409\u3002\u53a8\u827a\u4ea6\u4f1a\u540c\u6b65\u589e\u8fdb\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (124, '宫出口瑞灵', '【大大凶】', '人厌妖嫌的反狱怨灵', '夺取全身心程度的能力', '["\u51e1\u4eba\u7686\u4e0d\u77e5\uff0c", "\u552f\u6709\u6028\u7075\u6653\u3002", "\u6028\u4e43\u7acb\u8eab\u672c\uff0c", "\u6c38\u65e5\u4e0d\u53ef\u6d88\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u8fc7\u5206\u5ac9\u5992\u4ed6\u4eba\uff0c\u5f71\u54cd\u73b0\u5b9e\u751f\u6d3b\u3002\u6c89\u6ca6\u5176\u4e2d\u96be\u4ee5\u6446\u8131\u3002", "line": "\u8fd0\u52bf\uff1a\u8fc7\u5206\u5ac9\u5992\u4ed6\u4eba\uff0c\u5f71\u54cd\u73b0\u5b9e\u751f\u6d3b\u3002\u6c89\u6ca6\u5176\u4e2d\u96be\u4ee5\u6446\u8131\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u82e5\u80fd\u76f4\u9762\u5931\u8d25\u6216\u53ef\u7edd\u5730\u7ffb\u8eab\u3002\u9700\u8981\u6f14\u6280\u7684\u5de5\u4f5c\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u82e5\u80fd\u76f4\u9762\u5931\u8d25\u6216\u53ef\u7edd\u5730\u7ffb\u8eab\u3002\u9700\u8981\u6f14\u6280\u7684\u5de5\u4f5c\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6ce8\u610f\u529b\u6563\u6f2b\uff0c\u65e0\u6cd5\u4e13\u6ce8\u5b66\u4e60\u3002", "line": "\u5b66\u4e1a\uff1a\u6ce8\u610f\u529b\u6563\u6f2b\uff0c\u65e0\u6cd5\u4e13\u6ce8\u5b66\u4e60\u3002"}, {"label": "\u5065\u5eb7", "text": "\u6574\u4f53\u6076\u5316\u3002", "line": "\u5065\u5eb7\uff1a\u6574\u4f53\u6076\u5316\u3002"}], [{"label": "\u4f4f\u6240", "text": "\u5bb6\u4e2d\u538b\u6291\uff0c\u5750\u5367\u4e0d\u5b81\u3002\u5b9c\u8fc1\u5c45\u5730\u4e0b\u3002", "line": "\u4f4f\u6240\uff1a\u5bb6\u4e2d\u538b\u6291\uff0c\u5750\u5367\u4e0d\u5b81\u3002\u5b9c\u8fc1\u5c45\u5730\u4e0b\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u524d\u5f80\u91ca\u653e\u538b\u529b\u4e4b\u5730\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u524d\u5f80\u91ca\u653e\u538b\u529b\u4e4b\u5730\u3002"}, {"label": "\u4eba\u7f18", "text": "\u88ab\u4eba\u907f\u4e4b\u4e0d\u53ca\u3002", "line": "\u4eba\u7f18\uff1a\u88ab\u4eba\u907f\u4e4b\u4e0d\u53ca\u3002"}, {"label": "\u604b\u7231", "text": "\u6781\u5c0f\u6982\u7387\u89c5\u5f97\u77e5\u5fc3\u826f\u4f34\u3002", "line": "\u604b\u7231\uff1a\u6781\u5c0f\u6982\u7387\u89c5\u5f97\u77e5\u5fc3\u826f\u4f34\u3002"}, {"label": "\u5931\u7269", "text": "\u4f1a\u5931\u53bb\u76ee\u6807\u3002", "line": "\u5931\u7269\uff1a\u4f1a\u5931\u53bb\u76ee\u6807\u3002"}, {"label": "\u7231\u597d", "text": "\u89c2\u5bdf\u4eba\u7c7b\u3002", "line": "\u7231\u597d\uff1a\u89c2\u5bdf\u4eba\u7c7b\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (125, '森近霖之助', '小吉', '玩转外界百货的香霖堂店主', '判别物品名字和用途程度的能力', '["\u662f\u4ece\u4f55\u65f6\u8d77", "\u5916\u754c\u7684\u4eba\u7c7b", "\u53d8\u5f97\u8bfb\u4e0d\u8fdb", "\u8bf4\u660e\u4e66\u4e86\u5462\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e5\u5e38\u751f\u6d3b\u4e2d\u81ea\u6709\u65b0\u53d1\u73b0\u3002\u5bf9\u5468\u906d\u7684\u89c2\u5bdf\u4e0e\u8fd0\u6c14\u606f\u606f\u76f8\u5173\u3002", "line": "\u8fd0\u52bf\uff1a\u65e5\u5e38\u751f\u6d3b\u4e2d\u81ea\u6709\u65b0\u53d1\u73b0\u3002\u5bf9\u5468\u906d\u7684\u89c2\u5bdf\u4e0e\u8fd0\u6c14\u606f\u606f\u76f8\u5173\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0e\u7269\u4ef6\u6253\u4ea4\u9053\u7684\u81ea\u7531\u804c\u4e1a\u4e3a\u5409\u3002\u5c0f\u5356\u90e8\u3001\u4f5c\u5bb6\u3001\u9274\u5b9a\u5e08\u4e3a\u5927\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0e\u7269\u4ef6\u6253\u4ea4\u9053\u7684\u81ea\u7531\u804c\u4e1a\u4e3a\u5409\u3002\u5c0f\u5356\u90e8\u3001\u4f5c\u5bb6\u3001\u9274\u5b9a\u5e08\u4e3a\u5927\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u4e2d\u89c4\u4e2d\u77e9\u3002", "line": "\u4ea4\u6613\uff1a\u4e2d\u89c4\u4e2d\u77e9\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5174\u8da3\u6240\u5728\u5219\u5b66\u4e60\u81ea\u4f1a\u987a\u5229\u3002\u6587\u79d1\u6574\u4f53\u4e3a\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u5174\u8da3\u6240\u5728\u5219\u5b66\u4e60\u81ea\u4f1a\u987a\u5229\u3002\u6587\u79d1\u6574\u4f53\u4e3a\u5409\u3002"}], [{"label": "\u51fa\u884c", "text": "\u535a\u7269\u9986\u4e3a\u5927\u5409\u3002", "line": "\u51fa\u884c\uff1a\u535a\u7269\u9986\u4e3a\u5927\u5409\u3002"}, {"label": "\u5931\u7269", "text": "\u5e9f\u54c1\u4e4b\u4e2d\u53ef\u6dd8\u5f97\u5b9d\u85cf\u3002", "line": "\u5931\u7269\uff1a\u5e9f\u54c1\u4e4b\u4e2d\u53ef\u6dd8\u5f97\u5b9d\u85cf\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5e38\u7528\u5065\u8eab\u5668\u6750\u5219\u4e3a\u5409\u3002", "line": "\u5065\u5eb7\uff1a\u5e38\u7528\u5065\u8eab\u5668\u6750\u5219\u4e3a\u5409\u3002"}, {"label": "\u604b\u7231", "text": "\u4e0d\u5982\u7269\u4ef6\u5f97\u5fc3\u5e94\u624b\u3002", "line": "\u604b\u7231\uff1a\u4e0d\u5982\u7269\u4ef6\u5f97\u5fc3\u5e94\u624b\u3002"}, {"label": "\u7231\u597d", "text": "\u65e0\u8bba\u65b0\u54c1\u65e7\u7269\uff0c\u6446\u5f04\u7269\u4ef6\u4fbf\u53ef\u5f97\u5230\u4e50\u8da3\u3002", "line": "\u7231\u597d\uff1a\u65e0\u8bba\u65b0\u54c1\u65e7\u7269\uff0c\u6446\u5f04\u7269\u4ef6\u4fbf\u53ef\u5f97\u5230\u4e50\u8da3\u3002"}, {"label": "\u7269\u4ef6", "text": "\u6c89\u8ff7\u624b\u673a\u4f1a\u4e0e\u5e78\u8fd0\u5931\u4e4b\u4ea4\u81c2\u3002", "line": "\u7269\u4ef6\uff1a\u6c89\u8ff7\u624b\u673a\u4f1a\u4e0e\u5e78\u8fd0\u5931\u4e4b\u4ea4\u81c2\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (126, '稗田阿求', '吉', '记录幻想乡历史的书记员', '过目不忘程度的能力', '["\u773c\u524d\u7684\u4e16\u754c\uff0c", "\u662f\u5982\u6b64\u591a\u5f69\u3002", "\u8fd9\u6837\u7684\u4e00\u5207\uff0c", "\u6211\u600e\u80fd\u5fd8\u6000\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5b66\u8bc6\u5c06\u5927\u6709\u7528\u6b66\u4e4b\u5730\uff0c \u4f46\u4f1a\u56e0\u62d8\u6ce5\u7ec6\u679d\u672b\u8282\u800c\u505c\u6ede\u4e0d\u524d\u3002", "line": "\u8fd0\u52bf\uff1a\u5b66\u8bc6\u5c06\u5927\u6709\u7528\u6b66\u4e4b\u5730\uff0c \u4f46\u4f1a\u56e0\u62d8\u6ce5\u7ec6\u679d\u672b\u8282\u800c\u505c\u6ede\u4e0d\u524d\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5b66\u4e60\u6548\u7387\u6781\u9ad8\u3002\u9700\u80cc\u8bf5\u7684\u79d1\u76ee\u7686\u4e3a\u5927\u5409\u3002", "line": "\u5b66\u4e1a\uff1a\u5b66\u4e60\u6548\u7387\u6781\u9ad8\u3002\u9700\u80cc\u8bf5\u7684\u79d1\u76ee\u7686\u4e3a\u5927\u5409\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4ef0\u4ed7\u8bb0\u5fc6\u529b\u7684\u5de5\u4f5c\u4e3a\u5b9c\u3002\u521b\u4f5c\u5de5\u4f5c\u7686\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u4ef0\u4ed7\u8bb0\u5fc6\u529b\u7684\u5de5\u4f5c\u4e3a\u5b9c\u3002\u521b\u4f5c\u5de5\u4f5c\u7686\u4e3a\u5409\u3002"}, {"label": "\u4f4f\u6240", "text": "\u548c\u98ce\u4e3a\u5b9c\u3002", "line": "\u4f4f\u6240\uff1a\u548c\u98ce\u4e3a\u5b9c\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u4f53\u5f31\u591a\u75c5\u3002\u7a0d\u6709\u4e0d\u614e\u4fbf\u6709\u75c5\u5371\u4e4b\u865e\u3002\u52a1\u5fc5\u5f53\u5fc3\u3002", "line": "\u5065\u5eb7\uff1a\u4f53\u5f31\u591a\u75c5\u3002\u7a0d\u6709\u4e0d\u614e\u4fbf\u6709\u75c5\u5371\u4e4b\u865e\u3002\u52a1\u5fc5\u5f53\u5fc3\u3002"}, {"label": "\u51fa\u884c", "text": "\u95ed\u95e8\u4e0d\u51fa\u4e3a\u5999\u3002\u5b9c\u5c31\u8fd1\u9020\u8bbf\u6e29\u6cc9\u3002", "line": "\u51fa\u884c\uff1a\u95ed\u95e8\u4e0d\u51fa\u4e3a\u5999\u3002\u5b9c\u5c31\u8fd1\u9020\u8bbf\u6e29\u6cc9\u3002"}, {"label": "\u604b\u7231", "text": "\u666e\u666e\u901a\u901a\u3002", "line": "\u604b\u7231\uff1a\u666e\u666e\u901a\u901a\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5e7f\u4ea4\u4eb2\u670b\u3002", "line": "\u4eba\u7f18\uff1a\u5e7f\u4ea4\u4eb2\u670b\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u65e0\u9700\u7528\u773c\u4e4b\u4e8b\u3002\u97f3\u4e50\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u65e0\u9700\u7528\u773c\u4e4b\u4e8b\u3002\u97f3\u4e50\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (127, '雾雨魔理沙', '末吉', '普通即王道的魔法使', '使用魔法程度的能力', '["\u6982\u7387\u518d\u5fae\u5c0f\uff0c", "\u98ce\u9669\u603b\u4f1a\u6765\u3002", "\u542c\u5929\u7531\u547d\u4fbf", "\u662f\u5750\u4ee5\u5f85\u6bd9\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u4e4f\u5473\u800c\u5b89\u7a33\u7684\u751f\u6d3b\u65e5\u590d\u4e00\u65e5\u3002\u603b\u6709\u4e00\u5929\u4f1a\u53d1\u89c9\u5b89\u7a33\u5c31\u662f\u6700\u5927\u7684\u5e78\u798f\u3002", "line": "\u8fd0\u52bf\uff1a\u4e4f\u5473\u800c\u5b89\u7a33\u7684\u751f\u6d3b\u65e5\u590d\u4e00\u65e5\u3002\u603b\u6709\u4e00\u5929\u4f1a\u53d1\u89c9\u5b89\u7a33\u5c31\u662f\u6700\u5927\u7684\u5e78\u798f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u53ea\u8981\u575a\u6301\u4e0d\u61c8\uff0c\u4efb\u4f55\u79d1\u76ee\u90fd\u80fd\u5b66\u6709\u6240\u6210\u3002", "line": "\u5b66\u4e1a\uff1a\u53ea\u8981\u575a\u6301\u4e0d\u61c8\uff0c\u4efb\u4f55\u79d1\u76ee\u90fd\u80fd\u5b66\u6709\u6240\u6210\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5b9c\u7a33\u5b9a\u3002\u4efb\u804c\u4f01\u4e1a\u3001\u653f\u5e9c\u4e3a\u5409\u3002\u52a1\u5fc5\u91d1\u76c6\u6d17\u624b\u3002", "line": "\u5de5\u4f5c\uff1a\u5b9c\u7a33\u5b9a\u3002\u4efb\u804c\u4f01\u4e1a\u3001\u653f\u5e9c\u4e3a\u5409\u3002\u52a1\u5fc5\u91d1\u76c6\u6d17\u624b\u3002"}, {"label": "\u51fa\u884c", "text": "\u4eb2\u8fd1\u81ea\u7136\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u4eb2\u8fd1\u81ea\u7136\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5f53\u5fc3\u8611\u83c7\u3002", "line": "\u5065\u5eb7\uff1a\u5f53\u5fc3\u8611\u83c7\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e0e\u5fd7\u4e0d\u540c\u8005\u6709\u7f18\u3002", "line": "\u4eba\u7f18\uff1a\u4e0e\u5fd7\u4e0d\u540c\u8005\u6709\u7f18\u3002"}, {"label": "\u604b\u7231", "text": "\u826f\u597d\u706b\u82b1\u3002", "line": "\u604b\u7231\uff1a\u826f\u597d\u706b\u82b1\u3002"}, {"label": "\u5931\u7269", "text": "\u53ef\u5728\u5bb6\u4e2d\u5bfb\u56de\u3002", "line": "\u5931\u7269\uff1a\u53ef\u5728\u5bb6\u4e2d\u5bfb\u56de\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4f1a\u6210\u4e3a\u4ef2\u88c1\u8005\u3002", "line": "\u4e89\u7aef\uff1a\u4f1a\u6210\u4e3a\u4ef2\u88c1\u8005\u3002"}, {"label": "\u7231\u597d", "text": "\u6d77\u91cf\u6536\u85cf\u4e2d\u81ea\u6709\u65b0\u53d1\u73b0\u3002", "line": "\u7231\u597d\uff1a\u6d77\u91cf\u6536\u85cf\u4e2d\u81ea\u6709\u65b0\u53d1\u73b0\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5173\u952e\u65f6\u523b\u51fa\u624b\u85cf\u54c1\u4e3a\u5409\u3002", "line": "\u8d22\u8fd0\uff1a\u5173\u952e\u65f6\u523b\u51fa\u624b\u85cf\u54c1\u4e3a\u5409\u3002"}]]'::jsonb);
INSERT INTO public.omikuji_entries (fortune_number, character_name, fortune_type, subtitle, ability, poem_lines, note_blocks) VALUES (128, '博丽灵梦', '超大吉', '传达神谕的巫女', '飞翔于空中程度的能力', '["\u7adf\u80fd\u62bd\u5230\u6211", "\u770b\u6765\u4f60\u5df2\u7ecf", "\u53c2\u900f\u4e86\u5e78\u8fd0", "\u80cc\u540e\u7684\u7384\u673a\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6700\u5f3a\u8fd0\u52bf\uff0c\u5e78\u8fd0\u4e0d\u8bf7\u81ea\u6765\u3002\u65e0\u8bba\u505a\u4ec0\u4e48\u90fd\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u8fd0\u52bf\uff1a\u6700\u5f3a\u8fd0\u52bf\uff0c\u5e78\u8fd0\u4e0d\u8bf7\u81ea\u6765\u3002\u65e0\u8bba\u505a\u4ec0\u4e48\u90fd\u4e00\u5e06\u98ce\u987a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u4e0d\u5fc5\u8d39\u5fc3\u5b66\u4e60\uff0c\u603b\u4e4b\u4f1a\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u5b66\u4e1a\uff1a\u4e0d\u5fc5\u8d39\u5fc3\u5b66\u4e60\uff0c\u603b\u4e4b\u4f1a\u4e00\u5e06\u98ce\u987a\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5373\u4fbf\u6709\u5927\u89c4\u6a21\u5f02\u53d8\u603b\u4e4b\u4e5f\u80fd\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u5de5\u4f5c\uff1a\u5373\u4fbf\u6709\u5927\u89c4\u6a21\u5f02\u53d8\u603b\u4e4b\u4e5f\u80fd\u4e00\u5e06\u98ce\u987a\u3002"}, {"label": "\u4ea4\u6613", "text": "\u867d\u7136\u8d5a\u4e0d\u5230\u94b1\u4f46\u603b\u4e4b\u4f1a\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u4ea4\u6613\uff1a\u867d\u7136\u8d5a\u4e0d\u5230\u94b1\u4f46\u603b\u4e4b\u4f1a\u4e00\u5e06\u98ce\u987a\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5c24\u5b9c\u7a7a\u4e2d\u65c5\u884c\u3002", "line": "\u51fa\u884c\uff1a\u5c24\u5b9c\u7a7a\u4e2d\u65c5\u884c\u3002"}, {"label": "\u6c42\u533b", "text": "\u4fe1\u4ef0\u795e\u660e\u5219\u65e7\u75be\u81ea\u6108\u3002", "line": "\u6c42\u533b\uff1a\u4fe1\u4ef0\u795e\u660e\u5219\u65e7\u75be\u81ea\u6108\u3002"}, {"label": "\u5065\u5eb7", "text": "\u798f\u5bff\u5ef6\u5e74\u3002", "line": "\u5065\u5eb7\uff1a\u798f\u5bff\u5ef6\u5e74\u3002"}, {"label": "\u4f4f\u6240", "text": "\u4e45\u5c45\u4e3a\u5b89\u3002", "line": "\u4f4f\u6240\uff1a\u4e45\u5c45\u4e3a\u5b89\u3002"}, {"label": "\u604b\u7231", "text": "\u8654\u4fe1\u4e4b\u4eba\u4e3a\u5409\u3002", "line": "\u604b\u7231\uff1a\u8654\u4fe1\u4e4b\u4eba\u4e3a\u5409\u3002"}, {"label": "\u65b9\u4f4d", "text": "\u4e1c\u65b9\u4e3a\u5409\u3002", "line": "\u65b9\u4f4d\uff1a\u4e1c\u65b9\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u4e0e\u5947\u4eba\u602a\u5ba2\u6709\u7f18\u3002", "line": "\u4eba\u7f18\uff1a\u4e0e\u5947\u4eba\u602a\u5ba2\u6709\u7f18\u3002"}, {"label": "\u7231\u597d", "text": "\u591a\u65b9\u5c1d\u8bd5\u4fbf\u4f1a\u4e00\u5e06\u98ce\u987a\u3002", "line": "\u7231\u597d\uff1a\u591a\u65b9\u5c1d\u8bd5\u4fbf\u4f1a\u4e00\u5e06\u98ce\u987a\u3002"}]]'::jsonb);
