（姓名不详）', '小吉', '现身于雾中的妖精', '在雾中畅游程度的能力', '["\u6ca1\u6709\u540d\u5b57\u4e5f", "\u6ca1\u5173\u7cfb\u7684\u5566\u3002", "\u8fd9\u53cd\u800c\u663e\u5f97", "\u6211\u66f4\u5389\u5bb3\u561b\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u6ca1\u6709\u503c\u5f97\u79f0\u9053\u7684\u5927\u4e8b\u53d1\u751f\u3002\u65e0\u559c\u4ea6\u65e0\u5fe7\u3002", "line": "\u8fd0\u52bf\uff1a\u6ca1\u6709\u503c\u5f97\u79f0\u9053\u7684\u5927\u4e8b\u53d1\u751f\u3002\u65e0\u559c\u4ea6\u65e0\u5fe7\u3002"}, {"label": "\u4ea4\u6613", "text": "\u5982\u5e38\u8fdb\u884c\u3002\u656c\u754f\u81ea\u7136\u4e3a\u5409\u3002", "line": "\u4ea4\u6613\uff1a\u5982\u5e38\u8fdb\u884c\u3002\u656c\u754f\u81ea\u7136\u4e3a\u5409\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u52ff\u5b58\u671f\u5f85\u3002", "line": "\u5b66\u4e1a\uff1a\u52ff\u5b58\u671f\u5f85\u3002"}, {"label": "\u5065\u5eb7", "text": "\u751f\u9f99\u6d3b\u864e\u3002", "line": "\u5065\u5eb7\uff1a\u751f\u9f99\u6d3b\u864e\u3002"}, {"label": "\u604b\u7231", "text": "\u80fd\u8c08\u4e00\u573a\u5934\u8111\u7a7a\u7a7a\u7684\u604b\u7231\u3002", "line": "\u604b\u7231\uff1a\u80fd\u8c08\u4e00\u573a\u5934\u8111\u7a7a\u7a7a\u7684\u604b\u7231\u3002"}], [{"label": "\u4f4f\u6240", "text": "\u5f53\u5fc3\u9709\u53d8\uff0c\u83ab\u5fd8\u9664\u6e7f\u3002", "line": "\u4f4f\u6240\uff1a\u5f53\u5fc3\u9709\u53d8\uff0c\u83ab\u5fd8\u9664\u6e7f\u3002"}, {"label": "\u51fa\u884c", "text": "\u53bb\u5411\u4f55\u65b9\u90fd\u65e0\u6cd5\u770b\u6e05\u666f\u8272\u3002", "line": "\u51fa\u884c\uff1a\u53bb\u5411\u4f55\u65b9\u90fd\u65e0\u6cd5\u770b\u6e05\u666f\u8272\u3002"}, {"label": "\u4eba\u7f18", "text": "\u65d7\u9f13\u76f8\u5f53\u7684\u4eb2\u53cb\u9f50\u805a\uff0c\u5176\u4e50\u878d\u878d\u3002", "line": "\u4eba\u7f18\uff1a\u65d7\u9f13\u76f8\u5f53\u7684\u4eb2\u53cb\u9f50\u805a\uff0c\u5176\u4e50\u878d\u878d\u3002"}, {"label": "\u5bfb\u7269", "text": "\u4e27\u5931\u59d3\u540d\uff0c\u518d\u96be\u627e\u56de\u3002", "line": "\u5bfb\u7269\uff1a\u4e27\u5931\u59d3\u540d\uff0c\u518d\u96be\u627e\u56de\u3002"}]]'::jsonb);
（姓名不详）', '末吉', '就职于蒙尘图书馆的魔物', '瞬间找出所需书籍程度的能力', '["\u8bf7\u4fdd\u6301\u5b89\u9759\u3002", "\u82e5\u662f\u592a\u5608\u6742\uff0c", "\u4e66\u672c\u7684\u4f4e\u8bed", "\u4fbf\u8981\u542c\u6f0f\u4e86\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u52e4\u6073\u52aa\u529b\u7ec8\u5f52\u5e73\u51e1\uff0c\u4f46\u80fd\u5207\u5b9e\u5f97\u4ee5\u6210\u957f\u3002", "line": "\u8fd0\u52bf\uff1a\u52e4\u6073\u52aa\u529b\u7ec8\u5f52\u5e73\u51e1\uff0c\u4f46\u80fd\u5207\u5b9e\u5f97\u4ee5\u6210\u957f\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u6b63\u662f\u7528\u529f\u65f6\u3002\u6734\u5b9e\u52aa\u529b\u6700\u4e3a\u6709\u6548\u3002", "line": "\u5b66\u4e1a\uff1a\u6b63\u662f\u7528\u529f\u65f6\u3002\u6734\u5b9e\u52aa\u529b\u6700\u4e3a\u6709\u6548\u3002"}, {"label": "\u5c31\u4e1a", "text": "\u6559\u80b2\u884c\u4e1a\u4e3a\u5409\u3002", "line": "\u5c31\u4e1a\uff1a\u6559\u80b2\u884c\u4e1a\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u672a\u96e8\u7ef8\u7f2a\uff0c\u6f5c\u5fc3\u7814\u4e60\u5427\u3002\u5f53\u4e0b\u5e76\u975e\u8c0b\u5229\u4e4b\u65f6\u3002", "line": "\u4ea4\u6613\uff1a\u672a\u96e8\u7ef8\u7f2a\uff0c\u6f5c\u5fc3\u7814\u4e60\u5427\u3002\u5f53\u4e0b\u5e76\u975e\u8c0b\u5229\u4e4b\u65f6\u3002"}], [{"label": "\u604b\u7231", "text": "\u7a0d\u793a\u6bb7\u52e4\u4fbf\u53ef\u6210\u529f\u3002", "line": "\u604b\u7231\uff1a\u7a0d\u793a\u6bb7\u52e4\u4fbf\u53ef\u6210\u529f\u3002"}, {"label": "\u5065\u5eb7", "text": "\u72b6\u51b5\u4e0d\u4f73\u3002\u7f3a\u4e4f\u8fd0\u52a8\u7ec8\u81f4\u6076\u679c\u3002", "line": "\u5065\u5eb7\uff1a\u72b6\u51b5\u4e0d\u4f73\u3002\u7f3a\u4e4f\u8fd0\u52a8\u7ec8\u81f4\u6076\u679c\u3002"}, {"label": "\u664b\u5347", "text": "\u867d\u5f97\u4e0a\u53f8\u9752\u7750\uff0c\u5347\u8fc1\u4ecd\u975e\u6613\u4e8b\u3002", "line": "\u664b\u5347\uff1a\u867d\u5f97\u4e0a\u53f8\u9752\u7750\uff0c\u5347\u8fc1\u4ecd\u975e\u6613\u4e8b\u3002"}, {"label": "\u4eba\u7f18", "text": "\u516b\u9762\u73b2\u73d1\u53cd\u6210\u8d25\u7b14\u3002", "line": "\u4eba\u7f18\uff1a\u516b\u9762\u73b2\u73d1\u53cd\u6210\u8d25\u7b14\u3002"}, {"label": "\u7231\u597d", "text": "\u552f\u6709\u9605\u8bfb\uff0c\u522b\u65e0\u4ed6\u9009\u3002\u51fa\u73b0\u6b7b\u8005\u7684\u6545\u4e8b\u4e3a\u5409\u3002", "line": "\u7231\u597d\uff1a\u552f\u6709\u9605\u8bfb\uff0c\u522b\u65e0\u4ed6\u9009\u3002\u51fa\u73b0\u6b7b\u8005\u7684\u6545\u4e8b\u4e3a\u5409\u3002"}]]'::jsonb);
（白泽）', '大凶', '半为妖兽、半为师长', '创造历史程度的能力', '["\u5386\u53f2\u5e76\u975e\u662f", "\u5ba2\u89c2\u7684\u73b0\u8c61\uff0c", "\u800c\u662f\u7531\u4eba\u7c7b", "\u8be0\u91ca\u6240\u9020\u5c31\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u65e2\u5f80\u79ef\u7d2f\u571f\u5d29\u74e6\u89e3\u3002\u5b9c\u5f00\u521b\u65b0\u7bc7\u3002", "line": "\u8fd0\u52bf\uff1a\u65e2\u5f80\u79ef\u7d2f\u571f\u5d29\u74e6\u89e3\u3002\u5b9c\u5f00\u521b\u65b0\u7bc7\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u5386\u53f2\u6240\u5411\u62ab\u9761\u3002\u4f59\u8005\u52ff\u62b1\u671f\u671b\u3002", "line": "\u5b66\u4e1a\uff1a\u5386\u53f2\u6240\u5411\u62ab\u9761\u3002\u4f59\u8005\u52ff\u62b1\u671f\u671b\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u5b9c\u4ece\u4e8b\u80fd\u98a0\u8986\u5386\u53f2\u7684\u804c\u4e1a\u3002\u53d1\u660e\u5bb6\u3001\u9769\u547d\u5bb6\u3001\u5c0f\u8bf4\u5bb6\u4e3a\u5409\u3002", "line": "\u5de5\u4f5c\uff1a\u5b9c\u4ece\u4e8b\u80fd\u98a0\u8986\u5386\u53f2\u7684\u804c\u4e1a\u3002\u53d1\u660e\u5bb6\u3001\u9769\u547d\u5bb6\u3001\u5c0f\u8bf4\u5bb6\u4e3a\u5409\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u7761\u7720\u4e0d\u8db3\u3002", "line": "\u5065\u5eb7\uff1a\u7761\u7720\u4e0d\u8db3\u3002"}, {"label": "\u51fa\u884c", "text": "\u524d\u4eba\u672a\u81f3\u4e4b\u5730\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u524d\u4eba\u672a\u81f3\u4e4b\u5730\u4e3a\u5409\u3002"}, {"label": "\u4eba\u7f18", "text": "\u65e7\u65e5\u4eba\u8109\u5c3d\u5931\uff0c\u4f46\u5e78\u5f97\u65b0\u4ea4\u3002", "line": "\u4eba\u7f18\uff1a\u65e7\u65e5\u4eba\u8109\u5c3d\u5931\uff0c\u4f46\u5e78\u5f97\u65b0\u4ea4\u3002"}, {"label": "\u4e89\u7aef", "text": "\u4e0d\u65ad\u6492\u64ad\u7eb7\u4e89\u706b\u79cd\u3002", "line": "\u4e89\u7aef\uff1a\u4e0d\u65ad\u6492\u64ad\u7eb7\u4e89\u706b\u79cd\u3002"}, {"label": "\u4f4f\u6240", "text": "\u51b3\u610f\u8fc1\u5f80\u65b0\u5929\u5730\u4ece\u5934\u518d\u6765\uff0c\u5219\u53ef\u8bf8\u4e8b\u987a\u9042\u3002", "line": "\u4f4f\u6240\uff1a\u51b3\u610f\u8fc1\u5f80\u65b0\u5929\u5730\