大吉', '幻想乡最高速天狗记者', '操纵风程度的能力', '["\u94a2\u7b14\u80dc\u624b\u67aa\u3002", "\u7b14\u8eab\u8f7b\u626c\u626c\uff0c", "\u7b14\u4e0b\u7f00\u6587\u7ae0\uff0c", "\u7b14\u5c16\u95ea\u5bd2\u5149\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u5018\u82e5\u7b14\u529b\u591f\u6df1\u3001\u8138\u76ae\u591f\u539a\uff0c\u634f\u9020\u8fd0\u52bf\u4e5f\u4e0d\u5728\u8bdd\u4e0b\u3002", "line": "\u8fd0\u52bf\uff1a\u5018\u82e5\u7b14\u529b\u591f\u6df1\u3001\u8138\u76ae\u591f\u539a\uff0c\u634f\u9020\u8fd0\u52bf\u4e5f\u4e0d\u5728\u8bdd\u4e0b\u3002"}, {"label": "\u4ea4\u6613", "text": "\u84b8\u84b8\u65e5\u4e0a\u3002\u4f46\u751f\u610f\u8d8a\u662f\u6210\u529f\uff0c\u5c31\u8d8a\u62db\u4eba\u4ec7\u89c6\u3002", "line": "\u4ea4\u6613\uff1a\u84b8\u84b8\u65e5\u4e0a\u3002\u4f46\u751f\u610f\u8d8a\u662f\u6210\u529f\uff0c\u5c31\u8d8a\u62db\u4eba\u4ec7\u89c6\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u59a8\u788d\u4ed6\u4eba\u5b66\u4e60\uff0c\u81ea\u8eab\u5012\u662f\u9a6c\u9a6c\u864e\u864e\u3002", "line": "\u5b66\u4e1a\uff1a\u59a8\u788d\u4ed6\u4eba\u5b66\u4e60\uff0c\u81ea\u8eab\u5012\u662f\u9a6c\u9a6c\u864e\u864e\u3002"}, {"label": "\u51fa\u884c", "text": "\u884c\u65c5\u53ef\u589e\u6c14\u8fd0\u3002\u5f53\u6f2b\u6e38\u56db\u65b9\u3002", "line": "\u51fa\u884c\uff1a\u884c\u65c5\u53ef\u589e\u6c14\u8fd0\u3002\u5f53\u6f2b\u6e38\u56db\u65b9\u3002"}], [{"label": "\u75be\u75c5", "text": "\u98ce\u5bd2\u7f20\u8eab\u3002\u4ea6\u9700\u5f53\u5fc3\u8dcc\u6253\u635f\u4f24\u3002", "line": "\u75be\u75c5\uff1a\u98ce\u5bd2\u7f20\u8eab\u3002\u4ea6\u9700\u5f53\u5fc3\u8dcc\u6253\u635f\u4f24\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5fd9\u5fd9\u788c\u788c\uff0c\u6da8\u85aa\u65e0\u671b\u3002", "line": "\u8d22\u8fd0\uff1a\u5fd9\u5fd9\u788c\u788c\uff0c\u6da8\u85aa\u65e0\u671b\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5929\u964d\u98ce\u707e\u3002", "line": "\u4f4f\u6240\uff1a\u5929\u964d\u98ce\u707e\u3002"}, {"label": "\u604b\u7231", "text": "\u7a81\u53d1\u4e11\u95fb\uff0c\u96be\u6210\u6b63\u679c\u3002", "line": "\u604b\u7231\uff1a\u7a81\u53d1\u4e11\u95fb\uff0c\u96be\u6210\u6b63\u679c\u3002"}, {"label": "\u664b\u5347", "text": "\u9636\u7ea7\u4e4b\u522b\u4e0d\u53ef\u903e\u8d8a\u3002\u65ad\u5ff5\u4e3a\u5999\u3002", "line": "\u664b\u5347\uff1a\u9636\u7ea7\u4e4b\u522b\u4e0d\u53ef\u903e\u8d8a\u3002\u65ad\u5ff5\u4e3a\u5999\u3002"}]]'::jsonb);
（云山:变形程度的能力）', '["\u4eba\u751f\u5982\u6d6e\u4e91\u3002", "\u6101\u82e6\u538b\u8eab\u91cd\uff0c", "\u5219\u6709\u6cea\u5982\u96e8\uff0c", "\u7ec8\u81f3\u96fe\u6563\u65f6\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u9047\u5230\u56f0\u96be\u65f6\uff0c\u5b9a\u6709\u5f3a\u5927\u5996\u602a\u76f8\u52a9\u3002", "line": "\u8fd0\u52bf\uff1a\u9047\u5230\u56f0\u96be\u65f6\uff0c\u5b9a\u6709\u5f3a\u5927\u5996\u602a\u76f8\u52a9\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7cbe\u8fdb\u52ff\u4f11\uff0c\u529f\u6210\u82b1\u81ea\u5f00\u3002", "line": "\u5b66\u4e1a\uff1a\u7cbe\u8fdb\u52ff\u4f11\uff0c\u529f\u6210\u82b1\u81ea\u5f00\u3002"}, {"label": "\u8fd0\u52a8", "text": "\u683c\u6597\u4e3a\u5409\u3002", "line": "\u8fd0\u52a8\uff1a\u683c\u6597\u4e3a\u5409\u3002"}, {"label": "\u4ea4\u6613", "text": "\u52ff\u5b58\u5962\u5ff5\u3002\u5f53\u6452\u5f03\u6b32\u671b\u3002", "line": "\u4ea4\u6613\uff1a\u52ff\u5b58\u5962\u5ff5\u3002\u5f53\u6452\u5f03\u6b32\u671b\u3002"}, {"label": "\u5065\u5eb7", "text": "\u5403\u658b\u53ef\u4fdd\u4f53\u9b44\u5eb7\u5065\u3002", "line": "\u5065\u5eb7\uff1a\u5403\u658b\u53ef\u4fdd\u4f53\u9b44\u5eb7\u5065\u3002"}], [{"label": "\u51fa\u884c", "text": "\u5929\u7a7a\u4e4b\u65c5\u4e3a\u5409\u3002", "line": "\u51fa\u884c\uff1a\u5929\u7a7a\u4e4b\u65c5\u4e3a\u5409\u3002"}, {"label": "\u6bd4\u8bd5", "text": "\u767e\u6218\u65e0\u4e00\u8d25\uff0c\u4f46\u672a\u5fc5\u5f97\u80dc\u3002", "line": "\u6bd4\u8bd5\uff1a\u767e\u6218\u65e0\u4e00\u8d25\uff0c\u4f46\u672a\u5fc5\u5f97\u80dc\u3002"}, {"label": "\u5fc3\u613f", "text": "\u8010\u5fc3\u7b49\u5019\uff0c\u7cbe\u8fdb\u4e0d\u5df2\uff0c\u5fc5\u80fd\u5982\u613f\u3002", "line": "\u5fc3\u613f\uff1a\u8010\u5fc3\u7b49\u5019\uff0c\u7cbe\u8fdb\u4e0d\u5df2\uff0c\u5fc5\u80fd\u5982\u613f\u3002"}, {"label": "\u604b\u7231", "text": "\u5f53\u6452\u5f03\u6b32\u671b\u3002", "line": "\u604b\u7231\uff1a\u5f53\u6452\u5f03\u6b32\u671b\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u6210\u4f55\u4f53\u7edf\u3002", "line": "\u8d22\u8fd0\uff1a\u6210\u4f55\u4f53\u7edf\u3002"}, {"label": "\u4f4f\u6240", "text": "\u5b9c\u5bbd\u5e7f\u3002\u82e5\u6709\u53ef\u80fd\uff0c\u5bfa\u5e99\u4e3a\u5409\u3002", "line": "\u4f4f\u6240\uff1a\u5b9c\u5bbd\u5e7f\u3002\u82e5\u6709\u53ef\u80fd\uff0c\u5bfa\u5e99\u4e3a\u5409\u3002"}]]'::jsonb);
大大吉', '翱翔于夜色星间的大天狗', '操纵星空程度的能力', '["\u62ac\u5934\u4ef0\u671b\u5427\u3002", "\u90a3\u70b9\u70b9\u7e41\u661f\uff0c", "\u7686\u662f\u53d7\u6211\u7b49", "\u638c\u63a7\u7684\u7075\u9b42\u3002"]'::jsonb, '[[{"label": "\u8fd0\u52bf", "text": "\u9e3f\u8fd0\u5f53\u5934\u3002\u5fc3\u5fd7\u82e5\u4e0d\u575a\u5b9a\u5c06\u88ab\u8fd0\u6c14\u4f5c\u5f04\u3002", "line": "\u8fd0\u52bf\uff1a\u9e3f\u8fd0\u5f53\u5934\u3002\u5fc3\u5fd7\u82e5\u4e0d\u575a\u5b9a\u5c06\u88ab\u8fd0\u6c14\u4f5c\u5f04\u3002"}, {"label": "\u4ea4\u6613", "text": "\u8d85\u8d8a\u81ea\u6211\uff0c\u5546\u8def\u5e7f\u5f00\u3002\u4f46\u672a\u5fc5\u80fd\u6323\u94b1\u3002", "line": "\u4ea4\u6613\uff1a\u8d85\u8d8a\u81ea\u6211\uff0c\u5546\u8def\u5e7f\u5f00\u3002\u4f46\u672a\u5fc5\u80fd\u6323\u94b1\u3002"}, {"label": "\u5de5\u4f5c", "text": "\u4e0b\u5c5e\u5f87\u79c1\u821e\u5f0a\u3002", "line": "\u5de5\u4f5c\uff1a\u4e0b\u5c5e\u5f87\u79c1\u821e\u5f0a\u3002"}, {"label": "\u5b66\u4e1a", "text": "\u7406\u79d1\u4e3a\u5409\uff0c\u5929\u6587\u5c24\u4f73\u3002", "line": "\u5b66\u4e1a\uff1a\u7406\u79d1\u4e3a\u5409\uff0c\u5929\u6587\u5c24\u4f73\u3002"}, {"label": "\u8d22\u8fd0", "text": "\u5de8\u6b3e\u6d41\u52a8\u3002", "line": "\u8d22\u8fd0\uff1a\u5de8\u6b3e\u6d41\u52a8\u3002"}], [{"label": "\u5065\u5eb7", "text": "\u5c1a\u4f73\u3002\u4f46\u82e5\u98df\u4e0d\u679c\u8179\u5219\u75c5\u9b54\u5fc5\u81f3\u3002", "line": "\u5065\u5eb7\uff1a\u5c1a\u4f73\u3002\u4f46\u82e5\u98df\u4e0d\u679c\u8179\u5219\u75c5\u9b54\u5fc5\u81f3\u3002"}, {"label": "\u604b\u7231", "text": "\u9082\u9005\u6d6a\u6f2b\u604b\u60c5\u3002", "line": "\u604b\u7231\uff1a\u9082\u9005\u6d6a\u6f2b\u604b\u60c5\u3002"}, {"label": "\u4eba\u7f18", "text": "\u5de6\u53f3\u4f17\u4eba\u8fd0\u52bf\u3002", "line": "\u4eba\u7f18\uff1a\u5de6\u53f3\u4f17\u4eba\u8fd0\u52bf\u3002"}, {"label": "\u51fa\u884c", "text": "\u5b9c\u767b\u5c71\u3002", "line": "\u51fa\u884c\uff1a\u5b9c\u767b\u5c71\u3002"}, {"label": "\u7231\u597d", "text": "\u5b9c\u6444\u5f71\u3002", "line": "\u7231\u597d\uff1a\u5b9c\u6444\u5f71\u3002"}, {"label": "\u5fc3\u613f", "text": "\u5411\u6d41\u661f\u8bb8\u613f\u5373\u53ef\u5706\u6ee1\u3002", "line": "\u5fc3\u613f\uff1a\u5411\u6d41\u661f\u8bb8\u613f\u5373\u53ef\u5706\u6ee1\u3002"}]]'::jsonb);
